window.JLPT_META = {"title": "JLPT N2 — 直前対策", "levelsCount": 15, "levels": [{"id": 1, "file": "test01.json", "title_jp": "第1回", "title_uz": "1-bosqich", "minutes": 45, "ready": true}, {"id": 2, "file": "test02.json", "title_jp": "第2回", "title_uz": "2-bosqich", "minutes": 45, "ready": true}, {"id": 3, "file": "test03.json", "title_jp": "第3回", "title_uz": "3-bosqich", "minutes": 45, "ready": true}, {"id": 4, "file": "test04.json", "title_jp": "第4回", "title_uz": "4-bosqich", "minutes": 45, "ready": true}, {"id": 5, "file": "test05.json", "title_jp": "第5回", "title_uz": "5-bosqich", "minutes": 45, "ready": true}, {"id": 6, "file": "test06.json", "title_jp": "第6回", "title_uz": "6-bosqich", "minutes": 45, "ready": true}, {"id": 7, "file": "test07.json", "title_jp": "第7回", "title_uz": "7-bosqich", "minutes": 45, "ready": true}, {"id": 8, "file": "test08.json", "title_jp": "第8回", "title_uz": "8-bosqich", "minutes": 45, "ready": true}, {"id": 9, "file": "test09.json", "title_jp": "第9回", "title_uz": "9-bosqich", "minutes": 45, "ready": true}, {"id": 10, "file": "test10.json", "title_jp": "第10回", "title_uz": "10-bosqich", "minutes": 45, "ready": true}, {"id": 11, "file": "test11.json", "title_jp": "第11回", "title_uz": "11-bosqich", "minutes": 45, "ready": true}, {"id": 12, "file": "test12.json", "title_jp": "第12回", "title_uz": "12-bosqich", "minutes": 45, "ready": true}, {"id": 13, "file": "test13.json", "title_jp": "第13回", "title_uz": "13-bosqich", "minutes": 45, "ready": true}, {"id": 14, "file": "test14.json", "title_jp": "第14回", "title_uz": "14-bosqich", "minutes": 45, "ready": true}, {"id": 15, "file": "test15.json", "title_jp": "第15回", "title_uz": "15-bosqich", "minutes": 45, "ready": true}]};
window.JLPT_TESTS = {"1": {"id": 1, "title_jp": "第1回 模擬テスト", "title_uz": "1-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t1-v1-1", "options": ["こうぎ", "こうき", "ぎょうぎ", "ぎょうき"], "answer": 3, "tr": "U bolaligida odob-axloq qoidalarini oilada qattiq o'rgatilgan edi.", "stem": "彼女は子どものとき、【行儀作法】を家庭で厳しく教え込まれた。", "reading": "ぎょうぎ", "explanation_uz": "行儀作法 → ぎょうぎさほう (odob-axloq, yurish-turish qoidalari)"}, {"id": "t1-v1-2", "options": ["いちしゅん", "いつしゅん", "いっじゅん", "いっしゅん"], "answer": 4, "tr": "Xalqaro tanlovdagi g'alaba yosh musiqachining hayotini bir lahzada o'zgartirdi.", "stem": "国際コンクールでの優勝は、若い音楽家の人生を【一瞬】にして変えた。", "reading": "いっしゅん", "explanation_uz": "一瞬 → いっしゅん (bir lahza, bir on)"}, {"id": "t1-v1-3", "options": ["さそわれて", "おそわれて", "とらわれて", "うたわれて"], "answer": 1, "tr": "«Oz qoldi» degan so'zga qiziqib (vasvasaga tushib), beixtiyor teledo'kondan xarid qilib qo'ydim.", "stem": "「残りわずか」の声に【誘われて】、思わずテレビショッピングで買い物をしてしまった。", "reading": "さそわれて", "explanation_uz": "誘う → さそう (taklif qilmoq, qiziqtirmoq / vasvasaga solmoq)"}, {"id": "t1-v1-4", "options": ["ぶっぞう", "ぶっそう", "ぶつぞう", "ぶつそう"], "answer": 2, "tr": "Ilgari tinch shahar edi, yaqinda esa xavfli/notinch hodisalar ko'paydi.", "stem": "以前は静かな町だったのに、最近は【物騒な】事件が多くなった。", "reading": "ぶっそう", "explanation_uz": "物騒 → ぶっそう (xavfli, bexavotir bo'lmagan, notinch)"}, {"id": "t1-v1-5", "options": ["ええせい", "えいぜい", "えいせい", "ええぜい"], "answer": 3, "tr": "Grippdan o'lim darajasi pastligining bir sababi xalqning gigiyena bilimi yuqoriligidir.", "stem": "インフルエンザでの死亡率が低い理由の1つに、国民の【衛生】知識の高さがあげられる。", "reading": "えいせい", "explanation_uz": "衛生 → えいせい (gigiyena, sanitariya)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t1-v2-6", "options": ["飯きられて", "飽きられて", "館きられて", "飲きられて"], "answer": 2, "tr": "Tejamkor hayotdan charchagan iste'molchilarga faqat arzon bo'lgan mahsulotlar jonga tegib qoldi.", "stem": "節約生活に疲れた消費者に安いだけの商品は【あきられて】きた。", "reading": "あきられて", "explanation_uz": "飽きる → あきる (me'daga tegmoq, jonga tegmoq)"}, {"id": "t1-v2-7", "options": ["古展", "箇典", "個展", "古典"], "answer": 4, "tr": "«Genji monogatari» — Yaponiyaning vakillik qiluvchi mumtoz (klassik) adabiyotidir.", "stem": "『源氏物語』は日本の代表的な【こてん】文学だ。", "reading": "こてん", "explanation_uz": "古典 → こてん (mumtoz, klassik)"}, {"id": "t1-v2-8", "options": ["難いて", "嘆いて", "喝いて", "漢いて"], "answer": 2, "tr": "O'z kamchiliklaringga faqat qayg'uravermasdan (hasrat chekmasdan), kuchli tomonlaringni rivojlantirishing kerak.", "stem": "自分の欠点を【なげいて】ばかりいないで、長所を伸ばすべきだ。", "reading": "なげいて", "explanation_uz": "嘆く → なげく (qayg'urmoq, hasrat chekmoq, nola qilmoq)"}, {"id": "t1-v2-9", "options": ["激増", "激象", "劇増", "劇象"], "answer": 1, "tr": "Stress ko'p bo'lgan zamonamizda depressiyaga chalingan odamlar keskin ko'paymoqda.", "stem": "ストレスの多い現代、うつ病を病む人が【げきぞう】している。", "reading": "げきぞう", "explanation_uz": "激増 → げきぞう (keskin/tez ko'payish)"}, {"id": "t1-v2-10", "options": ["単水", "短水", "淡水", "採水"], "answer": 3, "tr": "Yuqori texnologiya tufayli dengiz suvi chuchuklashtirilib, ichish mumkin bo'ldi.", "stem": "高い技術力のおかげで海水が【たんすい】化されて、飲めるようになった。", "reading": "たんすい", "explanation_uz": "淡水 → たんすい (chuchuk suv) (淡水化 = chuchuklashtirish)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t1-v3-11", "options": ["質", "化", "力", "性"], "answer": 3, "tr": "O'z qo'ling bilan harflarni yozsang, xotira qobiliyati (kuchi) yanada oshar ekan.", "stem": "自分の手で文字を書くと記憶（　）がより高まるそうだ。", "explanation_uz": "記憶力 (きおくりょく) = xotirlash qobiliyati"}, {"id": "t1-v3-12", "options": ["品", "作", "物", "者"], "answer": 2, "tr": "Bu surat uning eng mashhur (namoyondalik) asaridir.", "stem": "この絵は彼の代表（　）である。", "explanation_uz": "代表作 (だいひょうさく) = muallifning eng mashhur / vakillik asari"}, {"id": "t1-v3-13", "options": ["区", "場", "所", "域"], "answer": 1, "tr": "Bu yer baland tog' o'simliklarini muhofaza qilish hududidir (zonasidir).", "stem": "ここは高山植物の保護（　）です。", "explanation_uz": "保護区 (ほごく) = qo'riqxona zonasi, muhofaza hududi"}, {"id": "t1-v3-14", "options": ["軍", "陣", "戦", "権"], "answer": 3, "tr": "Professional beysbolning rasmiy musobaqasi (o'yini) boshlanish arafasida.", "stem": "プロ野球の公式（　）が始まるところだ。", "explanation_uz": "公式戦 (こうしきせん) = rasmiy o'yin / musobaqa"}, {"id": "t1-v3-15", "options": ["悪", "副", "複", "反"], "answer": 2, "tr": "Bu dorining oshqozonni bezovta qiladigan nojo'ya ta'siri (aks ta'siri) bor.", "stem": "この薬は胃を荒らす（　）作用がある。", "explanation_uz": "副作用 (ふくさよう) = nojo'ya ta'sir"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga ma'no jihatidan eng mos keladigan so'zni tanlang.", "questions": [{"id": "t1-v4-16", "options": ["滅多に", "滅多", "まれ", "たま"], "answer": 2, "tr": "«Tarix takrorlanadi» deyiladi-ku, lekin bir xil bo'lib takrorlanishi kamdan-kam bo'ladi.", "stem": "「歴史は繰り返す」と言うが、同じように繰り返されることは（　）にない。", "reading": "めった", "explanation_uz": "滅多に〜ない (めったに〜ない) = kamdan-kam, deyarli bo'lmaydi"}, {"id": "t1-v4-17", "options": ["それぞれ", "しばしば", "ぞくぞく", "とうとう"], "answer": 2, "tr": "Kir yuvish mashinasi bunchalik tez-tez buzilaversa, yangisini sotib olishdan boshqa chora yo'q.", "stem": "洗濯機がこう（　）故障するのでは、買い替えるしかない。", "explanation_uz": "しばしば = tez-tez, bot-bot (たびたび)"}, {"id": "t1-v4-18", "options": ["セキュリティー", "コンディション", "オペレーション", "コンタクト"], "answer": 1, "tr": "Bu hududda yolg'iz yashovchi qariyalar ko'p bo'lib, xavfsizlik (security) masalasida xavotir bor.", "stem": "この地域は一人暮らしのお年寄りが多く、（　）に不安がある。", "explanation_uz": "セキュリティー = xavfsizlik, xavfsizlik tizimi"}, {"id": "t1-v4-19", "options": ["信頼", "資本", "舞台", "現実"], "answer": 3, "tr": "Mening orzum — global maydonda (sahna) faoliyat yuritishdir.", "stem": "私の夢は、グローバルな（　）で活躍することです。", "explanation_uz": "舞台 (ぶたい) = sahna, maydon (global maydon = グローバルな舞台)"}, {"id": "t1-v4-20", "options": ["独特", "格別", "特例", "特殊"], "answer": 1, "tr": "Bu uyning qurilish uslubi faqat shu hududga xosdir (o'ziga xosdir).", "stem": "この家の建て方は、この地方（　）のものです。", "explanation_uz": "独特 (どくとく) = o'ziga xos, betakror"}, {"id": "t1-v4-21", "options": ["調節", "管理", "修正", "修繕"], "answer": 4, "tr": "Tomni ta'mirlash bahonasida quyosh energiyasi tizimini o'rnatishga qaror qildik.", "stem": "屋根を（　）するついでに、太陽光発電システムを取り入れることにした。", "explanation_uz": "修繕 (しゅうぜん) = ta'mirlash, tuzatish"}, {"id": "t1-v4-22", "options": ["切り抜き", "切り取り", "書き取り", "選り抜き"], "answer": 1, "tr": "Gazetadagi taom maqolalaridan qirqib olingan parchalarni taomnoma tuzishda qo'llanma qilyapman.", "stem": "新聞の料理記事の（　）を献立の参考にしている。", "explanation_uz": "切り抜き (きりぬき) = gazetadan qirqib olingan parcha (vyrezka)"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin sinonimni tanlang.", "questions": [{"id": "t1-v5-23", "options": ["乗り換えになる", "交差している", "一体化している", "つながっている"], "answer": 4, "tr": "Bu xususiy temiryo'l keyingi bekatda JR bilan tutashgan (bog'langan).", "stem": "この私鉄は次の駅でJRと【連絡している】。", "reading": "れんらくしている", "explanation_uz": "連絡している = つながっている (bog'langan, tutashgan)"}, {"id": "t1-v5-24", "options": ["騒がれた", "おかしかった", "当たらなかった", "難しかった"], "answer": 3, "tr": "Saylov bo'yicha taxmin xato chiqdi (to'g'ri chiqmadi).", "stem": "選挙の予想が【外れた】。", "reading": "はずれた", "explanation_uz": "外れる (はずれる) = 当たらなかった (to'g'ri chiqmadi, adashdi)"}, {"id": "t1-v5-25", "options": ["非常に", "改めて", "逆に", "多少"], "answer": 3, "tr": "Yaqin yo'ldan borgan bo'lsak-da, aksincha ko'proq vaqt ketdi.", "stem": "近道したのに【かえって】時間がかかった。", "explanation_uz": "かえって = 逆に (aksincha, teskarisiga)"}, {"id": "t1-v5-26", "options": ["率直に", "適当に", "簡単に", "自由に"], "answer": 1, "tr": "Ochiqchasiga (samimiy) fikrimni aytsam, u taklifga qarshiman.", "stem": "はっきり意見を申し上げるなら、その案には【反対です】。", "explanation_uz": "率直に (そっちょくに) = はっきりと、ありのままに (ochiqchasiga, to'g'ridan-to'g'ri)"}, {"id": "t1-v5-27", "options": ["進めた", "終わらせた", "引き受けた", "補った"], "answer": 4, "tr": "Rahbar dam olish kuni ishga chiqib, xodimining kechikkan ishini to'ldirdi (yordam berdi).", "stem": "上司が休日出勤して、部下の遅れた仕事を【カバーした】。", "explanation_uz": "カバーした = 補った (おぎなった — kam-ko'stini to'ldirdi, qopladi)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilgan gapini tanlang.", "questions": [{"id": "t1-v6-28", "options": ["この仕事には能力のある人物を通用する予定だ。", "そんなへたな言い訳は、私には通用しない。", "この危険な仕事に、これだけの給料では通用しない。", "この本はあなたの勉強に通用するのでお読みなさい。"], "answer": 2, "tr": "通用 (つうよう) = yaroqli bo'lmoq, o'tmoq, qabul qilinmoq.", "stem": "通用", "optsTr": ["Bu ishga qobiliyatli odamni 'o'tkazish' rejamiz bor (noto'g'ri).", "Bunday puch bahonalar menga o'tmaydi (ish bermaydi). (to'g'ri)", "Bu xavfli ishga buncha oylik 'o'tmaydi' (noto'g'ri).", "Bu kitob sizning o'qishingizga 'o'tadi', o'qing (noto'g'ri)."]}, {"id": "t1-v6-29", "options": ["論文は、あらすじ書き上がっています。", "会議で経営方針のあらすじが決まった。", "仲間同士で激しいあらすじになってしまった。", "この小説のあらすじを400字以内にまとめなさい。"], "answer": 4, "tr": "あらすじ = qisqacha mazmun (syujet bayoni).", "stem": "あらすじ", "optsTr": ["Ilmiy maqola 'qisqacha syujeti' yozib bo'lindi (noto'g'ri).", "Yig'ilishda boshqaruv rejasining 'syujeti' hal bo'ldi (noto'g'ri).", "Do'stlar o'rtasida shiddatli 'syujet' yuz berdi (noto'g'ri).", "Ushbu romanning qisqacha mazmunini (syujetini) 400 belgidan oshirmay xulosa qiling. (to'g'ri)"]}, {"id": "t1-v6-30", "options": ["だれにでも迷惑な思い出の1つや2つはあるものだ。", "込んでいる電車の中で新聞を広げるのは、他の客に迷惑だ。", "こんな少ない給料では家族の生活はいい迷惑だ。", "病気だとわかったときにはもうすでに手遅れで、迷惑な状態だった。"], "answer": 2, "tr": "迷惑 (めいわく) = boshqalarga noqulaylik/tashvish tug'dirish.", "stem": "迷惑", "optsTr": ["Har kimda ham 'noqulay' xotira bitta-ikkita bo'ladi (noto'g'ri).", "Odam gavjum poyezdda gazeta yoyish — boshqa yo'lovchilarga halal beradi (noqulaylikdir). (to'g'ri)", "Bunday kam maosh bilan oilaning turmushi 'katta noqulaylik' (noto'g'ri).", "Kasal ekani bilinganda kech bo'lib, 'noqulay' holatda edi (noto'g'ri)."]}, {"id": "t1-v6-31", "options": ["この店は土日も休まず売買している。", "この商品は売買がよくて、生産が追いつかない。", "やむを得ない事情でこの土地を売買することにした。", "不動産を売買するには資格が必要だ。"], "answer": 3, "tr": "売買 (ばいばい) = oldi-sotdi (savdo qilish).", "stem": "売買", "optsTr": ["Bu do'kon shanba-yakshanba ham dam olmasdan 'oldi-sotdi qiladi' (noto'g'ri — 営業).", "Bu mahsulotning 'oldi-sotdisi' yaxshi bo'lib, yetkazib bo'lmayapti (noto'g'ri — 売れ行き).", "Majburiy vaziyat tufayli ushbu yerni oldi-sotdi qilishga (sotishga) qaror qildik. (to'g'ri)", "Ko'chmas mulkni oldi-sotdi qilish uchun litsenziya kerak (noto'g'ri)."]}, {"id": "t1-v6-32", "options": ["新しい法案は過半数の賛成を得たので国会で成立した。", "今回の地震の被害者の数は過半数だった。", "狭い会場にファンが過半数で押しかけてきた。", "彼が犯人だという証拠は過半数である。"], "answer": 1, "tr": "過半数 (かはんすう) = ko'pchilik qism (yarmidan ko'pi, 50% dan ortig'i).", "stem": "過半数", "optsTr": ["Yangi qonun loyihasi yarmidan ko'pining (ko'pchilikning) ovozini olib, parlamentda ma'qullandi. (to'g'ri)", "Bu galgi zilzila qurbonlarining soni 'ko'pchilik' edi (noto'g'ri).", "Tor zalga muxlislar 'ko'pchilik bo'lib' bostirib keldi (noto'g'ri).", "U jinoyatchi ekanligi haqidagi dalil 'yarmidan ko'p' (noto'g'ri)."]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t1-g1-33", "options": ["際に", "あげく", "上で", "ついでに"], "answer": 3, "tr": "Ishni o'zgartirish yaxshilab o'ylab ko'rgach qabul qilgan qarorim bo'lgani uchun, xato bo'lsa ham mayli.", "stem": "転職はよく考えた（　）決めたことですから、たとえ失敗してもかまいません。", "explanation_uz": "〜た上で (うえで) = ...gach, ...ganidan so'ng (oldin sinchiklab o'ylab, keyin qilingan harakat)"}, {"id": "t1-g1-34", "options": ["からいって", "だからといって", "だけあって", "といって"], "answer": 1, "tr": "Soliqlar oshishi qiyin. Ammo qariyalar soni tobora oshib borayotgan voqelikdan kelib chiqsak, iloj yo'q.", "stem": "税金が上がるのは困る。しかし高齢者がますます増える現実（　）、仕方がない。", "explanation_uz": "〜からいって = ...dan kelib chiqib mulohaza yuritilsa"}, {"id": "t1-g1-35", "options": ["的に", "用に", "寄りに", "向けに"], "answer": 4, "tr": "Bu yerdagi tay taomlari yaponlar uchun (yaponlarga mo'ljallab) achchiqligi biroz pasaytirilgan.", "stem": "ここのタイ料理は、日本人（　）すこし辛さをおさえてあります。", "explanation_uz": "〜向けに (むけに) = ...uchun maxsus mo'ljallangan"}, {"id": "t1-g1-36", "options": ["ことでは", "ものでは", "かぎりでは", "まででは"], "answer": 3, "tr": "Mening ko'rganim bo'yicha (kuzatishim doirasida) qaralsa, Yamada-sanni bunchalik yomon odam deb hisoblay olmayman.", "stem": "私が見た（　）、山田さんがそんなに悪い人だとは思えない。", "explanation_uz": "〜かぎりでは = ...ganimcha, ...doirasida hukm qilinsa"}, {"id": "t1-g1-37", "options": ["わけ", "もの", "こと", "はず"], "answer": 3, "tr": "«O'zim bo'lsam bundan ham yaxshi qilardim» deydigan bo'lsang, o'zing qilib ko'rishing kerak-da.", "stem": "「自分ならもっとうまくやれる」と言うなら、君がやってみる（　）だね。", "explanation_uz": "〜ことだ = ...qilish kerak (maslahat yoki kinoya)"}, {"id": "t1-g1-38", "options": ["反対で", "以外で", "片面で", "一方で"], "answer": 4, "tr": "Turmush qurgandan keyin ham ishlaydigan ayollar ko'payayotgan bir paytda, uy bekasi bo'lishni xohlaydigan ayollar ham ko'paymoqda.", "stem": "結婚後も仕事をする女性が増える（　）、専業主婦になりたい女性も増えている。", "explanation_uz": "〜一方で (いっぽうで) = bir tomondan ... bo'lsa, ikkinchi tomondan esa..."}, {"id": "t1-g1-39", "options": ["のあまり", "のせいか", "のくせに", "のおかげで"], "answer": 1, "tr": "Tekshiruv natijasidan haddan tashqari xavotirlanganimdan, tonggacha uxlay olmadim.", "stem": "検査の結果が心配（　）、朝まで眠ることができなかった。", "explanation_uz": "〜あまり = ...ning haddan ziyodligi natijasida"}, {"id": "t1-g1-40", "options": ["ことから", "ことだから", "ことに", "ことなら"], "answer": 1, "tr": "Bu meva salomatlik uchun juda foydali bo'lgani sababli, qadimdan «shifokorga hojat qoldirmas» deb ham ataladi.", "stem": "この果物はとても健康にいい（　）、昔から「医者いらず」とも呼ばれる。", "explanation_uz": "〜ことから = ...bo'lganligi sababli (sabab/kelib chiqish)"}, {"id": "t1-g1-41", "options": ["知りつつも", "知らないものの", "知るからには", "知らないくせに"], "answer": 1, "tr": "Salomatlikka zarar ekanligini bilsa ham, nega tamakini tashlay olmaydi-a!", "stem": "健康に悪いと（　）、どうして煙草がやめられない。", "explanation_uz": "〜つつも = ...sa ham, qaramay (ziddiyatli harakat)"}, {"id": "t1-g1-42", "options": ["するわけにはいかない", "しないわけにはいかない", "するべきでない", "してはいられない"], "answer": 2, "tr": "Agar oramizda hech kimning haydovchilik guvohnomasi bo'lmasa, men haydamasam bo'lmaydi (haydashga majburman).", "stem": "このなかでだれも免許を持っていないなら、私が運転（　）ね。", "explanation_uz": "〜ないわけにはいかない = ...maslikning iloji yo'q, shart"}, {"id": "t1-g1-43", "options": ["気に入らなかったにしても", "気に入らなかったとしたら", "気に入ったとしても", "気に入ったとしたら"], "answer": 1, "tr": "Garchi sovg'a yoqmagan bo'lsa ham, uni bergan kishiga hech bo'lmaganda minnatdorchilik maktubi yozish odobdandir.", "stem": "たとえ贈り物が（　）、下さった方にお礼の手紙くらい書くものですよ。", "explanation_uz": "たとえ〜にしても = garchi ... bo'lgan taqdirda ham"}, {"id": "t1-g1-44", "options": ["伝えていただけますか", "お伝えいただけますか", "お伝えになれますか", "お伝えいたしましょうか"], "answer": 2, "tr": "A: «Afsuski Tanaka tashqariga chiqqan edilar.»\nB: «U holda, A kompaniyasining Yamadasidan qo'ng'iroq bo'lganini yetkazib qo'ya olasizmi?»", "stem": "A「あいにく田中は外出しております。」\nB「では、A社の山田から電話があったと（　）。」", "explanation_uz": "お伝えいただけますか = yetkazib bera olasizmi (xushmuomala so'rov: お〜いただく)"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng to'g'ri bo'lakni tanlang.", "questions": [{"id": "t1-g2-45", "options": ["やれる", "やって", "できるか", "ものなら"], "answer": 4, "tr": "To'g'ri tartib: そんな勉強のやり方で合格できるか、やれるものならやってみればいいよ。", "explanation_uz": "To'g'ri tartib: 合格[できるか]、[やれる][★ものなら][やって]みればいいよ。 (3 → 1 → 4 → 2)", "prefix": "そんな勉強のやり方で合格", "suffix": "みればいいよ。", "starPos": 3, "order": [3, 1, 4, 2]}, {"id": "t1-g2-46", "options": ["がち", "飲める", "忘れ", "ありがたさを"], "answer": 3, "tr": "To'g'ri tartib: 日本人は、どこでも水がただで飲めるありがたさを忘れがちです。", "explanation_uz": "To'g'ri tartib: ただで[飲める][ありがたさを][★忘れ][がち]です。 (2 → 4 → 3 → 1)", "prefix": "日本人は、どこでも水がただで", "suffix": "です。", "starPos": 3, "order": [2, 4, 3, 1]}, {"id": "t1-g2-47", "options": ["なれば", "という", "ものでは", "平気になる"], "answer": 2, "tr": "To'g'ri tartib: 歯医者に行くのは、大人になれば平気になるというものではありません。", "explanation_uz": "To'g'ri tartib: 大人になれば[平気になる][という][★ものでは]ありません。 (1 → 4 → 2 → 3)", "prefix": "歯医者に行くのは、大人に", "suffix": "ありません。", "starPos": 3, "order": [1, 4, 2, 3]}, {"id": "t1-g2-48", "options": ["忘れた", "に", "かけるのを", "ばかり"], "answer": 1, "tr": "To'g'ri tartib: 私が家のかぎをかけるのを忘れたばかりに、どろぼうに入られてしまった。", "explanation_uz": "To'g'ri tartib: かぎを[かけるのを][★忘れた][ばかり][に] (3 → 1 → 4 → 2)", "prefix": "私が家のかぎを", "suffix": "どろぼうに入られてしまった。", "starPos": 2, "order": [3, 1, 4, 2]}, {"id": "t1-g2-49", "options": ["ある", "以上は", "うつす", "おそれが"], "answer": 4, "tr": "To'g'ri tartib: B「病気を人にうつすおそれがある以上は、学校を休んだほうがいいわよ。」", "explanation_uz": "To'g'ri tartib: 病気を人に[うつす][★おそれが][ある][以上は] (3 → 4 → 1 → 2)", "prefix": "B「病気を人に", "suffix": "学校を休んだほうがいいわよ。」", "starPos": 2, "order": [3, 4, 1, 2]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh joylariga eng to'g'ri variantni tanlang.", "passage_title": "囲碁の広がり", "passage": "少し前の日本の家庭には、たいてい囲碁（いご）の道具があった {{50}} 。子どもたちは、祖父や近所のおじさんたちが遊ぶのをそばで見て、自分たちもルールを覚えていった。だが最近は核家族が増えて、ルールを知らない若い親は子どもに教えることがなくなり、子どもたちも囲碁からは離れていった。\n囲碁は本当に強くなるためには、子どものときから始めるのが重要だそうだ。しかし、かつて1200万人とも言われた競技人口が300万人台にまで落ち込み、しかも子どもの数がとても少なくなった。囲碁にかかわる人々は、日本の囲碁の将来に {{51}} 。\nそこへ救いの神が現れた。1998年から雑誌に囲碁がテーマのマンガが連載され、大ヒットしたのだ。マンガはテレビアニメにもなり、子ども向けに囲碁を教えるテレビ番組も放送された。このマンガを {{52}} として、囲碁を始めた子どもはざっと100万人と言われる。\nだが何しろ日本人は熱しやすく冷めやすい国民だ。事実、すでに新しく囲碁を始める人は {{53}} 。\n「この機会を一時のブームで {{54}} 」と、関係者はいろいろなアイデアを出している。", "passage_tr": "Biroz avvalgi yapon xonadonlarida odatda go (igo) o'yini anjomlari bo'lar edi. Bolalar bobolari va qo'shni amakilarning o'ynashini yonidan kuzatib, o'zlari ham qoidalarini o'rganib olishardi. Ammo so'nggi paytlarda alohida yashovchi oilalar ko'payib, qoidani bilmaydigan yosh ota-onalar bolalariga o'rgatmay qo'ydi, bolalar ham godan uzoqlashdi.\nGo o'yinida chinakam kuchli bo'lish uchun bolalikdan boshlash muhim ekan. Biroq, bir paytlar 12 million kishi deb aytilgan o'yinchilar soni 3 milliongacha tushib ketdi, buning ustiga bolalar soni ham juda kamaydi. Go sohasidagi insonlar yapon gosi kelajagidan qattiq xavotirda edilar.\nShu paytda najotkor paydo bo'ldi. 1998-yildan jurnalda go mavzusidagi manga chop etila boshlab, juda mashhur bo'ldi. Manga teleanimatsiyaga aylandi, bolalar uchun go o'rgatadigan teledasturlar ham efirga uzatildi. Ushbu mangani turtki (sabab) qilib, go o'ynashni boshlagan bolalar taxminan 1 million kishi deb aytiladi.\nLekin nima bo'lganda ham yaponlar tez qizib, tez soviydigan xalqdir. Aslida allaqachon yangidan goni boshlayotganlar kamayib bormoqda.\n«Ushbu imkoniyatni vaqtinchalik shov-shuv bilan tugatib qo'ymaylik» deb, soha xodimlari turli g'oyalarni ilgari surmoqdalar.", "questions": [{"id": "t1-g3-50", "options": ["ことだ", "ものだ", "ところだ", "ようだ"], "answer": 2, "tr": "かつての習慣: 囲碁の道具があった[ものだ] (Ilgari bo'lar edi - o'tmishdagi xotira/odat).", "explanation_uz": "〜ものだ = o'tmishdagi doimiy holat / xotira", "blankNo": "50"}, {"id": "t1-g3-51", "options": ["大きな希望を持っていた", "強い不安を持っていた", "安心しかねなかった", "少しの心配もなかった"], "answer": 2, "tr": "日本の囲碁の将来に[強い不安を持っていた] (Kelajagidan qattiq xavotirda edilar).", "explanation_uz": "O'yinchilar soni keskin kamaygani sababli: 強い不安を持っていた", "blankNo": "51"}, {"id": "t1-g3-52", "options": ["きっかけ", "もと", "事情", "原因"], "answer": 1, "tr": "このマンガを[きっかけ]として = Ushbu mangani turtki qilib / bahona qilib.", "explanation_uz": "〜をきっかけとして = ...ni turtki / sabab qilib olib", "blankNo": "52"}, {"id": "t1-g3-53", "options": ["減りつつある", "減りそうもない", "増えるかもしれない", "増えざるを得ない"], "answer": 1, "tr": "新しく囲碁を始める人は[減りつつある] = Yangi boshlovchilar kamayib bormoqda.", "explanation_uz": "〜つつある = tobora ...yotgan bo'lmoq (davomiy o'zgarish)", "blankNo": "53"}, {"id": "t1-g3-54", "options": ["終わらせたい", "終わらせよう", "終わらせまい", "終わりたくない"], "answer": 3, "tr": "この機会を一時のブームで[終わらせまい]と = bir lahzalik shov-shuv bilan tugatib qo'ymaylik deb.", "explanation_uz": "〜まい = ...maslik niyati / qarori (tugatmaslikka qaror qilish)", "blankNo": "54"}]}]}]}, "2": {"id": 2, "title_jp": "第2回 模擬テスト", "title_uz": "2-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t2-v1-1", "options": ["はめられる", "おさめられる", "とられる", "しばられる"], "answer": 4, "tr": "Internet muhiti yaxshilansa, ofisga bog'lanib qolmasdan (cheklanmasdan), qayerda bo'lsa ham ishlash mumkin.", "stem": "ネット環境が整えばオフィスに【縛られる】ことなく、どこにいても仕事ができる。", "reading": "しばられる", "explanation_uz": "縛る → しばる (bog'lamoq, cheklamoq)"}, {"id": "t2-v1-2", "options": ["そうぞう", "ずうずう", "あらあら", "いまいま"], "answer": 1, "tr": "Poyezd ichida ko'plab bolalar ketayotgani sababli juda shovqin-suronli edi.", "stem": "電車の中は、たくさんの子どもが乗っていて【騒々しかった】。", "reading": "そうぞうしかった", "explanation_uz": "騒々しい → そうぞうしい (shovqinli, g'ovur-g'uvur)"}, {"id": "t2-v1-3", "options": ["ちょうし", "ちょうじ", "しゅうじ", "じゅうし"], "answer": 4, "tr": "Bizning kompaniya bu yildan suhbat sonini ko'paytirib, bilimdan ko'ra shaxsiyatga ahamiyat berib (muhim deb bilib) xodimlarni qabul qiladi.", "stem": "我が社は今年から面接の回数を増やして、知識より人物【重視】で社員を採用する。", "reading": "じゅうし", "explanation_uz": "重視 → じゅうし (muhim deb bilish, ahamiyat qaratish)"}, {"id": "t2-v1-4", "options": ["こうかん", "ごうがん", "こうがん", "ごうかん"], "answer": 1, "tr": "Xaridlar orqali to'plangan ballarni tovar kuponlariga almashtirish mumkin.", "stem": "お買い物でためたポイントは、商品券に【交換】できます。", "reading": "こうかん", "explanation_uz": "交換 → こうかん (almashtirish, o'zaro almashuv)"}, {"id": "t2-v1-5", "options": ["ほうぞう", "ほうそう", "ほうそう", "ほうぞう"], "answer": 3, "tr": "Supermarketlarda oziq-ovqatlarni qadoqlashni (o'rab-chirmashni) kamaytirish bo'yicha harakatlar olib borilmoqda.", "stem": "スーパーでは食品の【包装】を少なくする活動が進んでいる。", "reading": "ほうそう", "explanation_uz": "包装 → ほうそう (qadoqlash, o'rash)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t2-v2-6", "options": ["暖房", "暖冒", "断房", "断冒"], "answer": 1, "tr": "Quyosh energiyasi hosil qiladigan issiqlik isitish tizimiga, yorug'lik esa elektrga ishlatilishi mumkin.", "stem": "太陽エネルギーが生み出す熱は【だんぼう】に、光は電気に利用できる。", "reading": "だんぼう", "explanation_uz": "暖房 → だんぼう (isitish tizimi)"}, {"id": "t2-v2-7", "options": ["勘違い", "肝違い", "感違い", "塞違い"], "answer": 1, "tr": "U ikki kishini er-xotin deb yanglish (noto'g'ri tushunadigan) o'ylaydigan odamlar ko'p.", "stem": "あの2人は夫婦だと【かんちがい】している人が多い。", "reading": "かんちがい", "explanation_uz": "勘違い → かんちがい (yanglishish, noto'g'ri tushunish)"}, {"id": "t2-v2-8", "options": ["焦らして", "燃らして", "照らして", "烈らして"], "answer": 3, "tr": "Umumiy qoidalar (aql-idrok) bilan qiyoslab (solishtirib) ko'rsang, hozir nima qilishing kerakligi ayon bo'ladi.", "stem": "常識に【てらして】考えてみれば、君が今、何をすべきかわかるだろう。", "reading": "てらして", "explanation_uz": "照らす → てらす (solishtirmoq, qiyoslamoq; yoritmoq)"}, {"id": "t2-v2-9", "options": ["地敷", "地版", "地番", "地盤"], "answer": 4, "tr": "Bu atrofda zilzila oqibatida yer poydevori (tuproq qatlami) cho'kib ketdi.", "stem": "このあたりは地震で【じばん】が沈んでしまった。", "reading": "じばん", "explanation_uz": "地盤 → じばん (yer sathi, poydevor tuproq)"}, {"id": "t2-v2-10", "options": ["汚洗", "御染", "汚染", "冒染"], "answer": 3, "tr": "Zavod halokati tufayli zararli moddalar oqib, daryo ifloslandi.", "stem": "工場の事故で有害物質が流れ、川が【おせん】された。", "reading": "おせん", "explanation_uz": "汚染 → おせん (ifloslanish, zaharlanish)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t2-v3-11", "options": ["無", "反", "非", "不"], "answer": 3, "tr": "Hindistonlik Gandi zo'ravonliksiz (tinchlik) tamoyiliga tayanib, mustaqillik harakatiga boshchilik qildi.", "stem": "インドのガンジーは（　）暴力を信条に独立運動を指導した。", "explanation_uz": "非暴力 (ひぼうりょく) = zo'ravonliksizlik tamoyili"}, {"id": "t2-v3-12", "options": ["人", "風", "流", "派"], "answer": 4, "tr": "Yamada janoblari o'ziga xos uslubdagi (individual tipdagi) aktyor sifatida faoliyat yuritmoqda.", "stem": "山田氏は、個性（　）俳優として活躍している。", "explanation_uz": "個性派 (こせいは) = o'ziga xos individual yo'nalishga ega bo'lgan shaxs/aktyor"}, {"id": "t2-v3-13", "options": ["点", "見", "場", "所"], "answer": 1, "tr": "Barcha xodimlardan teatrni yaxshilash nuqtalari (takliflari) so'raladi.", "stem": "全社員に劇場の改善（　）を開く。", "explanation_uz": "改善点 (かいぜんてん) = yaxshilanishi kerak bo'lgan jihatlar/nuqtalar"}, {"id": "t2-v3-14", "options": ["方", "側", "界", "世"], "answer": 3, "tr": "Tabiat olami qonuniyatlariga qarshi chiqib bo'lmaydi.", "stem": "自然（　）の法則には逆らえない。", "explanation_uz": "自然界 (しぜんかい) = tabiat olami / tabiat dunyosi"}, {"id": "t2-v3-15", "options": ["近", "同", "何", "当"], "answer": 2, "tr": "Bolalar tengdosh bo'lganlari sababli, darrov do'stlashib ketishdi.", "stem": "子どもたちは（　）年齢とあって、すぐに仲よくなった。", "explanation_uz": "同年齢 (どうねんれい) = tengdosh, bir yoshdagi"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga ma'no jihatidan eng mos keladigan so'zni tanlang.", "questions": [{"id": "t2-v4-16", "options": ["制作", "工事", "閉鎖", "更新"], "answer": 4, "tr": "To'garakning veb-saytiga «Tadbirlar ma'lumoti»ni qo'shib, yangiladik (update qildik).", "stem": "サークルのホームページに「イベント情報」を追加し、（　）した。", "explanation_uz": "更新 (こうしん) = yangilash, yangi ma'lumot kiritish"}, {"id": "t2-v4-17", "options": ["上等", "優秀", "有効", "優良"], "answer": 2, "tr": "Eng a'lo natija ko'rsatgan talabaga universitet tomonidan rektor mukofoti beriladi.", "stem": "最も（　）な成績の学生には、大学から学長賞が贈られます。", "explanation_uz": "優秀 (ゆうしゅう) = a'lo, yetakchi, iqtidorli"}, {"id": "t2-v4-18", "options": ["重視", "指導", "活用", "刺激"], "answer": 4, "tr": "Xarid qilish kabi kundalik odat iste'molni rag'batlantirib (kuchaytirib), jamiyatni jonlantiradi.", "stem": "買い物という日常的な行いが、消費を（　）して世の中を元気にする。", "explanation_uz": "刺激 (しげき) = rag'batlantirish, qo'zg'atish"}, {"id": "t2-v4-19", "options": ["いらいら", "ぶつぶつ", "のろのろ", "まごまご"], "answer": 1, "tr": "Avtobus aslo kelavermagach, kutayotgan odamlar asta-sekin asabiylasha (g'azablana) boshladi.", "stem": "バスがなかなか来なくて、待っている人たちは次第に（　）し始めた。", "explanation_uz": "いらいら = asabiylashish, betoqat bo'lish"}, {"id": "t2-v4-20", "options": ["アプローチ", "アレンジ", "アシスト", "アドバイス"], "answer": 2, "tr": "Yapon sushisini moslashtirgan (modifikatsiya qilgan) g'arbona sushi chet elda mashhur.", "stem": "日本の寿司を（　）した洋風の寿司が海外で人気だ。", "explanation_uz": "アレンジ (arrange) = yangicha talqin qilish, moslashtirish"}, {"id": "t2-v4-21", "options": ["長期", "不変", "永遠", "不滅"], "answer": 3, "tr": "Baxt abadiy davom etishi mumkin emasmi-a?", "stem": "幸福が（　）に続くことはありえないのだろうか。", "explanation_uz": "永遠に (えいえんに) = abadiy, mangu"}, {"id": "t2-v4-22", "options": ["謙遜", "遠慮", "配慮", "恐縮"], "answer": 1, "tr": "U ulkan korporatsiya prezidenti o'zida aytarli iste'dod yo'qligini kamtarlik bilan aytadi.", "stem": "あの大企業の社長は自分にはこれといった才能はないと（　）している。", "explanation_uz": "謙遜 (けんそん) = kamtarlik qilish"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin sinonimni tanlang.", "questions": [{"id": "t2-v5-23", "options": ["記録した", "発表した", "重視した", "経験した"], "answer": 4, "tr": "O'yinda yutqazish alamini totib ko'rdim (boshdan kechirdim).", "stem": "試合に負けた悔しさを【味わった】。", "reading": "あじわった", "explanation_uz": "味わう → 経験した (boshdan kechirish, his qilish)"}, {"id": "t2-v5-24", "options": ["約束通り", "思いがけなく", "確かに", "都合よく"], "answer": 2, "tr": "Sayohat paytida kutilmaganda (tasodifan) eski do'stimni uchratib qoldim.", "stem": "旅先で【偶然】昔の友人に出会った。", "reading": "ぐうぜん", "explanation_uz": "偶然 → 思いがけなく (kutilmaganda, tasodifan)"}, {"id": "t2-v5-25", "options": ["変化がない", "よく変わる", "手間がかかる", "休みがない"], "answer": 1, "tr": "Zavoddagi bir xil (zerikarli, monoton) ishdan zerikib qoldim.", "stem": "工場の【単調な】作業にあきてきた。", "reading": "たんちょうな", "explanation_uz": "単調な → 変化がない (o'zgarishsiz, monoton)"}, {"id": "t2-v5-26", "options": ["のんびりした", "予想しない", "頼りになる", "元気のよい"], "answer": 3, "tr": "Yutqazib qiynalib turganda, kuchli (suyanadigan, ishonchli) ittifoqchi paydo bo'ldi.", "stem": "負けて困っているところに、【強力な】味方が現れた。", "reading": "きょうりょくな", "explanation_uz": "強力な → 頼りになる (ishonchli, suyansa bo'ladigan)"}, {"id": "t2-v5-27", "options": ["国際性がある", "物知りだ", "二カ国語を話す", "二重国籍だ"], "answer": 3, "tr": "U ikki tilda gaplashuvchi (bilingual) shaxsdir.", "stem": "彼は【バイリンガル】だ。", "explanation_uz": "バイリンガル = 二カ国語を話す (ikki tilda so'zlasha oladigan)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilgan gapini tanlang.", "questions": [{"id": "t2-v6-28", "options": ["彼は酒を飲むとすぐに本性を反映する。", "隠していた事実がついに世間に反映されてしまった。", "客の希望を反映して、配達のサービスを始めた。", "黒のドレスは色白の女性の美しさを特に反映していた。"], "answer": 3, "tr": "反映 (はんえい) = aks ettirish, inobatga olish.", "stem": "反映", "optsTr": ["U ichgach o'z xarakterini 'aks ettiradi' (noto'g'ri — 現す).", "Yashiringan haqiqat omma orasida 'aks etdi' (noto'g'ri — 知れ渡った).", "Mijozlarning istaklarini inobatga olib (aks ettirib), yetkazib berish xizmatini yo'lga qo'ydik. (to'g'ri)", "Qora ko'ylak oqtanli ayol go'zalligini 'aks ettirdi' (noto'g'ri — 引き立てる)."]}, {"id": "t2-v6-29", "options": ["話がおもしろくてためいきが出た。", "苦手な上司の声を聞いただけで、ぞっとためいきが出る。", "息子のひどい成績に母は思わずためいきをついた。", "プールに入る前に、ためいきをしてください。"], "answer": 3, "tr": "ためいき (溜め息) = chuqur xo'rsinish, nafas chiqarish.", "stem": "ためいき", "optsTr": ["Gap qiziq bo'lgani uchun 'xo'rsindim' (noto'g'ri — 笑った).", "Yoqtirmaydigan boshliq ovozidan qo'rqib 'xo'rsindi' (noto'g'ri).", "O'g'lining yomon baholarini ko'rib ona beixtiyor chuqur xo'rsinib qo'ydi. (to'g'ri)", "Basseynga tushishdan oldin 'xo'rsinib oling' (noto'g'ri — 準備運動)."]}, {"id": "t2-v6-30", "options": ["動物には、人間にない特殊な能力を持つものが多い。", "夜中に特殊な物音がして目が覚めた。", "彼って特殊にもてるけど、どこがいいのかしらね。", "今日は特殊にあなただけにプレゼントをあげます。"], "answer": 1, "tr": "特殊 (とくしゅ) = o'ziga xos, maxsus, g'ayrioddiy.", "stem": "特殊", "optsTr": ["Hayvonlar orasida insonda bo'lmagan o'ziga xos (maxsus) qobiliyatga ega bo'lganlari ko'p. (to'g'ri)", "Tunda 'maxsus' tovush eshitilib uyg'ondim (noto'g'ri — 奇妙な).", "U 'maxsus' mashhur (noto'g'ri — やたら).", "Bugun 'maxsus' sovg'a beraman (noto'g'ri — 特別)."]}, {"id": "t2-v6-31", "options": ["授業は個々の生徒の能力に合った加速度で進める。", "もう少し加速度をつけないと時間に遅れてしまう。", "あの人とはなぜか話の加速度が合わない。", "地上を離れた飛行機は一気に加速度を増した。"], "answer": 4, "tr": "加速度 (かそくど) = tezlanish (akseleratsiya).", "stem": "加速度", "optsTr": ["Darsni har bir o'quvchi qobiliyatiga mos 'tezlanish' bilan o'tamiz (noto'g'ri — ペース/速度).", "Biroz 'tezlanish' qo'shmasak kech qolamiz (noto'g'ri — スピード).", "U bilan gapning 'tezlanishi' to'g'ri kelmaydi (noto'g'ri — テンポ).", "Yerdan ko'tarilgan samolyot birdaniga tezlanishini oshirdi. (to'g'ri)"]}, {"id": "t2-v6-32", "options": ["私は工場建設に賛成の彼とは矛盾する立場にある。", "2人は最初から最後まで矛盾ばかりだ。", "税金は安くして行政サービスはよくしろだなんて、矛盾している。", "やっぱり聞くことと見るのでは矛盾している。"], "answer": 3, "tr": "矛盾 (むじゅん) = qarama-qarshilik, zidlik (mantiqsizlik).", "stem": "矛盾", "optsTr": ["Men zavod qurilishini qo'llagan u kishi bilan 'zid' pozitsiyadaman (noto'g'ri — 対立).", "Ikkovi boshidan oxirigacha 'zid' (noto'g'ri — 口喧嘩).", "Soliqni arzon qilib, davlat xizmatlarini yaxshilang deyish — mantiqan qarama-qarshidir (ziddir). (to'g'ri)", "Eshitish bilan ko'rish 'zid' (noto'g'ri — 異なる)."]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t2-g1-33", "options": ["わけ", "こと", "もの", "どころ"], "answer": 1, "tr": "Puli yo'q degani emas-ku, ammo keraksiz narsani sotib olmaslikka qaror qilganman.", "stem": "お金がない（　）ではないが、必要ないものは買わないことにしている。", "explanation_uz": "〜わけではない = mutlaqo ... degani emas (qisman rad etish)"}, {"id": "t2-g1-34", "options": ["としたら", "としても", "とすると", "となれば"], "answer": 2, "tr": "Hozirdan juda shoshib borgan taqdirda ham, baribir darsga ulgura olmasak kerak.", "stem": "これから大急ぎで行った（　）、授業に間に合わないだろう。", "explanation_uz": "〜としても = garchi ... bo'lgan taqdirda ham"}, {"id": "t2-g1-35", "options": ["最中に", "直後に", "途端に", "瞬間に"], "answer": 1, "tr": "Do'stim bilan gurunglashib turgan ayni paytimda boshqa bir do'stimdan qo'ng'iroq bo'lib qoldi.", "stem": "友人とおしゃべりをしている（　）、別の友人から電話がかかってきた。", "explanation_uz": "〜最中に (さいちゅうに) = ayni ... qilib turgan fursatda"}, {"id": "t2-g1-36", "options": ["信じかねない", "信じるしかない", "信じがたい", "信じざるを得ない"], "answer": 3, "tr": "Bu kichkina surat 100 million iyen turadi deb ishonish juda qiyin-a!", "stem": "この小さな絵が1億円もするなんて、（　）ですね。", "explanation_uz": "〜がたい = qilish/tasavvur qilish juda mushkul, qiyin"}, {"id": "t2-g1-37", "options": ["に対して", "に応じて", "に当たって", "に反して"], "answer": 4, "tr": "Bunday qiyin kitob sotilmaydi degan taxminga zid ravishda, 100 ming nusxadan ziyod sotildi.", "stem": "こんな難しい本は売れないだろうという予想（　）、10万冊以上売れた。", "explanation_uz": "〜に反して (にはんして) = ...ga qarama-qarshi o'laroq, zid bo'lib"}, {"id": "t2-g1-38", "options": ["するものか", "するものか", "しないものだ", "しないものか"], "answer": 2, "tr": "Boshqa aslo xato qilmayman deb qat'iy o'ylagan edim, ammo yana qilib qo'ydim.", "stem": "もう二度と失敗は（　）と思ったのに、またやってしまった。", "explanation_uz": "〜ものか = aslo ...mayman (qat'iy inkor qarori)"}, {"id": "t2-g1-39", "options": ["もう", "こう", "そう", "どう"], "answer": 3, "tr": "A: «Ko'rishmaganimizga ancha bo'ldi-ya!»\nB: «Haqiqatan ham. Shu mavzu esga tushgan ekan, otangizning betobligi shundan so'ng qanday bo'ldi?»", "stem": "A「お久しぶりです。」\nB「本当に。（　）言えば、お父さまの病気はその後、いかがですか。」", "explanation_uz": "そう言えば = aytgancha, shu esimga tushdi"}, {"id": "t2-g1-40", "options": ["したい", "した", "しよう", "しない"], "answer": 3, "tr": "Men turmush quramanmi yoki qurmaymanmi — bu sizga aloqasi bo'lmagan ishdir.", "stem": "私が結婚（　）がしまいが、あなたには関係ないことだ。", "explanation_uz": "〜ようが〜まいが = qilsam ham, qilmasam ham (baribir)"}, {"id": "t2-g1-41", "options": ["飲みすぎない", "飲みかねない", "飲みやすい", "飲みにくい"], "answer": 4, "tr": "Bu dorining donasi juda katta bo'lgani uchun, yutish juda noqulay (qiyin).", "stem": "この薬の粒は大きすぎて、とても（　）。", "explanation_uz": "〜にくい = qilish/yutish qiyin, noqulay"}, {"id": "t2-g1-42", "options": ["指導するしかないよ", "指導するわけがないよ", "指導するどころではないよ", "指導するはずがないよ"], "answer": 1, "tr": "A: «Chekkan bilan hamma ham kasal bo'lavermaydi-ku.»\nB: «Shunday bo'lsa-da shifokor nazdida, chekishni tashlashni tavsiya qilishdan boshqa chora yo'q.»", "stem": "A「たばこを吸っても、必ず病気になるわけではないだろう。」\nB「それでも医者にすれば、禁煙を（　）。」", "explanation_uz": "〜しかない = ...dan boshqa iloj/chora yo'q"}, {"id": "t2-g1-43", "options": ["歩くようにしたものの", "歩くようにしたところ", "歩くようにしたものが", "歩くようにしたところで"], "answer": 2, "tr": "Kompaniyadan bir bekat oldin tushib piyoda yurishga odatlangan edim, 3 oyda vaznim ancha kamaydi.", "stem": "会社の一駅前で降りて（　）、3カ月で体重がかなり減った。", "explanation_uz": "〜たところ = ...qilgan edimki, natijada..."}, {"id": "t2-g1-44", "options": ["お見せいただけますか", "見られていただけますか", "見ていただけますか", "見せていただけますか"], "answer": 4, "tr": "Yig'ilishda qatnasha olmaganim sababli, materiallarni ko'rsatib bera olasizmi?", "stem": "会議に出席できなかったので、資料を（　）", "explanation_uz": "見せていただけますか = ko'rsatib bera olasizmi (xushmuomala so'rov: 〜ていただく)"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng to'g'ri bo'lakni tanlang.", "questions": [{"id": "t2-g2-45", "options": ["忘れてしまう", "忘れない", "ので", "そばから"], "answer": 3, "tr": "To'g'ri tartib: 難しい漢字は、習うそばから忘れてしまうので、忘れないうちにきちんと復習しよう。", "explanation_uz": "To'g'ri tartib: 習う[そばから][忘れてしまう][★ので][忘れない] (4 → 1 → 3 → 2)", "prefix": "難しい漢字は、習う", "suffix": "うちにきちんと復習しよう。", "starPos": 3, "order": [4, 1, 3, 2]}, {"id": "t2-g2-46", "options": ["でも", "では", "次第", "話し方"], "answer": 4, "tr": "To'g'ri tartib: 同じ言葉でも、話し方次第では印象が変わってしまうことがある。", "explanation_uz": "To'g'ri tartib: 同じ言葉[でも][★話し方][次第][では] (1 → 4 → 3 → 2)", "prefix": "同じ言葉", "suffix": "印象が変わってしまうことがある。", "starPos": 2, "order": [1, 4, 3, 2]}, {"id": "t2-g2-47", "options": ["最初の", "限って", "無料", "レッスンに"], "answer": 2, "tr": "To'g'ri tartib: この学校では、最初のレッスンに限って無料で受けることができます。", "explanation_uz": "To'g'ri tartib: [最初の][レッスンに][★限って][無料] (1 → 4 → 2 → 3)", "prefix": "この学校では、", "suffix": "で受けることができます。", "starPos": 3, "order": [1, 4, 2, 3]}, {"id": "t2-g2-48", "options": ["の", "わりには", "年齢", "ピアノ"], "answer": 1, "tr": "To'g'ri tartib: この子は年齢のわりにはピアノが上手だ。", "explanation_uz": "To'g'ri tartib: この子は[年齢][★の][わりには][ピアノ] (3 → 1 → 2 → 4)", "prefix": "この子は", "suffix": "が上手だ。", "starPos": 2, "order": [3, 1, 2, 4]}, {"id": "t2-g2-49", "options": ["取る", "成績から", "こんな成績を", "見ても"], "answer": 3, "tr": "To'g'ri tartib: あの学生の今までの成績から見ても、こんな成績を取るなんて信じられない。", "explanation_uz": "To'g'ri tartib: [成績から][見ても][★こんな成績を][取る] (2 → 4 → 3 → 1)", "prefix": "あの学生の今までの", "suffix": "なんて信じられない。", "starPos": 3, "order": [2, 4, 3, 1]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh joylariga eng to'g'ri variantni tanlang.", "passage_title": "寿司の歴史と工夫", "passage": "あなたは日本のすし屋のカウンターで、「お好み」ですしを食べたことがありますか。\nカウンターのケースの中を見ながら、好きな魚を選び、それを注文して、にぎってもらうので、いちばんおいしい状態で食べられます。ただ自分がどれくらい食べたか、金額が {{50}} 注意が必要です。\nこのとき、たとえば「マグロ」と注文すると、通常、マグロのすしが2つ出てきます。なぜそうなのか。江戸時代のおすしは大きかったので、2つに切って出したなごりとか、計算しやすくするためだとか、いろいろな説があります。結局、はっきりとはわからなくて、「昔からそうなっている」としか {{51}} 。\nところで、この場合、 {{52}} で行けば食べればいいけれど、1人で行って10個食べるとしたら、魚は5種類しか食べられません。ある回転ずし店で、1枚の皿に違う種類のすしを1つずつ2個、乗せ始めました。これなら、食べた寿司の数だけ {{53}} が食べられるので人気が出て、客が増えたそうです。考えたら単純なアイデアです。でも「昔からそうなっている」ことをちょっと変えてみる、そこにお客が増えるかぎがありました。\n私たちの身の回りにも、「ちょっと変えてみたらよくなる」ことがたくさんあるかもしれません。常識 {{54}} 、頭を柔らかくしておくことが大事なのです。", "passage_tr": "Siz Yaponiyadagi sushi restoranining bar peshtaxtasida «o'z xohishingiz bo'yicha» (okonomi) sushi yeb ko'rganmisiz?\nVitrindagi baliqlarni ko'rib turib, yoqtirganingizni tanlab buyurtma berasiz va yangi tayyorlab beriladi, shuning uchun eng mazali holatida yeya olasiz. Faqat qancha yeganingiz va pul miqdorini payqash qiyin bo'lgani sababli ehtiyotkorlik zarur.\nBu paytda, masalan «Maguro» deb buyurtma bersangiz, odatda 2 dona maguro sushisi keltiriladi. Nega unday? Edo davridagi sushi katta bo'lgani uchun ikkiga bo'lib berilganidan qolgan odat degan yoki hisob-kitobni osonlashtirish uchun degan turli qarashlar bor. Yakunda aniq ma'lum bo'lmay, «qadimdan shunday bo'lib kelgan» deb aytishdan boshqa chora yo'q.\nAytgancha, bunday vaziyatda 2 kishi bo'lib borsangiz yaxshi-ku, lekin 1 kishi borib 10 dona yesa, atigi 5 xil baliqni tatib ko'ra oladi, xolos. Bir aylanma sushi do'koni 1 ta likopchaga 2 xil sushidan bittadan qo'yib bera boshladi. Shunday qilinganda yegan sushi sonicha har xil sushilarni yeyish mumkinligi sababli juda ommalashdi. O'ylab ko'rsa oddiy g'oya. Biroq «qadimdan shunday bo'lgan» narsani biroz o'zgartirib ko'rish — mijozlarni jalb qilish siri shu yerda edi.\nBizning atrofimizda ham «biroz o'zgartirsa yaxshi bo'ladigan» jihatlar juda ko'p bo'lishi mumkin. Qotib qolgan tushunchalarga yopishib olmasdan, fikrlashni moslashuvchan tutish muhimdir.", "questions": [{"id": "t2-g3-50", "options": ["わかりやすいので", "わかってしまうので", "わかりづらいので", "わかりかねないので"], "answer": 3, "tr": "金額が[わかりづらいので]注意が必要です = hisob-kitob miqdorini bilish qiyin bo'lgani uchun.", "explanation_uz": "〜づらい = bilish/aniqlash mushkul", "blankNo": "50"}, {"id": "t2-g3-51", "options": ["言えるでしょう", "言いようがありません", "言いかねません", "言うまでもありません"], "answer": 2, "tr": "昔からそうなっているとしか[言いようがありません] = «qadimdan shunday» deb aytishdan boshqa so'z yo'q.", "explanation_uz": "〜ようがない = aytishning/qilishning hech bir yo'li yo'q", "blankNo": "51"}, {"id": "t2-g3-52", "options": ["a 1人 ／ b 1個ずつ ／ c 1人", "a 1人 ／ b 2個ずつ ／ c 2人", "a 2人 ／ b 1個ずつ ／ c 1人", "a 2人 ／ b 2個ずつ ／ c 1人"], "answer": 3, "tr": "2人で行けば1個ずつ食べればいいけれど、1人で行って... (2 kishi borsa 1 donadan yeydi).", "explanation_uz": "Tartib: 2人 (a) / 1個ずつ (b) / 1人 (c)", "blankNo": "52"}, {"id": "t2-g3-53", "options": ["同じすし", "たくさんのすし", "全部のすし", "いろいろなすし"], "answer": 4, "tr": "食べた寿司の数だけ[いろいろなすし]が食べられる = yeganicha har xil turlarini yeyish mumkin.", "explanation_uz": "Turli baliq turlarini tatib ko'rish haqida: いろいろなすし", "blankNo": "53"}, {"id": "t2-g3-54", "options": ["にとらわれないで", "をこわさないように", "にかかわらないで", "をぬきにして"], "answer": 1, "tr": "常識[にとらわれないで]、頭を柔らかくしておくことが大事 = qolipga yopishib qolmasdan.", "explanation_uz": "〜にとらわれる = biror tushunchaga bandi/cheklanib qolish (にとらわれないで = cheklanmasdan)", "blankNo": "54"}]}]}]}, "3": {"id": 3, "title_jp": "第3回 模擬テスト", "title_uz": "3-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t3-v1-1", "options": ["せんだく", "ぜんだく", "せんたく", "ぜんたく"], "answer": 3, "tr": "Ko'ngillilik (volontyorlik) faoliyatini tanlov fanlariga kiritayotgan universitetlar ko'paymoqda.", "stem": "ボランティア活動を【選択科目】に取り入れている大学が多くなっている。", "reading": "せんたく", "explanation_uz": "選択 → せんたく (tanlov) (選択科目 = tanlov fani)"}, {"id": "t3-v1-2", "options": ["ほうだい", "ちょうだい", "ばくだい", "じんだい"], "answer": 1, "tr": "Aeroport qurish uchun juda ulkan (behiseb) xarajat ketadi.", "stem": "飛行場を建設するには【膨大な】費用がかかる。", "reading": "ぼうだい", "explanation_uz": "膨大 → ぼうだい (ulkan, bepoyon, behad ko'p)"}, {"id": "t3-v1-3", "options": ["しょうだん", "じょだん", "じょうたん", "じょうだん"], "answer": 4, "tr": "Oddiy aytmoqchi bo'lgan hazilim do'stimning ko'nglini og'ritib qo'ydi.", "stem": "軽く言ったつもりの【冗談】が友人を傷つけてしまった。", "reading": "じょうだん", "explanation_uz": "冗談 → じょうだん (hazil, mutoyiba)"}, {"id": "t3-v1-4", "options": ["きそい", "うばい", "あらそい", "うかがい"], "answer": 2, "tr": "Shu tarzda aholi o'sishda davom etsa, butun dunyoda oziq-ovqat va suv talashuvi (tortishuvi) yuzaga kelishi mumkin.", "stem": "このまま人口が増え続ければ、世界中で食糧や水の【奪い合い】になるであろう。", "reading": "うばいあい", "explanation_uz": "奪う → うばう (tortib olmoq) (奪い合い = tortishuv, talashuv)"}, {"id": "t3-v1-5", "options": ["ぜいのう", "しょうのう", "すうのう", "せいのう"], "answer": 4, "tr": "So'nggi paytlarda jinoyatchilikdan himoyalanish xususiyati (samaradorligi) yuqori bo'lgan uylarni barpo etish rivojlanmoqda.", "stem": "最近は【防犯】性能が高いマンションや住宅を作るさまざまな取り組みが進んでいる。", "reading": "せいのう", "explanation_uz": "性能 → せいのう (ishchanlik qobiliyati, samaradorlik, unumdorlik)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t3-v2-6", "options": ["隠れた", "陰れた", "隆れた", "隔れた"], "answer": 1, "tr": "U murabbiy sportchilarning yashiringan (ichki) qobiliyatini yuzaga chiqarishda juda mohir.", "stem": "あのコーチは選手の【かくれた】能力を引き出すのがうまい。", "reading": "かくれた", "explanation_uz": "隠れる → かくれる (yashirinmoq, pinhon bo'lmoq)"}, {"id": "t3-v2-7", "options": ["計統", "形統", "系統", "経統"], "answer": 3, "tr": "Vulqon kuli elektr tizimiga (tarmoqqa) kirib borib, turli nosozliklarni keltirib chiqarishi mumkin.", "stem": "火山灰は電気けいとうに入り込み、さまざまな誤作動を起こすことがある。", "reading": "けいとう", "explanation_uz": "系統 → けいとう (tizim, tarmoq)"}, {"id": "t3-v2-8", "options": ["構想", "高層", "後送", "効相"], "answer": 2, "tr": "Bundan buyon shahar binolari tobora ko'p qavatli (baland qavatli) bo'lib borsa kerak.", "stem": "これから先、都市の建築物はますます【こうそう】化が進むであろう。", "reading": "こうそう", "explanation_uz": "高層 → こうそう (baland qavatli, osmono'par)"}, {"id": "t3-v2-9", "options": ["解倣", "解封", "解報", "解放"], "answer": 4, "tr": "Inson butun umr tashvishlardan aslo qutulolmasa (ozod bo'lolmasa) kerak deb o'ylayman.", "stem": "人間は一生悩むことから【かいほう】されないのだと思う。", "reading": "かいほう", "explanation_uz": "解放 → かいほう (ozod bo'lish, qutulish)"}, {"id": "t3-v2-10", "options": ["並べて", "比べて", "列べて", "対べて"], "answer": 2, "tr": "Sabzavot va mevalarning to'yimlilik darajasi ilgarigisi bilan solishtirganda pasayib bormoqda.", "stem": "野菜や果物の栄養価は昔のものと【くらべて】低くなっている。", "reading": "くらべて", "explanation_uz": "比べる → くらべる (solishtirmoq, taqqoslamoq)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t3-v3-11", "options": ["多", "複", "重", "諸"], "answer": 4, "tr": "Turli holatlar (sabablar) tufayli ushbu tadbir bekor qilinadi.", "stem": "（　）事情により今回のイベントは中止する。", "explanation_uz": "諸事情 (しょじじょう) = turli sabablar/sharoitlar"}, {"id": "t3-v3-12", "options": ["日", "泊", "行", "出"], "answer": 1, "tr": "Yakshanba kuni oilaviy bir kunlik (borib-kelinadigan) sayohatdan zavqlandik.", "stem": "日曜日は家族で（　）帰りの旅行を楽しんだ。", "explanation_uz": "日帰り (ひがえり) = bir kunlik sayohat (tunab qolmasdan qaytish)"}, {"id": "t3-v3-13", "options": ["末", "来", "数", "真"], "answer": 2, "tr": "Yo'l qurilishi kelasi (moliyaviy) yildan boshlanadi.", "stem": "道路工事は（　）年度から始まる。", "explanation_uz": "来年度 (らいねんど) = kelasi moliyaviy/o'quv yili"}, {"id": "t3-v3-14", "options": ["風", "式", "的", "性"], "answer": 3, "tr": "Eng zamonaviy uskunalar bilan jihozlangan zamonaviy bino qad ko'tardi.", "stem": "最新の機器を備えた近代（　）なビルが建設された。", "explanation_uz": "近代的 (きんだいてき) = zamonaviy uslubdagi"}, {"id": "t3-v3-15", "options": ["感", "性", "化", "風"], "answer": 2, "tr": "Doim aniq-tiniq savollar beradigan bu yigitda kelajak porloqligini (potensialni) his qilaman.", "stem": "的確な質問をよくしてくる彼には将来（　）を感じる。", "explanation_uz": "将来性 (しょうらいせい) = istiqbol, kelajak imkoniyatlari"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga ma'no jihatidan eng mos keladigan so'zni tanlang.", "questions": [{"id": "t3-v4-16", "options": ["せいぜい", "そろそろ", "ゆうゆう", "まあまあ"], "answer": 4, "tr": "Imtihon qanday o'tdimi? Juda zo'r bo'lmadi-yu, ammo o'rtacha (yomon emas) bo'ldi deb o'ylayman.", "stem": "試験の出来ですか。すごくよくはなかったけど（　）だったと思います。", "explanation_uz": "まあまあ = o'rtacha, durustgina, qoniqarli"}, {"id": "t3-v4-17", "options": ["例える", "比べる", "たたえる", "こたえる"], "answer": 1, "tr": "Uni hayvonga qiyoslasak (o'xshatsak), injiq fe'l-atvori mushukka o'xshaydi.", "stem": "彼女を動物に（　）と、気まぐれなところがネコっぽいね。", "explanation_uz": "例える (たとえる) = o'xshatmoq, qiyoslamoq"}, {"id": "t3-v4-18", "options": ["評判", "結論", "誤解", "決定"], "answer": 3, "tr": "Har narsani darrov amalga oshiradigan u kishini hovliqma odam deb noto'g'ri tushunishadi (adashishadi).", "stem": "なんでもすぐ行動に移す彼は、気が短い人間だと（　）されている。", "explanation_uz": "誤解 (ごかい) = noto'g'ri tushunish, yanglish xulosa"}, {"id": "t3-v4-19", "options": ["不利", "不幸", "地味", "粗末"], "answer": 4, "tr": "Ilgari zodagonlardan tashqari kambag'al insonlar kichik va abgor (oddiy/g'aribona) uylarda yashashgan.", "stem": "昔は貴族以外のまずしい人々は、小さくて（　）な家に住んでいた。", "explanation_uz": "粗末 (そまつ) = oddiy, g'aribona, abgor"}, {"id": "t3-v4-20", "options": ["オープン", "フレッシュ", "ダイレクト", "ショック"], "answer": 2, "tr": "Yangi ishga kirgan xodimlar yangicha, jo'shqin (fresh) jozibaga to'ladir.", "stem": "新入社員は、（　）な魅力にあふれている。", "explanation_uz": "フレッシュ (fresh) = yangi, jo'shqin, navqiron"}, {"id": "t3-v4-21", "options": ["持ち", "造り", "取り", "兼ね"], "answer": 4, "tr": "Bu sport poyabzali yurishga qulaylik va chiroyli dizaynni o'zida birgalikda mujassam etgan.", "stem": "この運動靴は歩きやすさとデザインのよさを（　）備えている。", "explanation_uz": "兼ね備える (かねそなえる) = o'zida ikkala xususiyatni ham jamlamoq"}, {"id": "t3-v4-22", "options": ["季節品", "必需品", "付属品", "消耗品"], "answer": 2, "tr": "Ushbu savdo ko'chasida hayot uchun zarur barcha kundalik ehtiyoj mollari topiladi.", "stem": "この商店街で生活（　）はすべてそろう。", "explanation_uz": "生活必需品 (せいかつひつじゅひん) = hayotiy zarur vositalar/tovarlar"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin sinonimni tanlang.", "questions": [{"id": "t3-v5-23", "options": ["考えなしに", "思いっきり", "絶えず", "大量に"], "answer": 1, "tr": "Opam keraksiz narsalargacha o'ylab-netmasdan (ketma-ket, pala-partish) sotib olaveradi.", "stem": "姉はいらないものまで【やたらに】買い込んでしまう。", "reading": "やたらに", "explanation_uz": "やたらに = 考えなしに (o'ylamasdan, duch kelganicha)"}, {"id": "t3-v5-24", "options": ["余裕", "夢", "油断", "特徴"], "answer": 3, "tr": "U aslo bo'shashmaydigan (g'ofillik qilmaydigan, ehtiyotkor) inson.", "stem": "彼女は【隙のない】人だ。", "reading": "すきのない", "explanation_uz": "隙のない = 油断がない (ehtiyotkor, hushyor)"}, {"id": "t3-v5-25", "options": ["容易に", "計画的に", "注意深く", "素早く"], "answer": 3, "tr": "Yangi qonun loyihasini ishlab chiqishni ehtiyotkorlik bilan (sinchiklab) olib bormoqda.", "stem": "新しい法案作りを【慎重に】進める。", "reading": "しんちょうに", "explanation_uz": "慎重に → 注意深く (diqqat va ehtiyotkorlik bilan)"}, {"id": "t3-v5-26", "options": ["質問された", "称賛された", "注目された", "非難された"], "answer": 4, "tr": "Avariya keltirib chiqargan kompaniya rahbari OAV tomonidan qattiq tanqid qilindi (qoralandi).", "stem": "事故を起こした会社の社長はマスコミに【叩かれた】。", "reading": "たたかれた", "explanation_uz": "叩く (たたく) = 非難された (tanqid qilinmoq, qoralanmoq)"}, {"id": "t3-v5-27", "options": ["新しい", "めずらしい", "高い", "すばらしい"], "answer": 2, "tr": "Bu gitara cheklangan miqdorda chiqarilgan noyob (kamyob) buyumdir.", "stem": "このギターは限定生産の【レアな】ものだ。", "explanation_uz": "レアな (rare) = めずらしい (noyob, kamyob)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilgan gapini tanlang.", "questions": [{"id": "t3-v6-28", "options": ["この祭りは自然の恩恵に浴する感謝を表している。", "お世話になった人に恩恵返しをする。", "この神社のお守りは恩恵があると評判だ。", "先生の恩恵で、無事卒業することができた。"], "answer": 1, "tr": "恩恵 (おんけい) = inoyat, ne'mat, foyda/naf.", "stem": "恩恵", "optsTr": ["Bu festival tabiat ne'matlaridan bahramand bo'lganlik minnatdorchiligini bildiradi. (to'g'ri)", "Qaragan odamga 'ne'mat qaytaraman' (noto'g'ri — 恩返し).", "Bu tumor 'ne'matli' (noto'g'ri — ご利益).", "Ustozning 'ne'mati' bilan bitirdim (noto'g'ri — おかげ)."]}, {"id": "t3-v6-29", "options": ["税金が上がって、素人の生活は苦しくなった。", "これはとても素人には作れない料理だ。", "どこの素人かわからない男に娘を嫁にやるわけにはいかない。", "彼女は素人だけあって、とても美しい。"], "answer": 2, "tr": "素人 (しろうと) = havaskor, nohaqiqiy mutaxassis.", "stem": "素人", "optsTr": ["Soliq oshib, 'havaskorlar' turmushi qiyinlashdi (noto'g'ri — 庶民).", "Bu taomni havaskor (oddiy odam) aslo tayyorlay olmaydi. (to'g'ri)", "Qaysi 'havaskor' ekani noma'lum yigitga qizimni bermayman (noto'g'ri — 馬の骨).", "U 'havaskor' bo'lgani uchun chiroyli (noto'g'ri)."]}, {"id": "t3-v6-30", "options": ["夫に家事を手伝ってもらったが、ちょっとだらしない。", "こんなつまらない仕事、だらしなくてやっていられない。", "そんなことで落ちこむなんて、だらしないやつだ。", "彼女はきちんと家計簿をつけていて、とてもお金にだらしない。"], "answer": 3, "tr": "だらしない = irodasiz, bo'sh, o'zini tutolmaydigan, betartib.", "stem": "だらしない", "optsTr": ["Erim yordam berdi, lekin 'irodasiz' (noto'g'ri).", "Bunday zerikarli ishda 'irodasiz bo'lib' ishlab bo'lmaydi (noto'g'ri — ばかばかしい).", "Shunaqa arzimagan narsaga tushkunlikka tushadigan bo'sh, irodasiz ekansan-a! (to'g'ri)", "U hisob-kitobni aniq yuritadi va pulga 'pala-partish' (noto'g'ri — ziddiyat)."]}, {"id": "t3-v6-31", "options": ["日本では、話すことより読む勉強に重点を置く学校がいまだ多い。", "この計画の成功の重点は君の活躍にかかっている。", "彼は長年財界の重点だった。", "あの作家の重点のある言葉が気に入っている。"], "answer": 1, "tr": "重点 (じゅうてん) = asosiy e'tibor, urg'u (重点を置く).", "stem": "重点", "optsTr": ["Yaponiyada gapirishdan ko'ra o'qishga ko'proq urg'u beradigan (e'tibor qaratadigan) maktablar hali ham ko'p. (to'g'ri)", "Muvaffaqiyatning 'asosiy e'tibori' senga bog'liq (noto'g'ri — 鍵).", "U moliyaviy sohaning 'urg'usi' edi (noto'g'ri — 重鎮).", "Yozuvchining 'urg'uli' so'zlari (noto'g'ri — 重み)."]}, {"id": "t3-v6-32", "options": ["このコース修了者には資格を支給する。", "客は店員に品物の代金を現金で支給した。", "海外旅行をするなら旅券の支給手続きをしてください。", "この会社は、給料のほかに家族手当が支給される。"], "answer": 4, "tr": "支給 (しきゅう) = to'lab berish, beriladigan nafaqa/to'lov.", "stem": "支給", "optsTr": ["Kursni bitirganlarga malaka 'to'lanadi' (noto'g'ri — 付与/授与).", "Mijoz tovarni naqd pulda 'to'lab berdi' (noto'g'ri — 支払う).", "Pasportni 'to'lash' arizasi (noto'g'ri — 発行).", "Bu kompaniyada oylikdan tashqari oilaviy nafaqa ham to'lab beriladi (beriladi). (to'g'ri)"]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t3-g1-33", "options": ["上から", "上で", "上に", "上は"], "answer": 4, "tr": "Bir marta ishni zimmangga olgan ekansan, nima bo'lsa ham oxiriga yetkazishing shart.", "stem": "いったん仕事を引き受けた（　）、何があっても完成させなければならない。", "explanation_uz": "〜上は (うえは) = ...ekansan / modomiki ... qilar ekansan (qatiy burch)"}, {"id": "t3-g1-34", "options": ["せいで", "くせに", "ものの", "おかげで"], "answer": 4, "tr": "Hamyonimni unutib qoldirgan bo'lsam-da, kredit kartam borligi sharofati bilan arang xarid qila oldim.", "stem": "財布を忘れたが、クレジットカードを持っていた（　）、何とか買い物ができた。", "explanation_uz": "〜おかげで = ...ning sharofati / yaxshiligi tufayli"}, {"id": "t3-g1-35", "options": ["のことから", "のことだから", "のこととはいえ", "のことにしては"], "answer": 2, "tr": "Xasis bo'lgan u kishini bilganimiz uchun, asl brilliant sotib olishi aslo mumkin emas.", "stem": "けちな彼女（　）、本物のダイヤモンドなんか買うはずがない。", "explanation_uz": "〜のことだから = ...ning fe'lini bilganimiz sababli"}, {"id": "t3-g1-36", "options": ["以前では", "次第では", "程度では", "事情では"], "answer": 2, "tr": "A kompaniyasi raqib bo'lsa-da, shartlarga qarab birlashish muzokaralarini olib borsa bo'ladi.", "stem": "A社はライバルだが、条件（　）は合併の交渉をしてもよい。", "explanation_uz": "〜次第では (しだいでは) = ...ga qarab, holatga bog'liq ravishda"}, {"id": "t3-g1-37", "options": ["に応じて", "に向かって", "に備えて", "に関して"], "answer": 3, "tr": "Katta zilzilaga tayyorgarlik ko'rib, xarita orqali uygacha qaytish yo'lini tekshirib qo'yaylik.", "stem": "大地震（　）、地図で家までの帰り道を確認しておこう。", "explanation_uz": "〜に備えて (にそなえて) = ...ga tayyorgarlik ko'rish maqsadida"}, {"id": "t3-g1-38", "options": ["だけでは", "ぬきには", "ほどには", "のみでは"], "answer": 2, "tr": "«Gilos gulladi» deb yangiliklarda aytiladigan darajada, Yaponiyaning bahorini sakurasiz tasavvur etib (gapirib) bo'lmaydi.", "stem": "「さくらが咲いた」とニュースになるくらい、日本の春はさくら（　）語れない。", "explanation_uz": "〜ぬきには = ...siz, ...bo'lmasa (amalga oshmaydi)"}, {"id": "t3-g1-39", "options": ["はずされておりますので", "はずしていらっしゃいますので", "はずしておりますので", "はずしてしまいますので"], "answer": 3, "tr": "A: «Allo, Yamashita prezident shu yerdamilar?»\nB: «Hozir joylarida yo'q edilar (席を外しております), qayta qo'ng'iroq qildiraman.»", "stem": "A「もしもし、山下社長はいらっしゃいますか。」\nB「ただいま、席を（　）、折り返しご連絡差し上げます。」", "explanation_uz": "席を外しております = joyida yo'q (kamtarin nutq / kenjougo)"}, {"id": "t3-g1-40", "options": ["間に合いそうもない", "間に合わないはずがない", "間に合うわけでもない", "間に合うほかない"], "answer": 1, "tr": "Shoshib maqola yozyapman, ammo bunday ketishda muddatiga aslo ulgura olmasam kerak.", "stem": "急いで論文を書いているが、このままでは締め切りには（　）。", "explanation_uz": "〜そうもない = ulgura oladiganga o'xshamaydi (ehtimoli juda kam)"}, {"id": "t3-g1-41", "options": ["知っていただけに", "知らなかっただけに", "知っていたばかりに", "知らなかったばかりに"], "answer": 4, "tr": "Men bu yerdagi qoidani bilmaganim oqibatidagina barchangizga tashvish tug'dirdim.", "stem": "私がここの決まりを（　）、みなさんにご迷惑をおかけしました。", "explanation_uz": "〜ばかりに = faqatgina ... tufayli (yomon natija keltirib chiqardi)"}, {"id": "t3-g1-42", "options": ["人がいるはずだ", "人はいないはずだ", "人がいるということだ", "人がいないということだ"], "answer": 2, "tr": "Agar siz og'iz ochmasangiz, bu ishni biladigan hech kim bo'lmasligi kerak.", "stem": "あなたがしゃべらない限り、このことを知っている（　）。", "explanation_uz": "〜はずだ = ...bo'lishi aniq/tabiiy (知っている人はいないはずだ)"}, {"id": "t3-g1-43", "options": ["おいしいはずで", "おいしいわけではなく", "おいしくないはずで", "おいしくないわけではなく"], "answer": 2, "tr": "Taom qancha yangi bo'lsa shuncha mazali bo'ladi degani emas, biroz saqlangani shirinroq bo'ladigan ozuqalar ham bor.", "stem": "食べ物は新鮮であればあるほど（　）、少し古いほうがおいしい食品もある。", "explanation_uz": "〜わけではなく = mutlaqo shunday degani emas"}, {"id": "t3-g1-44", "options": ["つぐわけではない", "つがないではいられない", "ついではならない", "つがざるを得ない"], "answer": 1, "tr": "Zamonaviy Yaponiyada to'ng'ich o'g'il bo'lgani bilan oila vorisligini olishi shart emas.", "stem": "現代の日本では、長男だからといって必ず家を（　）。", "explanation_uz": "〜わけではない = doim ham shart/shunday degani emas"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng to'g'ri bo'lakni tanlang.", "questions": [{"id": "t3-g2-45", "options": ["助けて", "しては", "いるなら", "私と"], "answer": 2, "tr": "To'g'ri tartib: あなたが困っているなら、私としては助けてあげたいのだが……。", "explanation_uz": "To'g'ri tartib: 困って[いるなら][私と][★しては][助けて] (3 → 4 → 2 → 1)", "prefix": "あなたが困って", "suffix": "あげたいのだが……。", "starPos": 2, "order": [3, 4, 2, 1]}, {"id": "t3-g2-46", "options": ["平気", "10円を", "一方で", "節約する"], "answer": 3, "tr": "To'g'ri tartib: 私の妻は10円を節約する一方で、平気で高い服を買うことがある。", "explanation_uz": "To'g'ri tartib: 妻は[10円を][節約する][★一方で][平気] (2 → 4 → 3 → 1)", "prefix": "私の妻は", "suffix": "で高い服を買うことがある。", "starPos": 3, "order": [2, 4, 3, 1]}, {"id": "t3-g2-47", "options": ["もちろん", "甘すぎないので", "女性は", "男性に"], "answer": 1, "tr": "To'g'ri tartib: この店のケーキは甘すぎないので女性はもちろん、男性にも人気がある。", "explanation_uz": "To'g'ri tartib: [甘すぎないので][女性は][★もちろん][男性に] (2 → 3 → 1 → 4)", "prefix": "この店のケーキは", "suffix": "も人気がある。", "starPos": 3, "order": [2, 3, 1, 4]}, {"id": "t3-g2-48", "options": ["こと", "また", "どこか", "だから"], "answer": 4, "tr": "To'g'ri tartib: 時間にだらしない山下さんのことだから、またどこかでさぼっているのだろう。", "explanation_uz": "To'g'ri tartib: 山下さんの[こと][★だから][また][どこか] (1 → 4 → 2 → 3)", "prefix": "時間にだらしない山下さんの", "suffix": "でさぼっているのだろう。", "starPos": 2, "order": [1, 4, 2, 3]}, {"id": "t3-g2-49", "options": ["流れに", "進むと", "沿って", "歩く"], "answer": 3, "tr": "To'g'ri tartib: 人の歩く流れに沿って進むと、その先にイベント会場があった。", "explanation_uz": "To'g'ri tartib: 人の[歩く][流れに][★沿って][進むと] (4 → 1 → 3 → 2)", "prefix": "人の", "suffix": "その先にイベント会場があった。", "starPos": 3, "order": [4, 1, 3, 2]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh joylariga eng to'g'ri variantni tanlang.", "passage_title": "父子家庭への支援", "passage": "妻と離婚、または死別して20歳以下の子どもを育てている男性の家庭を「父子家庭」と言います（これに対し、母親と児童の家庭を「母子家庭」と言います）。最近の20年、離婚の増加により父子家庭の数は過去最高になりました。\n母子家庭には、その収入 {{50}} 、児童扶養手当という子どもを育てるためのお金が支給され、ほかにもさまざまな制度があります。日本は「夫が外でお金を稼ぎ、妻が家庭で家事・育児をする」という考えが強かったので、 {{51-a}} は経済的に苦しい家が多かったためです。\n一方、「 {{51-b}} と比べて {{51-c}} には経済的な問題はないだろう」と思われていたので、児童扶養手当は支給されていませんでした。\nところが父子家庭の収入は、母子家庭ほど {{52}} 、平均に比べたらずいぶん低いことがわかりました。 {{53}} 、日本では男性は長い残業も休日出勤もやるのが当たり前で、「保育園に子どもを迎えに行くから、5時には帰らなければならない」という男性を雇ってくれる会社は、あまり多くないのです。すでに働いていても、正社員でなくアルバイトになったり、男性であっても、 {{54}} 。\nそして、厚生労働省は低収入の父子家庭にも児童扶養手当を支給することを決定しました。この制度は2010年の年末から施行されることになり、約10万所帯が給付の対象になります。", "passage_tr": "Xotini bilan ajrashgan yoki xotini vafot etib, 20 yoshdan kichik bolani tarbiyalayotgan erkakning oilasi «otasiz oila» (fusikatei) deb ataladi. So'nggi 20 yilda ajrimlar ko'payishi bilan bunday oilalar soni tarixdagi eng yuqori darajaga yetdi.\nOnalik oilalariga ularning daromadiga qarab bola tarbiyasi nafaqasi to'lanadi. Yaponiyada «er tashqarida pul topadi, ayol esa uyda ro'zg'or va bola tarbiyasi bilan shug'ullanadi» degan tushuncha kuchli bo'lgani sababli, onalik oilalari moddiy jihatdan qiynalgan oilalar ko'p bo'lgan.\nBoshqa tomondan esa «onali oilalarga nisbatan otali oilalarda iqtisodiy muammo bo'lmasa kerak» deb hisoblangani bois, bolalar nafaqasi berilmas edi.\nVaholanki otali oilalarning daromadi onalarnikidek past bo'lmasa ham, o'rtacha ko'rsatkichdan ancha pastligi ma'lum bo'ldi. Buning ustiga, Yaponiyada erkaklar uzoq vaqt qo'shimcha ishlashi va dam olish kunlari ham ishlashi tabiiy hol bo'lib, «bolani bog'chadan olishim kerak, soat 5 da ketishim shart» degan erkakni ishga oladigan kompaniyalar juda kam. Hatto ishlab turgan bo'lsa ham, doimiy emas, balki soatbay ishchiga aylanib qolishadi.\nShuning uchun Sog'liqni saqlash vazirligi kam ta'minlangan otali oilalarga ham bolalar nafaqasini to'lashga qaror qildi.", "questions": [{"id": "t3-g3-50", "options": ["に伴った", "に応じた", "に比べた", "に沿った"], "answer": 2, "tr": "その収入[に応じた]児童扶養手当 = o'sha daromadiga mos keladigan nafaqa.", "explanation_uz": "〜に応じた (におうじた) = ...ga mos, muvofiq", "blankNo": "50"}, {"id": "t3-g3-51", "options": ["a 父子家庭 ／ b 母子家庭 ／ c 母子家庭", "a 父子家庭 ／ b 父子家庭 ／ c 母子家庭", "a 母子家庭 ／ b 母子家庭 ／ c 父子家庭", "a 母子家庭 ／ b 父子家庭 ／ c 父子家庭"], "answer": 3, "tr": "a 母子家庭 (onali oila) qiynalgan; b 母子家庭 ga qaraganda c 父子家庭 da muammo yo'q deb o'ylangan.", "explanation_uz": "Tartib: a 母子家庭 / b 母子家庭 / c 父子家庭", "blankNo": "51"}, {"id": "t3-g3-52", "options": ["低いにしても", "低いわけがなく", "低くはないものの", "低いと思ったら"], "answer": 3, "tr": "母子家庭ほど[低くはないものの]、平均に比べたらずいぶん低い = unchalik past bo'lmasa-da, o'rtachadan ancha past.", "explanation_uz": "〜ものの = ...bo'lsa-da, qaramasdan", "blankNo": "52"}, {"id": "t3-g3-53", "options": ["というのも", "だからといって", "にもかかわらず", "とはいえ"], "answer": 1, "tr": "[というのも]、日本では男性は長い残業もやるのが当たり前で = Negaki, Yaponiyada...", "explanation_uz": "というのも = sababi shundaki, negaki", "blankNo": "53"}, {"id": "t3-g3-54", "options": ["高収入になりかねません", "高収入にならざるを得ません", "低収入になり得ないのです", "低収入になり得るのです"], "answer": 4, "tr": "男性であっても、[低収入になり得るのです] = Erkak kishi bo'lsa ham kam daromadli bo'lib qolishi mumkin.", "explanation_uz": "〜得る (うる) = bo'lishi mumkin, ehtimoli bor", "blankNo": "54"}]}]}]}, "4": {"id": 4, "title_jp": "第4回 模擬テスト", "title_uz": "4-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t4-v1-1", "options": ["いわゆる", "あらゆる", "いたる", "とおる"], "answer": 3, "tr": "Robotlar fabrikalarda-ku mayli, Xalqaro kosmik stansiyagacha — har bir yerda (hamma joyda) qo'llanilmoqda.", "stem": "ロボットは、工場はもちろん国際宇宙ステーションまで、【至る所】で使われている。", "reading": "いたる", "explanation_uz": "至る所 → いたるところ (hamma joyda, har burchakda)"}, {"id": "t4-v1-2", "options": ["わりひき", "わりびき", "かつひき", "かつびき"], "answer": 2, "tr": "10 kun oldin band qilsangiz, erta chegirma (skidka) bilan mehmonxona narxi arzonlashadi.", "stem": "10日前までに予約をすると、早期【割引】で宿泊料金が安くなる。", "reading": "わりびき", "explanation_uz": "割引 → わりびき (chegirma, skidka)"}, {"id": "t4-v1-3", "options": ["はっそう", "はつそう", "ほっそう", "はつぞう"], "answer": 1, "tr": "Stol atrofida o'tirgandan ko'ra, sayr qilayotganda ish bo'yicha yangi g'oyalar quyilib kelishi ko'proq uchraydi.", "stem": "机に向かっているときより、散歩中に仕事の【発想】がわいてくることが多い。", "reading": "はっそう", "explanation_uz": "発想 → はっそう (g'oya, fikr uyg'onishi)"}, {"id": "t4-v1-4", "options": ["かんがく", "かんかく", "がんかく", "がんがく"], "answer": 2, "tr": "Pul qadrini his qilmaydigan (isrofgar) otam tufayli onam uzoq vaqt qiynalib yashagan.", "stem": "金銭感覚のなかった父に、母はずっと苦労させられていた。", "reading": "かんかく", "explanation_uz": "感覚 → かんかく (hissiyot, sezgi)"}, {"id": "t4-v1-5", "options": ["じんじゅう", "しんじゅう", "じんちょう", "しんちょう"], "answer": 4, "tr": "Nikoh inson umrining muhim voqeasi bo'lgani sababli, ehtiyotkorlik (vazminlik) bilan o'yla.", "stem": "結婚は人生の一大事だから【慎重】に考えなさい。", "reading": "しんちょう", "explanation_uz": "慎重 → しんちょう (ehtiyotkor, vazmin, puxta)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t4-v2-6", "options": ["吸集", "究収", "吸収", "急就"], "answer": 3, "tr": "U bola xuddi gubka (sponj) kabi o'rgatilgan barcha narsani o'ziga singdirib (yutib) oladi.", "stem": "あの子はまるでスポンジのように教えたことはすべて【きゅうしゅう】する。", "reading": "きゅうしゅう", "explanation_uz": "吸収 → きゅうしゅう (singdirish, shimib olish)"}, {"id": "t4-v2-7", "options": ["滞存", "滞在", "帯存", "帯在"], "answer": 2, "tr": "U olim ushbu orolda uzoq muddat yashab (turib), o'simliklarni tadqiq qilmoqda.", "stem": "あの学者は、この島に長期【たいざい】して、植物の研究をしている。", "reading": "たいざい", "explanation_uz": "滞在 → たいざい (vaqtincha istiqomat qilish, turish)"}, {"id": "t4-v2-8", "options": ["因む", "図む", "回む", "囲む"], "answer": 4, "tr": "Oila a'zolari birgalikda dasturxon atrofida jamlanishi (o'tirishi) kamayib ketdi.", "stem": "家族みんなで食卓を【かこむ】ことが少なくなってしまった。", "reading": "かこむ", "explanation_uz": "囲む → かこむ (o'rab olmoq, atrofida o'tirmoq)"}, {"id": "t4-v2-9", "options": ["安意", "安易", "案意", "案易"], "answer": 2, "tr": "Qizim reklamadagi fikrlarga osongina (yengil-yelpi) ishonib, qimmatbaho qo'shimchalarni sotib olaveradi.", "stem": "娘はチラシの体験談を【あんい】に信じて高いサプリメントをよく買っている。", "reading": "あんい", "explanation_uz": "安易 → あんい (yengil-yelpi, osongina)"}, {"id": "t4-v2-10", "options": ["嗅ぎ", "咲ぎ", "喝ぎ", "喫ぎ"], "answer": 1, "tr": "Xizmat iti yuk mashinasi ichidagi portlovchi moddani hidlab topdi.", "stem": "警察犬はトラックの中の爆発物を【かぎ】あてた。", "reading": "かぎ", "explanation_uz": "嗅ぐ → かぐ (hidlamoq, hid bilmoq)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t4-v3-11", "options": ["無", "不", "非", "反"], "answer": 3, "tr": "Tunning yarmida baland ovozda baqirib shovqin solish — beodoblikdir (aqlsizlikdir).", "stem": "夜中に大声で騒ぐなんて（　）常識だ。", "explanation_uz": "非常識 (ひじょうしき) = odobsizlik, madaniyatsizlik"}, {"id": "t4-v3-12", "options": ["悪", "非", "無", "不"], "answer": 4, "tr": "Bo'lim boshlig'i kun bo'yi xomush (kayfiyatsiz) yurdi.", "stem": "部長は1日中（　）機嫌だった。", "explanation_uz": "不機嫌 (ふきげん) = kayfiyatsiz, jahldor holat"}, {"id": "t4-v3-13", "options": ["化", "出", "下", "現"], "answer": 1, "tr": "Ikki kishining fikr qarama-qarshiligi yuzaga chiqadi (oshkor bo'ladi).", "stem": "2人の意見の対立が表面（　）する。", "explanation_uz": "表面化 (ひょうめんか) = oshkoralashish, yuzaga chiqish"}, {"id": "t4-v3-14", "options": ["性", "量", "率", "比"], "answer": 3, "tr": "Bu galgi saylovda qatnashish foizi (davomat ko'rsatkichi) yuqori bo'ldi.", "stem": "今回の選挙の投票（　）は高かった。", "explanation_uz": "投票率 (とうひょうりつ) = saylovda qatnashish foizi / davomat ko'rsatkichi"}, {"id": "t4-v3-15", "options": ["和", "家", "新", "手"], "answer": 4, "tr": "O'z qo'lim bilan tayyorlagan taomni do'stimga mehmon qilib tortiq qilaman.", "stem": "（　）料理を友人にふるまう。", "explanation_uz": "手料理 (てりょうり) = o'z qo'li bilan tayyorlagan taom"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga ma'no jihatidan eng mos keladigan so'zni tanlang.", "questions": [{"id": "t4-v4-16", "options": ["展開", "事情", "事態", "体制"], "answer": 2, "tr": "Tabiiy gazdan foydalanish butun dunyodagi energiya holatini (vaziyatini) o'zgartirsa kerak.", "stem": "天然ガスの利用は世界のエネルギー（　）を変えるであろう。", "explanation_uz": "エネルギー事情 (エネルギーじじょう) = energetika vaziyati/holati"}, {"id": "t4-v4-17", "options": ["フィット", "セット", "マット", "カット"], "answer": 1, "tr": "Qaddi-qomati kichik onam tanasiga mos tushadigan (fit bo'ladigan) kiyim topishga doim qiynaladi.", "stem": "小柄な母は体に（　）する服を探すのにいつも苦労している。", "explanation_uz": "フィットする (fit) = mos tushmoq, loyiq kelmoq"}, {"id": "t4-v4-18", "options": ["耕して", "稼いで", "整って", "扱って"], "answer": 4, "tr": "Ekin ekish tirik jon bilan muomala qilish (parvarishlash) bo'lgani sababli, suv quyishni kelasi haftaga qoldirib bo'lmaydi.", "stem": "畑作りは生きている命を（　）いるので、今週は忙しいから、水やりは来週というわけにはいかない。", "explanation_uz": "扱う (あつかう) = muomala qilmoq, parvarishlamoq"}, {"id": "t4-v4-19", "options": ["あくまでも", "おそらく", "いわゆる", "ほとんど"], "answer": 1, "tr": "Bu faqatgina (qat'iy qilib aytganda) mening shaxsiy fikrim, xolos. Boshqalar boshqacha fikrda bo'lsa kerak.", "stem": "これは（　）私の意見にすぎません。他の人はたぶん違う意見だと思います。", "explanation_uz": "あくまでも = faqatgina, mutlaqo (あくまでも〜にすぎない)"}, {"id": "t4-v4-20", "options": ["援助", "失敗", "文句", "遠慮"], "answer": 4, "tr": "Fikringiz bo'lsa, hech qanday tortinishsiz (uyalmasdan) menga aytavering.", "stem": "意見があれば何でも（　）なく私に言ってください。", "explanation_uz": "遠慮なく (えんりょなく) = tortinmasdan, bemalol"}, {"id": "t4-v4-21", "options": ["ちからづよく", "そそっかしく", "ずうずうしく", "くだらなく"], "answer": 3, "tr": "Uzun navbatning o'rtasiga bir ayol surbetlarcha (uyalmasdan) suqilib kirdi.", "stem": "長い行列の真ん中に、1人の女性が（　）割り込んできた。", "explanation_uz": "ずうずうしく = surbetlarcha, yuzsizlarcha"}, {"id": "t4-v4-22", "options": ["改良", "補助", "改正", "統制"], "answer": 3, "tr": "Qonun qayta ko'rib chiqilib (o'zgartirilib), soyabon ushlagan holda velosiped haydash taqiqlandi.", "stem": "法律が（　）され、傘を差したまま自転車に乗るのは禁止された。", "explanation_uz": "改正 (かいせい) = qonun yoki qoidani o'zgartirish/tuzatish"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin sinonimni tanlang.", "questions": [{"id": "t4-v5-23", "options": ["とても困る", "予定が狂う", "頭に来る", "不安だ"], "answer": 1, "tr": "Oylik olish oldidan to'satdan chiqqan xarajat juda qiyin (juda noqulay, ziyonli).", "stem": "給料前の急な出費は【痛い】。", "reading": "いたい", "explanation_uz": "痛い = とても困る (juda qiyin, noqulay, og'ir botadi)"}, {"id": "t4-v5-24", "options": ["続いて", "影響して", "戻って", "ひどくて"], "answer": 2, "tr": "Bahor boshidagi sovuq havo ta'sir qilib, sabzavotlar narxi ko'tarildi.", "stem": "春先の低温が【響き】、野菜の値段が高くなった。", "reading": "ひびき", "explanation_uz": "響く → 影響して (ta'sir qilmoq, oqibat keltirmoq)"}, {"id": "t4-v5-25", "options": ["毎回", "お互いに", "各自", "常に"], "answer": 3, "tr": "O'z yukingizga har bir kishi o'zi (alohida-alohida) hushyor bo'lsin.", "stem": "自分の荷物は【めいめいで】気をつけてください。", "reading": "めいめいで", "explanation_uz": "めいめいで = 各自 (かくじ — har bir kishi o'zi alohida)"}, {"id": "t4-v5-26", "options": ["障害", "仕事", "苦労", "心配"], "answer": 1, "tr": "Ayollarning jamiyatda faol bo'lishida bola parvarishi kabi katta to'siq (g'ov) mavjud.", "stem": "女性の社会進出には子育てという大きな【壁】がある。", "reading": "かべ", "explanation_uz": "壁 = 障害 (しょうがい — to'siq, g'ov)"}, {"id": "t4-v5-27", "options": ["週末", "昼休み", "祝日", "休みの日"], "answer": 4, "tr": "Dam olish kunlarini (off) asosan televizor ko'rib o'tkazaman.", "stem": "オフは【もっぱら】テレビを見て過ごす。", "explanation_uz": "オフ = 休みの日 (dam olish kuni)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilgan gapini tanlang.", "questions": [{"id": "t4-v6-28", "options": ["私どもの協会は何よりも自由と平等を演説しております。", "選挙中、声を限りに候補者の名前を演説した。", "新しい首相は、政策について国会で演説した。", "あの男は義務も果たさずに権利ばかり演説する。"], "answer": 3, "tr": "演説 (えんぜつ) = nutq so'zlash (siyosiy, ommaviy nutq).", "stem": "演説", "optsTr": ["Assotsiatsiyamiz ozodlikni 'nutq so'zlaydi' (noto'g'ri — 主張).", "Saylovda nomzod ismini 'nutq so'zladi' (noto'g'ri — 連呼).", "Yangi bosh vazir siyosiy rejalari haqida parlamentda nutq so'zladi. (to'g'ri)", "U majburiyatni bajarmay, faqat huquqlarni 'nutq so'zlaydi' (noto'g'ri)."]}, {"id": "t4-v6-29", "options": ["あなたの生まれは何月何日ですか。", "彼のあのがんこさは生まれのものでどうにもならない。", "乳歯から永久歯の生まれは10歳ぐらいに起きる。", "彼女は生まれがよいのか、どこか品がある。"], "answer": 4, "tr": "生まれ (うまれ) = nasl-nasab, kelib chiqish muhiti.", "stem": "生まれ", "optsTr": ["Tug'ilgan kuningiz qachon (noto'g'ri — 生年月日).", "Uning o'jarligi tug'ma (noto'g'ri — 生まれつき).", "Sut tishidan doimiy tishga almashish (noto'g'ri — 生え変わり).", "Uning nasl-nasabi (kelib chiqishi) yaxshi bo'lgani sabablimi, o'zida bir olijanoblik bor. (to'g'ri)"]}, {"id": "t4-v6-30", "options": ["最近子どもの様子が少し危うい。", "近所を危うい男がうろうろしている。", "この道路は夜とても暗いので、1人で歩くのは危うい。", "おぼれかけたが、危ういところで助けられた。"], "answer": 4, "tr": "危うい (あやうい) = xatarli, qilt ustida qolgan (危ういところで = arang/zo'rg'a).", "stem": "危うい", "optsTr": ["Bolaning ahvoli 'qilt ustida' (noto'g'ri — 怪しい).", "Mahallada 'shubhali' odam aylanib yuribdi (noto'g'ri — 怪しい).", "Kechasi qorong'i bo'lib yurish 'xavfli' (noto'g'ri — 危険/危ない).", "Cho'kib ketayozgandim, qilt ustida (arang, bir bahya qolganda) qutqarib qolishdi. (to'g'ri)"]}, {"id": "t4-v6-31", "options": ["彼のゴルフの腕前はまさに実物だ。", "この会社は名前だけで実物がない。", "写真では見ていたが、実物の美しさは想像以上だった。", "もし実物のダイヤなら、すごい値段のはずだ。"], "answer": 3, "tr": "実物 (じつぶつ) = asil nusxa, ko'z bilan ko'riladigan haqiqiy buyum.", "stem": "実物", "optsTr": ["Golf mahorati haqiqiy (noto'g'ri — 本物).", "Kompaniyaning mohiyati yo'q (noto'g'ri — 実質).", "Suratda ko'rgan edim, lekin haqiqiy buyumning o'zidagi go'zallik tasavvurimdan a'lo ekan. (to'g'ri)", "Asl brilliant (noto'g'ri — 本物)."]}, {"id": "t4-v6-32", "options": ["雨でもバザーは予測通りに行います。", "気象庁が予測した通り、今年の夏は異常に暑い。", "彼の競馬の予測は当たったためしがない。", "予測せぬ事態が起こり、会場は大混乱になった。"], "answer": 2, "tr": "予測 (よそく) = ilmiy yoki ma'lumotlarga asoslangan bashorat/taxmin.", "stem": "予測", "optsTr": ["Reja bo'yicha (noto'g'ri — 予定).", "Gidrometeorologiya markazi oldindan bashorat qilganidek, bu yil yoz g'ayritabiiy issiq bo'lmoqda. (to'g'ri)", "Ot poygasi taxmini (noto'g'ri — 予想).", "Kutilmagan vaziyat (noto'g'ri — 予期せぬ/予期しない)."]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t4-g1-33", "options": ["に反して", "に関して", "に応じて", "にしたがって"], "answer": 4, "tr": "Iqtisodiyot yomonlashib borgan sari, gazetadagi reklamalar ham kamayib boradi.", "stem": "景気が悪くなる（　）、新聞の広告が減ってくる。", "explanation_uz": "〜にしたがって = ...gan sari (bir narsa o'zgarishi bilan boshqasi ham o'zgarishi)"}, {"id": "t4-g1-34", "options": ["わりに", "かわりに", "ついでに", "ゆえに"], "answer": 1, "tr": "Bu restoran arzonligiga qaramasdan (arzonligiga yarasha) juda mazali bo'lgani sababli, doim mijozlarga to'la.", "stem": "このレストランは安い（　）おいしいので、いつも客でいっぱいだ。", "explanation_uz": "〜わりに (わりには) = ...ga qaramasdan, kutilganidan boshqacha"}, {"id": "t4-g1-35", "options": ["かぎり", "ばかり", "だけ", "きり"], "answer": 2, "tr": "Iye, Sato yana kelmadimi? Yaqindagina dam olgan edi-ku!", "stem": "え、佐藤さんはまた休みなの。こないだ休んだ（　）なのに。", "explanation_uz": "〜たばかり = yaqindagina ... bo'lgan"}, {"id": "t4-g1-36", "options": ["理由だ", "状態だ", "一方だ", "限界だ"], "answer": 3, "tr": "Oylik oshmayotgan bir paytda bola universitetga kirdi, turmush esa tobora qiyinlashib bormoqda.", "stem": "給料が上がらないのに子どもが大学に入り、生活が苦しくなる（　）。", "explanation_uz": "〜一方だ (いっぽうだ) = tobora faqat bir tomonga (yomon tomonga) qarab o'zgarmoqda"}, {"id": "t4-g1-37", "options": ["がち", "向き", "気味", "げ"], "answer": 3, "tr": "Bugun biroz shamollash alomati (shamollashdek holat) sezilgani uchun, vanna qilmay uxlayman.", "stem": "今日はかぜ（　）だから、おふろには入らないで寝ます。", "explanation_uz": "〜気味 (ぎみ) = biroz alomati bor, moyillik"}, {"id": "t4-g1-38", "options": ["とかいえば", "ともいえ", "とさえいえ", "とはいえ"], "answer": 4, "tr": "Garchi qonunni bilmagan bo'lsangiz ham, qoidani buzsangiz jinoyat hisoblanadi.", "stem": "たとえ法律を知らなかった（　）、決まりをやぶったら罪になる。", "explanation_uz": "〜とはいえ = garchi ... bo'lsa ham"}, {"id": "t4-g1-39", "options": ["いこうでは", "いかずには", "いっては", "いくわけで"], "answer": 1, "tr": "Kelinglar, bundan buyon barchamiz kuchimizni birlashtirib birgalikda harakat qilaylik!", "stem": "これから皆で力を合わせて、がんばって（　）ないか！", "explanation_uz": "〜（よう）ではないか = kelinglar, shunday qilaylik! (chaqiriq/targ'ib)"}, {"id": "t4-g1-40", "options": ["うかがってよろしいですか", "うかがっていただけますか", "申してよろしいですか", "申していただけますか"], "answer": 1, "tr": "A: «Allo, Sugiyama janoblari bormilar?»\nB: «Uzr, ismingizni so'rasam (bilsam) maylimi?»", "stem": "A「もしもし、杉山さんはいらっしゃいますか。」\nB「あの、お名前を（　）。」", "explanation_uz": "お名前をうかがってよろしいですか = ismingizni so'rasam maylimi (xushmuomala so'rov)"}, {"id": "t4-g1-41", "options": ["というわけではない", "といったところだ", "というわけだ", "といったようだ"], "answer": 1, "tr": "Harakat qilgan bilan albatta muvaffaqiyatga erishiladi degani emas, ammo qo'ldan kelgancha urinib ko'ramiz.", "stem": "がんばっても必ず成功する（　）が、やるだけはやろう。", "explanation_uz": "〜というわけではない = mutlaqo ... degani emas"}, {"id": "t4-g1-42", "options": ["出発するとすると", "出発したとすると", "出発するとしても", "出発したとしても"], "answer": 2, "tr": "Agar Kimura vaqtida uydan chiqqan deb hisoblasak, allaqachon yetib kelishi kerak edi, ammo hali ham yo'q.", "stem": "木村君が時間通りに家を（　）、もう着いているはずなのに、まだ来ていない。", "explanation_uz": "〜たとすると = agar ... deb faraz qilsak"}, {"id": "t4-g1-43", "options": ["やらざるを得ない", "やるわけにはいかない", "やるべきではない", "やらないかもしれない"], "answer": 1, "tr": "«O'zim qilaman» deb aytgan ekanman, o'zim qilmasdan boshqa ilojim yo'q.", "stem": "「私がやります」と言ったからには、私が（　）。", "explanation_uz": "〜からには〜ざるを得ない = aytgan ekansan, qilmaslikning iloji yo'q"}, {"id": "t4-g1-44", "options": ["してやったほうが", "させてやったほうが", "してあったほうが", "させてあったほうが"], "answer": 2, "tr": "Yosh xodimlarga mas'uliyatli ishni topshirib ko'rsak, o'zida ham ishtiyoq paydo bo'lmasmikin?", "stem": "若い社員に責任のある仕事を（　）、本人もやる気になるのではないか。", "explanation_uz": "〜させてやったほうが = qildirib ko'rgan ma'qulroq"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng to'g'ri bo'lakni tanlang.", "questions": [{"id": "t4-g2-45", "options": ["子どもを", "必死に守るのに", "でさえ", "人間が"], "answer": 2, "tr": "To'g'ri tartib: 動物でさえ子どもを必死に守るのに、人間が子どもを捨てるなんて許せない。", "explanation_uz": "To'g'ri tartib: 動物[でさえ][子どもを][★必死に守るのに][人間が] (3 → 1 → 2 → 4)", "prefix": "動物", "suffix": "子どもを捨てるなんて許せない。", "starPos": 2, "order": [3, 1, 2, 4]}, {"id": "t4-v2-46", "options": ["かねる", "ことが", "理解", "し"], "answer": 1, "tr": "To'g'ri tartib: 今の若者の考えは理解しかねることが多すぎる。", "explanation_uz": "To'g'ri tartib: [理解][し][★かねる][ことが] (3 → 4 → 1 → 2)", "prefix": "今の若者の考えは", "suffix": "多すぎる。", "starPos": 3, "order": [3, 4, 1, 2]}, {"id": "t4-g2-47", "options": ["行く", "まったく", "行く", "町の様子"], "answer": 1, "tr": "To'g'ri tartib: 私が東京に行くたびに、まったく町の様子が変わっている気がする。", "explanation_uz": "To'g'ri tartib: 東京に[行く][たびに][★まったく][町の様子] (3 → 1 → 2 → 4)", "prefix": "私が東京に", "suffix": "が変わっている気がする。", "starPos": 2, "order": [3, 1, 2, 4]}, {"id": "t4-g2-48", "options": ["結果を", "お知らせ", "反した", "ご期待に"], "answer": 3, "tr": "To'g'ri tartib: 残念ながら、みなさんのご期待に反した結果をお知らせしなければなりません。", "explanation_uz": "To'g'ri tartib: みなさんの[ご期待に][★反した][結果を][お知らせ] (4 → 3 → 1 → 2)", "prefix": "残念ながら、みなさんの", "suffix": "しなければなりません。", "starPos": 2, "order": [4, 3, 1, 2]}, {"id": "t4-g2-49", "options": ["あり", "中止", "によっては", "ということ"], "answer": 4, "tr": "To'g'ri tartib: B「いや、天気によっては中止ということもあり得るよ。」", "explanation_uz": "To'g'ri tartib: 天気[によっては][中止][★ということ][も][あり] (3 → 2 → 4 → 1)", "prefix": "B「いや、天気", "suffix": "得るよ。」", "starPos": 3, "order": [3, 2, 4, 1]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh joylariga eng to'g'ri variantni tanlang.", "passage_title": "地震速報の仕組み", "passage": "地震のない国から日本に来た人が驚くことの1つに、テレビやラジオの緊急地震速報があります。番組の途中で突然チャイムが鳴り、「〇〇地方で地震です」とアナウンスが流れます。ふつう放送から大きな揺れが来るまで数秒くらいですが、その間に火を消したりテーブルにもぐったりできます。\nその後、すぐに震源はどこか、津波の心配があるかどうかも放送されます。\nこれは1995年の阪神・淡路大震災を契機に地震計が日本各地に置かれ始め、そのデータをもとに地震の情報を少しでも早く {{50}} 、研究が始まったものです。2007年から一般人向けに放送されるようになりました。世界でも初めてのシステムです。\nでも、なぜ揺れを感じるか {{51}} 地震や津波が来るとわかるのでしょうか。\n地震が起きると、P波と呼ばれる小さな揺れと、S波と呼ばれる大きな揺れが同時に発生します。P波は毎秒7km、S波は毎秒4kmで進みます。\n先に {{52-a}} が来たときに、どのくらい後に {{52-b}} が来るか予測して、緊急地震速報が発表されるのです。いくつかの地点のP波とS波の時間差を見ると、震源がどこかもわかります。\n海底にもたくさん地震計が置かれ、地震波を観測するとデータを衛星に送ります。地震波は海の波より100倍速く着くので、津波が来るかどうか {{53}} 。\n2004年のスマトラ島沖地震であったら、多くの人の命が助かったことでしょう。今や津波は「tsunami」と、世界でそのまま通じる言葉になりました。津波情報も国境を越えて発信する必要があります。\n緊急地震速報もまだまだ不完全ですが、地震の多い日本 {{54}} の発明と言えるでしょう。", "passage_tr": "Zilzila bo'lmaydigan mamlakatlardan Yaponiyaga kelgan kishilar hayron bo'ladigan jihatlardan biri — bu tele va radio orqali beriladigan favqulodda zilzila tezkor xabarlaridir. Ko'rsatuv davomida to'satdan signal chalinib, «falon mintaqada zilzila» degan e'lon yangraydi. Odatda efirdan katta silkinish yetib kelgunicha bir necha soniya bo'ladi, lekin shu vaqt ichida olovni o'chirish yoki stol tagiga yashirinishga ulgurish mumkin.\nShundan so'ng darhol epitsentr qayerdaligi va sunami xavfi bor-yo'qligi ham ma'lum qilinadi.\nBu 1995-yildagi Buyuk Xanshin zilzilasi sabab bo'lib, Yaponiya bo'ylab seysmometrlar o'rnatila boshlangach, ushbu ma'lumotlar orqali zilzila xabarini ozgina bo'lsa ham tezroq yetkazish uchun ilmiy izlanishlar boshlanishi bilan yaratilgan. 2007-yildan xalqqa e'lon qilina boshlandi. Bu dunyodagi ilk tizimdir.\nLekin nega silkinishni his etishdan oldinoq zilzila va sunami kelishini bilish mumkin?\nZilzila yuz berganda P-to'lqin deb ataluvchi kichik to'lqin va S-to'lqin deb ataluvchi kuchli to'lqin bir paytda yuzaga keladi. P-to'lqin soniyasiga 7 km, S-to'lqin esa soniyasiga 4 km tezlikda harakatlanadi.\nAvval P-to'lqin yetib kelganda, qancha vaqtdan keyin S-to'lqin yetib kelishi hisoblab chiqilib, tezkor xabar e'lon qilinadi.\nDengiz tubiga ham ko'plab seysmometrlar joylashtirilgan. Seysmik to'lqin dengiz to'lqinidan 100 baravar tez harakatlangani bois, sunami kelish-kelmasligini oldindan hisoblash mumkin bo'ladi.\nFavqulodda zilzila xabari hali mukammal bo'lmasa-da, zilzilalarga boy Yaponiyaga xos bo'lgan ajoyib ixtiro deyish mumkin.", "questions": [{"id": "t4-g3-50", "options": ["伝えまいと", "伝えようと", "伝えないと", "伝えるなら"], "answer": 2, "tr": "少しでも早く[伝えようと]、研究が始まった = ozgina bo'lsa ham tezroq yetkazaylik deb izlanishlar boshlangan.", "explanation_uz": "〜ようと = ...qilish niyati/maqsadi bilan", "blankNo": "50"}, {"id": "t4-g3-51", "options": ["感じないかのうちに", "感じないままに", "感じてからでないと", "感じたとたんに"], "answer": 1, "tr": "なぜ揺れを[感じないかのうちに]わかるのでしょうか = nega silkinishni hali his qilar-qilmas bilish mumkin?", "explanation_uz": "〜ないかのうちに = ...qilar-qilmas, birdaniga", "blankNo": "51"}, {"id": "t4-g3-52", "options": ["a P波 ／ b P波", "a S波 ／ b S波", "a S波 ／ b P波", "a P波 ／ b S波"], "answer": 4, "tr": "先に[a P波]が来たときに、どのくらい後に[b S波]が来るか予測して (Avval P-to'lqin, keyin S-to'lqin).", "explanation_uz": "Oldin kichik P-to'lqin (a), ortidan katta S-to'lqin (b)", "blankNo": "52"}, {"id": "t4-g3-53", "options": ["計算し得ません", "計算しかねません", "計算し得ます", "計算しかねます"], "answer": 3, "tr": "津波が来るかどうか[計算し得ます] = kelish-kelmasligini oldindan hisoblab chiqish imkoniyati bor.", "explanation_uz": "〜得る (うる/える) = amalga oshira oladi, imkoni bor", "blankNo": "53"}, {"id": "t4-g3-54", "options": ["といったら", "とあって", "だからこそ", "だからといって"], "answer": 3, "tr": "地震の多い日本[だからこそ]の発明と言えるでしょう = zilzilasi ko'p bo'lgan Yaponiyaga aynan xos bo'lgan ixtiro.", "explanation_uz": "〜だからこそ = aynan ... bo'lgani sababliki", "blankNo": "54"}]}]}]}, "5": {"id": 5, "title_jp": "第5回 模擬テスト", "title_uz": "5-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t5-v1-1", "options": ["へんごう", "へんか", "へんこう", "へんかん"], "answer": 3, "tr": "Ota-onamning moliyaviy ahvoli tufayli, kasb-hunar kollejiga borish yo'nalishini o'zgartirdim.", "stem": "親の経済事情で、専門学校へ進路を【変更】した。", "reading": "へんこう", "explanation_uz": "変更 → へんこう (o'zgartirish, boshqasiga almashtirish)"}, {"id": "t5-v1-2", "options": ["からんだ", "ふくらんだ", "にらんだ", "はらんだ"], "answer": 2, "tr": "Ushbu sport turida Olimpiadada ilk medalni qo'lga kiritishga bo'lgan umid yanada oshdi (kengaydi).", "stem": "この種目ではオリンピック初となるメダルへの期待が【膨らんだ】。", "reading": "ふくらんだ", "explanation_uz": "膨らむ → ふくらむ (kengaymoq, shishmoq, oshmoq)"}, {"id": "t5-v1-3", "options": ["きろん", "しょろん", "がいろん", "じろん"], "answer": 3, "tr": "Talabalar orasida mashhurlik qozonayotgani «Iqtisodiyotga kirish / umumiy asoslari» kursidir.", "stem": "学生に人気があるのは「経済学【概論】」の講座だ。", "reading": "がいろん", "explanation_uz": "概論 → がいろん (kirish kursi, umumiy asoslar)"}, {"id": "t5-v1-4", "options": ["とうじょう", "ちょうじょう", "こうじょう", "ていじょう"], "answer": 2, "tr": "Mening toqqa chiqishdan maqsadim cho'qqiga chiqish emas, balki tabiatdan xotirjam zavqlanishdir.", "stem": "私の登山の目的は【頂上】に立つことではなく、大自然をゆっくり楽しむことにある。", "reading": "ちょうじょう", "explanation_uz": "頂上 → ちょうじょう (cho'qqi, eng baland nuqta)"}, {"id": "t5-v1-5", "options": ["すいじゅん", "すいじゅん", "すいしゅん", "ずいしゅん"], "answer": 2, "tr": "Tokio hukumati tibbiyot darajasini oshirishga qaratilgan yangi tizimni e'lon qildi.", "stem": "東京都は医療【水準】の向上を目指す新制度を発表した。", "reading": "すいじゅん", "explanation_uz": "水準 → すいじゅん (daraja, saviya)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t5-v2-6", "options": ["苦痛", "苦適", "具痛", "悲痛"], "answer": 1, "tr": "Zaif mavqedagi insonga ruhiy va jismoniy azob (og'riq) yetkazish vakolatni suiiste'mol qilish (power harassment) deyiladi.", "stem": "弱い立場の人に精神的、身体的【くつう】を与えることをパワーハラスメントという。", "reading": "くつう", "explanation_uz": "苦痛 → くつう (azob, og'riq)"}, {"id": "t5-v2-7", "options": ["冷えて", "寒えて", "凍えて", "涼えて"], "answer": 3, "tr": "Bugun ertalab qo'llar uvishib (muzlab), biror narsani ushlab bo'lmaydigan darajada sovuq edi.", "stem": "今朝は手が【こごえて】、物がうまくつかめないほど寒かった。", "reading": "こごえて", "explanation_uz": "凍える → こごえる (muzlamoq, uvishmoq)"}, {"id": "t5-v2-8", "options": ["挟って", "握って", "担って", "捕って"], "answer": 2, "tr": "Raqib jamoaning zaif tomonini qo'lga kiritib olganimiz (ushlab olganimiz) sababli, o'yinni o'zimizga qulay olib bordik.", "stem": "相手チームの弱点を【にぎって】いたので、試合を有利に進めることができた。", "reading": "にぎって", "explanation_uz": "握る → にぎる (siqimlab ushlamoq, qo'lda tutmoq)"}, {"id": "t5-v2-9", "options": ["理外", "理害", "利外", "利害"], "answer": 4, "tr": "Hamkor kompaniya bilan o'zaro manfaatlar mos kelib, shartnoma masalasi hal bo'ldi.", "stem": "取引先と【りがい】が一致して、契約の話がまとまった。", "reading": "りがい", "explanation_uz": "利害 → りがい (foyda va ziyon, manfaat)"}, {"id": "t5-v2-10", "options": ["克服", "告服", "降服", "攻服"], "answer": 1, "tr": "Og'ir mashg'ulotlarni ketma-ket bajarib, nihoyat o'z kamchiligimni yengib o'tishga (bartaraf etishga) muvaffaq bo'ldim.", "stem": "厳しいトレーニングを積み重ねて、やっと自分の欠点を【こくふく】することができた。", "reading": "こくふく", "explanation_uz": "克服 → こくふく (yengib o'tish, mag'lub etish)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t5-v3-11", "options": ["力", "重", "諸", "全"], "answer": 1, "tr": "Bu yumush jismoniy og'ir ish (kuch talab qiladigan ish) bo'lmagani uchun, keksalar uchun mos keladi.", "stem": "この作業は（　）仕事ではないので、お年寄りに向いている。", "explanation_uz": "力仕事 (ちからしごと) = og'ir jismoniy mehnat"}, {"id": "t5-v3-12", "options": ["中", "下", "外", "内"], "answer": 4, "tr": "O'tirish qandaydir qilib har bir kishiga 3000 iyen byudjet doirasida (ichida) yakunlandi.", "stem": "飲み会はなんとか1人3000円の予算（　）におさまった。", "explanation_uz": "予算内 (よさんない) = byudjet doirasida/ichida"}, {"id": "t5-v3-13", "options": ["家", "者", "人", "民"], "answer": 2, "tr": "U shahardagi nufuzli (ta'sir doirasi katta) shaxsdir.", "stem": "彼は町の有力（　）だ。", "explanation_uz": "有力者 (ゆうりょくしゃ) = nufuzli, obro'li shaxs"}, {"id": "t5-v3-14", "options": ["単", "各", "唯", "一"], "answer": 4, "tr": "Bu faqat bir shaxs (oddiy inson) sifatidagi shaxsiy fikrimdir.", "stem": "これは（　）個人としての意見です。", "explanation_uz": "一見 / 一個人 (いっこじん) = alohida bir shaxs, oddiy inson"}, {"id": "t5-v3-15", "options": ["感", "考", "観", "想"], "answer": 3, "tr": "Betob bo'lib chiqqanimdan beri hayotga bo'lgan qarashim (dunyoqarashim) butunlay o'zgardi.", "stem": "病気をして以来、人生（　）が変わった。", "explanation_uz": "人生観 (じんせいかん) = hayotga bo'lgan qarash, dunyoqarash"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga ma'no jihatidan eng mos keladigan so'zni tanlang.", "questions": [{"id": "t5-v4-16", "options": ["大事", "優先", "貴重", "重要"], "answer": 4, "tr": "Sharq tabobati butun vujudni ko'tarib turuvchi oyoqlarni alohida muhim (ahamiyatli) deb biladi.", "stem": "東洋医学は、全身を支える足を特に（　）視する。", "explanation_uz": "重要視する (じゅうようしする) = juda muhim deb hisoblamoq"}, {"id": "t5-v4-17", "options": ["増大", "急増", "増減", "激増"], "answer": 1, "tr": "Konditsioner chiqarib tashlayotgan issiqlik tashqaridagi havoni yanada qizdirib (kuchaytirib) yubormoqda.", "stem": "エアコンが吐き出す熱が、外の暑さをさらに（　）させている。", "explanation_uz": "増大 (ぞうだい) = kuchayish, ortish, ko'payish"}, {"id": "t5-v4-18", "options": ["あちこち", "まあまあ", "いちいち", "それぞれ"], "answer": 3, "tr": "Endi yosh bola emassan, har bitta mayda-chuyda narsani aytilmasa ham o'zing hal qilgin.", "stem": "もう子どもではないんだから、（　）言われなくても自分で決めなさいよ。", "explanation_uz": "いちいち = birma-bir, har bir mayda narsagacha"}, {"id": "t5-v4-19", "options": ["パート", "パーソナル", "パターン", "パッケージ"], "answer": 4, "tr": "Ushbu tovar sotilmasligining bir sababi uning qadoqlanish (package) dizayni o'ta oddiyligidir deb o'ylayman.", "stem": "この商品が売れない原因の1つは商品の（　）のデザインが平凡すぎるからだと思う。", "explanation_uz": "パッケージ (package) = qadoq, qadoqlash"}, {"id": "t5-v4-20", "options": ["面倒", "世話", "加減", "手数"], "answer": 1, "tr": "Ishdagi muammo bo'lsa, xodimlarga yaxshi qaraydigan (g'amxo'r) rahbarga maslahat solgan ma'qul.", "stem": "仕事の悩みなら（　）見のよい職場の上司に相談するのがいちばんだと思う。", "explanation_uz": "面倒見のよい (めんどうみのよい) = g'amxo'r, yaxshi qaraydigan"}, {"id": "t5-v4-21", "options": ["かしこい", "ふさわしい", "おめでたい", "したい"], "answer": 3, "tr": "Doktorlik unvonini oldi, to'yi ham belgilandi — uning uchun faqat quvonchli (muborak) ishlar davom etmoqda.", "stem": "博士号は取るし、結婚も決まったし、彼にとって（　）ことが続いている。", "explanation_uz": "おめでたい = quvonchli, tabriklashga arziydigan"}, {"id": "t5-v4-22", "options": ["包む", "含む", "帯びる", "握る"], "answer": 2, "tr": "Biroz toliqqandek bo'lsangiz, tarkibida C vitamini ko'p bo'lgan (o'z ichiga olgan) ozuqalarni iste'mol qilgan ma'qul.", "stem": "疲れ気味かなと思ったら、ビタミンCを多く（　）食品をとるといい。", "explanation_uz": "含む (ふくむ) = o'z ichiga olmoq, tarkibida bo'lmoq"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin sinonimni tanlang.", "questions": [{"id": "t5-v5-23", "options": ["延期になった", "中止になった", "見直された", "変更になった"], "answer": 2, "tr": "Sayr (hiking) yomg'ir sababli bekor qilindi (amalga oshmadi).", "stem": "ハイキングは雨で【流れた】。", "reading": "ながれた", "explanation_uz": "流れる → 中止になった (bekor bo'lmoq, qolib ketmoq)"}, {"id": "t5-v5-24", "options": ["すっかり", "ぼんやり", "くっきり", "いきなり"], "answer": 4, "tr": "Osmon to'satdan qorayib, yirik tomchili yomg'ir yog'a boshladi.", "stem": "空が【にわかに】暗くなり、大粒の雨が降り出した。", "reading": "にわかに", "explanation_uz": "にわかに = いきなり (to'satdan, birdaniga)"}, {"id": "t5-v5-25", "options": ["冷静な", "鋭い", "確かな", "温かい"], "answer": 1, "tr": "U doim atrof-olamga vazmin (hissiyotga berilmasdan, sovuqqon) nigoh bilan qaraydi.", "stem": "彼女はいつも【覚めた】目で世間を見ている。", "reading": "さめた", "explanation_uz": "覚めた目 = 冷静な (vazmin, bosiq, mulohazali)"}, {"id": "t5-v5-26", "options": ["むりやり", "こっそり", "しきりに", "わざわざ"], "answer": 1, "tr": "Do'stim meni majburlab (zo'rlab) bazmga sudrab olib bordi.", "stem": "友人に【強引に】パーティーに連れて行かれた。", "reading": "ごういんに", "explanation_uz": "強引に = むりやり (majburlab, zo'ravonlik bilan)"}, {"id": "t5-v5-27", "options": ["理解して", "評価して", "応援して", "仕上げて"], "answer": 3, "tr": "Katta hamkasbim mening ishimni qo'llab-quvvatlab (yordam berib) turadi.", "stem": "先輩は私の仕事を【サポート】してくれる。", "explanation_uz": "サポートする = 応援して (yordam bermoq, suyamoq)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilgan gapini tanlang.", "questions": [{"id": "t5-v6-28", "options": ["通勤時間を圧縮するため引っ越しをする。", "景気が悪いので、社員数を圧縮しなければならない。", "袋にふとんを入れて空気を抜くと、薄く圧縮できる。", "スカート丈を3センチ圧縮したら、イメージが変わった。"], "answer": 3, "tr": "圧縮 (あっしゅく) = siqish, hajmini kichraytirish (havosini chiqarib qisish).", "stem": "圧縮", "optsTr": ["Yo'l vaqtini qisqartirish (noto'g'ri — 短縮).", "Xodimlar sonini qisqartirish (noto'g'ri — 削減).", "Xaltaga ko'rpani solib havosini so'rib olinsa, yupqa qilib siqib (presslab) qo'yish mumkin. (to'g'ri)", "Yubkani kaltalatish (noto'g'ri — 詰める)."]}, {"id": "t5-v6-29", "options": ["このお菓子の名前はぼろがいい。", "彼女、上品ぶっているけれど、そのうちぼろを出すよ。", "去年買った服のデザインがぼろになって着られない。", "彼は他人のぼろばかり探すいやな男だ。"], "answer": 2, "tr": "ぼろ = yashiringan kamchilik, nuqson (ぼろを出す = sirini/kamchiligini fosh qilib qo'ymoq).", "stem": "ぼろ", "optsTr": ["Shirinlikning nomi yaxshi (noto'g'ri — ごろ).", "U o'zini olijanob ko'rsatmoqda, ammo tez orada asl qiyofasini (kamchiligini) fosh qilib qo'yadi. (to'g'ri)", "Kiyim dizayni eskirib (noto'g'ri — 流行遅れ).", "Odamlarning kamchiligini qidiradi (noto'g'ri — あら)."]}, {"id": "t5-v6-30", "options": ["これはたいへん上等なお品でございます。", "あの子は病気の母親の世話をして上等だ。", "上等な考えを持っている若者もたくさんいる。", "彼女は1人で5人の子どもを育てた上等な女性だ。"], "answer": 1, "tr": "上等 (じょうとう) = yuqori sifatli, a'lo darajali (buyum/mahsulot haqida).", "stem": "上等", "optsTr": ["Bu juda yuqori sifatli (a'lo darajadagi) buyumdir. (to'g'ri)", "Onasiga qarab 'a'lo' (noto'g'ri — えらい/感心).", "Ajoyib fikrga ega (noto'g'ri — 立派な).", "Ulug' ayol (noto'g'ri — 立派な)."]}, {"id": "t5-v6-31", "options": ["今日の練習の規律はいつもより忙しい。", "彼はまるで軍隊のように規律正しい生活をしている。", "社長の大胆な規律で会社は危機を脱した。", "受験資格を経験者だけに規律する。"], "answer": 2, "tr": "規律 (きりつ) = intizom, tartib-qoida (規律正しい = intizomli).", "stem": "規律", "optsTr": ["Mashg'ulot jadvali (noto'g'ri — スケジュール).", "U xuddi armiyadagidek qat'iy intizomli hayot kechiradi. (to'g'ri)", "Prezidentning qat'iy qarori (noto'g'ri — 決断).", "Tajribalilarga cheklash (noto'g'ri — 限定)."]}, {"id": "t5-v6-32", "options": ["こんな結果になるなんて空想もつきませんでした。", "子どものころからスターになる空想を見続けている。", "将来の生活の空想を立ててください。", "彼女は「もし大金持ちと結婚したら」とか、空想ばかりしている。"], "answer": 4, "tr": "空想 (くうそう) = xayol surish, fantaziya (asossiz xayollar).", "stem": "空想", "optsTr": ["Bunday bo'lishini o'ylamovdim (noto'g'ri — 予想).", "Yulduz bo'lish orzusini ko'rmoqda (noto'g'ri — 夢).", "Reja tuzing (noto'g'ri — 計画).", "U doim «agar boy odamga tegsam» kabi asossiz xayollarni suraveradi. (to'g'ri)"]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t5-g1-33", "options": ["ながらも", "かわりに", "とはいえ", "上に"], "answer": 4, "tr": "Mening xonam keng bo'lishi ustiga-ustak, yangi va juda shinamdir.", "stem": "私の部屋は広い（　）、新しくて気持ちがよい。", "explanation_uz": "〜上に (うえに) = ...ning ustiga-ustak, bundan tashqari"}, {"id": "t5-g1-34", "options": ["に続いて", "にかけて", "に渡って", "に及んで"], "answer": 2, "tr": "Ertadan dam olish kunlarigacha butun mamlakat bo'ylab yaxshi ob-havo davom etsa kerak.", "stem": "明日から週末（　）、全国的によい天気が続くでしょう。", "explanation_uz": "〜から〜にかけて = ...dan ...gacha bo'lgan davrda"}, {"id": "t5-g1-35", "options": ["いうこと", "いう人", "いうもの", "いうわけ"], "answer": 3, "tr": "Yomonligini bilaturib ham ba'zida gunoh qiladi. Inson tabiati degani o'zi shunaqa-da.", "stem": "悪いとわかっていても、時には罪をおかす。それが人間と（　）だ。", "explanation_uz": "〜というものだ = ...tabiati shundaydir (inson tabiati)"}, {"id": "t5-g1-36", "options": ["ならない", "なれない", "なるまい", "なりきれない"], "answer": 1, "tr": "Atigi bir raqam farqi bilan lotereyada yutqazib qo'yish — shunchalik alam qiladiki, chidab bo'lmaydi.", "stem": "たった1番違いで宝くじに外れるなんて、くやしくて（　）。", "explanation_uz": "〜てならない = juda ham, his-tuyg'uni jilovlab bo'lmaydi"}, {"id": "t5-g1-37", "options": ["なんとか", "なんでも", "なににとぞ", "なにしろ"], "answer": 4, "tr": "A: «Rangingiz o'chiq-ku.»\nB: «Nima bo'lganda ham juda band bo'lib, dam olishga fursat yo'q-da.»", "stem": "A「顔色が悪いですね。」\nB「（　）忙しくて、休むひまがないんです。」", "explanation_uz": "なにしろ = nima bo'lganda ham, qanday bo'lmasin"}, {"id": "t5-g1-38", "options": ["病気みたい", "病気がち", "病気っぽい", "病気ぎみ"], "answer": 2, "tr": "Bolaligimda tez-tez kasal bo'lib turar edim, ammo butunlay baquvvat bo'lib ketdim.", "stem": "子どものときは（　）でしたが、すっかり丈夫になりました。", "explanation_uz": "〜がち = tez-tez ... bo'ladigan (moyil bo'lgan)"}, {"id": "t5-g1-39", "options": ["食べるうちに", "食べたうちに", "食べもしないで", "食べるそばから"], "answer": 1, "tr": "Boshida yoqtirmagan yapon taomlarini ham asta-sekin yeyaverish asnosida yoqtirib qoldim.", "stem": "最初は嫌いだった日本食も、少しずつ（　）好きになってきた。", "explanation_uz": "〜うちに = ...qilib yuraverish davomida (o'zgarish sodir bo'lishi)"}, {"id": "t5-g1-40", "options": ["おっしゃってください", "申されてください", "言われていただけますか", "申していただけますか"], "answer": 1, "tr": "Xitoy tilini yaxshi bilaman. Tarjimon kerak bo'lsa xohlagan paytda aytavering.", "stem": "中国語は得意です。通訳が必要ならいつでも（　）。", "explanation_uz": "おっしゃってください = ayting, buyuring (xushmuomala so'rov: 言う ning sonkeigo shakli)"}, {"id": "t5-g1-41", "options": ["長生きをしたいものだ", "長生きはするものだ", "長生きをしたくないものだ", "長生きはしないものだ"], "answer": 3, "tr": "U doim «to'shakka mixlanib qolguncha uzoq yashashni aslo xohlamasdim» deydi-yu, lekin ozgina betob bo'lsa shov-shuv ko'taradi.", "stem": "彼はよく「寝たきりになってまで（　）」と言うが、病気になると大騒ぎする。", "explanation_uz": "〜たくないものだ = aslo ... bo'lishni xohlamasdim"}, {"id": "t5-g1-42", "options": ["とてもうまくなった", "あまりうまくならなかった", "きっ とうまくなるだろう", "うまくなるべきだ"], "answer": 2, "tr": "Bolaligimdan beri pianino o'rganib kelgan bo'lsam-da, unchalik yaxshi o'rganib keta olmadim.", "stem": "子どものときからずっとピアノを習ってはきたものの、（　）。", "explanation_uz": "〜ものの = ...gan bo'lsa-da (kutilgan natija bo'lmadi)"}, {"id": "t5-g1-43", "options": ["まずいわけではない", "まずくないわけでもない", "まずいわけがない", "まずくないわけにもいかない"], "answer": 3, "tr": "Eng sara masalliqlardan eng yetuk oshpaz tayyorlagan ekan, bemaza bo'lishi aslo mumkin emas!", "stem": "最高の材料で最高のシェフが作ったのだから、（　）。", "explanation_uz": "〜わけがない = aslo ... bo'lishi mumkin emas"}, {"id": "t5-g1-44", "options": ["することにはならない", "することにはならない", "したことにはなる", "したことになる"], "answer": 1, "tr": "Talabalar festivali haqida shunchaki fikr aytib, o'zing hech narsa qilmasang, qatnashgan hisoblanmaysan.", "stem": "学園祭について、ただ意見を言うだけで何もしなければ、参加（　）。", "explanation_uz": "〜ことにはならない = ...qilgan deb hisoblab bo'lmaydi"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng to'g'ri bo'lakni tanlang.", "questions": [{"id": "t5-g2-45", "options": ["発音", "だけ", "アメリカ育ち", "あって"], "answer": 4, "tr": "To'g'ri tartib: 彼女の英語はアメリカ育ちだけあって発音はきれいだが、文法は正しくない。", "explanation_uz": "To'g'ri tartib: [アメリカ育ち][だけ][★あって][発音] (3 → 2 → 4 → 1)", "prefix": "彼女の英語は", "suffix": "はきれいだが、文法は正しくない。", "starPos": 3, "order": [3, 2, 4, 1]}, {"id": "t5-g2-46", "options": ["とき", "あやまらざる", "お客様に", "を得ない"], "answer": 2, "tr": "To'g'ri tartib: 私のミスではないのにお客様にあやまらざるを得ないときも、たまにはあります。", "explanation_uz": "To'g'ri tartib: [お客様に][★あやまらざる][を得ない][とき] (3 → 2 → 4 → 1)", "prefix": "私のミスではないのに", "suffix": "も、たまにはあります。", "starPos": 2, "order": [3, 2, 4, 1]}, {"id": "t5-g2-47", "options": ["しても", "建てる", "と", "ずっと"], "answer": 3, "tr": "To'g'ri tartib: もし私が家を建てるとしたら、ずっと町の中心から遠いところだ。", "explanation_uz": "To'g'ri tartib: [建てる][★と][しても][ずっと] (2 → 3 → 1 → 4)", "prefix": "もし私が家を", "suffix": "町の中心から遠いところだ。", "starPos": 2, "order": [2, 3, 1, 4]}, {"id": "t5-g2-48", "options": ["限り", "雨の日", "来ない", "台風でも"], "answer": 1, "tr": "To'g'ri tartib: 優勝したマラソン選手は台風でも来ない限り、雨の日も練習を休むことはないそうだ。", "explanation_uz": "To'g'ri tartib: [台風でも][来ない][★限り][雨の日] (4 → 3 → 1 → 2)", "prefix": "優勝したマラソン選手は", "suffix": "も練習を休むことはないそうだ。", "starPos": 3, "order": [4, 3, 1, 2]}, {"id": "t5-g2-49", "options": ["収穫量は", "次第", "秋の", "夏の天気"], "answer": 4, "tr": "To'g'ri tartib: 米や果物の秋の収穫量は夏の天気次第です。", "explanation_uz": "To'g'ri tartib: [秋の][収穫量は][★夏の天気][次第] (3 → 1 → 4 → 2)", "prefix": "米や果物の", "suffix": "です。", "starPos": 3, "order": [3, 1, 4, 2]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh joylariga eng to'g'ri variantni tanlang.", "passage_title": "緑のカーテン", "passage": "最近の日本の夏の暑さには異常な {{50}} 。\n以前は体に悪いと言われたエアコンも、今では使わないと命が {{51}} 。しかしエアコンをつけると熱い空気が外に吹き出て外の空気が温まり、日が落ちても地面の温度が下がらず、夜も暑いままです。エアコンを使うことが、夏をますます {{52}} とも言えます。\n最近街を歩いていて、窓の外やベランダ一面にひもがつるされたり棒が立てられていて、下に植えた植物の葉が茂っているのを見かけませんか。あれを「緑のカーテン」と言います。\n人間が暑いと汗をかくように、植物も暑くなると根から水を吸い、葉の表面が汗をかいたようにぬれます。 {{53-a}} 葉の間を空気が通ると、 {{53-b}} 葉の間を通るよりたくさんの熱を奪います。そのために空気の温度が下がります。\nエアコンのない小学校で「緑のカーテン」を作ったところ、今まで暑くて勉強できなかった窓際の生徒たちも、落ち着いて勉強できるようになりました。\n電気代もかからないし、外の地面をあたためることもありません。緑色は勉強で疲れた目を休めるし、実のなる植物なら実を給食に使うこともあるそうです。電気代の節約 {{54}} 、見た目にも美しく食べることもできると、よいことばかりです。\n市役所が住民に「ぜひ緑のカーテンを作ってください」と呼びかけているところもあります。地球温暖化を食い止めるためにも、広がってほしいものです。", "passage_tr": "So'nggi paytlarda Yaponiyada yozning issiqligi g'ayritabiiy darajada deb aytish mumkin.\nIlgari salomatlikka yomon deb qaralgan konditsioner ham hozir ishlatilmasa hayot xavf ostida qoladigan darajada. Ammo konditsionerni yoqqanda issiq havo tashqariga haydalib, ko'chadagi havo isiydi, quyosh botsa ham yer soviymay, kechalari ham issiqligicha qoladi. Konditsioner ishlatish yozni yanada issiqroq qilmoqda deyish ham mumkin.\nYaqinda ko'chada yurganda derazalar tashqarisida yoki balkonda iplar tortilib, o'simlik barglari qoplab turganiga ko'zingiz tushmadimi? Buni «Yashil parda» (Midori no kaaten) deb atashadi.\nInson issiqda terlaganidek, o'simlik ham issiq bo'lganda ildizidan suv tortib, barglar sathi xuddi terlagandek namlanadi. Namlangan barglar orasidan havo o'tsa, quruq barglar orasidan o'tgandan ko'ra ancha ko'p issiqlikni o'ziga yutadi. Shu sababli havoning harorati pasayadi.\nKonditsioneri bo'lmagan maktabda «yashil parda» o'rnatilgach, issiqdan o'qiy olmagan deraza yonidagi o'quvchilar ham xotirjam o'qiy boshladilar.\nElektr energiyasini tejash-ku mayli, ko'rinishi ham chiroyli va mevasini yeyish ham mumkin — faqatgina yaxshilik keltiradi.", "questions": [{"id": "t5-g3-50", "options": ["ことがあります", "ものがあります", "わけです", "ところです"], "answer": 2, "tr": "夏の暑さには異常な[ものがあります] = yozning issiqligida g'ayritabiiylik bor.", "explanation_uz": "〜ものがある = ...deb hisoblaydigan jihati bor", "blankNo": "50"}, {"id": "t5-g3-51", "options": ["危ないばかりです", "危ないはずです", "危ないほどです", "危ないところです"], "answer": 3, "tr": "使わないと命が[危ないほどです] = ishlatilmasa hayot xavf ostida qoladigan darajada.", "explanation_uz": "〜ほどです = ...darajada", "blankNo": "51"}, {"id": "t5-g3-52", "options": ["過ごしやすくする", "暑くしている", "涼しくする", "快適にする"], "answer": 2, "tr": "夏をますます[暑くしている]とも言えます = yozni yanada issiqroq qilmoqda deyish ham mumkin.", "explanation_uz": "Issiqlik tashqariga chiqishi sababli: 暑くしている", "blankNo": "52"}, {"id": "t5-g3-53", "options": ["a ぬれた ／ b かわいた", "a かわいた ／ b ぬれた", "a ぬれた ／ b ぬれた", "a かわいた ／ b かわいた"], "answer": 1, "tr": "a ぬれた (nam) barglar oralig'idan o'tsa, b かわいた (quruq) barglardan o'tgandan ko'proq issiqlikni yutadi.", "explanation_uz": "Tartib: a ぬれた / b かわいた", "blankNo": "53"}, {"id": "t5-g3-54", "options": ["はともかく", "どころか", "ばかりで", "のみならず"], "answer": 4, "tr": "電気代の節約[のみならず]、見た目にも美しく = elektr tejashdan tashqari, ko'rinishi ham go'zal.", "explanation_uz": "〜のみならず = faqatgina ... bo'lib qolmasdan, balki", "blankNo": "54"}]}]}]}, "6": {"id": 6, "title_jp": "第6回 模擬テスト", "title_uz": "6-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t6-v1-1", "options": ["だどう", "だっとう", "だとう", "たとう"], "answer": 3, "tr": "Ushbu sifat uchun 10 ming iyen bo'lsa, ancha munosib (adolatli/o'rinli) narx bo'lsa kerak.", "stem": "この品質で1万円なら、まあ【妥当な】値段でしょう。", "reading": "だとう", "explanation_uz": "妥当 → だとう (o'rinli, munosib, to'g'ri keladigan)"}, {"id": "t6-v1-2", "options": ["じゅんがん", "しゅんかん", "しゅんがん", "じゅんかん"], "answer": 4, "tr": "Qon aylanishi (sirkulyatsiyasi) yomonlashsa, charchoq osonlikcha chiqmaydigan tana holatiga kelib qoladi.", "stem": "血液の【循環】が悪くなると、疲れが取れにくい体になってしまう。", "reading": "じゅんかん", "explanation_uz": "循環 → じゅんかん (aylanish, sirkulyatsiya)"}, {"id": "t6-v1-3", "options": ["そんとく", "そんどく", "そうとく", "そうどぐ"], "answer": 1, "tr": "U doim foyda va zararni hisob-kitob qilib harakatlanadigan odamdir.", "stem": "あの人はいつも【損得】を判断して行動するような人間だ。", "reading": "そんとく", "explanation_uz": "損得 → そんとく (foyda va zarar, naf)"}, {"id": "t6-v1-4", "options": ["いじょくしゅう", "いじょくじゅう", "いしょくじゅう", "いじょくしゅう"], "answer": 3, "tr": "Kiyinish, ovqatlanish va uy-joyga (衣食住) daraja qo'yilsa, mening holimda taomdan keyin uy turadi.", "stem": "衣食住に【順位】をつけるなら、私の場合は、食の次に住がくる。", "reading": "いしょくじゅう", "explanation_uz": "衣食住 → いしょくじゅう (kiyim, taom va boshpana — hayotiy ehtiyojlar)"}, {"id": "t6-v1-5", "options": ["ぬく", "くだく", "のぞく", "はぶく"], "answer": 4, "tr": "Ovqat tayyorlashdagi mashaqqatni tejaydigan (kamaytiradigan) oshxona anjomlarini Onalar kuni sovg'asi qildim.", "stem": "料理の手間を【省く】調理器具を母の日のプレゼントにした。", "reading": "はぶく", "explanation_uz": "省く → はぶく (qisqartirmoq, tejamoq, chetlab o'tmoq)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t6-v2-6", "options": ["微妙", "微妙", "徴明", "徴明"], "answer": 1, "tr": "14-15 yosh bolalikning intihosi va ulg'ayishning ibtidosi bo'lgan nozik (o'ta sezgir/murakkab) davrdir.", "stem": "14〜15歳という年齢は子どもの終わりであり、大人の始まりである【びみょう】な時期だ。", "reading": "びみょう", "explanation_uz": "微妙 → びみょう (nozik, sezgir, o'zgaruvchan)"}, {"id": "t6-v2-7", "options": ["添う", "充う", "補う", "授う"], "answer": 3, "tr": "Ro'zg'or byudjetini to'ldirish (yetishmovchilikni qoplash) uchun ishlashga chiqadigan uy bekalari tobora ko'paymoqda.", "stem": "家計を【おぎなう】ために働きに出る主婦は増え続けている。", "reading": "おぎなう", "explanation_uz": "補う → おぎなう (to'ldirmoq, qoplamoq)"}, {"id": "t6-v2-8", "options": ["創置", "構置", "操置", "装置"], "answer": 4, "tr": "Inson bosh miyasida hatto kompyuter ham yetolmaydigan xotira qurilmasi (tizimi) mavjud emish.", "stem": "人の頭の中にはパソコンも及ばないような記憶【そうち】があるという。", "reading": "そうち", "explanation_uz": "装置 → そうち (qurilma, apparat)"}, {"id": "t6-v2-9", "options": ["出勤", "出緊", "出務", "出働"], "answer": 1, "tr": "Ishga borishdan oldin kompaniya yaqinidagi qahvaxonada nonushta qilishni odat qilganman.", "stem": "【しゅっきん】前に会社の近くの喫茶店で朝食を食べることにしている。", "reading": "しゅっきん", "explanation_uz": "出勤 → しゅっきん (ishga chiqish, xizmatga borish)"}, {"id": "t6-v2-10", "options": ["湯けて", "解けて", "割けて", "削けて"], "answer": 2, "tr": "50 yil muqaddam xaritada bo'lmagan Himolaydagi bu ko'l muzning erishi natijasida hosil bo'lgan.", "stem": "50年前までは地図になかったヒマラヤのこの湖は、氷が【とけて】できた。", "reading": "とけて", "explanation_uz": "解ける (溶ける) → とける (erimoq)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t6-v3-11", "options": ["場", "時", "防", "間"], "answer": 2, "tr": "Yomg'ir suvini idishda to'plab, yong'in sodir bo'lgan paytda o'chirishga ishlatamiz.", "stem": "雨水をタンクにためて、火災（　）の消火に使う。", "explanation_uz": "火災時 (かさいじ) = yong'in payti/vaqti"}, {"id": "t6-v3-12", "options": ["非", "不", "未", "無"], "answer": 3, "tr": "Uzoq yillar davomida hal bo'lmagan (yechilmagan) hodisa nihoyat oydinlashdi.", "stem": "長年（　）解決だった事件が解決した。", "explanation_uz": "未解決 (みかいけつ) = hali yechilmagan, hal etilmagan"}, {"id": "t6-v3-13", "options": ["試", "実", "始", "再"], "answer": 1, "tr": "Yangi dastgohni sinov tariqasida ishlatib ko'ramiz (sinov haydovi).", "stem": "新しい機械の（　）運転をする。", "explanation_uz": "試運転 (しうんてん) = sinov tariqasida ishga tushirish"}, {"id": "t6-v3-14", "options": ["権", "戦", "力", "上"], "answer": 3, "tr": "Harbiy kuchga tayanmaydigan diplomatiyani xohlaymiz.", "stem": "軍事（　）に頼らない外交を望む。", "explanation_uz": "軍事力 (ぐんじりょく) = harbiy qudrat/kuch"}, {"id": "t6-v3-15", "options": ["面", "期", "別", "差"], "answer": 4, "tr": "Bolalarning o'sishi va rivojlanishida individual farq (shaxsiy tafovut) katta bo'ladi.", "stem": "子どもの成長は個人（　）が大きい。", "explanation_uz": "個人差 (こじんさ) = individual farq, shaxsiy tafovut"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga ma'no jihatidan eng mos keladigan so'zni tanlang.", "questions": [{"id": "t6-v4-16", "options": ["めでたく", "おしく", "醜く", "懐かしく"], "answer": 4, "tr": "Eski fotosuratlar albomi chiqib qolib, bolaligimni sog'inch bilan esladim.", "stem": "古いアルバムが出てきて、子ども時代を（　）思い出した。", "reading": "なつかしく", "explanation_uz": "懐かしく (なつかしく) = sog'inch/quvonch bilan eslash"}, {"id": "t6-v4-17", "options": ["納得", "了解", "公認", "承知"], "answer": 1, "tr": "Iqtisodiyot tiklanayotgani bois, o'zim to'liq qanoat hosil qilgunimcha ish izlashni davom ettirishga qaror qildim.", "stem": "景気が回復しつつあるので、自分で（　）できるまで就職活動を続けることにした。", "explanation_uz": "納得 (なっとく) = qanoat hosil qilish, rozi bo'lish"}, {"id": "t6-v4-18", "options": ["ワンセット", "ワンパターン", "ワンクッション", "ワンタッチ"], "answer": 2, "tr": "Bo'lim boshlig'ining tanbehlari doim bir xil qolipda (o'zgarishsiz, one-pattern) bo'ladi.", "stem": "課長のお説教はいつも（　）だ。", "explanation_uz": "ワンパターン (one pattern) = bir xil shablon, o'zgarishsiz qolip"}, {"id": "t6-v4-19", "options": ["繰り上げて", "引き分けて", "相次いで", "乗り出して"], "answer": 3, "tr": "Bu yil sport olamida yangi yulduzlar ketma-ket (biri ketidan biri) dunyoga keldi.", "stem": "今年はスポーツ界に新しいスターが（　）誕生した。", "explanation_uz": "相次いで (あいついで) = ketma-ket, birin-ketin"}, {"id": "t6-v4-20", "options": ["なかなか", "ひろびろ", "てんてん", "はきはき"], "answer": 4, "tr": "U adashgan bola o'z ismini dadil va ravon (tiniq) aytib bergani sababli, darrov ota-onasini topishga muvaffaq bo'ldik.", "stem": "その迷子は自分の名前を（　）と答えたので、すぐに親を見つけることができた。", "explanation_uz": "はきはき = dadil, ravon, tiniq"}, {"id": "t6-v4-21", "options": ["宿泊", "泊まり", "日帰り", "遠出"], "answer": 2, "tr": "So'nggi paytlarda oilaviy tunab qolinadigan sayohatlarga chiqish kamaydi.", "stem": "最近家族で（　）がけの旅行に出かけることが少なくなった。", "explanation_uz": "泊まりがけ (とまりがけ) = tunab qolish bilan bo'ladigan sayohat"}, {"id": "t6-v4-22", "options": ["観測", "記憶", "誤解", "錯覚"], "answer": 4, "tr": "Ko'z aldanuvidan (illyuziyadan) foydalangan zamonaviy san'at ko'rgazmasida ajoyib tuyg'ulardan bahramand bo'ldim.", "stem": "目の（　）を利用した現代アート展で不思議な感覚を楽しんできた。", "explanation_uz": "錯覚 (さっかく) = illyuziya, yanglish sezgi (目の錯覚 = ko'z aldanuvi)"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin sinonimni tanlang.", "questions": [{"id": "t6-v5-23", "options": ["すぐに", "明日までに", "必ず", "とりあえず"], "answer": 1, "tr": "Mas'ul xodim qaytsa, darhol (qayta) qo'ng'iroq qiladi.", "stem": "担当者が戻りましたら、折り返し電話を差し上げます。【すぐに】", "reading": "おりかえし", "explanation_uz": "折り返し = すぐに (darhol, to'xtamasdan)"}, {"id": "t6-v5-24", "options": ["出版する", "翻訳する", "脱線する", "延長する"], "answer": 3, "tr": "U professorning gapi darrov mavzudan chetga chiqib ketadi.", "stem": "あの教授の話はすぐ【それる】。", "reading": "それる", "explanation_uz": "それる = 脱線する (だっせんする — mavzudan chetga chiqish)"}, {"id": "t6-v5-25", "options": ["全速力で", "たちまち", "休まずに", "なんとか"], "answer": 3, "tr": "Marafonchi to'xtamasdan (bir nafasda, uzluksiz) qiyalikdan pastga tushdi.", "stem": "マラソン選手は、【一気に】坂を下った。", "reading": "いっきに", "explanation_uz": "一気に = 休まずに (to'xtamasdan, bir zarbda)"}, {"id": "t6-v5-26", "options": ["不愉快な", "不安な", "真剣な", "得意な"], "answer": 1, "tr": "U xabarni eshitib dadam norozi (yoqimsiz) qiyofaga kirdi.", "stem": "そのニュースを聞いて父は【苦い顔】をした。", "reading": "にがいかお", "explanation_uz": "苦い顔 = 不愉快な顔 (norozi, yoqimsiz qiyofa)"}, {"id": "t6-v5-27", "options": ["低下", "上達", "信用", "承知"], "answer": 2, "tr": "Ularning til bilish mahorati ancha o'sdi (yaxshilandi).", "stem": "彼らの語学力は【レベルアップ】している。", "explanation_uz": "レベルアップ = 上達 (じょうたつ — o'sish, mohirlik oshishi)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilgan gapini tanlang.", "questions": [{"id": "t6-v6-28", "options": ["子どものころの思い出が頭の中を往復する。", "毎朝学校へバスで往復している。", "工事が終わり、道路はすっかり往復している。", "家と会社の間を往復するだけの毎日だ。"], "answer": 4, "tr": "往復 (おうふく) = borib-kelish (ikki nuqta orasida qatnash).", "stem": "往復", "optsTr": ["Xotiralar miyada aylanadi (noto'g'ri).", "Har kuni maktabga borib-keladi (noto'g'ri — 通学).", "Yo'l tiklandi (noto'g'ri — 復旧).", "Uy bilan ishxona o'rtasida shunchaki qatnashdan iborat kundalik hayot. (to'g'ri)"]}, {"id": "t6-v6-29", "options": ["昔の町並みをあらわれにして観光客を呼ぶ。", "一度あきらめた歌手になる希望があらわれになった。", "この投票率の低さは、政治への無関心のあらわれだ。", "お祭りには、たくさんの人々のあらわれがある。"], "answer": 3, "tr": "あらわれ (現れ) = ifodasi, belgisi, ko'rinishi.", "stem": "あらわれ", "optsTr": ["Ko'cha ko'rinishi (noto'g'ri).", "Umid paydo bo'ldi (noto'g'ri — 復活).", "Ovoz berish foizining bunday pastligi — siyosatga bo'lgan beparvolikning ifodasidir (ko'rinishidir). (to'g'ri)", "Odamlar yig'iladi (noto'g'ri)."]}, {"id": "t6-v6-30", "options": ["勉強した効力があって合格した。", "仕事をまかせられて大きな効力を感じる。", "この薬は古くなると、効力がほとんど失われる。", "この部屋の間取りは効力が悪い。"], "answer": 3, "tr": "効力 (こうりょく) = kuch, ta'sir kuchi, samara (dori, qonun va h.k.).", "stem": "効力", "optsTr": ["Harakat samarasi (noto'g'ri — 甲斐).", "Mas'uliyat hissi (noto'g'ri — やりがい).", "Bu dori eskirib qolsa, ta'sir kuchi deyarli yo'qoladi. (to'g'ri)", "Xona joylashuvi qulay emas (noto'g'ri — 使い勝手)."]}, {"id": "t6-v6-31", "options": ["息子は見事な会社に就職できて喜んでいる。", "私の友人の画家は有名ではないが見事な絵を描く。", "20歳になればもう見事な大人といえる。", "あの子は幼い弟の世話をよくする見事な子どもだ。"], "answer": 2, "tr": "見事 (みごと) = ajoyib, qoyilmaqom, ko'rkam (san'at, mahorat haqida).", "stem": "見事", "optsTr": ["Yaxshi kompaniya (noto'g'ri — 立派な).", "Rassom do'stim mashhur emas, ammo qoyilmaqom (ajoyib) suratlar chizadi. (to'g'ri)", "To'laqonli katta odam (noto'g'ri — 一人前).", "Yaxshi bola (noto'g'ri — えらい/感心な)."]}, {"id": "t6-v6-32", "options": ["犯人につかまっていた人質が開放された。", "この庭園は、日曜日だけ市民に開放される。", "旅行から帰ってきて、駅でみんな開放した。", "最近景気がようやく開放してきた。"], "answer": 2, "tr": "開放 (かいほう) = keng jamoatchilik uchun ochiq qilib qo'yish (eshigini ochish).", "stem": "開放", "optsTr": ["Garovdagilar ozod qilindi (noto'g'ri — 解放).", "Ushbu bog' faqat yakshanba kunlari shahar aholisi uchun ochiq qilib qo'yiladi. (to'g'ri)", "Bekatda tarqaldi (noto'g'ri — 解散).", "Iqtisod tiklandi (noto'g'ri — 回復)."]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t6-g1-33", "options": ["において", "によって", "にあたって", "について"], "answer": 2, "tr": "A: «Kelasi hafta shifoxonadan chiqa olamanmi?»\nB: «Tekshiruv natijasiga qarab, balki bundan ham tezroq chiqa olarsiz.»", "stem": "A「来週には退院できますか。」\nB「検査の結果（　）は、もっと早くできるかもしれませんよ。」", "explanation_uz": "〜によって(は) = ...ga qarab, holatga bog'liq ravishda"}, {"id": "t6-g1-34", "options": ["をきっかけに", "をもとにして", "を通じて", "をめぐって"], "answer": 1, "tr": "Poyezdda tasodifan yonma-yon o'tirib qolishimiz turtki (sabab) bo'lib, u bilan uchrasha boshladik.", "stem": "電車でたまたま隣に座ったこと（　）、彼女と付き合い始めた。", "explanation_uz": "〜をきっかけに = ...ni turtki/sabab qilib olib"}, {"id": "t6-g1-35", "options": ["というのに", "といったところで", "といっても", "といえば"], "answer": 3, "tr": "Kompaniya direktori deyilgani bilan, xodimlari atigi 2 kishidan iborat, xolos.", "stem": "彼は会社の社長だ（　）、従業員は2人しかいない。", "explanation_uz": "〜といっても = ...deyilsa-da (aslida kutilganidan kam)"}, {"id": "t6-g1-36", "options": ["他方", "反面", "反対", "半分"], "answer": 2, "tr": "Avtomobilda sayohat qilish qulay bo'lgani bilan, boshqa tomondan charchatadi va halokat xavfi ham yuqori.", "stem": "車による旅行は便利な（　）、疲れるし事故の危険性も高い。", "explanation_uz": "〜反面 (はんめん) = boshqa tomondan esa (qarama-qarshi xususiyat)"}, {"id": "t6-g1-37", "options": ["するどころか", "したところで", "してみたところで", "するところが"], "answer": 1, "tr": "Ishim band bo'lib, uylanish tugul (u yoqda tursin), hatto sevgan qiz ham topa olmayapman.", "stem": "仕事が忙しく、結婚（　）彼女さえ見つけることができない。", "explanation_uz": "〜どころか = ...tugul, ...u yoqda tursin"}, {"id": "t6-g1-38", "options": ["もの", "こと", "ところ", "わけ"], "answer": 1, "tr": "Hamma ishdan haydalib ketishdan qo'rqqani sababli prezidentga hech narsa deya olmayapti.", "stem": "みんな、くびになるのがこわい（　）だから、社長に何も言えないでいる。", "explanation_uz": "〜ものだから = ...bo'lgani sababli (sabab/oqlanish)"}, {"id": "t6-g1-39", "options": ["来るだろう", "来ないか", "来るものか", "来たか"], "answer": 4, "tr": "Endi keldimi desam, allaqachon qaytib ketibdi. Bunchalik band odam-a!", "stem": "今（　）と思ったら、もう帰ってしまった。なんて忙しい人だ。", "explanation_uz": "〜かと思ったら = ...bo'ldi deb o'ylashim bilanoq (kutilmagan harakat)"}, {"id": "t6-g1-40", "options": ["作るはずがない", "作るしかない", "作りかねない", "作りようがない"], "answer": 2, "tr": "Bugun oqshom xotinim uyda yo'q, shuning uchun o'zim ovqat pishirishimdan boshqa chora yo'q.", "stem": "今夜は妻がいないから、自分で料理を（　）。", "explanation_uz": "〜しかない = ...dan boshqa iloj yo'q"}, {"id": "t6-g1-41", "options": ["してはいけない", "しないといけない", "するのはいけない", "するわけにはいかない"], "answer": 2, "tr": "Sayyohlik agentligiga xabar berishim shart bo'lgani uchun, sayohatga borish-bormasligingiz haqida tezda javob bering.", "stem": "旅行会社に連絡（　）ので、旅行に参加するかしないか早く返事をください。", "explanation_uz": "〜ないといけない = ...masam bo'lmaydi (shart)"}, {"id": "t6-g1-42", "options": ["頼むにほかならない", "頼むよりほかはない", "頼むほかよりない", "頼むほかにある"], "answer": 2, "tr": "Kompyuter ishlamayapti. Bunday bo'lgach, sotib olgan do'konga ta'mirlashni iltimos qilishdan boshqa iloj yo'q.", "stem": "パソコンが動かない。こうなったら買ったお店に修理を（　）。", "explanation_uz": "〜よりほかはない = ...dan o'zga chora yo'q"}, {"id": "t6-g1-43", "options": ["結婚することには", "結婚しないことには", "結婚するからには", "結婚しないからには"], "answer": 3, "tr": "B: «Rahmat. Modomiki turmush qurar ekanmiz, baxtli oila barpo etmoqchiman.»", "stem": "B「ありがとう。（　）、幸せな家庭を作りたいです。」", "explanation_uz": "〜からには = modomiki ... qilar ekanman (qatiy niyat)"}, {"id": "t6-g1-44", "options": ["寝てあげなさい", "寝られてしまいなさい", "寝てしまいなさい", "寝かせておきなさい"], "answer": 4, "tr": "Dadang har kuni erta tongda ishga ketadi, shuning uchun yakshanba kuni hech bo'lmasa o'z holiga qo'yib uxlashiga qo'yib bering.", "stem": "お父さんは毎朝早く出かけるのだから、日曜くらいは（　）。", "explanation_uz": "〜ておきなさい = o'z holida qoldir (寝かせておきなさい = uxlashiga imkon ber)"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng to'g'ri bo'lakni tanlang.", "questions": [{"id": "t6-g2-45", "options": ["心配", "疲れ", "ようで", "気味の"], "answer": 3, "tr": "To'g'ri tartib: 部長は忙しすぎて疲れ気味のようで心配です。", "explanation_uz": "To'g'ri tartib: [疲れ][気味の][★ようで][心配] (2 → 4 → 3 → 1)", "prefix": "部長は忙しすぎて", "suffix": "です。", "starPos": 3, "order": [2, 4, 3, 1]}, {"id": "t6-g2-46", "options": ["近づいて", "行く", "どころでは", "台風が"], "answer": 2, "tr": "To'g'ri tartib: 明日は旅行の予定だが、台風が近づいて行くどころではなくなった。", "explanation_uz": "To'g'ri tartib: [台風が][近づいて][★行く][どころでは] (4 → 1 → 2 → 3)", "prefix": "明日は旅行の予定だが、", "suffix": "なくなった。", "starPos": 3, "order": [4, 1, 2, 3]}, {"id": "t6-g2-47", "options": ["言われて", "忘れて", "あると", "いながら"], "answer": 4, "tr": "To'g'ri tartib: 今日の朝早くから会議があると知っていながら、忘れてしまって遅刻した。", "explanation_uz": "To'g'ri tartib: 会議が[あると][言われて][★いながら][忘れて] (3 → 1 → 4 → 2)", "prefix": "今日の朝早くから会議が", "suffix": "しまって、遅刻した。", "starPos": 2, "order": [3, 1, 4, 2]}, {"id": "t6-g2-48", "options": ["だれが", "リーさんに", "見ても", "決まって"], "answer": 3, "tr": "To'g'ri tartib: B「もちろん、だれが見てもリーさんに決まっているよ。」", "explanation_uz": "To'g'ri tartib: [だれが][見ても][★リーさんに][決まって] (1 → 3 → 2 → 4)", "prefix": "B「もちろん、", "suffix": "いるよ。」", "starPos": 3, "order": [1, 3, 2, 4]}, {"id": "t6-g2-49", "options": ["やらないと", "体力に", "応じて", "かえって"], "answer": 1, "tr": "To'g'ri tartib: 運動はその人の体力に応じてやらないと、かえって体をこわしますよ。", "explanation_uz": "To'g'ri tartib: [体力に][応じて][★やらないと][かえって] (2 → 3 → 1 → 4)", "prefix": "運動はその人の", "suffix": "体をこわしますよ。", "starPos": 3, "order": [2, 3, 1, 4]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh joylariga eng to'g'ri variantni tanlang.", "passage_title": "現代の占いブーム", "passage": "現代は科学の時代 {{50}} 、占いの好きな人は多い。朝のテレビ番組では、必ずといっていいほど、「今日の運勢」を取り上げているし、女性向けの雑誌の新年号は、「今年のあなたの運命」という特集を {{51}} 作れない。\n実は大会社の社長や政治家にも占い師に頼る人が少なくない。\n占いが科学的に正しいかどうかはわからない。しかし占い師はたくさんの人を見てきている。顔だけで「この人はどんな人か。何に悩んでいるか」とわかるのではないか。相談する人も悩みを {{52}} だけで心が軽くなるものだ。\nまた、ある人が「こんな仕事を始めたいのだが」と相談して、占い師が「最初は苦労するけれど、かならず成功すると占いに出ています」と答えたとする。\nたとえば、3年やってなかなか成功せず {{53}} 、「占い師が『最初は苦労する』と言ってたな」と思い直して、その後さらに10年がんばって成功するかもしれない。\n生まれた日や名前や血液型で運命が {{54}} 。だが占いをうまく使えば、迷ったときに背中を押してくれたり、心を支えてくれるものになるのだ。", "passage_tr": "Hozirgi davr ilm-fan zamoni bo'lishiga qaramasdan, folbinlikni yoqtiradiganlar ko'p. Ertalabki teledasturlarda «kunlik munajjimlar bashorati» ko'rsatiladi, ayollar jurnallarining yangi yil sonini esa fol mavzusisiz tayyorlab bo'lmaydi.\nAslida yirik korporatsiyalar rahbarlari va siyosatchilar orasida ham munajjimlarga tayanadiganlar kam emas.\nFol ilmiy jihatdan to'g'rimi-yo'qmi bilmaymiz, ammo folbinlar juda ko'p odamni ko'rishgan. Yuzining o'zidan uning qanday insonligini va nimadan qiynalayotganini bilib olishsa kerak. Maslahat so'rab borgan inson ham dardini eshittirib olishning (aytishning) o'zi bilan ko'ngli yengil tortadi.\nYana biror kishi ish boshlamoqchi bo'lib borsa va «boshida qiynalasiz, ammo oxiri albatta omad keltiradi» deb aytsa, u inson 3 yil ishlab qiynalib taslim bo'layozganda «folbin boshida qiynalasan degandi-ku» deb o'zini qo'lga olib, yana 10 yil ishlab muvaffaqiyatga erishishi mumkin.\nTug'ilgan kun, ism yoki qon guruhi bilan taqdir hal bo'lib qolmaydi, albatta. Ammo folbinlikdan to'g'ri foydalanilsa, ikkilanib turganda dadillik berib, ruhiy tayanch bo'la oladi.", "questions": [{"id": "t6-g3-50", "options": ["にもかかわらず", "にかかわって", "にかけても", "につけても"], "answer": 1, "tr": "科学の時代[にもかかわらず]、占いの好きな人は多い = ilm-fan davri bo'lishiga qaramasdan.", "explanation_uz": "〜にもかかわらず = ...bo'lishiga qaramay", "blankNo": "50"}, {"id": "t6-g3-51", "options": ["なければ", "ぬきには", "とわずに", "なくては"], "answer": 2, "tr": "特集を[ぬきには]作れない = maxsus maqolalarsiz chiqarib bo'lmaydi.", "explanation_uz": "〜ぬきには = ...siz (amalga oshmaydi)", "blankNo": "51"}, {"id": "t6-g3-52", "options": ["聞いてあげる", "聞かせてあげる", "聞いてもらう", "聞かせてもらう"], "answer": 3, "tr": "悩みを[聞いてもらう]だけで心が軽くなる = dardini eshittirib olishning o'zi bilan.", "explanation_uz": "〜てもらう = o'zi uchun qildirib olish", "blankNo": "52"}, {"id": "t6-g3-53", "options": ["あきらめられるが", "あきらめきれず", "あきらめるところを", "あきらめたのに"], "answer": 3, "tr": "なかなか成功せず[あきらめるところを] = taslim bo'layozgan joyida / arafasida.", "explanation_uz": "〜ところを = ayni ... bo'layotgan vaziyatda", "blankNo": "53"}, {"id": "t6-g3-54", "options": ["決めるものがない", "決めることがない", "決まるものではない", "決まることはない"], "answer": 4, "tr": "運命が[決まることはない] = taqdir belgilanishi aslo yo'q (mumkin emas).", "explanation_uz": "〜ことはない = aslo bunday bo'lmaydi / bunga hojat yo'q", "blankNo": "54"}]}]}]}, "7": {"id": 7, "title_jp": "第7回 模擬テスト", "title_uz": "7-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t7-v1-1", "options": ["かんてい", "かんじょう", "かんでい", "かんしょう"], "answer": 2, "tr": "Bunchalik oziq-ovqat xarajati ketishini hisob-kitobga (rejamga) kiritmagan edim.", "stem": "こんなに食費がかかるとは【勘定】に入れてなかった。", "reading": "かんじょう", "explanation_uz": "勘定 → かんじょう (hisob-kitob, hisobga olish)"}, {"id": "t7-v1-2", "options": ["てっていてき", "てつていてき", "てつでいてき", "てっていてき"], "answer": 4, "tr": "Samolyot halokati sabablarini tubdan (to'liq va atroflicha) tekshirmoqdalar.", "stem": "飛行機事故の原因を【徹底的】に調査する。", "reading": "てっていてき", "explanation_uz": "徹底的 → てっていてき (tubdan, har tomonlama, izchil)"}, {"id": "t7-v1-3", "options": ["かわかした", "さらした", "みたした", "ほした"], "answer": 4, "tr": "Quyosh nurida quritilgan sabzavotlarda D vitamini ko'payadi.", "stem": "太陽光に【干した】野菜は、ビタミンDが増える。", "reading": "ほした", "explanation_uz": "干す → ほす (quritmoq, oftobda quritmoq)"}, {"id": "t7-v1-4", "options": ["げこう", "げごう", "かこう", "かごう"], "answer": 3, "tr": "U kompaniyaning moliyaviy ahvoli so'nggi bir necha yilda pasayib (tushib) bormoqda.", "stem": "あの会社の経営状況はここ数年【下降】している。", "reading": "かこう", "explanation_uz": "下降 → かこう (pasayish, pastga qarab ketish)"}, {"id": "t7-v1-5", "options": ["かかえて", "おぼえて", "たくわえて", "おさえて"], "answer": 1, "tr": "Dam olsa ham ketmaydigan charchoqni o'zida ko'tarib yurgan zamonaviy insonlar ko'payib qoldi.", "stem": "休んでも取れない疲れを【抱えて】いる現代人が多くなった。", "reading": "かかえて", "explanation_uz": "抱える → かかえる (ko'tarib/tutib yurmoq, yuk/muammoni o'zida saqlamoq)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t7-v2-6", "options": ["敬う", "尊う", "仰う", "拝う"], "answer": 1, "tr": "Chin dildan hurmat qiladigan opera xonandamning Yaponiyaga ilk bor kelishi belgilandi, hozirdanoq hayajondaman.", "stem": "心から【やまう】オペラ歌手の初来日が決定して、今からわくわくしている。", "reading": "やまう", "explanation_uz": "敬う → うやまう (e'zozlamoq, hurmat qilmoq)"}, {"id": "t7-v2-7", "options": ["非評", "比評", "品評", "批評"], "answer": 4, "tr": "Yangi yozuvchining debyut asari saytda qattiq tanqid qilindi (baholandi).", "stem": "新人作家のデビュー作はサイトで厳しく【ひひょう】された。", "reading": "ひひょう", "explanation_uz": "批評 → ひひょう (tanqid, taqriz, baho)"}, {"id": "t7-v2-8", "options": ["電染", "伝染", "伝線", "電線"], "answer": 2, "tr": "Esnash nega boshqalarga yuqishi hali ilmiy jihatdan aniqlanmagan.", "stem": "あくびはなぜ他人に【でんせん】するのかは、まだ学問的にわかっていない。", "reading": "でんせん", "explanation_uz": "伝染 → でんせん (yuqish, infeksiya/ta'sir o'tishi)"}, {"id": "t7-v2-9", "options": ["貴重", "希重", "貴調", "希調"], "answer": 1, "tr": "Yashayotgan vaqtimiz cheklanganligini o'ylasak, qimmatli vaqtni bekorga o'tkazib bo'lmaydi.", "stem": "生きている時間に限りがあると考えると、【きちょう】な時間を無駄にはできない。", "reading": "きちょう", "explanation_uz": "貴重 → きちょう (qimmatli, nodir, qadrli)"}, {"id": "t7-v2-10", "options": ["慕集", "暮集", "募集", "墓集"], "answer": 3, "tr": "Yaqin atrofdagi qulaylik do'konida (kombini) yarim kunlik sotuvchi xodimlar qabul qilinmoqda (ishga chaqirilmoqda).", "stem": "近くのコンビニで、アルバイト店員を【ぼしゅう】している。", "reading": "ぼしゅう", "explanation_uz": "募集 → ぼしゅう (yollash, qabul qilish, to'plash)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t7-v3-11", "options": ["性", "権", "行", "業"], "answer": 4, "tr": "Avtomobillar bilan ifodalangan ishlab chiqarish sohasi (sanoati) Yaponiya savdosini yetaklab kelgan.", "stem": "自動車に代表される製造（　）が日本の貿易をリードしてきた。", "explanation_uz": "製造業 (せいぞうぎょう) = ishlab chiqarish sanoati/tarmog'i"}, {"id": "t7-v3-12", "options": ["未", "非", "不", "来"], "answer": 1, "tr": "Voyaga yetmagan shaxslar va haydovchilar spirtli ichimlik ichishi taqiqlanadi.", "stem": "（　）成年の人と運転手は、お酒を飲んではいけませんよ。", "explanation_uz": "未成年 (みせいねん) = voyaga yetmagan shaxs"}, {"id": "t7-v3-13", "options": ["明", "美", "名", "大"], "answer": 3, "tr": "Shekspirning asarlarida juda ko'plab mashhur iqtiboslar (mashhur iboralar) mavjud.", "stem": "シェイクスピアの作品には数々の（　）文句がある。", "explanation_uz": "名文句 (めいもんく) = mashhur ibora, ajoyib iqtibos"}, {"id": "t7-v3-14", "options": ["化", "心", "感", "面"], "answer": 3, "tr": "Yaqinda tennisda to'p uzatishimda (servis) barqarorlik hissi/sifati paydo bo'ldi.", "stem": "最近、テニスのサーブに安定（　）が出てきた。", "explanation_uz": "安定感 (あんていかん) = barqarorlik hissi, ishonchlilik"}, {"id": "t7-v3-15", "options": ["人", "者", "工", "士"], "answer": 1, "tr": "Qo'li shirin (mahoratli) oshpazni ishga yollamoqchimiz.", "stem": "腕のいい料理（　）を雇う。", "explanation_uz": "料理人 (りょうりにん) = oshpaz"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'zni tanlang.", "questions": [{"id": "t7-v4-16", "options": ["堅実", "謙虚", "地味", "丁寧"], "answer": 2, "tr": "U Yaponiyadagi birinchi raqamli matematik bo'lishiga qaramay, aslo kibrlanmaydigan kamtarin shaxsdir.", "stem": "彼は日本一の数学者なのに、決していばらない（　）な人柄だ。", "reading": "けんきょ", "explanation_uz": "謙虚 (けんきょ) = kamtar, xokisor"}, {"id": "t7-v4-17", "options": ["訴える", "止める", "治める", "捕らえる"], "answer": 1, "tr": "Marafon musobaqasida bel yoki tizza og'rig'idan shikoyat qilayotgan tajribasi kam yuguruvchilar ko'p.", "stem": "マラソン大会で、腰やひざの痛みを（　）、経験の浅いランナーが多い。", "reading": "うったえる", "explanation_uz": "（痛みを）訴える = og'riqdan shikoyat qilmoq/arz qilmoq"}, {"id": "t7-v4-18", "options": ["立ち合った", "取り合った", "張り合った", "落ち合った"], "answer": 4, "tr": "O'tirish kuni do'stlar bilan izakaya (restoran)da uchrashdik (belgilangan joyda to'plandik).", "stem": "飲み会の日、友だちと居酒屋で（　）。", "reading": "おちあった", "explanation_uz": "落ち合う (おちあう) = kelishilgan joyda uchrashmoq"}, {"id": "t7-v4-19", "options": ["キャンペーン", "コンテスト", "ショッピング", "キャンプ"], "answer": 1, "tr": "Vokzal oldidagi maydonda o'tkinchilarga aksiya (targ'ibot)dagi sharbatni bepul tarqatishayotgan edi.", "stem": "駅前の広場で通行人に（　）中のジュースを無料で配っていた。", "explanation_uz": "キャンペーン (campaign) = aksiya, reklama kompaniyasi"}, {"id": "t7-v4-20", "options": ["学者", "芸能", "冒険", "競技"], "answer": 3, "tr": "Sarguzashtsevarlar (sayyoh-sarguzashtchilar) orasida go'yo bola ulg'aymasdan katta bo'lib qolgandek insonlar ko'p deb o'ylayman.", "stem": "（　）家には子どもがそのまま大人になったような人が多いと思う。", "reading": "ぼうけん", "explanation_uz": "冒険家 (ぼうけんか) = sarguzashtsevar, sayyoh"}, {"id": "t7-v4-21", "options": ["いまに", "しきりに", "いくぶん", "ひとまず"], "answer": 4, "tr": "Ishni boshlashdan oldin hozircha (vaqtincha) choy ichib, charchoqni chiqaring.", "stem": "仕事を始める前に（　）お茶でも飲んで、疲れをとってください。", "reading": "ひとまず", "explanation_uz": "ひとまず = hozircha, avvalambor, vaqtincha"}, {"id": "t7-v4-22", "options": ["すまない", "やむを得ない", "とんでもない", "やかましい"], "answer": 3, "tr": "Hech narsa bo'lmagandek yolg'on gapiradigan u odamning siyosatchi bo'lishi aqlga sig'maydigan (bema'ni) gapdir.", "stem": "平気でうそをつくあの男が政治家になるだなんて、（　）話だ。", "reading": "とんでもない", "explanation_uz": "とんでもない = aqlga sig'mas, bo'lmag'ur, asossiz"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin so'zni tanlang.", "questions": [{"id": "t7-v5-23", "options": ["欠けていた", "満ちていた", "輝いていた", "甘えていた"], "answer": 2, "tr": "Raqibim o'ziga bo'lgan ishonchga to'lib-toshgan edi.", "stem": "ライバルは自信に【あふれていた】。", "reading": "あふれていた", "explanation_uz": "あふれる ≈ 満ちる (to'lib-toshmoq)"}, {"id": "t7-v5-24", "options": ["その後", "犯人", "隠れた事情", "被害"], "answer": 3, "tr": "Hodisaning yashirin sabablarini (orqa tomonini) bildirmasdan tekshirmoqda.", "stem": "事件の【裏を】こっそり調べる。", "reading": "うらを", "explanation_uz": "裏 ≈ 隠れた事情 (parda ortidagi / yashirin holatlar)"}, {"id": "t7-v5-25", "options": ["その場で", "一瞬", "本来", "実際に"], "answer": 4, "tr": "Jinoyatchi anavi kishi. Haqiqatan ham (amalda) men o'z ko'zim bilan ko'rganman.", "stem": "犯人はあの人です。【現に】私はこの目で見たんですから。", "reading": "げんに", "explanation_uz": "現に ≈ 実際に (amalda, fakt sifatida, haqiqatan ham)"}, {"id": "t7-v5-26", "options": ["丁寧に", "進んで", "無理に", "適切に"], "answer": 1, "tr": "Ustoz shaxsan o'zi juda erinmay (sinchkovlik/muloyimlik bilan) o'quvchiga yo'l-yo'riq ko'rsatdi.", "stem": "先生が自ら【手を取って】生徒を指導した。", "reading": "てをとって", "explanation_uz": "手を取って ≈ 丁寧に (juda sinchkovlik va g'amxo'rlik bilan)"}, {"id": "t7-v5-27", "options": ["更新", "誤り", "破壊", "変更"], "answer": 2, "tr": "Tizim xatoligi (error) tufayli muhim xatni jo'nata olmadim.", "stem": "システムの【エラー】で、大事なメールを送れなかった。", "reading": "えらー", "explanation_uz": "エラー ≈ 誤り (xatolik, nosozlik)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Berilgan so'zning gapda eng to'g'ri ishlatilgan variantini tanlang.", "questions": [{"id": "t7-v6-28", "options": ["この料理を作るときは、ときどき火の強さを加減しなさい。", "加減の悪いことに、出かけようとしたときに雨が降り出してきた。", "あの男の常識の加減はその程度のものだよ。", "風邪をひいて、すっかり加減ができなくなった。"], "answer": 1, "tr": "加減 (kagen) = me'yoriga keltirish, moslashtirish, holat.", "stem": "【加減】の使い方として最もよいものを選びなさい。", "explanation_uz": "「火の強さを加減する」= olov balandligini me'yoriga keltirmoq (to'g'ri ishlatilish)."}, {"id": "t7-v6-29", "options": ["優勝という大きなねらいに向かってがんばる。", "税金を下げた政府のねらいは、今度の選挙に勝つことだ。", "この道路は来年までの完成をねらいにしている。", "今日の買い物のねらいは冬の洋服です。"], "answer": 2, "tr": "ねらい (nerai) = maqsad, ko'zlangan reja/muddao.", "stem": "【ねらい】の使い方として最もよいものを選びなさい。", "explanation_uz": "「政府のねらいは〜」= hukumatning ko'zlagan maqsadi... (to'g'ri ishlatilish)."}, {"id": "t7-v6-30", "options": ["会社は法律に陽気な人を求めています。", "あの子は陽気にふるまっているが、両親の離婚にとても傷ついている。", "しっかり勉強すれば若い君たちの将来は陽気だ。", "今日は母親の陽気がいつになくいい。"], "answer": 2, "tr": "陽気 (youki) = quvnoq, xushchaqchaq, ob-havo holati.", "stem": "【陽気】の使い方として最もよいものを選びなさい。", "explanation_uz": "「陽気にふるまう」= o'zini xushchaqchaq va quvnoq tutmoq (to'g'ri ishlatilish)."}, {"id": "t7-v6-31", "options": ["彼女はとても気配のいい人だ。", "被災地の人々の気配をレポートする。", "故郷の町はすっかり気配が変わってしまった。", "この家は人の住んでいる気配がまったくない。"], "answer": 4, "tr": "気配 (kehai) = alomat, belgi, sharpasi.", "stem": "【気配】の使い方として最もよいものを選びなさい。", "explanation_uz": "「人の住んでいる気配がない」= odam yashayotganlik belgisi/sharpasi sezilmaydi (to'g'ri ishlatilish)."}, {"id": "t7-v6-32", "options": ["西洋の小説には、聖書から引用された言葉が多い。", "秘密の情報がこっそり国外に引用されてしまった。", "教授の本を1週間引用させていただいた。", "他人の力をいつも引用するわけにはいかない。"], "answer": 1, "tr": "引用 (in'you) = iqtibos keltirish, sitata olish.", "stem": "【引用】の使い方として最もよいものを選びなさい。", "explanation_uz": "「聖書から引用された言葉」= Injildan iqtibos olingan so'zlar (to'g'ri ishlatilish)."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi qavs ichiga eng mos keluvchi grammatik shaklni tanlang.", "questions": [{"id": "t7-g1-33", "options": ["にそなえて", "に対して", "に際して", "に応えて"], "answer": 4, "tr": "Mijozlarning istaklariga binoan (javoban), soat 20:00 gacha xizmat ko'rsatishga qaror qildik.", "stem": "お客様のご希望（　）、夜8時まで営業することにしました。", "explanation_uz": "「〜に応えて」= ...ga javoban, istak/talabni qondirish maqsadida."}, {"id": "t7-g1-34", "options": ["前に", "後に", "際に", "間に"], "answer": 3, "tr": "Poyezddan tushayotganda soyabonni unutib qoldirmaslikka e'tibor bering.", "stem": "電車を降りる（　）、傘を忘れないようにしてください。", "explanation_uz": "「〜に際して / 際(に)」= ...aynan shu vaziyatda / paytida (rasmiy uslub)."}, {"id": "t7-g1-35", "options": ["せいか", "ことか", "わけか", "ものか"], "answer": 1, "tr": "Kecha yomg'irda qolib iviganim sababli bo'lsa kerak, bugun nimagadir isitmalayapman.", "stem": "きのう雨にぬれた（　）、今日はなんとなく熱っぽい。", "explanation_uz": "「〜せい（で/か）」= ...yomon natijaning sababi bo'lib (tufayli)."}, {"id": "t7-g1-36", "options": ["笑って", "笑うどころで", "笑わずには", "笑わなくて"], "answer": 3, "tr": "Hayvonchalarning yoqimli harakatlariga kulmasdan tura olmadim.", "stem": "動物たちのかわいい動きに、（　）はいられませんでした。", "explanation_uz": "「〜ずにはいられない」= ...qilmasdan tura olmaslik."}, {"id": "t7-g1-37", "options": ["楽しいらしく", "楽しげに", "楽しいように", "楽しいそうに"], "answer": 2, "tr": "Boshlig'i bilan urishib kompaniyadan ketgan u qiz yangi ish joyida zavq bilan (quvnoq qiyofada) ishlamoqda.", "stem": "上司とけんかして会社を辞めた彼女は、新しい職場で生き生きと（　）働いている。", "explanation_uz": "「〜げ（に）」= ...kayfiyat/ko'rinish bilan (－げ)."}, {"id": "t7-g1-38", "options": ["これ", "それ", "あれ", "どれ"], "answer": 1, "tr": "A: «Bu reja bo'yicha biron fikringiz bormi?» — B: «Xo'sh, aytarli (alohida) biror fikrim yo'q.»", "stem": "A「この計画について、なにか意見がありますか。」\\nB「そうですね、（　）と言ってありません。」", "explanation_uz": "「これと言って（〜ない）」= aytarli hech narsa yo'q."}, {"id": "t7-g1-39", "options": ["詰めて", "入れて", "注いで", "込めて"], "answer": 4, "tr": "Menga yordam bergan meribon insonga minnatdorchilik tuyg'usini jo qilib xat yozdim.", "stem": "助けてくれた人に、感謝の気持ちを（　）手紙を書いた。", "explanation_uz": "「〜を込めて」= chin ko'ngildan tuyg'u/mehr bilan qo'shib."}, {"id": "t7-g1-40", "options": ["生活する最中に", "生活する上では", "生活しようとするために", "生活することには"], "answer": 2, "tr": "Qishloqda yashash nuqtai nazaridan (yashash uchun) mashina zarur bo'lgani uchun haydovchilik maktabiga borishga qaror qildim.", "stem": "田舎で（　）車が必要なので、自動車学校に行くことにした。", "explanation_uz": "「〜上では」= ...nuqtai nazaridan, ...jihatdan qaraganda."}, {"id": "t7-g1-41", "options": ["食べさせてあげよう", "食べてあげよう", "食べさせてしまおう", "食べてしまおう"], "answer": 1, "tr": "Yangi taomni o'rganganim sababli, darhol tayyorlab oyimga yegizib (tatitib) ko'ray deb o'ylayapman.", "stem": "新しい料理を覚えたので、さっそく作って母に（　）と思う。", "explanation_uz": "「食べさせてあげる」= yegizib bermoq / taomdan bahramand qilmoq."}, {"id": "t7-g1-42", "options": ["しておけばよかった", "しないでおけばよかった", "したままでよかった", "しないままでよかった"], "answer": 1, "tr": "Astoydil hujjatni tayyorlagan bo'lsam-da, ko'p xatolar chiqib qoldi. Oldindan tekshirib qo'ysam bo'lar ekan!", "stem": "がんばって書類を作ったのに、ミスがたくさん見つかってしまった。確認（　）よ。", "explanation_uz": "「〜ておけばよかった」= ...qilib qo'yganimda yaxshi bo'lardi (afsus ifodasi)."}, {"id": "t7-g1-43", "options": ["出ただけあって", "出ているにしては", "出ただけあっては", "出ているにしろ"], "answer": 2, "tr": "Maeda mashhur universitetning filologiya fakultetini bitirganiga qaramasdan (nisbatan olganda), so'zlarni tez-tez noto'g'ri ishlatadi.", "stem": "前田君は有名な大学の文学部を（　）、よく言葉を間違えて使う。", "explanation_uz": "「〜にしては」= ...deb hisoblaganda unga xos bo'lmagan tarzda / kutilganidan boshqacha."}, {"id": "t7-g1-44", "options": ["あきらめざるを得ない", "あきらめるわけにいかない", "あきらめられない", "あきらめかねる"], "answer": 1, "tr": "Men musiqa universitetiga kirishni istayman, lekin oilamizning moliyaviy ahvolida voz kechishga majbur bo'laman shekilli.", "stem": "私は音楽大学に行きたいのだが、我が家の経済状態では（　）だろう。", "explanation_uz": "「〜ざるを得ない」= ...qilishdan boshqa iloji yo'q / majbur bo'lmoq."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi yulduzcha (★) o'rniga keladigan eng to'g'ri variantni tanlang.", "questions": [{"id": "t7-g2-45", "options": ["ことには", "使って", "実際に", "みない"], "answer": 4, "tr": "U mahsulot qanchalik ajoyib bo'lmasin, amalda ishlatib ko'rilmaguncha ishonib bo'lmaydi.", "explanation_uz": "Tartib: 実際に(3) 使って(2) みない(4) ことには(1) → 「〜てみないことには (ishlatib ko'rmaguncha)」", "prefix": "その製品がどんなにすばらしくても、", "suffix": "信用できない。", "starPos": 3, "order": [3, 2, 4, 1]}, {"id": "t7-g2-46", "options": ["遠足は", "とっての", "大人に", "とって"], "answer": 1, "tr": "Kichik bolalar uchun ekskursiya kattalar uchun xorijiy sayohat kabi katta quvonchdir.", "explanation_uz": "Tartib: とっての(2) 遠足は(1) 大人に(3) とって(4) → Yulduzcha 2-o'rinda: 遠足は(1)", "prefix": "小さな子どもに", "suffix": "の海外旅行くらい大きな楽しみだ。", "starPos": 2, "order": [2, 1, 3, 4]}, {"id": "t7-g2-47", "options": ["ないが", "わけでも", "許さない", "なら"], "answer": 2, "tr": "Chin dildan pushaymon bo'layotgan bo'lsa kechirmayman ham emas-ku, ammo durustroq uzr so'rashini xohlayman.", "explanation_uz": "Tartib: なら(4) 許さない(3) わけでも(2) ないが(1) → Yulduzcha 3-o'rinda: わけでも(2)", "prefix": "心から反省している", "suffix": "ちゃんと謝ってほしい。", "starPos": 3, "order": [4, 3, 2, 1]}, {"id": "t7-g2-48", "options": ["考え", "思い切って", "末", "抜いた"], "answer": 3, "tr": "Uch kun davomida chuqur o'ylab bo'lgach, nihoyat qat'iy qarorga kelib ishdan bo'shashga qaror qildim.", "explanation_uz": "Tartib: 考え(1) 抜いた(4) 末(3) 思い切って(2) → 「〜考え抜いた末 (chuqur o'ylash natijasida)」", "prefix": "3日間、", "suffix": "会社を辞めることにしました。", "starPos": 3, "order": [1, 4, 3, 2]}, {"id": "t7-g2-49", "options": ["思い出そう", "何だっ", "と", "たっけ"], "answer": 4, "tr": "Anavi xonandaning ismi nima edi deb eslashga qancha urinmayin, aslo eslay olmayapman.", "explanation_uz": "Tartib: 何だっ(2) たっけ(4) と(3) 思い出そう(1) → Yulduzcha 2-o'rinda: たっけ(4)", "prefix": "あの歌手の名前は", "suffix": "としても、どうしても思い出せない。", "starPos": 2, "order": [2, 4, 3, 1]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh o'rinlarga eng mos keluvchi javobni tanlang.", "passage": "現代の日本人の30〜34歳の人でまだ結婚していない人は、男性が50%近く、女性が約30%で、これは30年前に比べて男性は3倍、女性は4倍になっている。\n　結婚しない理由は、1つには長引く不景気で、経済的に家庭を持つ自信のない【 50-a 】が増えたことがある。また、世間も「人は絶対、結婚するべきだ」という考え方が薄くなってきた。【 50-b 】でも、コンビニや電化製品のおかげで、家事をしてくれる人が必要なくなった。女性も仕事を持つ人が多くなり、生活のために【 51 】ことも理由の1つだ。\n　しかし親【 52 】「若いうちはいいけれど、年を取ってから1人ではさびしい」と心配でたまらず、「何とか結婚してほしい」と悩む人が多い。\n　そこである会社が親同士の「代理お見合いパーティー」を開いたところ、多くの申し込みがあったそうだ。\n　親たちは子どもの写真と仕事や趣味を書いた紙を持ち、それを異性の子どもを持つ親に見せて自分の子どもを売り込む。自分の娘や息子もすでに【 53 】、親も必死である。「大人ならば、結婚相手【 54 】、親に頼らず自分で見つけたらどうだ」と言う人も多い。\n　しかし考えれば、日本ではちょっと前までは子どもの結婚相手を、親、特に父親が決めたものだ。そう考えれば、それほど新しいことではないのかもしれない。", "questions": [{"id": "t7-g3-50", "options": ["a 独身者 ／ b 独身", "a 既婚者 ／ b 既婚", "a 独身者 ／ b 既婚", "a 既婚者 ／ b 独身"], "answer": 1, "tr": "a: 独身者 (bo'ydoqlar/turmush qurmaganlar), b: 独身 (bo'ydoqlik holati).", "explanation_uz": "50-a bo'sh joyga «独身者» (oila qurmagan insonlar), 50-b ga esa «独身でも» (oila qurmasdan yolg'iz bo'lsa ham) mos keladi.", "blankNo": 50}, {"id": "t7-g3-51", "options": ["結婚しなくてはならなかった", "結婚せざるを得なくなった", "結婚しなくてもよくなった", "結婚してはいられなくなった"], "answer": 3, "tr": "...ayollar ham ishli bo'lib, tirikchilik uchun turmush qurish shart bo'lmay qolganligi...", "explanation_uz": "「〜しなくてもよくなった」= ...qilishga hojat qolmay qoldi / shart bo'lmay qoldi.", "blankNo": 51}, {"id": "t7-g3-52", "options": ["によっては", "からすると", "でさえ", "については"], "answer": 2, "tr": "Lekin ota-onalar nuqtai nazaridan qaralganda...", "explanation_uz": "「親からすると」= ota-onalar nuqtai nazaridan / ota-onalar qarashi bo'yicha.", "blankNo": 52}, {"id": "t7-g3-53", "options": ["若いからといって", "若いからこそ", "若くないとはいえ", "若くないとあって"], "answer": 4, "tr": "O'zlarining qiz yoki o'g'illari allaqachon yosh emasligi ma'lum bo'lgani sababli, ota-onalar ham jon-jahdi bilan harakat qilmoqda.", "explanation_uz": "「〜とあって」= ...vaziyat bo'lganligi sababli.", "blankNo": 53}, {"id": "t7-g3-54", "options": ["のみは", "くらいは", "さえ", "こそ"], "answer": 2, "tr": "«Katta odam bo'lgandan keyin, hech bo'lmaganda turmush o'rtog'ini ota-onaga tayanmasdan o'zi topishi kerak emasmi...»", "explanation_uz": "「結婚相手くらいは」= hech bo'lmaganda umr yo'ldoshini bo'lsa ham.", "blankNo": 54}]}]}]}, "8": {"id": 8, "title_jp": "第8回 模擬テスト", "title_uz": "8-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t8-v1-1", "options": ["せんじょ", "せんざい", "せんじょう", "せんたく"], "answer": 3, "tr": "Idish yuvish mashinasi (posudomoyka) ishlatib ko'rilsa, noqulay tomonlari ham bor.", "stem": "食器【洗浄機】は、使ってみると不便なところもある。", "reading": "せんじょう", "explanation_uz": "洗浄 → せんじょう (yuvish, tozalash)"}, {"id": "t8-v1-2", "options": ["しんけいしつ", "しんきょうしつ", "じんけいしつ", "じんきょうしつ"], "answer": 1, "tr": "Kichik hamkasbning (kouhai) birinchi taassuroti asabiy/o'ta sezgir va ishonchsizdek tuyuldi.", "stem": "後輩の第一印象は【神経質】で頼りない感じだ。", "reading": "しんけいしつ", "explanation_uz": "神経質 → しんけいしつ (asabiy, serzarda, o'ta ta'sirchan)"}, {"id": "t8-v1-3", "options": ["ざいもう", "さいぼう", "さいもう", "さいほう"], "answer": 4, "tr": "Rivojlanayotgan davlatlar ayollari daromad topa olishi uchun tikuvchilik mahorati bo'yicha o'quv-trening boshlandi.", "stem": "途上国の女性が収入を得られるように、【裁縫】技術の研修を開始した。", "reading": "さいほう", "explanation_uz": "裁縫 → さいほう (tikuvchilik, kiyim tikish)"}, {"id": "t8-v1-4", "options": ["うのう", "ゆうえき", "ゆうのう", "ゆうこう"], "answer": 3, "tr": "Iqtisodiyot shaharlarga yig'ilayotgan qobiliyatli va g'ayratli insonlarning mehnati evaziga o'sib kelgan deyish mumkin.", "stem": "経済は、都市に集まってくる【有能】で意欲のある人々によって成長してきたといえる。", "reading": "ゆうのう", "explanation_uz": "有能 → ゆうのう (iqtidorli, salohiyatli, qobiliyatli)"}, {"id": "t8-v1-5", "options": ["ふせぐ", "かせぐ", "そそぐ", "かつぐ"], "answer": 2, "tr": "Osonlikcha pul topishni (ishlamay daromad ko'rishni) uyat bilmaydigan yaponlar ko'payib ketdi.", "stem": "楽をして【稼ぐ】ことを恥としない日本人が多くなってしまった。", "reading": "かせぐ", "explanation_uz": "稼ぐ → かせぐ (pul topmoq, daromad qilmoq)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t8-v2-6", "options": ["不政", "不成", "不正", "不制"], "answer": 3, "tr": "Ba'zi odamlar noqonuniy yo'l bilan naf ko'radigan jamiyat bo'lishi aslo mumkin emas.", "stem": "一部の人間が【ふせい】に利益を得るような世の中であってはならない。", "reading": "ふせい", "explanation_uz": "不正 → ふせい (adolatsiz, noqonuniy, nohaq)"}, {"id": "t8-v2-7", "options": ["届", "居", "展", "届"], "answer": 4, "tr": "Turmush o'rtog'im bilan bafurja gaplashib olgach, ajrashish to'g'risida ariza (xabarnoma) topshirdim.", "stem": "妻とよく話し合ったうえで、離婚【とどけ】を出した。", "reading": "とどけ", "explanation_uz": "届 → とどけ (ariza, xabarnoma, bildirishnoma)"}, {"id": "t8-v2-8", "options": ["分責", "分析", "分積", "分折"], "answer": 2, "tr": "O'tgan yillardagi savollarni tahlil qilib, qisqa muddatda universitetga kirish salohiyatini shakllantirmoqchiman.", "stem": "過去問題を【ぶんせき】し、短期間で大学合格の力を身につけるつもりだ。", "reading": "ぶんせき", "explanation_uz": "分析 → ぶんせき (tahlil, analiz)"}, {"id": "t8-v2-9", "options": ["天燃", "天然", "伝燃", "伝然"], "answer": 2, "tr": "Shakar dalalardan olinadigan tabiiy ta'm beruvchidir (ziravor).", "stem": "砂糖は畑からできる【てんねん】の調味料だ。", "reading": "てんねん", "explanation_uz": "天然 → てんねん (tabiiy)"}, {"id": "t8-v2-10", "options": ["注いで", "沿いで", "泊いで", "沖いで"], "answer": 1, "tr": "Bizning kompaniya «ekologik toza mahsulotlar»ni ishlab chiqishga butun kuchini bag'ishlamoqda (sarflamoqda).", "stem": "我が社は「環境にやさしい商品」の開発に力を【そそいで】います。", "reading": "そそいで", "explanation_uz": "注ぐ → そそぐ (kuch/e'tibor bag'ishlamoq, quymoq)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t8-v3-11", "options": ["者", "人", "線", "陣"], "answer": 3, "tr": "Moda olamining oldingi saflarida (birinchi chizig'ida) faoliyat yuritadi.", "stem": "ファッション界の第一（　）で活躍する。", "explanation_uz": "第一線 (だいいっせん) = eng oldingi saf, yetakchi pozitsiya"}, {"id": "t8-v3-12", "options": ["現", "今", "在", "再"], "answer": 1, "tr": "O'z vataningizdagi manzilni emas, hozir yashab turgan joriy manzilingizni yozing.", "stem": "あなたの国の住所ではなく、今住んでいる（　）住所を書いてください。", "explanation_uz": "現住所 (げんじゅうしょ) = hozirgi yashash manzili"}, {"id": "t8-v3-13", "options": ["雨", "荒", "悪", "激"], "answer": 3, "tr": "Tog'ga ko'p chiqaman, biroq yomon ob-havo bo'lsa darhol ortga qaytishni qoida qilganman.", "stem": "よく山に登るが、（　）天候になったらすぐ引き返すことにしている。", "explanation_uz": "悪天候 (あくてんこう) = noqulay/yomon ob-havo"}, {"id": "t8-v3-14", "options": ["値", "面", "感", "下"], "answer": 2, "tr": "Ushbu transport vositasida xavfsizlik jihatidan muammo mavjud.", "stem": "この乗り物は安全（　）での問題がある。", "explanation_uz": "安全面 (あんぜんめん) = xavfsizlik jihati/tomoni"}, {"id": "t8-v3-15", "options": ["反", "非", "悪", "不"], "answer": 4, "tr": "U xaltadek osilgan noqulay va beo'xshov kiyim kiyib olgan.", "stem": "彼はだぶだぶで（　）格好な服を着ている。", "explanation_uz": "不格好 (ぶかっこう) = beo'xshov, xunuk, beo'rin"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'zni tanlang.", "questions": [{"id": "t8-v4-16", "options": ["着々", "近々", "急に", "にわかに"], "answer": 2, "tr": "Kuni kecha uni ota-onamga tanishtirdim. Yaqin kunlarda to'y o'tkazmoqchimiz.", "stem": "先日、彼を両親に紹介しました。（　）結婚式をあげるつもりです。", "reading": "ちかぢか", "explanation_uz": "近々 (ちかぢか) = yaqinda, tez kunlarda"}, {"id": "t8-v4-17", "options": ["バンク", "ハント", "ハンデ", "ハンター"], "answer": 3, "tr": "50 yoshdagi noqulaylikni (yosh to'sig'ini) pisand qilmay, qayta ishga joylashishi hal bo'ldi.", "stem": "50代という年齢の（　）をものともせず、再就職が決まった。", "explanation_uz": "ハンデ (handicap) = noqulaylik, kamchilik, to'siq"}, {"id": "t8-v4-18", "options": ["震える", "越える", "支える", "覚える"], "answer": 4, "tr": "Ishda ham, o'qishda ham o'zini unutadigan darajada berilib ketishning o'zidan katta quvonch his qilaman.", "stem": "仕事でも勉強でも我を忘れるほど夢中になることそのものに、喜びを（　）。", "reading": "おぼえる", "explanation_uz": "（喜びを）覚える = quvonch/hissiyot tuyg'usini his qilmoq"}, {"id": "t8-v4-19", "options": ["重要", "主要", "重大", "長大"], "answer": 2, "tr": "Dunyoning yetakchi 7 ta davlati (Katta yettilik) yig'ilib, xalqaro anjuman o'tkazildi.", "stem": "世界の（　）7カ国が集まって、国際会議が開かれた。", "reading": "しゅよう", "explanation_uz": "主要 (しゅよう) = asosiy, yetakchi"}, {"id": "t8-v4-20", "options": ["だらしない", "もったいない", "みっともない", "ものすごい"], "answer": 3, "tr": "Birovning narsasiga ko'z olaytirish kabi uyatli (sharmandali) qiliqni bas qil.", "stem": "人のものを欲しがるなんて、（　）まねはやめなさい。", "reading": "みっともない", "explanation_uz": "みっともない = xunuk, sharmandali, uyatli"}, {"id": "t8-v4-21", "options": ["油断", "怠慢", "停止", "休暇"], "answer": 1, "tr": "Hali vaqt bemalol deb beparvolik (xotirjamlik) qilganim sababli, hozir hisobot muddati yetib kelib qiyin ahvoldaman.", "stem": "まだたっぷり時間があると（　）していたため、今レポートの締め切りに追われて大変です。", "reading": "ゆだん", "explanation_uz": "油断 (ゆだん) = xotirjamlikka berilish, hushyorlikni yo'qotish"}, {"id": "t8-v4-22", "options": ["減少", "縮小", "節約", "解約"], "answer": 3, "tr": "Chirmashuvchi o'simliklar bilan soya hosil qilib elektr energiyasi xarajatini tejaymiz.", "stem": "つる性の植物で日陰を作って電気代を（　）する。", "reading": "せつやく", "explanation_uz": "節約 (せつやく) = tejash, iqtisod qilish"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin so'zni tanlang.", "questions": [{"id": "t8-v5-23", "options": ["不安な", "十分な", "危うい", "問題の"], "answer": 2, "tr": "U ishonch bildirishga arziydigan (yetarli darajada ishonchli) inson.", "stem": "彼は信頼するに【足りる】人物だ。", "reading": "たりる", "explanation_uz": "足りる ≈ 十分な (yetarli bo'lgan, arziydigan)"}, {"id": "t8-v5-24", "options": ["おおよそ", "おそらく", "少なくとも", "多ければ"], "answer": 1, "tr": "Bayramga yig'iladigan sayyohlar taxminan 100 ming kishini tashkil qilsa kerak.", "stem": "祭りに集まる観光客は、【ざっと】十万人だろう。", "reading": "ざっと", "explanation_uz": "ざっと ≈ おおよそ (taxminan, chamasi)"}, {"id": "t8-v5-25", "options": ["よっている", "基づく", "違反する", "合っている"], "answer": 3, "tr": "Bu harakat qonunbuzarlik hisoblanadi (qonunga zid).", "stem": "その行動は法律に【触れる】。", "reading": "ふれる", "explanation_uz": "（法に）触れる ≈ 違反する (qonunni buzmoq, ziddiyat keltirib chiqarmoq)"}, {"id": "t8-v5-26", "options": ["信仰上の", "不思議な", "特殊な", "想像上の"], "answer": 4, "tr": "Ibodatxona eshigidagi rasmda to'qima (xayoliy) hayvon tasvirlangan.", "stem": "お寺のふすまの絵は【架空の】動物だ。", "reading": "かくうの", "explanation_uz": "架空 ≈ 想像上 (xayoliy, to'qima, hayotda yo'q)"}, {"id": "t8-v5-27", "options": ["規則", "特色", "方針", "伝統"], "answer": 2, "tr": "Har bir universitetning o'ziga xos xarakteri / o'ziga xosligi (rangi) bo'ladi.", "stem": "大学ごとに、その学校の【カラー】というものがある。", "explanation_uz": "カラー ≈ 特色 (o'ziga xos xususiyat, xarakter)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Berilgan so'zning gapda eng to'g'ri ishlatilgan variantini tanlang.", "questions": [{"id": "t8-v6-28", "options": ["電車の中で騒いでいる子どもにだれも警告しなかった。", "彼は他人の間違いばかり警告するいやな人間だ。", "世界各地の気候変化は人類に地球の異常を警告している。", "二度とこのような失敗をしないよう警告してまいります。"], "answer": 3, "tr": "警告 (keikoku) = ogohlantirish, ogohlikka chaqirish.", "stem": "【警告】の使い方として最もよいものを選びなさい。", "explanation_uz": "「気候変化は地球の異常を警告している」= iqlim o'zgarishi insoniyatni yer shari xavfidan ogohlantirmoqda (to'g'ri ishlatilish)."}, {"id": "t8-v6-29", "options": ["大企業につながりの子会社に入社した。", "来月工事が完成すると道路はつながりになる。", "子どもたちは手をつながりながら歩いている。", "彼は夫の兄で、私とは血のつながりはない。"], "answer": 4, "tr": "つながり (tsunagari) = bog'liqlik, qarindoshlik/aloqa munosabati.", "stem": "【つながり】の使い方として最もよいものを選びなさい。", "explanation_uz": "「血のつながりはない」= qon-qarindoshlik aloqasi yo'q (to'g'ri ishlatilish)."}, {"id": "t8-v6-30", "options": ["今年の会費の余計は来年に回しますのでよろしく。", "会社の経営がうまくいっていないという証拠は余計にある。", "ついひと言余計なことを言って、上司を怒らせてしまった。", "お金なら余計にあるのでどうぞご心配しないでください。"], "answer": 3, "tr": "余計 (yokei) = ortiqcha, keraksiz.", "stem": "【余計】の使い方として最もよいものを選びなさい。", "explanation_uz": "「余計なことを言って」= ortiqcha gap aytib yuborib... (to'g'ri ishlatilish)."}, {"id": "t8-v6-31", "options": ["法律上は罪にならないが、世間が許しません。", "大人になったら広い世間を旅行してみたい。", "退職したら畑仕事でもしてのんびり世間を送りたい。", "若者の世間ではそんなことは常識だそうだ。"], "answer": 1, "tr": "世間 (seken) = jamiyat, jamoatchilik, el-yurt qarashi.", "stem": "【世間】の使い方として最もよいものを選びなさい。", "explanation_uz": "「世間が許しません」= jamoatchilik (el-yurt) kechirmaydi (to'g'ri ishlatilish)."}, {"id": "t8-v6-32", "options": ["テレビが故障したので、新しいものと交代した。", "昼と夜姉妹で交代しながら、母の看病をした。", "このぼくの本と君の本を交代しないか。", "彼は文系志望だったのだが、理系に交代した。"], "answer": 2, "tr": "交代 (koutai) = navbatlashish, almashib turish.", "stem": "【交代】の使い方として最もよいものを選びなさい。", "explanation_uz": "「姉妹で交代しながら」= opa-singillar navbatlashib... (to'g'ri ishlatilish)."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi qavs ichiga eng mos keluvchi grammatik shaklni tanlang.", "questions": [{"id": "t8-g1-33", "options": ["来るか", "来たか", "来つつ", "来ないか"], "answer": 2, "tr": "Oilaning barcha a'zolari to'planib, go'yo Yangi yil bayrami kelgandek bo'ldi.", "stem": "家族全員が集まって、まるで正月が（　）のようだ。", "explanation_uz": "「まるで〜かのようだ」= go'yo xuddi ...dek (tashbeh ifodasi)."}, {"id": "t8-g1-34", "options": ["して", "すれば", "したら", "しないと"], "answer": 1, "tr": "A: «Sashimi to'g'rashni o'rgating.» — B: «Avvalo, pichoqni ushlashingizdan boshlab noto'g'ri-ku.»", "stem": "A「おさしみの切り方を教えて。」\\nB「まず、ほうちょうの持ち方から（　）間違っているよ。」", "explanation_uz": "「〜からして」= ...dan boshlab hatto (eng asosiy/boshlang'ich nuqtadan misol keltirish)."}, {"id": "t8-g1-35", "options": ["によっては", "にとっては", "については", "にかけては"], "answer": 2, "tr": "Siz uchun cho'ntak puli bo'lishi mumkin, lekin men uchun 100 ming iyen katta pul.", "stem": "あなたにはおこづかいでも、私（　）10万円は大金です。", "explanation_uz": "「〜にとって（は）」= ...shaxs uchun, ...nuqtai nazaridan."}, {"id": "t8-g1-36", "options": ["あり得る", "あり得ない", "あるらしい", "ありそうだ"], "answer": 2, "tr": "Hatto Xokkaydo bo'lsa ham, avgustda qor yog'ishi mumkin bo'lmagan hodisadir.", "stem": "いくら北海道でも8月に雪が降るなんて、（　）。", "explanation_uz": "「〜得ない（えない）」= bo'lishi mumkin emas / imkonsiz."}, {"id": "t8-g1-37", "options": ["泣くよう", "泣くそう", "泣いたよう", "泣きそう"], "answer": 4, "tr": "Lin professordan qattiq tanbeh olib, yig'lab yuboray degan holatda edi.", "stem": "リンさんは教授に厳しく指導され、（　）になっていた。", "explanation_uz": "「動詞ます形 ＋ そう」= ...holatga tushay degan (hozir sodir bo'lish arafasida)."}, {"id": "t8-g1-38", "options": ["上は", "中は", "下は", "間は"], "answer": 1, "tr": "Turmush qurgach qonun jihatidan er yoki xotin familiyasini olish mumkin bo'lsa-da, 95% holatda erkakning familiyasi olinadi.", "stem": "結婚したら法律（　）男女どちらの姓になってもよいが、95％が男性の姓になっている。", "explanation_uz": "「〜上（は）」= ...nuqtai nazaridan / rasmiy me'yor jihatidan."}, {"id": "t8-g1-39", "options": ["申される方が", "言っている方が", "おっしゃる方が", "呼ばれる方が"], "answer": 3, "tr": "A: «Direktor janoblari, Yamamoto degan shaxs keldilar.» — B: «Bu yerga taklif qiling.»", "stem": "A「社長、山本さまと（　）が見えましたが。」\\nB「こちらにお通ししてくれ。」", "explanation_uz": "「〜とおっしゃる方」= ...deb aytuvchi shaxs (hurmat shakli)."}, {"id": "t8-g1-40", "options": ["間違えてしまった", "間違えずにすんだ", "間違えるはずだった", "間違えようがなかった"], "answer": 1, "tr": "Savolni yaxshilab o'qimaganim sababli javobni xato belgilab qo'ydim.", "stem": "よく問題を読まなかったせいで、答えを（　）。", "explanation_uz": "「〜せいで」salbiy oqibat bilan birga keladi → 間違えてしまった."}, {"id": "t8-g1-41", "options": ["行かないままなら", "行くままなら", "行かないくらいなら", "行くくらいなら"], "answer": 4, "tr": "Isitma baland bo'lib turib majburlab maktabga borgandan ko'ra, uyda dam olganing ma'qul.", "stem": "熱が高いのに無理をして学校に（　）、休んだほうがいいよ。", "explanation_uz": "「〜くらいなら」= ...qilgandan ko'ra (yomonroq variantni qiyoslash)."}, {"id": "t8-g1-42", "options": ["をするはずがない", "をしないはずがない", "をすることもない", "をしないこともない"], "answer": 1, "tr": "Qanchalik qiyin ahvolda yashayotgan bo'lmasin, vijdonli u insonning o'g'irlik qilishi aslo mumkin emas.", "stem": "いくら生活に困っているからと言って、まじめな彼が盗み（　）。", "explanation_uz": "「〜はずがない」= mutlaqo bo'lishi mumkin emas / aslo unday emas."}, {"id": "t8-g1-43", "options": ["捨てかねないで", "捨てようかと思って", "捨てきれないで", "捨てたがって"], "answer": 3, "tr": "Xonanda bo'lishimga ota-onam qarshi bo'lib universitetga kirgan bo'lsam-da, orzuyimdan butunlay voz kecha olmayapman.", "stem": "歌手になることを両親に反対されて大学に進学したが、夢を（　）いる。", "explanation_uz": "「〜きれない」= oxirigacha / butunlay qila olmaslik."}, {"id": "t8-g1-44", "options": ["やめられることになった", "やめてあげることになった", "やめさせてもらうことになった", "やめさせられることになった"], "answer": 4, "tr": "Soliq pullarini o'z manfaati uchun sarflagan shahar hokimi fuqarolarning bosimi natijasida lavozimidan chetlatildi (majburiy ketkazildi).", "stem": "税金を自分のために使った市長は、市民の力によって（　）。", "explanation_uz": "「〜させられる」= majburlanmoq (majhul-istak shakli) + 「〜ことになる」."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi yulduzcha (★) o'rniga keladigan eng to'g'ri variantni tanlang.", "questions": [{"id": "t8-g2-45", "options": ["会社に", "入ってくる", "会社の", "たび"], "answer": 2, "tr": "Yangi xodim kompaniyaga kelgan har gal kompaniya qoidalarini o'rgatib qo'yish kerak.", "explanation_uz": "Tartib: 会社に(1) 入ってくる(2) たび(4) 会社の(3) → Yulduzcha 2-o'rinda: 入ってくる(2)", "prefix": "新しい社員が", "suffix": "規則を教えてやらなければいけない。", "starPos": 2, "order": [1, 2, 4, 3]}, {"id": "t8-g2-46", "options": ["待たされて", "加えて", "次々と", "長い時間"], "answer": 4, "tr": "Bu jaziramaga qo'shimcha ravishda uzoq vaqt kuttirilib, ketma-ket yiqilib tushganlar bo'ldi.", "explanation_uz": "Tartib: 加えて(2) 長い時間(4) 待たされて(1) 次々と(3) → Yulduzcha 2-o'rinda: 長い時間(4)", "prefix": "この暑さに", "suffix": "倒れる人が出た。", "starPos": 2, "order": [2, 4, 1, 3]}, {"id": "t8-g2-47", "options": ["も", "が", "逃げように", "逃げ道"], "answer": 1, "tr": "Ko'z o'ngimda ayiq paydo bo'ldi, orqam esa vodiy bo'lib, qochishga yo'l ham yo'qligidan shoshilib daraxtga chiqdim.", "explanation_uz": "Tartib: 逃げように(3) も(1) 逃げ道(4) が(2) → Yulduzcha 2-o'rinda: も(1)", "prefix": "目の前に熊がいたが、後ろは谷で", "suffix": "なく、あわてて木に登った。", "starPos": 2, "order": [3, 1, 4, 2]}, {"id": "t8-g2-48", "options": ["間違い", "名前", "だらけで", "だけが"], "answer": 2, "tr": "Bu inshodagi kanjilar xatolarga to'la bo'lib, faqatgina ismi to'g'ri kanjida yozilgan.", "explanation_uz": "Tartib: 間違い(1) だらけで(3) 名前(2) だけが(4) → Yulduzcha 3-o'rinda: 名前(2)", "prefix": "この作文の漢字は", "suffix": "正しい漢字で書けている。", "starPos": 3, "order": [1, 3, 2, 4]}, {"id": "t8-g2-49", "options": ["と", "から", "言っても", "必ず"], "answer": 3, "tr": "Zamonaviy davrda universitetni tamomlagan bilan har doim ham ish topish kafolatlangan emas.", "explanation_uz": "Tartib: から(2) と(1) 言っても(3) 必ず(4) → Yulduzcha 3-o'rinda: 言っても(3)", "prefix": "現代は大学を出た", "suffix": "就職できない時代だ。", "starPos": 3, "order": [2, 1, 3, 4]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh o'rinlarga eng mos keluvchi javobni tanlang.", "passage": "どの時代にも、かならず流行語【 50 】。\n　たとえば「サボる」などということばは、もうすっかり普通になってしまったが、あれはもともと「サボタージュ（注1）」からきている。\n　それから、「セコい」ということば、あれはもともとは「セコンドハンド（注2）」という外来語から出たことばである、その略語（注3）である「セコハン」を経由（注4）して、「セコハン」は、多くの場合「【 51-a 】古物」という意味だから、「あいつが着ているものは、どうもセコイ」というのはよっぽど古いもの、【 51-b 】ものを着ているという意味になった。そこから「けちんぼう」という意味が派生（注5）してきて、「お前、セコイこと言うなよ」みたいに使われるようになったのである。\n　このように、ことばとしてどんどん市民権を獲得してしまったことばもあるのである。今「サボる」「セコい」と聞いても、それが【 52 】だと思う人などほとんどいないかもしれない。\n　いまでは、ひらがなで「さぼる」「せこい」と書くようにさえなったから、もはや日本語【 53 】。けれども、日本語の語彙として定着するまでにはやはり時間が必要である。さぼる、せこい、などでもおそらく出現してから五十年以上は経っているように想像される。\n　したがって、まだ定着しないうちの、生な流行語のようなものはやはり、【 54 】のが上品な話し方だと言えるのである。\n（林望『日本語は死にかかっている』NTT出版）", "questions": [{"id": "t8-g3-50", "options": ["といったわけがある", "というわけがある", "といったことがある", "というものがある"], "answer": 4, "tr": "Har qanday zamonda albatta urf bo'lgan so'zlar (sleng/moda iboralar) mavjud bo'ladi.", "explanation_uz": "「〜というものがある」= ...kabi narsa/hodisa mavjud bo'ladi.", "blankNo": 50}, {"id": "t8-g3-51", "options": ["a 高い ／ b 安い", "a 安いらしい ／ b 高いらしい", "a 高いような ／ b 安いような", "a 安っぽい ／ b 安っぽい"], "answer": 4, "tr": "a: 安っぽい (arzonbaho ko'rinishdagi), b: 安っぽい (arzonbaho).", "explanation_uz": "51-a va 51-b ikkalasiga ham «安っぽい» (arzonbaho, sifatsiz) mos tushadi.", "blankNo": 51}, {"id": "t8-g3-52", "options": ["日本語", "外来語", "流行語", "略語"], "answer": 2, "tr": "Hozir «saboru» yoki «sekoi» so'zlarini eshitib ularni o'zlashma so'z (gairaigo) deb o'ylaydigan odam deyarli yo'q.", "explanation_uz": "「外来語 (gairaigo)」= chet tilidan kirib kelgan o'zlashma so'z.", "blankNo": 52}, {"id": "t8-g3-53", "options": ["として完全に忘れ去られたのだろう", "としてすっかり定着したのであろう", "としてはけっして使えないだろう", "とはまったく言えないだろう"], "answer": 2, "tr": "...yapon tili sifatida butunlay mustahkam o'rnashib qolgan bo'lsa kerak.", "explanation_uz": "「日本語としてすっかり定着したのであろう」= yapon tili sifatida to'liq singib ketgan bo'lsa kerak.", "blankNo": 53}, {"id": "t8-g3-54", "options": ["できるだけ使う", "できれば使う", "できるかぎり使わない", "少しは使ってみる"], "answer": 3, "tr": "Shuning uchun, hali to'liq singib ketmagan xom yangi iboralarni imkon qadar ishlatmaslik madaniyatli nutq uslubi hisoblanadi.", "explanation_uz": "「できるかぎり使わない」= imkon qadar ishlatmaslik.", "blankNo": 54}]}]}]}, "9": {"id": 9, "title_jp": "第9回 模擬テスト", "title_uz": "9-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t9-v1-1", "options": ["すいじゅん", "すいしゅん", "ひょうじゅん", "ひょうしゅん"], "answer": 3, "tr": "Vazni me'yoriy (standart) bo'lsa ham, semizman deb xavotirlanadigan ayollar ko'p.", "stem": "【標準的】な体重なのに、太っていると悩む女性が多い。", "reading": "ひょうじゅん", "explanation_uz": "標準的 → ひょうじゅんてき (me'yoriy, standart)"}, {"id": "t9-v1-2", "options": ["せいぼう", "こうぼう", "せいほう", "こうほう"], "answer": 2, "tr": "Parlamentda hukmron partiya va muxolifat partiyasi o'rtasida hujum va mudofaa (keskin kurash) davom etmoqda.", "stem": "国会では、与党と野党の【攻防】が続いている。", "reading": "こうぼう", "explanation_uz": "攻防 → こうぼう (hujum va himoya, keskin kurash)"}, {"id": "t9-v1-3", "options": ["とぼしい", "ただしい", "くわしい", "きびしい"], "answer": 3, "tr": "To'liq tibbiy ko'rikda (Ningen Dock) shifokordan yakkama-yakka tekshiruv natijalarining batafsil tushuntirishini olish mumkin.", "stem": "人間ドックは医師から1対1で検査結果の【詳しい】説明が受けられる。", "reading": "くわしい", "explanation_uz": "詳しい → くわしい (batafsil, mufassal)"}, {"id": "t9-v1-4", "options": ["けっかん", "けってん", "けっぽう", "けつらく"], "answer": 1, "tr": "Talabalar bilim darajasi pasayishining sababi qabul imtihonlari tizimidagi nuqson (kamchilik) deb hisoblaydiganlar ko'p.", "stem": "大学生の学力低下の原因は入試制度の【欠陥】だと主張する人は多い。", "reading": "けっかん", "explanation_uz": "欠陥 → けっかん (nuqson, kamchilik, defekt)"}, {"id": "t9-v1-5", "options": ["だてかんばん", "たてかんばん", "たてがんばん", "だてがんはん"], "answer": 2, "tr": "Magistral yo'l bo'yidagi o'rnatma reklama taxtasi (shit) ancha yuqori reklama samarasiga ega.", "stem": "国道沿いの【立て看板】にはかなりの広告効果がある。", "reading": "たてかんばん", "explanation_uz": "立て看板 → たてかんばん (tik turuvchi reklama taxtasi/shiti)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t9-v2-6", "options": ["緩らぐ", "揺らぐ", "震らぐ", "振らぐ"], "answer": 2, "tr": "Imtihon topshiradigan universitetni tanlagan bo'lsam-da, rostdan ham shu to'g'rimi deb ko'nglim ikkilanmoqda (chayqalmoqda).", "stem": "受験する大学を決めたものの、これで本当にいいのかと気持ちが【ゆらぐ】。", "reading": "ゆらぐ", "explanation_uz": "揺らぐ → ゆらぐ (chayqalmoq, ikkilanmoq, beqaror bo'lmoq)"}, {"id": "t9-v2-7", "options": ["与期", "余期", "世期", "予期"], "answer": 4, "tr": "Hayot kutilmagan hodisalarning ketma-ketligidan iborat, shuning uchun ko'p ham siqilmaslik kerak.", "stem": "人生は【よき】せぬことの連続なんだから、あまりくよくよしないほうがいいよ。", "reading": "よき", "explanation_uz": "予期 → よき (oldindan kutish/rejalash; 予期せぬ = kutilmagan)"}, {"id": "t9-v2-8", "options": ["濃くて", "巧くて", "厚くて", "密くて"], "answer": 1, "tr": "Bu kitobning mazmuni juda boy (mazmundor/to'laqonli) bo'lib, meni qoniqtirdi.", "stem": "この本は内容が【こくて】満足した。", "reading": "こくて", "explanation_uz": "濃い → こい (quyug', boy, mazmundor)"}, {"id": "t9-v2-9", "options": ["盗い", "襲い", "狙い", "追い"], "answer": 3, "tr": "Mina uzoq vaqt davomida insonlarni farqsiz nishonga olib keluvchi dahshatli quroldir.", "stem": "地雷は長期にわたって無差別に人々を【ねらい】続ける、恐ろしい兵器だ。", "reading": "ねらい", "explanation_uz": "狙う → ねらう (mo'ljalga olmoq, nishonga olmoq)"}, {"id": "t9-v2-10", "options": ["避中", "途中", "道中", "逐中"], "answer": 2, "tr": "Uyga qaytish yo'lida mototsikldagi kishi sumkamni yulqib qochdi.", "stem": "帰宅【とちゅう】にバイクに乗った男にバッグをひったくられた。", "reading": "とちゅう", "explanation_uz": "途中 → とちゅう (yo'l ustida, o'rtasida)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t9-v3-11", "options": ["風", "法", "流", "様"], "answer": 3, "tr": "Mening taom pishirishim birovdan o'rganilgan emas, butunlay o'zimning uslubimdir (o'zicha o'rgangan).", "stem": "私の料理はだれかに習ったのではなく、まったくの自己（　）です。", "explanation_uz": "自己流 (じこりゅう) = o'ziga xos shaxsiy uslub"}, {"id": "t9-v3-12", "options": ["料", "量", "力", "性"], "answer": 2, "tr": "Zamonaviy insonlarga kuniga 10 000 qadam yurishga teng jismoniy harakat miqdori zarur emish.", "stem": "現代人は1日に1万歩歩くだけの運動（　）が必要だそうだ。", "explanation_uz": "運動量 (うんどうりょう) = jismoniy mashq / harakat hajmi"}, {"id": "t9-v3-13", "options": ["判", "系", "番", "紙"], "answer": 4, "tr": "Qiziqarli maqola mahalliy gazetada chop etilgan ekan.", "stem": "おもしろい記事が地方（　）に載っていた。", "explanation_uz": "地方紙 (ちほうし) = mahalliy gazeta/nashr"}, {"id": "t9-v3-14", "options": ["末", "下", "済", "外"], "answer": 4, "tr": "Kutilmagan (taxminlardan tashqari) shaxs yangi prezident (bosh direktor) bo'ldi.", "stem": "予想（　）の人物が新社長になった。", "explanation_uz": "予想外 (よそうがい) = kutilmagan, taxmindan tashqari"}, {"id": "t9-v3-15", "options": ["心", "性", "力", "内"], "answer": 1, "tr": "Yakka-yagona farzand bo'lgan u yigitda boshqalarga suyanish hissi (qaramlik) kuchli.", "stem": "一人っ子の彼は依頼（　）が強い。", "explanation_uz": "依頼心 (いらいしん) = boshqalarga suyanish/tayanib yashash tuyg'usi"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'zni tanlang.", "questions": [{"id": "t9-v4-16", "options": ["そそっかしく", "にぶく", "おしく", "ずうずうしく"], "answer": 1, "tr": "Oyim shoshqaloqlik qilib ko'pincha hamyonini olmasdan bozorga ketib qoladi.", "stem": "母は（　）てよく財布を持たずに買い物に行ってしまう。", "reading": "そそっかしい", "explanation_uz": "そそっかしい = shoshqaloq, parishonxotir"}, {"id": "t9-v4-17", "options": ["失って", "狂って", "送って", "違って"], "answer": 2, "tr": "Uyqu tartibim buzilib ketib, so'nggi paytlarda uxlay olmaydigan bo'lib qoldim.", "stem": "睡眠のリズムが（　）しまい、最近眠れなくなってしまった。", "reading": "くるって", "explanation_uz": "（リズムが）狂う = ritm/tartib izdan chiqmoq, buzilmoq"}, {"id": "t9-v4-18", "options": ["レース", "ペース", "リース", "ケース"], "answer": 4, "tr": "Ushbu holatda bu maxsus holat (vaziyat) bo'lgani uchun sug'urta to'lovi to'lanmaydi.", "stem": "この場合、特殊な（　）なので保険金は支払われません。", "explanation_uz": "ケース (case) = holat, vaziyat, hodisa"}, {"id": "t9-v4-19", "options": ["盛り", "成り", "右肩", "仕立"], "answer": 3, "tr": "Hozirgi yoshlar maosh muttasil o'sib borgan ko'tarilish (babbl) davrini bilmaydigan avloddir.", "stem": "今の若者は給料が（　）上がりに増えたバブルの時代を知らない世代である。", "reading": "みぎかた", "explanation_uz": "右肩上がり (みぎかたあがり) = muntazam o'sish/ko'tarilish"}, {"id": "t9-v4-20", "options": ["うっかり", "わざと", "まさか", "ふと"], "answer": 2, "tr": "Qasddan (atayin) telefoningizga qaraganim yo'q, o'zimniki bilan adashtirib qo'ydim.", "stem": "（　）あなたの携帯電話を見たのではなく、私のと間違えてしまったのです。", "reading": "わざと", "explanation_uz": "わざと = qasddan, atayin"}, {"id": "t9-v4-21", "options": ["非常", "異常", "救急", "休息"], "answer": 2, "tr": "Hech ketmaydigan surunkali charchoq tanadagi anomaliya / nosozlikdan dalolat berishi ko'p uchraydi.", "stem": "なかなか取れない疲労は、体の（　）を示すことが多い。", "reading": "いじょう", "explanation_uz": "異常 (いじょう) = noodatiy holat, anomaliya, nosozlik"}, {"id": "t9-v4-22", "options": ["奨学金", "保証金", "手付金", "入学金"], "answer": 1, "tr": "Ota-onasining moddiy ahvolidan qat'i nazar, iqtidorli o'quvchilar universitetga kira olishi uchun stipendiya (grant) tizimini kengaytirish kerak.", "stem": "親の経済力に関係なく、能力のある生徒が大学に進学できるよう（　）の制度を拡大すべきだ。", "reading": "しょうがくきん", "explanation_uz": "奨学金 (しょうがくきん) = stipendiya, grant"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin so'zni tanlang.", "questions": [{"id": "t9-v5-23", "options": ["さっさと", "うろうろと", "そうっと", "ゆうゆうと"], "answer": 1, "tr": "U telefonni qo'yishi bilanoq shoshilinch ravishda (chaqqon) xonadan chiqib ketdi.", "stem": "彼は電話を切ると【あわただしく】部屋を出ていった。", "reading": "あわただしく", "explanation_uz": "あわただしく ≈ さっさと (tezda, shoshilib)"}, {"id": "t9-v5-24", "options": ["変更", "考慮", "逆に", "無視"], "answer": 3, "tr": "So'z tartibini teskari qilib (almashtirib), ifodani kuchaytirmoqda.", "stem": "語順を【さかさまにして】、表現を強調する。", "reading": "さかさまにして", "explanation_uz": "さかさまに ≈ 逆に (teskari qilib, o'rnini almashtirib)"}, {"id": "t9-v5-25", "options": ["順調に", "徐々に", "急速に", "意外に"], "answer": 1, "tr": "Olimpiada o'yinlariga tayyorgarlik bir maromda (muvaffaqiyatli) davom etmoqda.", "stem": "オリンピックの準備は、【着々と】進んでいる。", "reading": "ちゃくちゃくと", "explanation_uz": "着々と ≈ 順調に (rejaga muvofiq, bir maromda o'ngidan kelib)"}, {"id": "t9-v5-26", "options": ["中断して", "停止して", "変更して", "油断して"], "answer": 4, "tr": "Oddiy shamollash deb e'tiborsiz (beparvo) qaramaslik kerak.", "stem": "たかが風邪だと言って、【甘く見て】はいけません。", "reading": "あまくみて", "explanation_uz": "甘く見る ≈ 油断する (mensimaslik, beparvo/hushyorsiz qarash)"}, {"id": "t9-v5-27", "options": ["評判が悪い", "新鮮味がない", "人気がある", "いい加減だ"], "answer": 2, "tr": "So'nggi paytlardagi teleseriallar bir xillik botqog'iga botgan (hech qanday yangiligi yo'q).", "stem": "最近のテレビドラマは【マンネリ化している】。", "reading": "まんねりかしている", "explanation_uz": "マンネリ化 ≈ 新鮮味がない (yangilik yo'q, bir xil zerikarli qolipga tushib qolgan)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Berilgan so'zning gapda eng to'g'ri ishlatilgan variantini tanlang.", "questions": [{"id": "t9-v6-28", "options": ["子どもを失った親の悲しみはとても推定できない。", "病院で毎月血圧を推定しています。", "電話の声から推定すると、犯人は若い男性だ。", "人の秘密を推定するのはやめなさい。"], "answer": 3, "tr": "推定 (suitei) = taxmin qilish, chamalash, xulosa chiqarish.", "stem": "【推定】の使い方として最もよいものを選びなさい。", "explanation_uz": "「声から推定すると〜」= ovozidan taxmin qilinganda... (to'g'ri ishlatilish)."}, {"id": "t9-v6-29", "options": ["遅くなったので、そろそろごぶさたします。", "病気のため、会議はごぶさたさせてもらう。", "先日は突然お宅にごぶさたし、失礼いたしました。", "大学を卒業以来、先生にはすっかりごぶさたしている。"], "answer": 4, "tr": "ごぶさた (gobusata) = uzoq vaqt xabar olmaslik / ko'rishmaslik.", "stem": "【ごぶさた】の使い方として最もよいものを選びなさい。", "explanation_uz": "「先生にはすっかりごぶさたしている」= ustozdan ancha vaqt xabar ololmay uzrli holatdaman (to'g'ri ishlatilish)."}, {"id": "t9-v6-30", "options": ["たとえ単純な食事でもいいから朝食は食べなさい。", "思ったよりも単純に運転免許が取れた。", "彼は単純な性格だから、細かいことは気にしないと思う。", "まさか1回戦で単純に負けてしまうとはだれも思わなかった。"], "answer": 3, "tr": "単純 (tanjun) = sodda, jo'n, samimiy.", "stem": "【単純】の使い方として最もよいものを選びなさい。", "explanation_uz": "「単純な性格」= sodda/samimiy fe'l-atvor (to'g'ri ishlatilish)."}, {"id": "t9-v6-31", "options": ["お互いこんな足元に住んでいるとは知らなかった。", "お酒を飲みすぎて足元がふらつき、ひとりで歩けない。", "親の足元を離れてからもうだいぶたった。", "買い物は足元の店で済ますことが多い。"], "answer": 2, "tr": "足元 (ashimoto) = qadam bosish holati, oyoq osti.", "stem": "【足元】の使い方として最もよいものを選びなさい。", "explanation_uz": "「足元がふらつき」= mastlikdan qadamlari chayqalib... (to'g'ri ishlatilish)."}, {"id": "t9-v6-32", "options": ["最近はうつ病患者が超過している。", "タクシー会社は深夜の料金を超過する。", "家を建てたのだが、最初の予算をかなり超過してしまい大変だ。", "薬を超過するときは必ず医師に相談してください。"], "answer": 3, "tr": "超過 (chouka) = me'yordan / limitdan oshib ketish.", "stem": "【超過】の使い方として最もよいものを選びなさい。", "explanation_uz": "「予算をかなり超過してしまい」= byudjetdan ancha oshib ketib... (to'g'ri ishlatilish)."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi qavs ichiga eng mos keluvchi grammatik shaklni tanlang.", "questions": [{"id": "t9-g1-33", "options": ["に連れて", "に沿って", "に並べて", "に並んで"], "answer": 2, "tr": "Juda qadimdan bu daryo oqimi bo'ylab shahar rivojlanib kelgan.", "stem": "ずっと昔から、この川の流れ（　）町が発展してきた。", "explanation_uz": "「〜に沿って」= ...yoqalab, bo'ylab."}, {"id": "t9-g1-34", "options": ["を通じて", "をもとにして", "をまわって", "をめぐって"], "answer": 4, "tr": "Qishloqda to'g'on qurish-qurmaslik masalasi atrofida aholining fikri ikkiga bo'lindi.", "stem": "村にダムを作るかどうか（　）、住民の意見は2つにわかれた。", "explanation_uz": "「〜をめぐって」= ...mavzusi atrofida / borasida (tortishuv)."}, {"id": "t9-g1-35", "options": ["にかけては", "にかかっては", "にかかわっては", "につけては"], "answer": 1, "tr": "O'zlashtirishi sust bolalarga dars berish bobida undan mohirroq ustoz yo'q edi.", "stem": "できない子を教えること（　）、彼以上にうまい先生はいなかった。", "explanation_uz": "「〜にかけては」= ...sohasi/borasida eng zo'ri (mahorat ifodasi)."}, {"id": "t9-g1-36", "options": ["となると", "としても", "とすると", "としたら"], "answer": 4, "tr": "Agar chet elga sayohatga chiqa oladigan bo'lsam, albatta Misr ehromlarini ko'rishni orzu qilaman.", "stem": "もし海外旅行に行ける（　）、ぜひエジプトのピラミッドを見たいものだ。", "explanation_uz": "「〜としたら」= agar ...bo'lsa (faraz qilish)."}, {"id": "t9-g1-37", "options": ["ことなく", "わけなく", "しかなく", "ほかなく"], "answer": 1, "tr": "Oxirigacha hech kim safdan chiqmasdan (tashlab ketmasdan), hamma bitirib chiqdi.", "stem": "最後までだれも脱落する（　）、全員が卒業できました。", "explanation_uz": "「〜ことなく」= ...qilmasdan (rasmiy inkor)."}, {"id": "t9-g1-38", "options": ["言ったら", "言っても", "言うなら", "言わなくても"], "answer": 2, "tr": "Natija aniq bo'ldi. Endi bundan keyin u-bu deb gapirgan bilan foydasi yo'q.", "stem": "結果は決まってしまった。今さらあれこれ（　）はじまらない。", "explanation_uz": "「〜て（も）はじまらない」= ...qilgan bilan foydasi yo'q / kech bo'ldi."}, {"id": "t9-g1-39", "options": ["ならでは", "なかぎり", "なくして", "ないでは"], "answer": 3, "tr": "Hatto puling ko'p bo'lsa ham, salomatliksiz hayotdan lazzatlanib bo'lmaydi.", "stem": "たとえお金があっても、健康（　）人生は楽しめない。", "explanation_uz": "「〜なくして（は）」= ...siz, ...mavjud bo'lmasa."}, {"id": "t9-g1-40", "options": ["ごらんになられていただき", "見させてくださり", "ごらんいただき", "見られてくださり"], "answer": 3, "tr": "Har doim bizning veb-saytimizni ko'rib borganingiz uchun tashakkur.", "stem": "いつも小社のホームページを（　）、ありがとうございます。", "explanation_uz": "「ご覧いただき」= ko'rib berganingiz / tomosha qilganingiz uchun (hurmat shakli)."}, {"id": "t9-g1-41", "options": ["食べられたくもないが", "食べられなくもないが", "食べたくもないが", "食べたこともないが"], "answer": 2, "tr": "Bu daraxt mevasini yesa bo'ladi-ku (yeb bo'lmaydigan darajada emas), biroq unchalik mazali emas.", "stem": "この木の実（　）、あまりおいしくはない。", "reading": "たべられなくもないが", "explanation_uz": "「〜なくもない」= ...emas ham emas (qisman tasdiq)."}, {"id": "t9-g1-42", "options": ["するわけない", "するほかない", "しないわけない", "しないほかない"], "answer": 2, "tr": "Qo'l ostimdagi xodim kasallik sababli kelmagan ekan, uning o'rniga ishini bajarishdan boshqa ilojim yo'q.", "stem": "部下が病気で休んでいる以上、私が代わりに彼の仕事を（　）。", "explanation_uz": "「〜以上（は） ...ほかない」= ...ekan, boshqa chora yo'q."}, {"id": "t9-g1-43", "options": ["行くようになっています", "行ったようになっています", "行くことにしています", "行ったことにしています"], "answer": 3, "tr": "A: «Salomatlik uchun biron narsa qilasizmi?» — B: «Ha, har kuni sayr qilishni odat qilganman.»", "stem": "A「健康のために何かしていますか。」\\nB「そうですね、毎日散歩に（　）。」", "explanation_uz": "「〜ことにしている」= ...qilishni odat/qoida qilganman (shaxsiy qaror)."}, {"id": "t9-g1-44", "options": ["高くてもかまわないが", "高くてもしかたがないとはいえ", "高くてはかまわないが", "高くてはしかたがないとしても"], "answer": 2, "tr": "Tokioda yer maydoni torligi tufayli uy narxi qimmat bo'lishi tabiiy bo'lsa-da, butun umr halol ishlab ham sotib ololmaslik aqlga sig'maydi.", "stem": "東京は土地がせまいから家が（　）、一生真面目に働いても買えないなんておかしい。", "explanation_uz": "「〜とはいえ」= ...bo'lishiga qaramasdan / bo'lsa ham."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi yulduzcha (★) o'rniga keladigan eng to'g'ri variantni tanlang.", "questions": [{"id": "t9-g2-45", "options": ["子どもがいる", "生活が苦しくなる", "からこそ", "というけれど"], "answer": 4, "tr": "Bolalar ko'p bo'lsa turmush qiyinlashadi deyishsa-da, bolalarim borligi uchungina astoydil ishlashga kuch paydo bo'ladi.", "explanation_uz": "Tartib: 生活が苦しくなる(2) というけれど(4) 子どもがいる(1) からこそ(3) → Yulduzcha 2-o'rinda: というけれど(4)", "prefix": "子どもがたくさんいると", "suffix": "仕事をがんばる力が出る。", "starPos": 2, "order": [2, 4, 1, 3]}, {"id": "t9-g2-46", "options": ["助け合いの気持ちが", "なるにつれ", "豊かに", "薄く"], "answer": 2, "tr": "Jamiyat boyib borgani sayin o'zaro bir-biriga yordam berish hissi so'nib bordi.", "explanation_uz": "Tartib: 豊かに(3) なるにつれ(2) 助け合いの気持ちが(1) 薄く(4) → Yulduzcha 2-o'rinda: なるにつれ(2)", "prefix": "世の中が", "suffix": "なってきた。", "starPos": 2, "order": [3, 2, 1, 4]}, {"id": "t9-g2-47", "options": ["とともに", "ときは", "とき", "きれいだったが"], "answer": 3, "tr": "Ushbu uy qurilgan vaqtda chiroyli bo'lgan bo'lsa-da, vaqt o'tishi bilan u yer-bu yerini ta'mirlash zarurati tug'ildi.", "explanation_uz": "Tartib: ときは(2) きれいだったが(4) とき(3) とともに(1) → Yulduzcha 3-o'rinda: とき(3)", "prefix": "この家も建てた", "suffix": "あちこち修理が必要になってきた。", "starPos": 3, "order": [2, 4, 3, 1]}, {"id": "t9-g2-48", "options": ["普通のカレー", "いっても", "じゃなくて", "と"], "answer": 2, "tr": "A: «Bugungi kechki ovqatga nima?» B: «Kari. Kari deganim bilan oddiy kari emas, hindcha uslubdagisi.»", "explanation_uz": "Tartib: と(4) いっても(2) 普通のカレー(1) じゃなくて(3) → Yulduzcha 2-o'rinda: いっても(2)", "prefix": "A「今日の夕食は何かな。」\\nB「カレーよ。カレー", "suffix": "インド風のものよ。」", "starPos": 2, "order": [4, 2, 1, 3]}, {"id": "t9-g2-49", "options": ["ほか", "より", "ない", "借りる"], "answer": 1, "tr": "Pulingiz yetishmayotgan bo'lsa, ota-onangizdan qarz olishdan boshqa ilojingiz yo'qdir.", "explanation_uz": "Tartib: 借りる(4) より(2) ほか(1) ない(3) → Yulduzcha 3-o'rinda: ほか(1)", "prefix": "お金が足りないなら、親に", "suffix": "だろうね。", "starPos": 3, "order": [4, 2, 1, 3]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh o'rinlarga eng mos keluvchi javobni tanlang.", "passage": "日本では、電車やバスなど公共交通機関でのケータイの通話を禁止している。しかし、ときどき緊急の用事で通話している人を見かける事がある。手短に（注1）すむのならよいが、長々と話をしている人を見るとついイライラしてしまう。これと似たような経験をお持ちの方も多いだろう。\n　電車やバスで聞こえてくる会話はまったく【 50 】のに、ケータイは不快に感じてしまう。なぜかケータイは気になって仕方がない。この疑問をアメリカの心理学者が解明し、このほど科学誌に発表した。（中略）\n　電車内でのケータイ会話について研究を行ったのは、コーネル大学の心理学者ローレン・エンバーソン博士のチームだ。研究チームは対面会話とケータイを比較し、周りの人が受ける影響について実験を行った。\n　それによると、周りの人は聞こえてくる会話の内容が把握（注2）できないと、ストレスを感じるという。対面会話であれば、話の流れがなんとなくでも【 51-a 】、不必要な情報であれば【 51-b 】ことができる。一方、ケータイの場合は電話の向こうの声が聞き取れないため、話の流れが見えず、内容が気になって無視できなくなってしまうというのだ。「人間は簡単に想像のつくものに対して、無視することができる。しかし次に何が起こるか【 52 】に対しては、常に注意を払ってしまう。ケータイは話が【 53 】聞こえるために、無意識に話の全体像をつかもうと脳は緊張した状態を持続することになる」と、ローレン博士は説明している。\n　つまりケータイは、話している声だけでなく、その内容も周りのイライラの原因になっているようだ。公共交通機関でのケータイ使用は【 54 】。\n（ロケットニュース24　2010年9月20日付）", "questions": [{"id": "t9-g3-50", "options": ["気にならない", "気がつかない", "気にする", "気にいらない"], "answer": 1, "tr": "Poyezd yoki avtobusdagi oddiy suhbatlar aslo g'ashga tegmasa-da...", "explanation_uz": "「気にならない (e'tibor tortmaydi/g'ashga tegmaydi)」", "blankNo": 50}, {"id": "t9-g3-51", "options": ["a 無視でき ／ b 無視する", "a 理解でき ／ b 無視する", "a 理解でき ／ b 理解する", "a 無視でき ／ b 理解する"], "answer": 2, "tr": "a: 理解でき (tushunish mumkin bo'lib), b: 無視する (e'tibor bermay qo'yish).", "explanation_uz": "51-a ga «理解でき» (tushunib olinib), 51-b ga esa «無視する» (keraksiz bo'lsa e'tiborsiz qoldirish) mos tushadi.", "blankNo": 51}, {"id": "t9-g3-52", "options": ["想像できるもの", "理解できるもの", "無視できるもの", "わからないもの"], "answer": 4, "tr": "...ammo keyin nima bo'lishi noma'lum bo'lgan narsaga nisbatan doimo miya diqqat qaratadi.", "explanation_uz": "「何が起こるかわからないもの」= nima bo'lishi tushunarsiz/noma'lum bo'lgan narsa.", "blankNo": 52}, {"id": "t9-g3-53", "options": ["全部", "全然", "半分だけ", "半分しか"], "answer": 3, "tr": "Telefon suhbatida gapning faqat yarmi eshitilgani sababli...", "explanation_uz": "「半分だけ」= faqat yarmi (bir tomonlama ovoz).", "blankNo": 53}, {"id": "t9-g3-54", "options": ["控えてはならない", "控えるものではない", "控えるべきだろう", "控えるわけだろう"], "answer": 3, "tr": "Jamoat transportida telefon orqali gaplashishni cheklash lozim bo'lsa kerak.", "explanation_uz": "「控えるべきだろう」= o'zini tiyish / cheklash lozim bo'lsa kerak.", "blankNo": 54}]}]}]}, "10": {"id": 10, "title_jp": "第10回 模擬テスト", "title_uz": "10-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t10-v1-1", "options": ["にゅうに", "にゅうか", "にゅうこ", "にゅうひん"], "answer": 2, "tr": "Sotuvga chiqish kunidan 1 kun oldin yangi tovar omborga kelib tushdi (qabul qilindi).", "stem": "発売日より1日早く、新商品が【入荷】した。", "reading": "にゅうか", "explanation_uz": "入荷 → にゅうか (tovarning kelishi, qabul qilinishi)"}, {"id": "t10-v1-2", "options": ["ありむ", "ゆうぶ", "うむ", "うぶ"], "answer": 3, "tr": "Bizning kompaniya xodimlarni ishga olishda muloqot qobiliyatining bor-yo'qligiga katta e'tibor beradi.", "stem": "我が社は採用の際、コミュニケーション能力の【有無】を重視します。", "reading": "うむ", "explanation_uz": "有無 → うむ (mavjudligi yoki yo'qligi)"}, {"id": "t10-v1-3", "options": ["なつかしく", "はずかしく", "ちかしく", "ふるめかしく"], "answer": 1, "tr": "Ikki bortli kostyum keksalar uchun qadrdon/xotirali, yoshlar nigohida esa yangicha tuyuladi.", "stem": "ダブルのスーツはお年寄りには【懐かしく】、若者の目には新鮮にうつるようだ。", "reading": "なつかしく", "explanation_uz": "懐かしい → なつかしい (qadrdon, sog'inch uyg'otuvchi)"}, {"id": "t10-v1-4", "options": ["なだめて", "いましめて", "おさめて", "なぐさめて"], "answer": 4, "tr": "Ish topolmay tushkunlikka tushgan do'stimga qanday tasalli berishni bilmay, so'z topolmayapman.", "stem": "就職が決まらず落ち込む友人をどう【慰めて】よいのか、言葉が見つからない。", "reading": "なぐさめて", "explanation_uz": "慰める → なぐさめる (tasalli bermoq, ko'nglini ko'tarmoq)"}, {"id": "t10-v1-5", "options": ["しょうぞく", "そうぞく", "しょうそく", "そうそく"], "answer": 2, "tr": "Otam vafot etgach, uy va yer kabi mol-mulkni meros qilib oldim.", "stem": "父親が亡くなり、家や土地などの財産を【相続】した。", "reading": "そうぞく", "explanation_uz": "相続 → そうぞく (meros qilib olish, vorislik)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t10-v2-6", "options": ["対象", "対称", "対照", "対症"], "answer": 3, "tr": "U ikki yozuvchining ijodiy asarlari bir-biriga mutlaqo qarama-qarshi (kontrast) xarakterga ega.", "stem": "あの2人の作家の作品は【たいしょう】的である。", "reading": "たいしょう", "explanation_uz": "対照的 → たいしょうてき (keskin farq qiluvchi, kontrast)"}, {"id": "t10-v2-7", "options": ["覚えて", "学えて", "賞えて", "覚へて"], "answer": 1, "tr": "U yapon teleseriallari orqali maroq bilan so'zlarni yod olmoqda.", "stem": "彼女は日本のテレビドラマで、楽しく言葉を【おぼえて】いる。", "reading": "おぼえて", "explanation_uz": "覚える → おぼえる (yodlamoq, esda saqlamoq)"}, {"id": "t10-v2-8", "options": ["会答", "快答", "解答", "改答"], "answer": 3, "tr": "Bu matematika masalasining to'g'ri yechimini (javobini) bilmaganim sababli tushuntirib bering.", "stem": "この数学の問題の【かいとう】がわからないので、教えてください。", "reading": "かいとう", "explanation_uz": "解答 → かいとう (masala yechimi, javob)"}, {"id": "t10-v2-9", "options": ["乾杯", "観杯", "幹杯", "換杯"], "answer": 1, "tr": "Otamning tavallud ayyomida butun oila ancha vaqtdan so'ng yig'ilib, pivo bilan qadah urishtirdik.", "stem": "父の誕生日に家族全員が久しぶりに集まって、ビールで【かんぱい】した。", "reading": "かんぱい", "explanation_uz": "乾杯 → かんぱい (qadah ko'tarish, tost)"}, {"id": "t10-v2-10", "options": ["反らえず", "敵らえず", "抗らえず", "逆らえず"], "answer": 4, "tr": "Zamon talabiga (oqimiga) qarshi borolmay, taksafonlar soni qisqarib bormoqda.", "stem": "時代の流れには【さからえず】、公衆電話の数が減っている。", "reading": "さからえず", "explanation_uz": "逆らう → さからう (qarshi bormoq, bo'ysunmaslik)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t10-v3-11", "options": ["古", "同", "先", "前"], "answer": 4, "tr": "Bosh direktorning eskirgan (zamondan orqada qolgan) qarashlariga bir chora ko'rishsa yaxshi bo'lardi.", "stem": "社長の（　）時代的な考え方をなんとかしてほしい。", "explanation_uz": "前時代的 (ぜんじだいてき) = o'tmishdan qolgan, eskirgan"}, {"id": "t10-v3-12", "options": ["未", "非", "無", "不"], "answer": 3, "tr": "Odamlar soliq to'layotganda norozilik bildirishadi-yu, lekin uning qayerga sarflanishiga mutlaqo beparvodir.", "stem": "人は税金を払うときは文句を言うが、その使い道には（　）関心だ。", "explanation_uz": "無関心 (むかんしん) = beparvo, qiziqmaydigan"}, {"id": "t10-v3-13", "options": ["逆", "反", "非", "悪"], "answer": 1, "tr": "Haddan ortiq qattiqqo'l tarbiya teskari natija (aksincha samara) keltirib chiqardi.", "stem": "厳しすぎるしつけが（　）効果となってしまった。", "explanation_uz": "逆効果 (ぎゃくこうか) = teskari samara / kutilmagan salbiy natija"}, {"id": "t10-v3-14", "options": ["制", "型", "系", "形"], "answer": 1, "tr": "Ota-onalar navbatma-navbat (navbatchilik tizimi asosida) maktab yo'lini nazorat qilib chiqmoqdalar.", "stem": "保護者たちは交代（　）で、通学路をパトロールしている。", "explanation_uz": "交代制 (こうたいせい) = navbatchilik tizimi"}, {"id": "t10-v3-15", "options": ["向", "側", "型", "様"], "answer": 2, "tr": "Jadvalni ikkinchi tomonning (sherikning) qulayligiga qarab belgilaymiz.", "stem": "スケジュールは相手（　）の都合で決めます。", "explanation_uz": "相手側 (あいてがわ) = qarshi tomon, sherik tomon"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'zni tanlang.", "questions": [{"id": "t10-v4-16", "options": ["異動", "進行", "運用", "移動"], "answer": 4, "tr": "Velosiped ekologiyaga foydali harakatlanish vositasi sifatida katta umid uyg'otmoqda.", "stem": "自転車は地球にやさしい（　）手段として期待されている。", "reading": "いどう", "explanation_uz": "移動 (いどう) = harakatlanish, ko'chish"}, {"id": "t10-v4-17", "options": ["詰めた", "収めた", "治めた", "努めた"], "answer": 2, "tr": "Tadbir kutilganidek katta muvaffaqiyat qozondi.", "stem": "イベントは期待通りの成功を（　）。", "reading": "おさめた", "explanation_uz": "（成功を）収める = muvaffaqiyatga erishmoq/qozonmoq"}, {"id": "t10-v4-18", "options": ["あちこち", "しばしば", "のろのろ", "たちまち"], "answer": 4, "tr": "Ziyofat taomlari tortilishi bilanoq, likopchalar bir zumda (ko'z ochib yumguncha) bo'shab qoldi.", "stem": "パーティーの料理が出されると、（　）皿が空になってしまった。", "reading": "たちまち", "explanation_uz": "たちまち = bir zumda, ko'z ochib yumguncha"}, {"id": "t10-v4-19", "options": ["リーダー", "ターゲット", "プログラム", "サービス"], "answer": 2, "tr": "40 yoshlardagi ayollarni nishon (maqsadli auditoriya) qilib olgan moda jurnali sotuvga chiqmoqda.", "stem": "40代の女性を（　）にしたファッション誌が発売される。", "explanation_uz": "ターゲット (target) = nishon, mo'ljallangan auditoriya"}, {"id": "t10-v4-20", "options": ["価格", "値札", "過剰", "強化"], "answer": 1, "tr": "Supermarketlar o'rtasidagi keskin narx raqobati xaridorlar uchun quvonarli holatdir.", "stem": "スーパー間の激しい（　）競争は買う側にとってはありがたいことだ。", "reading": "かかく", "explanation_uz": "価格競争 (かかくきょうそう) = narxlar borasidagi raqobat"}, {"id": "t10-v4-21", "options": ["恵まれて", "揺れて", "触れて", "与えられて"], "answer": 1, "tr": "Bolalar kattalar o'ylaganidan ko'ra ancha boy tasavvur qobiliyatiga ega bo'ladilar.", "stem": "子どもは大人が思う以上に、はるかに想像力に（　）いる。", "reading": "めぐまれて", "explanation_uz": "（〜に）恵まれている = ...jihatdan boy/in'om etilgan"}, {"id": "t10-v4-22", "options": ["交流", "共通", "合流", "共同"], "answer": 2, "tr": "Dunyo afsona va miflarida o'zaro mushtarak (umumiy) bo'lgan mavzular ko'p uchraydi.", "stem": "世界各地の神話は互いに（　）するテーマが多い。", "reading": "きょうつう", "explanation_uz": "共通する (きょうつうする) = mushtarak bo'lmoq, o'xshash bo'lmoq"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin so'zni tanlang.", "questions": [{"id": "t10-v5-23", "options": ["課題", "問題", "例題", "話題"], "answer": 4, "tr": "Internetda eng so'nggi dolzarb mavzularni (yangiliklarni) qidirmoqdaman.", "stem": "ネットで最新の【トピック】を検索する。", "explanation_uz": "トピック ≈ 話題 (dolzarb mavzu, yangilik)"}, {"id": "t10-v5-24", "options": ["激しく", "急に", "運悪く", "予想通り"], "answer": 3, "tr": "Mushakbozlik kuni baxtga qarshi yomg'ir yog'a boshladi.", "stem": "花火大会当日、【あいにく】雨が降り出してきた。", "reading": "あいにく", "explanation_uz": "あいにく ≈ 運悪く (baxtga qarshi, noqulay tarzda)"}, {"id": "t10-v5-25", "options": ["だまされた", "断られた", "誘われた", "馬鹿にされた"], "answer": 1, "tr": "Tili shirin anavi yigitning tuzog'iga tushdim (aldanib qoldim).", "stem": "口のうまいあの男に【担がれた】。", "reading": "かつがれた", "explanation_uz": "担がれる ≈ だまされる (laqillatilib aldanmoq)"}, {"id": "t10-v5-26", "options": ["仕事ぶり", "普段", "学習態度", "性質"], "answer": 4, "tr": "U odam tashqi ko'rinishidan shunday tuyulsa-da, asl tabiatida (ich-ichida) juda jiddiy inson.", "stem": "あの人、ああ見えても【根は】まじめなんですよ。", "reading": "ねは", "explanation_uz": "根は ≈ 性質・本性 (asl tabiati, ichki xarakteri)"}, {"id": "t10-v5-27", "options": ["めずらしい", "すばらしい", "おいしい", "なつかしい"], "answer": 2, "tr": "Ajoyib va qimmatbaho sovg'angiz uchun katta rahmat.", "stem": "【結構なもの】をいただき、ありがとうございます。", "reading": "けっこうなもの", "explanation_uz": "結構なもの ≈ すばらしいもの (ajoyib, a'lo darajadagi tuhfa)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Berilgan so'zning gapda eng to'g'ri ishlatilgan variantini tanlang.", "questions": [{"id": "t10-v6-28", "options": ["みなの都合を聞いて次の会議の日程を調整する。", "都会の農地のほとんどが、住宅地に調整されてしまった。", "部屋の冷房の強弱は自由に調整できます。", "荒れた土地を調整して、野菜畑にした。"], "answer": 1, "tr": "調整 (chousei) = muvofiqlashtirish, tartibga solish, jadvalni kelishish.", "stem": "【調整】の使い方として最もよいものを選びなさい。", "explanation_uz": "「日程を調整する」= kun tartibi va vaqtini muvofiqlashtirmoq (to'g'ri ishlatilish)."}, {"id": "t10-v6-29", "options": ["何もこんな大変な仕事すきずきですることない。", "だれがいちばん美人かって？ それはすきずきだよ。", "娘は食べ物のすきずきが多くて困っています。", "この洋服のデザインは私のすきずきに合わない。"], "answer": 2, "tr": "すきずき (sukizuki) = har kimning o'z didiga bog'liq bo'lishi.", "stem": "【すきずき】の使い方として最もよいものを選びなさい。", "explanation_uz": "「それはすきずきだよ」= bu har kimning o'z didi va qarashiga bog'liq (to'g'ri ishlatilish)."}, {"id": "t10-v6-30", "options": ["何かわからないが透明な不安を感じる。", "あの人は政治的には透明なので、意見を聞いてみよう。", "歌手の透明な歌声がコンサート会場に響き渡った。", "嫌な仕事が片付いて気持ちが透明になった。"], "answer": 3, "tr": "透明 (toumei) = tiniq, shaffof, mayin.", "stem": "【透明】の使い方として最もよいものを選びなさい。", "explanation_uz": "「透明な歌声」= musaffo, tiniq jarangdor ovoz (to'g'ri ishlatilish)."}, {"id": "t10-v6-31", "options": ["明日の雨が降る見当は50パーセントです。", "優勝候補が相手では勝てる見当はない。", "彼女のトランプ占いの見当は気味が悪いほどよく当たる。", "断りの理由は言わないが、彼の表情で大体の見当がついた。"], "answer": 4, "tr": "見当 (kentou) = taxmin, mulohaza; 見当がつく = taxmin qila olmoq.", "stem": "【見当】の使い方として最もよいものを選びなさい。", "explanation_uz": "「大体の見当がついた」= umumiy taxmini oydinlashdi (to'g'ri ishlatilish)."}, {"id": "t10-v6-32", "options": ["両親に借金を申請してみようと思う。", "海外旅行に行くのでパスポートを申請した。", "恋人に思い切って結婚を申請した。", "飛行機を予約するときはいつも窓際の席を申請する。"], "answer": 2, "tr": "申請 (shinsei) = rasmiy ariza topshirish, murojaat qilish.", "stem": "【申請】の使い方として最もよいものを選びなさい。", "explanation_uz": "「パスポートを申請した」= pasport olish uchun rasmiy ariza berdim (to'g'ri ishlatilish)."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi qavs ichiga eng mos keluvchi grammatik shaklni tanlang.", "questions": [{"id": "t10-g1-33", "options": ["に増し", "に反し", "にかけ", "に加え"], "answer": 4, "tr": "Yozda quyosh nuri yetishmaganiga qo'shimcha ravishda kuzdagi uzoq yog'ingarchilik sababli sholi hosili xarob bo'lishidan xavotir olinmoqda.", "stem": "夏の日照不足（　）秋の長雨で、米の不作が心配されます。", "explanation_uz": "「〜に加え（て）」= ...ga qo'shimcha ravishda."}, {"id": "t10-g1-34", "options": ["すら", "ほど", "こそ", "さえ"], "answer": 3, "tr": "Avvalo aynan siyosatchilarning o'zi o'z xulq-atvorini to'g'rilashi lozim.", "stem": "まず政治家（　）、自分のおこないを正すべきだ。", "explanation_uz": "「〜こそ」= aynan ...ning o'zi (ta'kidlash)."}, {"id": "t10-g1-35", "options": ["着く際", "着き次第", "着く途中", "着いたとたん"], "answer": 2, "tr": "Mashinada kutib olgani boraman, shuning uchun vokzalga yetib borishingiz bilanoq qo'ng'iroq qiling.", "stem": "車でお迎えに行きますから、駅に（　）お電話をください。", "explanation_uz": "「動詞ます形 ＋ 次第」= ...qilishi bilanoq darhol."}, {"id": "t10-g1-36", "options": ["間違えるたびに", "間違えるにつけ", "間違えるかたわら", "間違えながら"], "answer": 1, "tr": "Ustoz har gal talaffuzda xato qilganimda, qayta-qayta takrorlattiradi.", "stem": "先生は私が発音を（　）、何度も繰り返させる。", "explanation_uz": "「〜たびに」= har gal ...qilganda."}, {"id": "t10-g1-37", "options": ["前もって", "関して", "先立って", "先がけて"], "answer": 3, "tr": "Safarga jo'nashdan oldin oldindan mehmonxonani band qilib qo'ydim.", "stem": "出発に（　）、あらかじめホテルを予約しておいた。", "explanation_uz": "「〜に先立って」= ...dan oldin, muqaddam (rasmiy reja/faoliyatda)."}, {"id": "t10-g1-38", "options": ["お話しになれる", "話してくださる", "話していただく", "お話しになさる"], "answer": 1, "tr": "A: «Yaqin atrofda yig'ilish o'tkazish uchun yaxshi joy bilmaysanmi?» — B: «Kompaniya ortidagi restoranda xotirjam gaplasha olasiz deb o'ylayman.»", "stem": "（会社で）\\nA「近くに打ち合わせをするためのいい場所を知らないか。」\\nB「会社の裏のレストランなら、落ち着いて（　）と思います。」", "explanation_uz": "「お話しになれる」= suhbatlasha olmoq (hurmat + imkoniyat shakli)."}, {"id": "t10-g1-39", "options": ["たえられない", "なれない", "しょうがない", "しょうもない"], "answer": 3, "tr": "Yaponiya futbol terma jamoasi yutqazgani sababli alamdan chiday olmayapman (ichim yonmoqda).", "stem": "サッカーの日本チームが負けたので、くやしくて（　）。", "explanation_uz": "「〜てしょうがない」= ...tufayli chidab bo'lmaydigan darajada kuchli."}, {"id": "t10-g1-40", "options": ["できないはずがない", "できるはずがない", "できないかもしれない", "できるかもしれない"], "answer": 2, "tr": "3 kunda shuncha ishni bajarish aslo imkoni yo'q deb o'ylagandim, lekin astoydil ishlab tugatdim.", "stem": "3日でこれだけの仕事をするなんて（　）と思ったが、がんばってやり終えた。", "explanation_uz": "「できるはずがない」= uddalashning mutlaqo iloji yo'q."}, {"id": "t10-g1-41", "options": ["食べないようにしたほうがいい", "食べないようにしたい", "食べるようにしたほうがいい", "食べるようにしたい"], "answer": 1, "tr": "Erim shifokordan «tuxumni ko'p yemaslikka harakat qilganingiz ma'qul» degan ogohlantirish olgan emish.", "stem": "夫は医者から、「あまりたまごを（　）」と注意されたそうだ。", "explanation_uz": "「〜ないようにしたほうがいい」= ...qilmaslikka harakat qilganingiz ma'qul."}, {"id": "t10-g1-42", "options": ["聞かれたかぎりでは", "聞かれたかぎり", "聞かれないかぎりでは", "聞かれないかぎり"], "answer": 4, "tr": "Qarshi tomon so'ramaguncha telefon raqamimni bermaslikni o'zimga qoida qilganman.", "stem": "相手から（　）、電話番号を教えないことにしている。", "explanation_uz": "「〜ないかぎり」= ...bo'lmaguncha / ...qilinmasa."}, {"id": "t10-g1-43", "options": ["消えつつある", "消えつついる", "消しつつある", "消しつついる"], "answer": 1, "tr": "To'qayzor bo'lgan joyda ko'p qavatli uy qurildi. Shahardan yashillik asta-sekin yo'qolib bormoqda.", "stem": "林があったところにマンションが建った。少しずつ街から緑が（　）。", "explanation_uz": "「〜つつある」= ...jarayon davom etmoqda (sekin-asta sodir bo'lish)."}, {"id": "t10-g1-44", "options": ["笑われようと", "笑われようとして", "笑わされようと", "笑わせようとして"], "answer": 4, "tr": "Bemor bolajonlarni kuldirish maqsadida shifoxonada qiziqarli spektakl namoyish etildi.", "stem": "病気の子どもたちを（　）、病院で楽しい劇が行われた。", "explanation_uz": "「笑わせようとして」= kuldirish, quvontirish niyatida (orttirma nisbat)."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi yulduzcha (★) o'rniga keladigan eng to'g'ri variantni tanlang.", "questions": [{"id": "t10-g2-45", "options": ["された", "どんなに", "反対", "ところで"], "answer": 1, "tr": "Menga qanchalik qarshilik qilishmasin, men baribir unga uylanish niyatidaman.", "explanation_uz": "Tartib: どんなに(2) 反対(3) された(1) ところで(4) → Yulduzcha 3-o'rinda: された(1)", "prefix": "たとえ", "suffix": "、私は彼女と結婚するつもりだ。", "starPos": 3, "order": [2, 3, 1, 4]}, {"id": "t10-g2-46", "options": ["なら", "泣く", "くやしくて", "くらい"], "answer": 2, "tr": "Bahosi yomonligidan alam qilib yig'lagandan ko'ra, ko'proq dars qilsa bo'lardi-ku!", "explanation_uz": "Tartib: くやしくて(3) 泣く(2) くらい(4) なら(1) → Yulduzcha 2-o'rinda: 泣く(2)", "prefix": "成績が悪いのが", "suffix": "もっと勉強すればよいのに。", "starPos": 2, "order": [3, 2, 4, 1]}, {"id": "t10-g2-47", "options": ["ニュースを", "大きさを", "通じて", "地震の被害の"], "answer": 4, "tr": "Radio xabarlari orqali zilzila keltirgan zararning ko'lamini ilk bor angladim.", "explanation_uz": "Tartib: ニュースを(1) 通じて(3) 地震の被害の(4) 大きさを(2) → Yulduzcha 3-o'rinda: 地震の被害の(4)", "prefix": "ラジオの", "suffix": "はじめて知った。", "starPos": 3, "order": [1, 3, 4, 2]}, {"id": "t10-g2-48", "options": ["と", "手伝える", "なると", "人がいない"], "answer": 1, "tr": "Kimdan so'rasam ham yordamlashadigan odam yo'q ekan, bir o'zim bajarishdan boshqa ilojim qolmaydi.", "explanation_uz": "Tartib: 手伝える(2) 人がいない(4) と(1) なると(3) → Yulduzcha 3-o'rinda: と(1)", "prefix": "だれに聞いても", "suffix": "、私1人でやるしかない。", "starPos": 3, "order": [2, 4, 1, 3]}, {"id": "t10-g2-49", "options": ["でも", "では", "食べない", "ダイエット中"], "answer": 3, "tr": "Ko'z o'ngimda noz-ne'matlar tursa, qanchalik parhezda bo'lmayin, yemasdan turolmayman.", "explanation_uz": "Tartib: ダイエット中(4) でも(1) 食べない(3) では(2) → Yulduzcha 3-o'rinda: 食べない(3)", "prefix": "目の前にごちそうを出されたら、いくら", "suffix": "いられない。", "starPos": 3, "order": [4, 1, 3, 2]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh o'rinlarga eng mos keluvchi javobni tanlang.", "passage": "花を愛する人は【 50 】。そのため、たくさんの客に来てほしい観光地では、花を植えてお客を呼ぼうとするところが増えました。\n　しかし花にとって、本当に来てほしいのは人間ではなく、自分の花粉（注1）を運んで実を結ばせてくれる虫や鳥たちです。来てほしい生物は花【 51 】違い、花は色や形や匂いで自分の花粉を運ぶ生物を呼び寄せます。\n　夜に咲く花に白が多いのも、冬に咲く花に黄色が多いのも、夜や冬に飛ぶ虫がその色を好むからです。\n　赤が見えない虫と違って、鳥は赤い色が【 52 】。鳥を誘おうとする花には、赤い色が多いと言われています。\n　「ハナバチ」は名前のとおり、花をまわり、花粉やミツを集め、幼虫に与えるハチです。ハナバチだけに来てほしい花は、深い筒型（注2）の形のものが多いそうです。ちょうどハナバチの重さと大きさで開く、【 53 】「自動ドア」があり、その奥にミツがあるというわけです。\n　匂いも大事です。花は大体よい香りがしますが、中にはくさった肉のような匂いの花もあります。世界最大の花のラフレシアもそうです。そして、このラフレシアが誘っているのはハエなのです。ハエは【 54 】を好むからです。\n　こういう花の工夫を見ると、「いったい花の脳みそはどこにあるんだろう」とふしぎな気がしませんか。", "questions": [{"id": "t10-g3-50", "options": ["多くはありません", "少なくありません", "少ししかいません", "めったにいません"], "answer": 2, "tr": "Gullarni sevadigan insonlar kam emas (juda ko'p).", "explanation_uz": "「少なくありません」= kam emas (ko'pchilikni tashkil qiladi).", "blankNo": 50}, {"id": "t10-g3-51", "options": ["によって", "にとって", "について", "にあたって"], "answer": 1, "tr": "Gullar jalb qilmoqchi bo'lgan tirik mavjudotlar gul turiga qarab har xil bo'ladi...", "explanation_uz": "「花によって（違い）」= gulning turiga qarab har xil bo'lishi.", "blankNo": 51}, {"id": "t10-g3-52", "options": ["見ます", "見えません", "見えます", "見られません"], "answer": 3, "tr": "Qizil rangni ko'ra olmaydigan hasharotlardan farqli o'laroq, qushlar qizil rangni ko'ra oladilar.", "explanation_uz": "「赤い色が見えます」= qushlar qizil rangni yaxshi ko'ra oladilar.", "blankNo": 52}, {"id": "t10-g3-53", "options": ["たとえ", "いわば", "いわゆる", "なぜならば"], "answer": 2, "tr": "Xuddi arining og'irligi va o'lchami bilan ochiladigan go'yo «avtomatik eshik» mavjud bo'lib...", "explanation_uz": "「いわば (go'yo, aytish mumkinki)」", "blankNo": 53}, {"id": "t10-g3-54", "options": ["ラフレシア", "大きい花", "よい香り", "いやな匂い"], "answer": 4, "tr": "Chunki pashshalar badbo'y (yoqimsiz) hidni xush ko'radilar.", "explanation_uz": "「いやな匂い」= yoqimsiz badbo'y hid.", "blankNo": 54}]}]}]}, "11": {"id": 11, "title_jp": "第11回 模擬テスト", "title_uz": "11-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t11-v1-1", "options": ["しょうかい", "じょうがい", "しょうがい", "じょうかい"], "answer": 3, "tr": "Kechasi uxlamasdan yashash tartibiga o'tib, uyqu buzilishi (insomniya/disomniya) kasalligiga uchradim.", "stem": "夜型の生活をしているうちに【睡眠障害】になってしまった。", "reading": "しょうがい", "explanation_uz": "障害 → しょうがい (buzilish, to'siq, xastalik)"}, {"id": "t11-v1-2", "options": ["そうとう", "しょうとう", "あいとう", "そうおう"], "answer": 1, "tr": "Yerga tushadigan quyosh nurining 1 soatlik energiya miqdori insoniyat 1 yilda ishlatadigan miqdorga tengdir (mos keladi).", "stem": "地球に降る太陽光の1時間のエネルギー量は、人類が1年間に使う量に【相当する】。", "reading": "そうとう", "explanation_uz": "相当 → そうとう (teng kelish, mos kelish)"}, {"id": "t11-v1-3", "options": ["けいこう", "かたこう", "けいむき", "かたむき"], "answer": 1, "tr": "Tug'ilish kamayib, ota-onalar oldindan shoshilib bolalariga ortiqcha yordam berish moyilligi kuchaymoqda.", "stem": "少子化が進み、親が先回りして子どもを助ける【傾向】が強い。", "reading": "けいこう", "explanation_uz": "傾向 → けいこう (moyillik, tendensiya)"}, {"id": "t11-v1-4", "options": ["たたき", "かがやき", "いき", "みがき"], "answer": 4, "tr": "O'zimning kuchli tomonlarimni charxlab (sayqallab) borsam albatta muvaffaqiyatga erishaman deb ishonaman.", "stem": "私は自分の長所を【磨き】続ければ必ず成功すると信じている。", "reading": "みがき", "explanation_uz": "磨く → みがく (sayqallamoq, charxlamoq, rivojlantirmoq)"}, {"id": "t11-v1-5", "options": ["はっこう", "はっき", "ほっこう", "ほっき"], "answer": 2, "tr": "Inson qiyin vaziyatga tushgandagina o'zidagi bor kuch-qudratini to'liq namoyon eta oladi.", "stem": "人間は困ったことが起きたときのほうが、持っている力を【発揮】できる。", "reading": "はっき", "explanation_uz": "発揮 → はっき (namoyon etish, ko'rsatish)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t11-v2-6", "options": ["監獄", "強罰", "強盗", "獄盗"], "answer": 3, "tr": "Dunyoning qariyb 30 ta davlati xalqaro qaroqchilar (bosqinchilar) guruhidan zarar ko'rmoqda.", "stem": "世界の30カ国近くの国が、国際【ごうとう】団の被害を受けている。", "reading": "ごうとう", "explanation_uz": "強盗 → ごうとう (bosqinchi, qaroqchi, talonchi)"}, {"id": "t11-v2-7", "options": ["衝突", "障突", "衝突", "将突"], "answer": 1, "tr": "To'qnashuvdan aynan oldin avtomatik tormozlanib to'xtaydigan avtomobil ishlab chiqildi.", "stem": "【しょうとつ】直前で自動的にブレーキがかかって停止する車が開発された。", "reading": "しょうとつ", "explanation_uz": "衝突 → しょうとつ (to'qnashuv, zarba)"}, {"id": "t11-v2-8", "options": ["注くす", "就くす", "尽くす", "着くす"], "answer": 3, "tr": "U sevgan insoni uchun borini fido qiladigan (jon kuydiradigan) fe'l-atvorli inson.", "stem": "彼女は好きな相手に【つくす】タイプだ。", "reading": "つくす", "explanation_uz": "尽くす → つくす (borini bermoq, fido qilmoq, xizmat ko'rsatmoq)"}, {"id": "t11-v2-9", "options": ["仰意", "掲意", "傾意", "敬意"], "answer": 4, "tr": "Hamkor davlatning madaniyatiga hurmat bilan yondashish xalqaro hamkorlikda muhim omildir.", "stem": "相手の国の文化に【けいい】を払うことは、国際協力上大切なことだ。", "reading": "けいい", "explanation_uz": "敬意 → けいい (hurmat, ehtirom)"}, {"id": "t11-v2-10", "options": ["改める", "政める", "敢める", "変める"], "answer": 1, "tr": "Universitetni bitirgandan so'ng bir necha yil yangi bitiruvchi sifatida ish qidirish imkoni bo'lishi uchun tizimni isloh qilish (o'zgartirish) lozim.", "stem": "大学卒業後数年は新卒として就職活動をできるよう、システムを【あらためる】べきだ。", "reading": "あらためる", "explanation_uz": "改める → あらためる (isloh qilmoq, yangilamoq, to'g'rilamoq)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t11-v3-11", "options": ["感", "性", "料", "度"], "answer": 4, "tr": "U yangi sportchiga nisbatan e'tibor darajasi (qiziqish darajasi) eng yuqoridir.", "stem": "あの新人選手がいちばん注目（　）が高い。", "explanation_uz": "注目度 (ちゅうもくど) = diqqat/e'tibor darajasi"}, {"id": "t11-v3-12", "options": ["高", "最", "名", "長"], "answer": 1, "tr": "Mobil telefonlar so'nggi 10 yilda hayratlanarli darajada yuqori unumdorlikka (yuqori quvvatga) ega bo'ldi.", "stem": "携帯電話はこの10年間で驚くほど（　）性能になっている。", "explanation_uz": "高性能 (こうせいのう) = yuqori unumdorlik, yuqori sifatli texnik ko'rsatkich"}, {"id": "t11-v3-13", "options": ["済", "下", "案", "的"], "answer": 3, "tr": "Bu hali loyiha rejasidan (qoralama taklifidan) boshqa narsa emas.", "stem": "これはまだ計画（　）に過ぎません。", "explanation_uz": "計画案 (けいかくあん) = reja loyihasi, taklif"}, {"id": "t11-v3-14", "options": ["代", "異", "単", "別"], "answer": 4, "tr": "Ertaga guruhdan ajralib alohida (mustaqil) harakat qilamiz.", "stem": "明日はグループから離れて（　）行動をとる。", "explanation_uz": "別行動 (べつこうどう) = alohida/ajralib harakat qilish"}, {"id": "t11-v3-15", "options": ["機", "器", "技", "基"], "answer": 2, "tr": "Oshxonada o't o'chirgich (ognetushitel) bo'lmaganida, yong'in chiqib ketgan bo'lardi.", "stem": "台所に消火（　）がなかったら、火事になってしまっただろう。", "explanation_uz": "消火器 (しょうかき) = o't o'chirish moslamasi (ognetushitel)"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'zni tanlang.", "questions": [{"id": "t11-v4-16", "options": ["正面", "後者", "前方", "先頭"], "answer": 3, "tr": "Qariyb 50 metr oldindagi svetofordan chapga burilsangiz, dengiz ko'rinadi.", "stem": "約50メートル（　）の信号を左に曲がると、海が見えてくる。", "reading": "ぜんぽう", "explanation_uz": "前方 (ぜんぽう) = old tomon, oldinda"}, {"id": "t11-v4-17", "options": ["正式", "正確", "正道", "正規"], "answer": 1, "tr": "Ushbu kechada erkaklarning rasmiy kiyimi smokin (taksido) hisoblanadi.", "stem": "このパーティーでは、男性の（　）な服装はタキシードです。", "reading": "せいしき", "explanation_uz": "正式 (せいしき) = rasmiy, qonuniy"}, {"id": "t11-v4-18", "options": ["適切", "残念", "器用", "皮肉"], "answer": 4, "tr": "U professor savollarga piching (istehzoli) javob bergani uchun hamma uni yoqtirmaydi.", "stem": "あの教授は質問に（　）な答え方をするので、嫌われている。", "reading": "ひにく", "explanation_uz": "皮肉 (ひにく) = kinoya, istehzo, piching"}, {"id": "t11-v4-19", "options": ["たびたび", "どうにか", "かなり", "くれぐれも"], "answer": 4, "tr": "(Xatda) Havo sovib qolganligi sababli, iltimos, o'zingizni ehtiyot qiling.", "stem": "（手紙で）寒くなりましたので（　）お体にお気をつけください。", "reading": "くれぐれも", "explanation_uz": "くれぐれも = qat'iy ravishda, iltimos (g'amxo'rlik ifodasi)"}, {"id": "t11-v4-20", "options": ["失業", "失望", "失脚", "失礼"], "answer": 2, "tr": "Iqtisodiyot o'nglanmayotganligi sababli xalq vazirlar mahkamasidan hafsalasi pir bo'lmoqda (umidsizlanmoqda).", "stem": "景気がなかなか回復せず、国民は内閣に（　）している。", "reading": "しつぼう", "explanation_uz": "失望 (しつぼう) = umidsizlik, hafsala pir bo'lishi"}, {"id": "t11-v4-21", "options": ["立ち", "兼ね", "巡り", "触れ"], "answer": 3, "tr": "Onam ishonchli shifokor bilan uchrashish (taqdiri bog'lanish) nasib qilib, omadi chopdi.", "stem": "母は信頼できる医師に（　）会えて運がよかった。", "reading": "めぐりあう", "explanation_uz": "巡り合う (めぐりあう) = taqdir taqozosi bilan uchrashmoq"}, {"id": "t11-v4-22", "options": ["ハード", "ワイド", "ユニーク", "シンプル"], "answer": 4, "tr": "Aftidan, bu muammo o'ylagandek oddiy (sodda) emasga o'xshaydi, yechimiga ancha vaqt ketishi mumkin.", "stem": "どうもこの問題は思ったほど（　）ではなさそうで、解決に時間がかかるかもしれない。", "explanation_uz": "シンプル (simple) = oddiy, sodda"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin so'zni tanlang.", "questions": [{"id": "t11-v5-23", "options": ["急に", "少しだけ", "ますます", "まあまあ"], "answer": 3, "tr": "Tanaka so'nggi paytlarda yanada (tobora) ochilib, go'zallashib ketdi.", "stem": "田中さんはこのごろ、【一段と】きれいになった。", "reading": "いちだんと", "explanation_uz": "一段と ≈ ますます (yanada, tobora ko'proq)"}, {"id": "t11-v5-24", "options": ["上がった", "落ちた", "順調だ", "不調だ"], "answer": 4, "tr": "Uning so'nggi paytlarda savdo ko'rsatkichlari qoniqarsiz (orqada, sust).", "stem": "彼はこのところ営業成績が【ふるわない】。", "reading": "ふるわない", "explanation_uz": "ふるわない ≈ 不調だ (sust, ko'ngildagidek emas)"}, {"id": "t11-v5-25", "options": ["表現", "基準", "常識", "方法"], "answer": 2, "tr": "U oddiy insonning o'lchov mezonlari bilan ta'riflab bo'lmaydigan shaxsdir.", "stem": "彼は普通の人間の【ものさし】では語れない人物だ。", "reading": "ものさし", "explanation_uz": "ものさし ≈ 基準 (o'lchov mezoni, me'yor)"}, {"id": "t11-v5-26", "options": ["のんきな", "気楽な", "無愛想な", "無遠慮な"], "answer": 4, "tr": "Birovning narsasini so'ramasdan ishlatish yuzsizlik (betgachoparlik/uyatsizlik)dir.", "stem": "人のものを勝手に使うとは【あつかましい】やつだ。", "reading": "あつかましい", "explanation_uz": "あつかましい ≈ 無遠慮な (yuzsiz, mulohazasiz, betgachopar)"}, {"id": "t11-v5-27", "options": ["広告主", "協力者", "指導者", "責任者"], "answer": 1, "tr": "Musiqiy ko'rsatuvning bosh homiysi (reklama beruvchisi) aniqlandi.", "stem": "音楽番組の【スポンサー】が決まった。", "explanation_uz": "スポンサー ≈ 広告主 (homiy, reklama beruvchi kompaniya)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Berilgan so'zning gapda eng to'g'ri ishlatilgan variantini tanlang.", "questions": [{"id": "t11-v6-28", "options": ["出版社と合流して、テレビドラマを製作する。", "あの2人はひそかに合流しあっている。", "先生たちと6時に駅で合流して、そこから食事に行こう。", "クラス全員が合流して、野外学習に出かけた。"], "answer": 3, "tr": "合流 (gouryuu) = birlashish, uchrashib birga davom etish.", "stem": "【合流】の使い方として最もよいものを選びなさい。", "explanation_uz": "「駅で合流して〜」= vokzalda uchrashib/qo'shilib birga ovqatlangani boramiz (to'g'ri ishlatilish)."}, {"id": "t11-v6-29", "options": ["この週刊誌の記事は、ほとんどでたらめばかりだ。", "でたらめを使って、授業をさぼった。", "彼女がそんなにでたらめだとは気づかずに、だまされてしまった。", "ずっと掃除していなかったので、部屋がでたらめだ。"], "answer": 1, "tr": "でたらめ (detarame) = asossiz uydirma, safsata, bema'nilik.", "stem": "【でたらめ】の使い方として最もよいものを選びなさい。", "explanation_uz": "「記事はでたらめばかりだ」= maqola uydirma va safsatalardan iborat (to'g'ri ishlatilish)."}, {"id": "t11-v6-30", "options": ["大学を新設する計画はどうやら肯定的に結論された。", "上司はその企画に対し、肯定的な意見を持っている。", "これだけ元気になれば外出も肯定的でしょうね。", "その件は肯定的にお受けいたします。"], "answer": 2, "tr": "肯定的 (kouteiteki) = ijobiy, ma'qullovchi.", "stem": "【肯定的】の使い方として最もよいものを選びなさい。", "explanation_uz": "「肯定的な意見」= ijobiy/qo'llab-quvvatlovchi fikr (to'g'ri ishlatilish)."}, {"id": "t11-v6-31", "options": ["大統領の演説は要旨をおさえている。", "この町は交通上の要旨として発達した。", "論文には、その要旨を書いたものを付けてください。", "今回の事件にはいろいろな要旨が関係している。"], "answer": 3, "tr": "要旨 (youshi) = asosiy mazmun, xulosa, tezis.", "stem": "【要旨】の使い方として最もよいものを選びなさい。", "explanation_uz": "「論文に要旨を付ける」= dissertatsiyaga uning qisqacha tezis/mazmunini ilova qilmoq (to'g'ri ishlatilish)."}, {"id": "t11-v6-32", "options": ["この事件の犯人を指定するのは難しい。", "就職はその人の人生を指定するともいえる。", "代表者は投票によって指定しようではないか。", "パーティーの参加者は指定された服装で来てください。"], "answer": 4, "tr": "指定 (shitei) = belgilangan, maxsus ko'rsatilgan.", "stem": "【指定】の使い方として最もよいものを選びなさい。", "explanation_uz": "「指定された服装」= belgilangan kiyim shakli (dreskod) (to'g'ri ishlatilish)."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi qavs ichiga eng mos keluvchi grammatik shaklni tanlang.", "questions": [{"id": "t11-g1-33", "options": ["よらず", "はおろか", "どころか", "にかぎらず"], "answer": 4, "tr": "Germaniyada pivo nafaqat yozda, balki qishda ham juda ko'p iste'mol qilinadi.", "stem": "ドイツではビールは夏（　）、冬にもよく飲まれている。", "explanation_uz": "「〜に限らず」= nafaqat ..., balki boshqa payt/holatda ham."}, {"id": "t11-g1-34", "options": ["もので", "ものの", "ものか", "ものなら"], "answer": 2, "tr": "Haydovchilik guvohnomasini yaqindagina olgan bo'lsam-da, mashina haydashga unchalik ishonchim yo'q.", "stem": "まだ、免許を取ったばかりの（　）、運転に自信がありません。", "explanation_uz": "「〜ものの」= ...bo'lsa-da / bo'lishiga qaramasdan."}, {"id": "t11-g1-35", "options": ["ありようがない", "ありがたい", "ありかねる", "あり得なくない"], "answer": 4, "tr": "Bunday og'ir vaziyatda omon qolish imkonsizdek tuyulsa-da, bo'lishi mumkin bo'lmagan hodisa emas (bo'lishi mumkin).", "stem": "その状況で助かるなんて不可能に思えますが、（　）ことです。", "explanation_uz": "「あり得なくない」= bo'lishi ehtimoldan xoli emas (ikki karra inkor = tasdiq)."}, {"id": "t11-g1-36", "options": ["最初", "開始", "初めて", "はじめ"], "answer": 4, "tr": "Boshida shahar hokimi turgan barcha xodimlar tabiiy ofatga tayyorgarlik mashg'ulotlarida qatnashdilar.", "stem": "市長を（　）とする職員全員が、災害に備え訓練に取り組んだ。", "explanation_uz": "「〜をはじめ（とする）」= ...boshchiligida, boshida ...bo'lgan barcha."}, {"id": "t11-g1-37", "options": ["行って", "行った", "行く", "行こう"], "answer": 2, "tr": "O'g'lim 20 yil avval Amerikaga ketganicha, biror marta ham vataniga qaytib kelmadi.", "stem": "息子は20年前にアメリカに（　）きり、一度も帰国していない。", "explanation_uz": "「動詞た形 ＋ きり」= ...qilganicha boshqa qaytmaslik/o'zgarmaslik."}, {"id": "t11-g1-38", "options": ["言おうか", "言うまいか", "言えないか", "言わないか"], "answer": 4, "tr": "«Yoqimli ishtaha» deb aytishar-aytmas, bolalar taomni yeyishga kirishib ketishdi.", "stem": "「いただきます」と言ったか（　）のうちに、子どもたちは食べ始めた。", "explanation_uz": "「〜たか〜ないかのうちに」= ...qilar-qilmas bilanoq."}, {"id": "t11-g1-39", "options": ["にあたる", "による", "における", "にいたる"], "answer": 3, "tr": "Yaponiya ichki bozoridagi meva iste'moli hajmi so'nggi paytlarda kamayib bormoqda.", "stem": "日本国内（　）果物の消費量は、最近減少している。", "explanation_uz": "「〜における」= ...dagi / ...dagi sohada (joy va vaqt munosabati)."}, {"id": "t11-g1-40", "options": ["なにも", "いつも", "なんでも", "どこも"], "answer": 1, "tr": "Dorini bir marta ichishni unutib qoldirgan bilan darrov o'lib qoladigan narsa emas-ku, bunchalik xavotirlanma.", "stem": "1回薬を飲み忘れたからといって、（　）死ぬわけではないんだから、そんなに心配しなくていいよ。", "explanation_uz": "「なにも〜わけではない」= darrov ...degani emas / aslo unday emas."}, {"id": "t11-g1-41", "options": ["あげるはずがない", "あげることがない", "あげないはずがない", "あげないこともない"], "answer": 4, "tr": "Darhol qaytarib beradigan bo'lsang, senga qarz berib turmasligim ham mumkin emas (berishim mumkin).", "stem": "すぐに返してくれるなら、お金を貸して（　）。", "explanation_uz": "「〜ないこともない」= ...emas ham emas (qarz berishga tayyorman)."}, {"id": "t11-g1-42", "options": ["だれもが想像しただろう", "だれが想像しただろう", "だれでも想像できただろう", "だれも想像できただろう"], "answer": 2, "tr": "Men bolaligimda ichki sayohatdan ko'ra xorijiy sayohat arzonroq bo'lishini kim ham tasavvur qilibdi deysiz?! (hech kim kutmagan).", "stem": "私が子どものころ、国内旅行より海外旅行のほうが安くなるなんて（　）。", "explanation_uz": "「だれが〜だろう（か）」= kim ham o'ylabdi deysiz (inkor ma'nosidagi ritorik savol)."}, {"id": "t11-g1-43", "options": ["いないからこそ", "いなくもないからこそ", "いないからといって", "いないことはないから"], "answer": 3, "tr": "Qoidaga amal qilayotganlar deyarli yo'qligi sababli deb, siz ham qoidani buzishingiz mumkin degani emas.", "stem": "決まりを守っている人がほとんど（　）、あなたも守らなくていいわけではない。", "explanation_uz": "「〜からといって（〜わけではない）」= ...bo'lgani sababli deb aslo ...degani emas."}, {"id": "t11-g1-44", "options": ["おこしください", "おまいりください", "こされてください", "うかがってください"], "answer": 1, "tr": "Kompaniyamiz suhbatida qatnashuvchilar 10-sana soat 10:00 gacha bosh ofis binosiga tashrif buyurishingiz so'raladi.", "stem": "当社の面接を受ける方は、10日の10時までに本社ビルに（　）。", "explanation_uz": "「お越しください」= kelishingizni so'raymiz (kelmoq fe'lining hurmat shakli)."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi yulduzcha (★) o'rniga keladigan eng to'g'ri variantni tanlang.", "questions": [{"id": "t11-g2-45", "options": ["効くが", "人に", "アレルギー", "よっては"], "answer": 4, "tr": "Bu dori yaxshi ta'sir qiladi-yu, lekin ba'zi odamlarda allergiya qo'zg'atishi mumkinligi tufayli ehtiyotkorlik zarur.", "explanation_uz": "Tartib: 効くが(1) 人に(2) よっては(4) アレルギー(3) → Yulduzcha 3-o'rinda: よっては(4)", "prefix": "この薬はよく", "suffix": "を起こすので、注意が必要だ。", "starPos": 3, "order": [1, 2, 4, 3]}, {"id": "t11-g2-46", "options": ["予想した", "基づいて", "結果", "に"], "answer": 1, "tr": "O'tgan 10 yillik ma'lumotlarga asoslanib qilingan prognoz xulosasiga ko'ra, bolalar soni kamayishda davom etsa kerak.", "explanation_uz": "Tartib: に(4) 基づいて(2) 予想した(1) 結果(3) → Yulduzcha 3-o'rinda: 予想した(1)", "prefix": "過去10年間のデータ", "suffix": "、これからも子どもは減り続けるだろう。", "starPos": 3, "order": [4, 2, 1, 3]}, {"id": "t11-g2-47", "options": ["また忘れて", "ことか", "注意された", "わからないのに"], "answer": 2, "tr": "Vazifani unutib qoldirmaslik haqida necha bor ogohlantirilganimni bilmayman-u, ammo yana unutib qo'yibman.", "explanation_uz": "Tartib: 注意された(3) ことか(2) わからないのに(4) また忘れて(1) → Yulduzcha 2-o'rinda: ことか(2)", "prefix": "宿題を忘れないように何度", "suffix": "しまった。", "starPos": 2, "order": [3, 2, 4, 1]}, {"id": "t11-g2-48", "options": ["あわてて", "にせよ", "ばかなことを", "いた"], "answer": 4, "tr": "U paytda sarosimada bo'lgan taqdirimda ham, bema'ni ish qilib qo'yganimdan pushaymonman.", "explanation_uz": "Tartib: あわてて(1) いた(4) にせよ(2) ばかなことを(3) → Yulduzcha 2-o'rinda: いた(4)", "prefix": "あのときは", "suffix": "してしまったと後悔している。", "starPos": 2, "order": [1, 4, 2, 3]}, {"id": "t11-g2-49", "options": ["しっかりしていても", "兄のほうが", "よい", "いえば"], "answer": 1, "tr": "Yosh jihatidan qaralsa akasi ko'proq mustaqil va hushyor bo'lishi kerak bo'lsa-da, ukasi ancha jiddiyroq.", "explanation_uz": "Tartib: いえば(4) 兄のほうが(2) しっかりしていても(1) よい(3) → Yulduzcha 3-o'rinda: しっかりしていても(1)", "prefix": "年齢から", "suffix": "はずなのに、弟のほうがしっかりしている。", "starPos": 3, "order": [4, 2, 1, 3]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh o'rinlarga eng mos keluvchi javobni tanlang.", "passage": "ほんの数十年前は、たばこを吸うことは大人の男性にとって、悪いこと【 50 】当然のことと思われていた。新幹線も禁煙車両は1両だけだった。1980年、たばこの煙が嫌いな人が集まって当時の国鉄（今のJR）と国を相手に、「他人のたばこの煙を吸わない権利」を求める裁判を起こした。\n　裁判は7年もかかったあげく、結局【 51 】。判決理由は「列車の中で隣の人のたばこの煙を吸わされるのは一時的なこと。たばこを吸うのは日本社会では普通のこと」ということだった。\n　しかし、訴えた人々は、【 52 】がっかりも怒りもしなかった。なぜならば「私もたばこはいやだ」と言い出す人が増えて、国鉄もその声を無視することができなくなり、すでに新幹線の車両の7割が禁煙になっていた。事実上は勝ったと言えるからだ。\n　その後、たばこを吸っている本人よりも、隣でその煙を吸ってしまう人のほうが煙の【 53 】ことがわかって、いっそう分煙対策（注）が進んだ。\n　2003年には「健康増進法」という法律もできて、病院や学校など公共の場はほとんどが禁煙になった。歩きたばこを禁止する町も出てきた。\n　今やたばこを吸う人の肩身はますます狭くなり、限られた場所でこっそり吸うしかなくなった。そして2010年にはたばこが大幅に値上げされた。近い将来には1箱1000円になるとも言われている。そうなると【 54 】得ない人もさらに増えるだろう。\n（注）分煙＝たばこを吸う場所や人を分けること", "questions": [{"id": "t11-g3-50", "options": ["以上に", "というより", "とすれば", "にかけては"], "answer": 2, "tr": "O'n yillar oldin chekish katta yoshli erkaklar uchun yomon narsa bo'lishdan ko'ra, tabiiy hol deb qaralardi.", "explanation_uz": "「〜というより（当然のこと）」= ...dan ko'ra tabiiy holat deb.", "blankNo": 50}, {"id": "t11-g3-51", "options": ["訴えは認められた", "訴えは認められなかった", "訴えを認めがたかった", "訴えを認めかねた"], "answer": 2, "tr": "Sud 7 yil davom etgan bo'lsa-da, oxir-oqibat da'vo qanoatlantirilmadi (rad etildi).", "explanation_uz": "「訴えは認められなかった」= da'vo qabul qilinmadi / rad etildi.", "blankNo": 51}, {"id": "t11-g3-52", "options": ["負けただけあって", "負けたからといって", "負けたとしたら", "負けたとしても"], "answer": 2, "tr": "Biroq da'vogarlar sudda yutqazgan bo'lsalar-da, na xafa bo'lishdi va na g'azablanishdi.", "explanation_uz": "「負けたからといって（〜ない）」= mag'lub bo'lgani sababli deb aslo tushkunlikka tushmadilar.", "blankNo": 52}, {"id": "t11-g3-53", "options": ["害はない", "害が少ない", "害が大きい", "害が変わらない"], "answer": 3, "tr": "...tutunni passiv yutayotgan yonidagi odamga zarari kattaroqligi aniqlandi.", "explanation_uz": "「害が大きい」= zarari kattaroq bo'lishi.", "blankNo": 53}, {"id": "t11-g3-54", "options": ["禁煙し", "たばこを吸わざるを", "たばこを吸い", "禁煙せざるを"], "answer": 4, "tr": "Bunday holatda chekishni tashlashga majbur bo'ladiganlar soni yanada ortadi.", "explanation_uz": "「禁煙せざるを得ない」= chekishni tashlashga majbur bo'lmoq.", "blankNo": 54}]}]}]}, "12": {"id": 12, "title_jp": "第12回 模擬テスト", "title_uz": "12-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t12-v1-1", "options": ["とける", "かける", "つける", "あける"], "answer": 3, "tr": "Mahalliy aholi hunar o'rganib, ishga joylasha olishi uchun yordam ko'rsatish zarur.", "stem": "現地の人々が技術を身につけ、仕事に【就ける】ような援助が必要だ。", "reading": "つける", "explanation_uz": "就く → つく (ishga/lavozimga joylashmoq; 就ける = ishga kira oladigan)"}, {"id": "t12-v1-2", "options": ["ちょうせつ", "ちゅうせつ", "ちょうせち", "ちゅうせち"], "answer": 1, "tr": "Harakatsizlik (kamharakatlik) natijasida terlab tana haroratini boshqarish (tartibga solish) funksiyasi zaiflashib qoladi.", "stem": "運動不足であると、汗をかいて体温を【調節】する機能が弱くなってしまう。", "reading": "ちょうせつ", "explanation_uz": "調節 → ちょうせつ (tartibga solish, boshqarish)"}, {"id": "t12-v1-3", "options": ["きじょう", "きしょう", "ぎじょう", "きっしょう"], "answer": 2, "tr": "Ertalab uyg'onish (o'rindan turish) qiyin bo'lgan insonlar tushgacha oftobda sayr qilsa yaxshi.", "stem": "朝、【起床】するのがつらい人は、午前中、太陽光線を浴びるとよい。", "reading": "きしょう", "explanation_uz": "起床 → きしょう (o'rindan turish, uyg'onish)"}, {"id": "t12-v1-4", "options": ["ねつちゅう", "ねつじゅう", "ねっちゅう", "ねっじゅう"], "answer": 3, "tr": "Sato onlayn o'yinlarga qattiq berilib ketgan (sho'ng'ib ketgan).", "stem": "佐藤さんは、オンラインゲームに【熱中】している。", "reading": "ねっちゅう", "explanation_uz": "熱中 → ねっちゅう (berilib ketish, sho'ng'ish)"}, {"id": "t12-v1-5", "options": ["うつらない", "ゆずらない", "まわらない", "さがらない"], "answer": 2, "tr": "Avtobus yoki poyezdda qariyalarga joy bermaydigan yoshlar ko'p.", "stem": "バスや電車でお年寄りに席を【譲らない】若者が多い。", "reading": "ゆずらない", "explanation_uz": "譲る → ゆずる (joy berish, o'rnini bo'shatish)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t12-v2-6", "options": ["科画", "科学", "化画", "化学"], "answer": 4, "tr": "Ichimlik suvi va taomlarda ishlatiladigan kimyoviy moddalarning xavfsizligidan xavotirlanadiganlar ko'p.", "stem": "飲み水や食事に使用されている【かがく】物質の安全性に不安のある人が多い。", "reading": "かがく", "explanation_uz": "化学 → かがく (kimyo, kimyoviy)"}, {"id": "t12-v2-7", "options": ["有効", "優効", "有抗", "結抗"], "answer": 1, "tr": "Ushbu flayerning amal qilish (yaroqlilik) muddati bugundan boshlab 1 hafta etib belgilanadi.", "stem": "このチラシの【ゆうこう】期間は、本日より1週間とさせていただきます。", "reading": "ゆうこう", "explanation_uz": "有効 → ゆうこう (yaroqli, amaldagi)"}, {"id": "t12-v2-8", "options": ["消耗", "失耗", "減耗", "省耗"], "answer": 1, "tr": "Bu jaziramada bobom butunlay kuch-quvvatini yo'qotdi (charchab toliqdi).", "stem": "この暑さで祖父は体力をすっかり【しょうもう】してしまった。", "reading": "しょうもう", "explanation_uz": "消耗 → しょうもう (charchash, quvvat sarfi/yo'qotish)"}, {"id": "t12-v2-9", "options": ["示めて", "占めて", "閉めて", "締めて"], "answer": 2, "tr": "Yaponiya hududining taxminan 70 foizini o'rmonlar egallagan ko'm-ko'k tabiatli mamlakatlardan biridir.", "stem": "日本は国土の約70パーセントを森林が【しめて】いる緑豊かな国の1つである。", "reading": "しめて", "explanation_uz": "占める → しめる (egallamoq, qamrab olmoq)"}, {"id": "t12-v2-10", "options": ["用項", "要項", "用領", "要領"], "answer": 4, "tr": "Uzoq va ma'no-mazmunidan uzoq (chalkash) gapni eshitayotgan tomon ham charchab ketadi.", "stem": "長くて【ようりょう】を得ない話は、聞くほうも疲れてしまう。", "reading": "ようりょう", "explanation_uz": "要領 → ようりょう (mohiyat, asosiy ma'no/yo'sinda; 要領を得ない = mujmal)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t12-v3-11", "options": ["本", "総", "来", "各"], "answer": 2, "tr": "Yaponiyaning umumiy aholi soni tobora kamayib bormoqda.", "stem": "日本の（　）人口はますます減少していく。", "explanation_uz": "総人口 (そうじんこう) = umumiy aholi soni"}, {"id": "t12-v3-12", "options": ["始", "前", "再", "予"], "answer": 3, "tr": "Yangi zaminda hayotni qaytadan boshlashga (qayta start olishga) qaror qildim.", "stem": "新しい土地で（　）出発することにした。", "explanation_uz": "再出発 (さいしゅっぱつ) = qayta boshlash, yangidan yo'lga chiqish"}, {"id": "t12-v3-13", "options": ["先", "場", "事", "業"], "answer": 1, "tr": "Kelasi oydan boshlab ish joyim (tashkilotim) o'zgaradi.", "stem": "来月から勤務（　）が変わります。", "explanation_uz": "勤務先 (きんむさき) = ish joyi"}, {"id": "t12-v3-14", "options": ["直", "生", "現", "未"], "answer": 2, "tr": "Bu dastur to'g'ridan-to'g'ri voqea joyidan jonli efirda (jonli translyatsiya) uzatilmoqda.", "stem": "この番組は現場からの（　）放送だ。", "explanation_uz": "生放送 (なまほうそう) = jonli efir, to'g'ridan-to'g'ri translyatsiya"}, {"id": "t12-v3-15", "options": ["大", "多", "一", "重"], "answer": 3, "tr": "Musiqiy guruh a'zolarini to'plash o'ziga yarasha ancha katta mashaqqat bo'ldi.", "stem": "バンドのメンバーを集めるのは（　）苦労だった。", "explanation_uz": "一苦労 (ひとくろう) = ancha-muncha mashaqqat/qiyinchilik"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'zni tanlang.", "questions": [{"id": "t12-v4-16", "options": ["わりに", "いわゆる", "あらゆる", "やたらに"], "answer": 2, "tr": "Bu aytish mumkinki (xalq tilidagi) o'tish davri qarshiligi bo'lib, bola durust ulg'ayayotganidan dalolat beradi.", "stem": "それは（　）反抗期というもので、子どもがきっちんと成長しているということです。", "reading": "いわゆる", "explanation_uz": "いわゆる = aytish mumkinki, xalq tilida aytiladigan"}, {"id": "t12-v4-17", "options": ["研いで", "砕いて", "噛んで", "畳んで"], "answer": 3, "tr": "Tishlarni yaxshilab chaynash orqali harakatlantirmasa mustahkam bo'lmaydi.", "stem": "歯はよく（　）刺激しないと丈夫にならない。", "reading": "かんで", "explanation_uz": "噛む (かむ) = chaynash"}, {"id": "t12-v4-18", "options": ["書籍", "活字", "報道", "印刷"], "answer": 2, "tr": "So'nggi paytlarda bosma matnlardan uzoqlashish kuchayib, gazeta savdosi ham tushib ketdi.", "stem": "最近、（　）離れが進んで、新聞の売り上げも落ちた。", "reading": "かつじばなれ", "explanation_uz": "活字離れ (かつじばなれ) = kitob/bosma matndan uzoqlashish"}, {"id": "t12-v4-19", "options": ["メディア", "ベース", "ブーム", "ペース"], "answer": 3, "tr": "Anime ommalashuvi (bum/shov-shuv) ta'sirida ovoz berish aktyori mashhur kasbga aylandi.", "stem": "アニメ（　）の影響で声優は人気の職業となった。", "explanation_uz": "ブーム (boom) = ommaviy qiziqish to'lqini, shov-shuv"}, {"id": "t12-v4-20", "options": ["担当", "保証", "承知", "責任"], "answer": 2, "tr": "Ertangi kun nima bo'lishini bilmaysan. Ertangi kunning kafolati yo'qligi barcha insonlarga tegishlidir.", "stem": "明日のことはわからない。明日の（　）はないということはすべての人にあてはまる。", "reading": "ほしょう", "explanation_uz": "保証 (ほしょう) = kafolat"}, {"id": "t12-v4-21", "options": ["不利", "不正", "不可", "不平"], "answer": 1, "tr": "Imtihon ingliz tilida o'tkazilganligi sababli, yapon talabalari uchun noqulay (noo'ng'ay/ustunliksiz) bo'ldi.", "stem": "試験は英語で行われたので、日本人学生には（　）だった。", "reading": "ふり", "explanation_uz": "不利 (ふり) = noqulay, noo'rin, zararga ishlaydigan"}, {"id": "t12-v4-22", "options": ["意思", "利益", "純粋", "魅力"], "answer": 4, "tr": "Yaponiya qishloq xo'jaligida joziba (qiziqish/jozibadorlik) his qilayotgan yoshlar ko'paydi.", "stem": "日本の農業に（　）を感じる若者が増えてきた。", "reading": "みりょく", "explanation_uz": "魅力 (みりょく) = joziba, maftunkorlik"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin so'zni tanlang.", "questions": [{"id": "t12-v5-23", "options": ["始める", "休む", "直す", "閉じる"], "answer": 4, "tr": "Nihoyat do'konni yopishga (faoliyatini tugatishga) qaror qildik.", "stem": "とうとう店を【たたむ】ことにした。", "reading": "たたむ", "explanation_uz": "（店を）たたむ ≈ 閉じる (do'konni butunlay yopmoq)"}, {"id": "t12-v5-24", "options": ["華やかに", "明るく", "静かに", "騒がしく"], "answer": 3, "tr": "Final poygasining starti e'lon qilingach, maydon sukunatga cho'mdi (jim-jit bo'lib qoldi).", "stem": "決勝レースのスタートが告げられると、場内は【しいんと】なった。", "reading": "しいんと", "explanation_uz": "しいんと ≈ 静かに (jim-jit, sukunat ichida)"}, {"id": "t12-v5-25", "options": ["作り直して", "取り消して", "利用して", "掃除して"], "answer": 1, "tr": "Eski hovli-uyni qayta ta'mirlab (o'zgartirib) qahvaxonaga aylantirmoqchimiz.", "stem": "古い民家を【改造して】喫茶店にする。", "reading": "かいぞうして", "explanation_uz": "改造する ≈ 作り直す (qayta qurmoq, rekonstruksiya qilmoq)"}, {"id": "t12-v5-26", "options": ["興味", "関係", "運", "苦労"], "answer": 2, "tr": "Nimadandir pul bilan hech aloqam / nasibam bog'lanmaydi.", "stem": "お金にはなぜか【縁がない】。", "reading": "えんがない", "explanation_uz": "縁がない ≈ 関係がない (aloqasi/bog'liqligi yo'q)"}, {"id": "t12-v5-27", "options": ["常識のない", "期待はずれの", "遠慮ない", "突然の"], "answer": 3, "tr": "Uning gapni to'g'ridan-to'g'ri (hech tortinmasdan) aytganiga hamma hayron qoldi.", "stem": "彼の【ストレートな】発言に、みな驚いた。", "explanation_uz": "ストレートな ≈ 遠慮ない (ochiqchasiga, tortinmay to'g'ri aytilgan)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Berilgan so'zning gapda eng to'g'ri ishlatilgan variantini tanlang.", "questions": [{"id": "t12-v6-28", "options": ["上司と一緒に外出すると緊張で恐縮してしまう。", "泊めていただいた上にごちそうにまでなって、恐縮です。", "みなで恐縮して卒業記念の写真をとってもらった。", "大勢の人の前で話すなんて、まったく恐縮してしまった。"], "answer": 2, "tr": "恐縮 (kyoushuku) = xijolat bo'lish, minnatdorchilik va uzr aralash his.", "stem": "【恐縮】の使い方として最もよいものを選びなさい。", "explanation_uz": "「ごちそうにまでなって、恐縮です」= mehmondorchilik uchun xijolatdaman/minnatdorman (to'g'ri ishlatilish)."}, {"id": "t12-v6-29", "options": ["娘が帰ってこないので、心当たりに次々と電話した。", "んないい奥さんをもらうなんて、彼は女性の心当たりがある。", "私の本当の気持ちを、親友に心当たりに打ち明けた。", "君はふだんからの心当たりがなっていない。"], "answer": 1, "tr": "心当たり (kokoroatari) = taxmin qilinayotgan manzil/joy.", "stem": "【心当たり】の使い方として最もよいものを選びなさい。", "explanation_uz": "「心当たりに次々と電話した」= ehtimolli barcha tanish joylarga ketma-ket qo'ng'iroq qildim (to'g'ri ishlatilish)."}, {"id": "t12-v6-30", "options": ["今日は寒いので、さわやかな食べ物がいい。", "受付の女性はさわやかな笑顔で応対している。", "5月の空に鳥がさわやかに飛んでいる。", "彼女は細くてさわやかな字を書く。"], "answer": 2, "tr": "さわやか (sawayaka) = yoqimli, tetiklantiruvchi, xushfe'l.", "stem": "【さわやか】の使い方として最もよいものを選びなさい。", "explanation_uz": "「さわやかな笑顔」= samimiy va xushchaqchaq tabassum (to'g'ri ishlatilish)."}, {"id": "t12-v6-31", "options": ["この企画は先輩が焦点となって進められる。", "2人の話し合いは焦点がずれていて、結論が出ない。", "今年の入社試験は面接が焦点です。", "よくわかるように焦点してください。"], "answer": 2, "tr": "焦点 (shouten) = asosiy diqqat markazi, fokus.", "stem": "【焦点】の使い方として最もよいものを選びなさい。", "explanation_uz": "「焦点がずれていて」= asosiy muhokama mavzusidan chalg'ib... (to'g'ri ishlatilish)."}, {"id": "t12-v6-32", "options": ["くれぐれも、みなさま方の考慮ある行動をお願い致します。", "あの社員にはしっかりした考慮があるので仕事をまかせられる。", "参加者の年齢や体力を考慮して、旅行プランを立てた。", "どうも今回の事件にはあの人物が考慮しているようだ。"], "answer": 3, "tr": "考慮 (kouryo) = hisobga olish, e'tiborga olish.", "stem": "【考慮】の使い方として最もよいものを選びなさい。", "explanation_uz": "「年齢や体力を考慮して」= yoshi va jismoniy quvvatini inobatga olib (to'g'ri ishlatilish)."}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi qavs ichiga eng mos keluvchi grammatik shaklni tanlang.", "questions": [{"id": "t12-g1-33", "options": ["とたん", "まま", "あと", "ばかり"], "answer": 4, "tr": "Bu kuchukcha kechagina tug'ilgani tufayli, hali ko'zlari ochilmagan.", "stem": "この子犬は、きのう生まれた（　）で、まだ目が開いていない。", "explanation_uz": "「動詞た形 ＋ ばかり」= ...qilinganiga endigina ozgina vaqt bo'ldi."}, {"id": "t12-g1-34", "options": ["により", "につき", "にとり", "に関し"], "answer": 1, "tr": "Yo'l harakati sharoiti sababli, sayohat 1 haftaga qoldiriladi.", "stem": "交通事情（　）、旅行は1週間延期します。", "explanation_uz": "「〜により」= ...sababli / tufayli (rasmiy bildirishnoma)."}, {"id": "t12-g1-35", "options": ["途中", "ついで", "かたわら", "最中"], "answer": 2, "tr": "Kechki ovqat tayyorlash fursatidan foydalanib, ertangi nonushtani ham tayyorlab qo'yay.", "stem": "晩ごはんを作る（　）に、明日の朝ごはんも作っておこう。", "explanation_uz": "「〜ついでに」= ...qilish asnosida / fursatdan foydalanib."}, {"id": "t12-g1-36", "options": ["かけ", "つつ", "ながら", "がち"], "answer": 1, "tr": "Poyezd bekatga yetib kelgani uchun o'qib tugatilmagan (chala) kitobni yopib sumkaga soldim.", "stem": "電車が駅に着いたので、読み（　）の本を閉じてバッグにしまった。", "explanation_uz": "「動詞ます形 ＋ かけ」= chala qolgan / davom etayotgan harakat."}, {"id": "t12-g1-37", "options": ["にかけて", "に応じて", "にかかわって", "に際して"], "answer": 4, "tr": "Tamaki sotib olish paytida yoshni tasdiqlovchi hujjat talab qilinadigan bo'ldi.", "stem": "たばこの購入（　）は、年齢を証明するものが必要になりました。", "explanation_uz": "「〜に際して（は）」= ...holatida / paytida (rasmiy uslub)."}, {"id": "t12-g1-38", "options": ["以上", "ためで", "うえでも", "ことには"], "answer": 3, "tr": "O'z ona tilini yaxshi tushunish nuqtai nazaridan ham, chet tilini o'rganish juda foydali ishdir.", "stem": "自分の国の言葉をよく理解する（　）、外国語を学ぶのはよいことだ。", "explanation_uz": "「〜うえで（も）」= ...nuqtai nazaridan / jihatidan qaraganda ham."}, {"id": "t12-g1-39", "options": ["出るか", "出ないか", "出るや", "出たが"], "answer": 3, "tr": "Mehmon eshikdan chiqishi bilanoq chiroqni o'chirish juda odobsizlikdir.", "stem": "お客さんがげんかんを（　）いなや、電気を消すなんて失礼なことです。", "explanation_uz": "「動詞辞書形 ＋ やいなや」= ...qilishi bilanoq darhol."}, {"id": "t12-g1-40", "options": ["写していただきました", "写させていただきました", "写させてあげました", "写していただけました"], "answer": 2, "tr": "Kecha sizdan olgan materiallarni qaytarmoqdaman. Darsga kelmagan kunimdagi qismini ko'chirib oldim.", "stem": "きのうお借りした資料、お返しします。休んだときの分を（　）。", "explanation_uz": "「写させていただきました」= ijozatingiz bilan ko'chirib oldim (kamtarinlik ifodasi)."}, {"id": "t12-g1-41", "options": ["ならないうちに", "なるあいだに", "なりそうなうちに", "ならないあいだに"], "answer": 1, "tr": "Allaqachon soat 7 bo'ldi. Ayollar havo qorong'i bo'lmasdan oldin tezroq uylariga ketsinlar.", "stem": "もう7時です。女性のみなさんは暗く（　）、早く帰ってください。", "explanation_uz": "「〜ないうちに」= ...bo'lmasdan oldin / paytida."}, {"id": "t12-g1-42", "options": ["食べ終えるなら", "食べ終えたら", "食べ終えると", "食べ終えれば"], "answer": 2, "tr": "Tushdan keyin majlis o'tkazamiz. Tushlikni yeb bo'lishingiz bilanoq darhol majlislar xonasiga keling.", "stem": "午後から会議を開きます。昼食を（　）すぐ会議室に来てください。", "explanation_uz": "「〜たらすぐ」= ...harakat tugashi bilanoq darhol."}, {"id": "t12-g1-43", "options": ["間違えるからには", "間違えたからには", "間違えるものなら", "間違えようものなら"], "answer": 4, "tr": "Mening fortepiano ustozim shu qadar qattiqqo'l ediki, hatto bir dona joyda adashib ketsangiz, mashg'ulotni darhol to'xtatardi.", "stem": "私のピアノの先生はきびしくて、一カ所でも（　）練習をすぐストップさせた。", "explanation_uz": "「動詞意向形 ＋ ものなら」= mabodo ...qilib qo'ysa (yomon natija)."}, {"id": "t12-g1-44", "options": ["にもかかわらず", "というしかなくて", "だけのこと・はあって", "ばかりではなくて"], "answer": 3, "tr": "Bu sumka qimmat bo'lganiga yarasha, 10 yil ishlatilsa ham mutlaqo shakli buzilmadi.", "stem": "さすがにこのバッグは高かった（　）、10年使ってもまったく形がくずれない。", "explanation_uz": "「〜だけのことはある」= ...bo'lganiga yarasha arziydi (maqtov)."}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の＿★＿に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi yulduzcha (★) o'rniga keladigan eng to'g'ri variantni tanlang.", "questions": [{"id": "t12-g2-45", "options": ["いって", "ことは", "からと", "あきらめる"], "answer": 1, "tr": "Bir marta imtihondan yiqilgan sababli deb voz kechishga aslo hojat yo'q.", "explanation_uz": "Tartib: からと(3) いって(1) あきらめる(4) ことは(2) → Yulduzcha 2-o'rinda: いって(1)", "prefix": "1回試験に失敗した", "suffix": "ないですよ。", "starPos": 2, "order": [3, 1, 4, 2]}, {"id": "t12-g2-46", "options": ["もとで", "水がないという", "条件の", "きびしい"], "answer": 3, "tr": "Sahro jonivorlari suv yo'qligi kabi qattiq sharoitlar ostida jon-jahdi bilan yashab qolmoqda.", "explanation_uz": "Tartib: 水がないという(2) きびしい(4) 条件の(3) もとで(1) → Yulduzcha 3-o'rinda: 条件の(3)", "prefix": "砂漠の動物たちは", "suffix": "必死に生きている。", "starPos": 3, "order": [2, 4, 3, 1]}, {"id": "t12-g2-47", "options": ["ついて", "お金の問題は", "英語の授業に", "ともかくとして"], "answer": 4, "tr": "Amerika universitetiga borishda pul masalasi o'z yo'liga, ingliz tilidagi darslarni o'zlashtirib keta olarmikanman?", "explanation_uz": "Tartib: お金の問題は(2) ともかくとして(4) 英語の授業に(3) ついて(1) → Yulduzcha 2-o'rinda: ともかくとして(4)", "prefix": "アメリカの大学に行くのに、", "suffix": "いけるのだろうか。", "starPos": 2, "order": [2, 4, 3, 1]}, {"id": "t12-g2-48", "options": ["かわって", "副社長が", "会社経営", "社長に"], "answer": 1, "tr": "Kasalxonada yotgan prezident o'rniga vitse-prezident kompaniya boshqaruviga mas'ul bo'ldi.", "explanation_uz": "Tartib: 社長に(4) かわって(1) 副社長が(2) 会社経営(3) → Yulduzcha 2-o'rinda: かわって(1)", "prefix": "入院中の", "suffix": "にあたることになった。", "starPos": 2, "order": [4, 1, 2, 3]}, {"id": "t12-g2-49", "options": ["少なくは", "ものだって", "非常識に", "なってしまった"], "answer": 2, "tr": "A: «Bu jamiyat qoidasi degan narsa.» B: «10 yil avvalgi oddiy qoidalar bugun g'ayrioddiy bema'nilikka aylanib qolgan holatlar ham kam emas.»", "explanation_uz": "Tartib: 非常識に(3) なってしまった(4) ものだって(2) 少なくは(1) → Yulduzcha 3-o'rinda: ものだって(2)", "prefix": "A「これが社会の常識というものだ。」\\nB「10年前の常識が", "suffix": "ないよ。」", "starPos": 3, "order": [3, 4, 2, 1]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh o'rinlarga eng mos keluvchi javobni tanlang.", "passage": "それまでおだやかだった人が、ちょっとしたことを【 50 】はげしく怒り出すことがあります。まるでその人の血管が突然切れたように見えることから、カタカナで「キレる」と言うようになりました。\n　だまって教室を出ようとした生徒を先生が注意したところ、突然その中学生がナイフを取り出して、先生を刺し殺す事件がありました。その事件以来「キレる若者」が社会の問題になりました。\n　ところが2000年から10代の若者がキレて起こす事件数は大きく増えていないのに、50代、60代の人がキレる事件が非常に多くなりました。\n　たとえば「ちょっと電車が遅れたり、眠っているお客を起こしたりしたとき、怒ってキレるのは中高年の男性です」と証言する駅員もいます。\n　特に、客にはあまり【 51 】サービス業の人たち、役所の公務員などを相手に、つまらないことで何時間も大声で怒るような人が増えました。\n　本来ならキレる若者を注意【 52 】大人が、なぜキレるのでしょうか。\n　昔の老人は、長い人生で得た知識や経験を尊敬されました。現代は次々と新しい機械や技術ができて、ついていけない中高年も少なくありません。以前なら技術を教えて【 53-a 】若者から、教えて【 53-b 】ならなくなりました。これはつらいことでしょう。また会社を辞めてから、地域に話し相手もいない男性が多いのです。心の中にこういう不満やさびしさをかかえることが、中高年がキレる原因かもしれません。\n　人生経験のゆたかな大人【 54 】、おだやかな人ばかりではないのです。", "questions": [{"id": "t12-g3-50", "options": ["チャンスに", "きっかけに", "ついでに", "はじめに"], "answer": 2, "tr": "O'sha paytgacha bosiq bo'lgan inson kichik bir sabab tufayli to'satdan qattiq g'azablanib ketishi mumkin.", "explanation_uz": "「〜をきっかけに」= ...tufayli, sabab bo'lib.", "blankNo": 50}, {"id": "t12-g3-51", "options": ["文句を言うべき", "文句を言うような", "文句を言えない", "文句を言わせない"], "answer": 3, "tr": "Ayniqsa mijozlariga e'tiroz bildira olmaydigan xizmat ko'rsatish xodimlari...", "explanation_uz": "「文句を言えない」= e'tiroz bildira olmaydigan.", "blankNo": 51}, {"id": "t12-g3-52", "options": ["するべき", "していく", "しがちな", "しかねない"], "answer": 1, "tr": "Aslida asabiy yoshlarni ogohlantirishi lozim bo'lgan katta yoshlilar nega o'zlari bunday qilmoqda?", "explanation_uz": "「注意するべき（大人）」= ogohlantirishi lozim bo'lgan.", "blankNo": 52}, {"id": "t12-g3-53", "options": ["a くれた ／ b あげなければ", "a もらった ／ b くれなければ", "a もらった ／ b あげなければ", "a やった ／ b もらわなければ"], "answer": 4, "tr": "Ilgari yoshlarga mahorat o'rgatgan bo'lsa, endi yoshlardan o'rganishga majbur bo'lib qoldi.", "explanation_uz": "53-a «やった» (yoshlarga o'rgatib bergan), 53-b «もらわなければ» (yoshlardan o'rganmasa bo'lmay qoldi).", "blankNo": 53}, {"id": "t12-g3-54", "options": ["としては", "だからといって", "だからこそ", "とはいえ"], "answer": 2, "tr": "Hayot tajribasi boy katta yoshli bo'lgani bilan, hamma ham bosiq bo'lavermaydi.", "explanation_uz": "「〜だからといって（〜ない）」= ...bo'lgani sababli deb hamma ham unday emas.", "blankNo": 54}]}]}]}, "13": {"id": 13, "title_jp": "第13回 模擬テスト", "title_uz": "13-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t13-v1-1", "options": ["おおわれて", "ねらわれて", "みまわれて", "ためらわれて"], "answer": 1, "tr": "Tinch okeani yuqori bosimi bilan qoplanib, quyoshli kunlar ko'payib, har joyda kuchli jazirama davom etmoqda.", "stem": "太平洋高気圧に【覆われて】晴れる日が多く、各地で激しい暑さが続いている。", "reading": "おおわれて", "explanation_uz": "覆われる → おおわれる (qoplanmoq, qamrab olinmoq)"}, {"id": "t13-v1-2", "options": ["ばつくん", "ばっくん", "ばつぐん", "ばっぐん"], "answer": 3, "tr": "Uning harakat koordinatsiyasi (sport qobiliyati) ajoyib darajada yaxshi.", "stem": "彼は運動神経が【抜群】にいい。", "reading": "ばつぐん", "explanation_uz": "抜群 → ばつぐん (ajoyib, tengsiz, ajralib turadigan)"}, {"id": "t13-v1-3", "options": ["びょうほん", "ひょうぽん", "ひょうほん", "びょうぽん"], "answer": 3, "tr": "Muzeydagi kit nusxasini (namunasini) tepaga qarab ko'rib, uning kattaligini his qildim.", "stem": "博物館の鯨の【標本】を見上げて、その大きさを実感した。", "reading": "ひょうほん", "explanation_uz": "標本 → ひょうほん (namuna, eksponat, nusxa)"}, {"id": "t13-v1-4", "options": ["とろい", "はやい", "わるい", "にぶい"], "answer": 4, "tr": "Eski kompyuter bo'lgani sababli, ishlashi (reaksiyasi) sekin / sust.", "stem": "古いパソコンなので、動作が【鈍い】。", "reading": "にぶい", "explanation_uz": "鈍い → にぶい (sekin, sust, o'tmas)"}, {"id": "t13-v1-5", "options": ["みつけん", "こうけん", "みつこん", "こうこん"], "answer": 2, "tr": "U bolaligidan shifokor bo'lib jamiyatga hissa qo'shishni xohlar edi.", "stem": "彼女は子どものころから、医者となって世の中に【貢献】したいと考えていた。", "reading": "こうけん", "explanation_uz": "貢献 → こうけん (hissa qo'shish, xizmat qilish)"}]}, {"id": "v2", "type": "kanji_writing", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanjida yozish uchun eng to'g'risini tanlang.", "questions": [{"id": "t13-v2-1", "options": ["仮大", "加大", "過大", "課大"], "answer": 3, "tr": "O'ziga haddan tashqari yuqori baho beradigan odamlar kichik bir muvaffaqiyatsizlikdan ham tushkunlikka tushib qolishlari oson.", "stem": "自分を【かだい】評価している人は、ちょっとした失敗にも落ち込みやすい。", "reading": "かだい", "explanation_uz": "過大 → かだい (haddan tashqari katta/yuqori; 過大評価 = ortiqcha baholash)"}, {"id": "t13-v2-2", "options": ["縮める", "減める", "損める", "短める"], "answer": 1, "tr": "Jahon rekordini naq 0.5 soniyaga qisqartirgan yaxshi natija bilan g'alaba qozondi.", "stem": "世界記録をなんと0.5秒も【ちぢめる】好タイムで優勝した。", "reading": "ちぢめる", "explanation_uz": "縮める → ちぢめる (qisqartirmoq, qisqartirish)"}, {"id": "t13-v2-3", "options": ["再終", "最終", "再修", "最修"], "answer": 2, "tr": "Prezidentning yakuniy qarori hech qachon o'zgarmaydi.", "stem": "社長の【さいしゅう】決定は絶対に変わらない。", "reading": "さいしゅう", "explanation_uz": "最終 → さいしゅう (yakuniy, so'nggi)"}, {"id": "t13-v2-4", "options": ["分拍", "分拒", "分抽", "分担"], "answer": 4, "tr": "U uy ishlari va bola tarbiyasini eri bilan taqsimlab, birgalikda ishlashni davom ettirmoqda.", "stem": "彼女は家事や育児を夫と【ぶんたん】し、共働きを続けている。", "reading": "ぶんたん", "explanation_uz": "分担 → ぶんたん (vazifalarni bo'lib olish, taqsimlash)"}, {"id": "t13-v2-5", "options": ["主める", "納める", "押める", "得める"], "answer": 2, "tr": "Soliq to'lash har bir fuqaroning burchidir.", "stem": "税金を【おさめる】のは国民の義務だ。", "reading": "おさめる", "explanation_uz": "納める → おさめる (to'lamoq, topshirmoq)"}]}, {"id": "v3", "type": "word_formation", "instruction_jp": "（ ）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga qo'yish uchun eng to'g'ri so'z yasovchi qo'shimchani tanlang.", "questions": [{"id": "t13-v3-1", "options": ["多", "数", "複", "高"], "answer": 1, "tr": "Bu zaldan ko'p maqsadli (turli maqsadlarda) foydalanish mumkin.", "stem": "このホールは（【多】）目的に使用できる。", "explanation_uz": "多目的 → たもくてき (ko'p maqsadli)"}, {"id": "t13-v3-2", "options": ["本", "現", "初", "新"], "answer": 3, "tr": "Gavayilik bo'lgan mening birinchi marta qor ko'rish tajribam Yaponiyaning Xokkaydo shahrida bo'lgan edi.", "stem": "ハワイ出身の私が、雪を見た（【初】）体験は日本の北海道だった。", "explanation_uz": "初体験 → はつたいけん (ilk tajriba, birinchi marta boshdan kechirish)"}, {"id": "t13-v3-3", "options": ["次", "後", "期", "末"], "answer": 4, "tr": "Yangi vokzal binosining qurib bitkazilishi moliya yilining oxiriga rejalashtirilgan.", "stem": "新しい駅ビルの完成は年度（【末】）の予定です。", "explanation_uz": "年度末 → ねんどまつ (moliya/o'quv yili oxiri)"}, {"id": "t13-v3-4", "options": ["別", "層", "間", "代"], "answer": 2, "tr": "U mashhur guruh muxlislarining yosh toifasi asosan o'smirlardan iborat.", "stem": "あのアイドルグループのファンの年齢（【層】）は10代が中心だ。", "explanation_uz": "年齢層 → ねんれいそう (yosh qatlami/toifasi)"}, {"id": "t13-v3-5", "options": ["本", "上", "少", "総"], "answer": 1, "tr": "Ob-havo ma'lumotiga ko'ra, yomg'ir tushdan keyin jala/shiddatli yog'ishga aylanadi.", "stem": "天気予報によると、雨は午後から（【本】）降りになる。", "explanation_uz": "本降り → ほんぶり (chinakam yog'ingarchilik, kuchli yomg'ir)"}]}, {"id": "v4", "type": "context_vocab", "instruction_jp": "（ ）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gap mazmuniga mos keluvchi eng to'g'ri so'zni tanlang.", "questions": [{"id": "t13-v4-1", "options": ["排水", "削除", "消費", "蒸発"], "answer": 4, "tr": "O'simliklar ildizidan tortib olgan namlikni bug'lantirganda atrofdagi issiqlikni o'ziga oladi, shuning uchun issiqqa qarshi foydalidir.", "stem": "植物は根から吸い上げた水分を（【蒸発】）させるとき、周囲から熱を奪うので暑さ対策に役立つ。", "explanation_uz": "蒸発 → じょうはつ (bug'lanish)"}, {"id": "t13-v4-2", "options": ["すっきり", "はっきり", "すっかり", "しっかり"], "answer": 1, "tr": "Keraksiz narsalarni dadillik bilan tashlab yuborganimdan so'ng xona saranjom-ozoda bo'lib, kayfiyat ko'tarildi.", "stem": "使わないものを思い切って捨てたら、部屋が（【すっきり】）して気持ちがいい。", "explanation_uz": "すっきり (saranjom, toza, yengil)"}, {"id": "t13-v4-3", "options": ["割れて", "濡れて", "飢えて", "逸れて"], "answer": 3, "tr": "U boy er-xotin moddiy jihatdan to'q bo'lsa-da, ma'naviy (ruhiy) jihatdan och (chanqoq).", "stem": "あのお金持ちの夫婦は物質的には満たされていても、精神的には（【飢えて】）いる。", "explanation_uz": "飢える → うえる (och qolmoq, chanqoq/tashna bo'lmoq)"}, {"id": "t13-v4-4", "options": ["強大", "多大", "膨大", "巨大"], "answer": 4, "tr": "Misr sahrosining o'rtasida bahaybat (ulkan) piramida qad ko'tarib turibdi.", "stem": "エジプトの砂漠の真ん中には（【巨大】）なピラミッドがそびえている。", "explanation_uz": "巨大 → きょだい (ulkan, bahaybat)"}, {"id": "t13-v4-5", "options": ["ハングリー", "ポピュラー", "マイナー", "フリー"], "answer": 3, "tr": "U Fransiyada mashhur bo'lsa-da, Yaponiyada hali uncha tanilmagan (kam taniqli) xonanda.", "stem": "彼はフランスでは人気があるが、日本ではまだ（【マイナー】）な歌手だ。", "explanation_uz": "マイナー (minor / kam tanilgan, kichik doiradagi)"}, {"id": "t13-v4-6", "options": ["課程", "練習", "過程", "活動"], "answer": 1, "tr": "Universitet va kollejlarning o'quv dasturiga (kurikulumiga) kasbiy yo'naltirish kiritilishi majburiy etib belgilanadi.", "stem": "大学や短大の教育（【課程】）に職業指導が義務化される。", "explanation_uz": "課程 → かてい (o'quv kursi, ta'lim dasturi)"}, {"id": "t13-v4-7", "options": ["中断", "脱出", "出口", "出場"], "answer": 2, "tr": "Zilzila paytida eng muhimi 'omon qolish'dir, qochib chiqish yo'li to'silmasa, qolganini eplasa bo'ladi.", "stem": "地震のとき大切なのは「生き残る」ことで、（【脱出】）経路が断たれなければあとのことはなんとかなる。", "explanation_uz": "脱出 → だっしゅつ (chiqib ketish, qutulish)"}]}, {"id": "v5", "type": "paraphrase", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin so'zni tanlang.", "questions": [{"id": "t13-v5-1", "options": ["リミット", "ゴール", "ピーク", "チェックポイント"], "answer": 3, "tr": "U sportchi allaqachon o'zining eng cho'qqi davridan (ravnaq davridan) o'tib ketgan.", "stem": "あの選手はもう【盛り】を過ぎた。", "explanation_uz": "盛り（さかり）＝ ピーク (eng avjiga chiqqan cho'qqi davri)"}, {"id": "t13-v5-2", "options": ["効力", "意味", "評価", "損得"], "answer": 1, "tr": "Ishga kirishda diplomning samadorligi/kuchi (ta'siri) hali ham birmuncha bor.", "stem": "就職の際の学歴の【有効性】はまだいくぶんある。", "explanation_uz": "有効性（ゆうこうせい）＝ 効力（こうりょく） (kuch, ta'sir, yaroqlilik)"}, {"id": "t13-v5-3", "options": ["別々に", "続々と", "同時に", "突然に"], "answer": 3, "tr": "Boshlang'ich sinf o'quvchilarining bilim sinovi butun mamlakat bo'ylab bir vaqtda (birdaniga) o'tkazildi.", "stem": "小学生の学力テストが全国で【いっせいに】行われた。", "explanation_uz": "いっせいに ＝ 同時に (bir paytda, birdaniga)"}, {"id": "t13-v5-4", "options": ["予測して", "見抜いて", "受け取って", "尊重して"], "answer": 2, "tr": "Ona o'g'lining ko'nglini (hissiyotlarini) sezib/anglab turibdi.", "stem": "母親は息子の気持ちを【察している】。", "explanation_uz": "察する（さっする）＝ 見抜く（みぬく） (payqamoq, sezib tushunmoq)"}, {"id": "t13-v5-5", "options": ["口外する", "利用する", "制限する", "混乱させる"], "answer": 1, "tr": "Kompaniyaning muhim ma'lumotlarini tashqariga sizdirish (oshkor qilish).", "stem": "会社の重要な情報を【リークする】。", "explanation_uz": "リークする ＝ 口外する (og'izdan chiqarmoq, sirni oshkor qilmoq)"}]}, {"id": "v6", "type": "usage", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Berilgan so'z qaysi gapda eng to'g'ri ma'noda ishlatilganini tanlang.", "questions": [{"id": "t13-v6-1", "options": ["今、事故の原因を測定しているところです。", "この程度のトラブルは前もって測定していた。", "学者はこの地域に大地震が起こると測定した。", "子どもの運動能力を測定するためにテストを行う。"], "answer": 4, "tr": "Bolalarning jismoniy qobiliyatini o'lchash uchun test o'tkaziladi.", "stem": "【測定】", "explanation_uz": "測定（そくてい）— asbob yoki standart mezon asosida o'lchash, aniqlash. 4-gap to'g'ri.", "optsTr": ["Hozir falokat sababini o'lchashmoqda (xato, 調査/究明 ishlatiladi).", "Bu darajadagi muammoni oldindan o'lchagandim (xato, 想定 ishlatiladi).", "Olimlar bu hududda katta zilzila bo'lishini o'lchashdi (xato, 予測 ishlatiladi).", "Bolalarning jismoniy qobiliyatini o'lchash (aniqlash) uchun test o'tkaziladi."]}, {"id": "t13-v6-2", "options": ["彼女のすぐれた音感は生まれつきの筋である。", "あいつの言うことはめちゃくちゃで、筋が通っていない。", "上司とはことごとく筋が合わない。", "あんなことをする彼の筋は理解できない。"], "answer": 2, "tr": "Uning gapi pala-partish bo'lib, mantiqqa to'g'ri kelmaydi (mantiqsiz).", "stem": "【筋】", "explanation_uz": "筋が通る（すじがとおる）— mantiqan to'g'ri, izchil bo'lmoq. 2-gap to'g'ri.", "optsTr": ["Uning ajoyib musiqiy sezgisi tug'ma qobiliyatdir (xato, 才能/素質 ishlatiladi).", "Uning aytayotgan gapi chalkash bo'lib, hech qanday mantiqqa to'g'ri kelmaydi.", "Boshliq bilan butunlay mantiq mos kelmaydi (xato, 意見/気が合わない ishlatiladi).", "Bunday qilgan uning mantiqini tushunib bo'lmaydi (xato, 意図/理由 ishlatiladi)."]}, {"id": "t13-v6-3", "options": ["彼なら途中で逃げ出すようなひきょうなことは絶対にしないはずだ。", "こんなひきょうなテレビ番組は子どもに見せたくない。", "若い女性が電車の中で化粧するなんてひきょうだ。", "酔っぱらったひきょうな姿を彼女に見られてしまって恥ずかしい。"], "answer": 1, "tr": "U bo'lsa yarmida qochib ketadigan nomardlikni (pastkashlikni) aslo qilmaydi.", "stem": "【ひきょう】", "explanation_uz": "ひきょう（卑怯）— nomard, pastkash, qo'rqoq. 1-gap to'g'ri.", "optsTr": ["U yarmida qochib ketadigan nomardlikni aslo qilmaydi.", "Bunday nomard teleko'rsatuvni bolalarga ko'rsatgim kelmaydi (xato, くだらない ishlatiladi).", "Yosh ayol poyezdda bo'yanishi nomardlikdir (xato, マナー違反 ishlatiladi).", "Mast holatdagi nomard qiyofamni sevgilim ko'rib qolib uyaldim (xato, みっともない ishlatiladi)."]}, {"id": "t13-v6-4", "options": ["この件に関して、いい見解があったらぜひ教えてください。", "その考えには不満の見解が、あちこちであがった。", "今後、いっそうの努力をする見解でありますので、よろしくお願いします。", "この問題には、老人と若者の間に大きな見解の差がある。"], "answer": 4, "tr": "Bu masalada keksalar va yoshlar qarashlari o'rtasida katta farq bor.", "stem": "【見解】", "explanation_uz": "見解（けんかい）— rasmiy yoki falsafiy nuqtai nazar, qarash. 4-gap to'g'ri.", "optsTr": ["Bu masala bo'yicha yaxshi fikringiz bo'lsa ayting (xato, アイデア/意見 ishlatiladi).", "U fikrga nisbatan norozilik fikrlari ko'tarildi (xato, 不満の声 ishlatiladi).", "Bundan buyon yanada harakat qilish fikridamiz (xato, 所存/考え ishlatiladi).", "Bu masalada keksalar va yoshlar o'rtasida qarashlar/fikrlar borasida katta farq bor."]}, {"id": "t13-v6-5", "options": ["政治は今年度の清書を発表した。", "連絡先の電話番号を紙切れにさっと清書して彼女に渡した。", "作文の間違いを調べて、清書して出した。", "受付でご自分のお名前とご住所を清書してください。"], "answer": 3, "tr": "Inshodagi xatolarni tekshirib, oqqa ko'chirib (toza yozib) topshirdim.", "stem": "【清書】", "explanation_uz": "清書（せいしょ）— qoralamani xatosiz, chiroyli qilib oqqa ko'chirish. 3-gap to'g'ri.", "optsTr": ["Hukumat bu yilgi toza yozuvni e'lon qildi (xato, 白書/方針 ishlatiladi).", "Telefon raqamni qog'ozga tezda toza yozib unga berdim (xato, メモして ishlatiladi).", "Inshodagi xatolarni tekshirib, xatosiz oqqa ko'chirib topshirdim.", "Qabulxonada ismingiz va manzilingizni toza yozing (xato, 記入して ishlatiladi)."]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_sent_form", "instruction_jp": "次の文の（ ）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi qavs ichiga qo'yish uchun eng to'g'ri grammatik shaklni tanlang.", "questions": [{"id": "t13-g1-1", "options": ["かかって", "渡って", "続いて", "過ぎて"], "answer": 2, "tr": "Yangi o't o'chiruvchilarning mashg'ulotlari yarim yil davomida qat'iy o'tkaziladi.", "stem": "消防士の新人隊員の訓練は、半年に（【渡って】）きびしく行われる。", "explanation_uz": "〜にわたって（渡って）— butun muddat yoki masofa davomida qamrab olish."}, {"id": "t13-g1-2", "options": ["に及ぶ", "に伴う", "に沿う", "に関する"], "answer": 4, "tr": "Jinoyatchiga oid (tegishli) ma'lumotni biladiganlar yaqin oradagi politsiya bo'limiga xabar bering.", "stem": "犯人（【に関する】）情報をご存知の方は、お近くの警察にお知らせください。", "explanation_uz": "〜に関する（関する）— ...ga oid, ...haqida."}, {"id": "t13-g1-3", "options": ["泣いていたか", "泣こうか", "泣かないか", "泣くまいか"], "answer": 1, "tr": "Go'dak hozirgina yig'layotganmidi desam, allaqachon jilmayib kulib o'tiribdi.", "stem": "赤ちゃんは今（【泣いていたか】）と思ったら、もうにこにこ笑っている。", "explanation_uz": "〜かと思ったら — ...qilgan edi hamki, darhol keyingi harakat sodir bo'ldi."}, {"id": "t13-g1-4", "options": ["せいか", "ところ", "あげく", "どころか"], "answer": 3, "tr": "U restoran shuncha uzoq kuttirganining oqibatida, olib kelgan taomi menyudagidan boshqa narsa bo'lib chiqdi.", "stem": "あのレストランはさんざん待たせた（【あげく】）、出てきたのはメニューと違うものだった。", "explanation_uz": "〜あげく（に）— ko'p urinish/kutish oqibatida salbiy natija yuz berishi."}, {"id": "t13-g1-5", "options": ["にしても", "にしたら", "においても", "において"], "answer": 2, "tr": "Yaponlar nuqtai nazaridan tabiiy tuyulgan odatlar boshqa mamlakatlar uchun g'alati bo'lgan holatlar ko'p.", "stem": "日本人（【にしたら】）あたりまえの習慣が、他の国から見ておかしいことはたくさんある。", "explanation_uz": "〜にしたら（にすれば）— ...ning nuqtai nazaridan qaraganda."}, {"id": "t13-g1-6", "options": ["基づく", "及ぼす", "伴う", "通じる"], "answer": 3, "tr": "Kompyuterda ishlash tufayli yuzaga keladigan charchoqqa dam olishdan ko'ra sport bilan shug'ullanish yaxshiroq.", "stem": "コンピューターでの作業に（【伴う】）疲れには、休むよりむしろ運動したほうがよい。", "explanation_uz": "〜に伴う（ともなう）— ...bilan birga keladigan, hamrohlik qiladigan."}, {"id": "t13-g1-7", "options": ["変わらない", "ならない", "およばない", "過ぎない"], "answer": 4, "tr": "Oddiygina xizmatchi bo'lgan men shunday katta uyni sotib ola olmasligim aniq.", "stem": "平凡なサラリーマンに（【過ぎない】）私が、そんな大きな家を買えるわけがない。", "explanation_uz": "〜にすぎない（過ぎない）— shunchaki ...dan boshqa narsa emas."}, {"id": "t13-g1-8", "options": ["かけた", "ぬいた", "通った", "去った"], "answer": 2, "tr": "Yuguruvchi 4 soat sarflab, 42.195 km masofani oxirigacha yugurib o'tdi.", "stem": "ランナーは4時間かけて42.195キロを走り（【ぬいた】）。", "explanation_uz": "動詞マス形＋ぬく（抜く）— qiyinchiliklarga qaramay oxirigacha yetkazmoq."}, {"id": "t13-g1-9", "options": ["送っていただけたでしょうか", "送っていただけないでしょうか", "送ればよろしいでしょうか", "送ってよろしいでしょうか"], "answer": 2, "tr": "Ming bor uzr, zudlik bilan hujjatlarni yuborib bera olmaysizmi? Ertangi yig'ilish uchun kerak edi.", "stem": "大変申し訳ございませんが、至急書類を（【送っていただけないでしょうか】）。明日の会議に必要なんです。", "explanation_uz": "〜ていただけないでしょうか — muloyim iltimos qilish shakli."}, {"id": "t13-g1-10", "options": ["よいことになっている", "よいはずはない", "よいことにもなっている", "よくないはずはない"], "answer": 1, "tr": "Ushbu bekatga qo'yilgan soyabonlarni erkin olib turish mumkin qilib belgilangan, ammo albatta qaytarib bering.", "stem": "この駅においてある傘は自由に借りて（【よいことになっている】）が、ちゃんと返してください。", "explanation_uz": "〜てよいことになっている — qoida yoki tartib bo'yicha ruxsat etilgan."}, {"id": "t13-g1-11", "options": ["出るよりほかない", "出ないべきだ", "出るべきではない", "出ないわけにいかない"], "answer": 3, "tr": "To'fon yaqinlashayotgan bunday paytda dengizga chiqmaslik kerak.", "stem": "台風が近づいているこんなときに、海に（【出るべきではない】）。", "explanation_uz": "〜べきではない — albatta ...qilmaslik kerak (qoidaga binoan)."}, {"id": "t13-g1-12", "options": ["見たら見るほど", "見てもあると", "見れば見るほど", "見ようと見まいと"], "answer": 3, "tr": "Suratlar orqali bilar edim, ammo haqiqiy Fuji tog'i qaraganing sari go'zallashadigan tog'dir.", "stem": "写真では知っていたが、本物の富士山は（【見れば見るほど】）美しい山だ。", "explanation_uz": "〜ば〜ほど — ...qilganing sari, ...qilgan sari yanada."}]}, {"id": "g2", "type": "grammar_sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi yulduzcha (★) o'rniga keluvchi to'g'ri so'zni tanlang.", "questions": [{"id": "t13-g2-1", "options": ["大人に", "本の中には", "とって", "向けの"], "answer": 2, "tr": "Bolalar uchun mo'ljallangan kitoblar ichida kattalar uchun ham qiziqarli bo'lganlari juda ko'p.", "explanation_uz": "子ども【向けの】【★本の中には】【大人に】【とって】おもしろいものもたくさんある。", "prefix": "子ども", "suffix": "おもしろいものもたくさんある。", "starPos": 2, "order": [4, 2, 1, 3]}, {"id": "t13-g2-2", "options": ["値段も", "味も", "よい", "安ければ"], "answer": 4, "tr": "U restoran narxi ham arzon bo'lishi bilan birga taomi ham mazali, ammo doim odam ko'pligi noqulay.", "explanation_uz": "あのレストランは【値段も】【★安ければ】【味も】【よい】が、いつも込んでいるのが困る。", "prefix": "あのレストランは", "suffix": "が、いつも込んでいるのが困る。", "starPos": 2, "order": [1, 4, 2, 3]}, {"id": "t13-g2-3", "options": ["新しい", "新社長", "として", "体制"], "answer": 3, "tr": "Sobiq prezidentning o'g'lini yangi rahbar etib tayinlab, yangi tuzilmani boshlashmoqda.", "explanation_uz": "前の社長の息子を【新社長】【★として】【新しい】【体制】をスタートさせる。", "prefix": "前の社長の息子を", "suffix": "をスタートさせる。", "starPos": 2, "order": [2, 3, 1, 4]}, {"id": "t13-g2-4", "options": ["日本料理", "は", "ぬきにしては", "語れない"], "answer": 1, "tr": "Soya sousisiz yapon taomlarini tasavvur qilib bo'lmaydi.", "explanation_uz": "しょうゆを【ぬきにしては】【★日本料理】【は】【語れない】。", "prefix": "しょうゆを", "suffix": "。", "starPos": 2, "order": [3, 1, 2, 4]}, {"id": "t13-g2-5", "options": ["わかって", "笑う", "泣くやら", "やらで"], "answer": 2, "tr": "Qizining omon-esonligini bilib, yig'lash va kulish aralash oila to'polon bo'lib ketdi.", "explanation_uz": "娘が無事と【わかって】【泣くやら】【★笑う】【やらで】家族は大騒ぎだった。", "prefix": "娘が無事と", "suffix": "家族は大騒ぎだった。", "starPos": 3, "order": [1, 3, 2, 4]}]}, {"id": "g3", "type": "grammar_passage_context", "instruction_jp": "次の文章を読んで、文章全体の趣旨を踏まえて、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh o'rinlar uchun kontekstga mos eng to'g'ri javobni tanlang.", "passage": "人間が考えるときは、右脳と左脳が同時に働いています。左脳は言葉や論理を、右脳は形、音などの感覚を受け持っています。[ 50 ]、考える力を高めるには、その両方をきたえる必要があります。\n歩いていると脳の働きが活発になり、いろいろな考えがわいてきます。このことは昔から経験的に知られていました。\n古代ギリシャの大哲学者プラトンは、弟子たちに[ 51 ]といわれます。18世紀ドイツの哲学者カントも、散歩する哲学者として知られています。彼が散歩に出るのはきっちり3時半で、夕方の6時に散歩を終えました。近所の人たちは、まったく変わらないカントの生活を見て時計代わりに使ったといいます。\n企業におけるアイデア生産は、ほとんど室内で行われています。狭い室内に閉じこもって、言葉で「あでもない、こうでもない」とやり合っているわけです。言葉によるアイデア生産を行っていると、論理的な左脳は活発になりますが、右脳は[ 52 ]。その結果、せっかく浮かんだアイデアも「現実的でない」と[ 53 ]ことが多くなります。\n一方、歩きながらアイデア生産を行ったら、どうなるでしょうか。\n歩くのは両手両足を動かす運動ですから、左脳にも右脳にも新鮮な血液が送られ、両方ともリフレッシュされます。歩くことに集中し始めると[ 54-a ]の考えが弱くなり、感覚的な[ 54-b ]が働きやすい状態になってきます。その結果、新鮮なアイデアが浮かびやすくなるわけです。会議を始める前に、みんなで歩いてみるのはどうでしょう。", "questions": [{"id": "t13-g3-1", "options": ["したがって", "とはいえ", "あるいは", "しかも"], "answer": 1, "tr": "［ 50 ］bo'sh o'rniga mos bog'lovchini tanlang.", "stem": "［ 50 ］に入る最もよいものを選びなさい。", "explanation_uz": "Xulosa chiqarish uchun 「したがって (shuning uchun)」 mos keladi.", "blankNo": 50}, {"id": "t13-g3-2", "options": ["歩きながら講義した", "歩いたまま講義した", "歩く際に講義した", "歩くついでに講義した"], "answer": 1, "tr": "［ 51 ］bo'sh o'rniga mos iborani tanlang.", "stem": "［ 51 ］に入る最もよいものを選びなさい。", "explanation_uz": "Yurib turgan holda ma'ruza qilganini ifodalash uchun 「歩きながら講義した」 to'g'ri.", "blankNo": 51}, {"id": "t13-g3-3", "options": ["活発になります", "生き生きとします", "休みがちになります", "休みそうになります"], "answer": 3, "tr": "［ 52 ］bo'sh o'rniga mos ifodani tanlang.", "stem": "［ 52 ］に入る最もよいものを選びなさい。", "explanation_uz": "Faol bo'lmay dam olishga moyillikni ifodalash uchun 「休みがちになります」 to'g'ri.", "blankNo": 52}, {"id": "t13-g3-4", "options": ["賛成される", "肯定される", "反省される", "否定される"], "answer": 4, "tr": "［ 53 ］bo'sh o'rniga mos fe'lni tanlang.", "stem": "［ 53 ］に入る最もよいものを選びなさい。", "explanation_uz": "G'oyalar inkor etilishi haqida borgani uchun 「否定される」 to'g'ri.", "blankNo": 53}, {"id": "t13-g3-5", "options": ["a 左脳 / b 左脳", "a 右脳 / b 右脳", "a 左脳 / b 右脳", "a 右脳 / b 左脳"], "answer": 3, "tr": "［ 54-a ］va［ 54-b ］uchun to'g'ri juftlikni tanlang.", "stem": "［ 54-a ］ / ［ 54-b ］に入る組み合わせとして最もよいものを選びなさい。", "explanation_uz": "Mantiqiy chap miya fikri susayib, sezgir o'ng miya faollashadi: 「a 左脳 / b 右脳」.", "blankNo": 54}]}]}]}, "14": {"id": 14, "title_jp": "第14回 模擬テスト", "title_uz": "14-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t14-v1-1", "options": ["あきらめる", "うめる", "つとめる", "やめる"], "answer": 4, "tr": "Mas'uliyatni o'z bo'yniga olib, deputatlikdan iste'foga chiqadi (ketadi).", "stem": "責任をとって、議員を【辞める】。", "reading": "やめる", "explanation_uz": "辞める → やめる (iste'foga chiqmoq, ishdan ketmoq)"}, {"id": "t14-v1-2", "options": ["じょうひ", "しょうひ", "しょうび", "じょうび"], "answer": 2, "tr": "LED lampalarning elektr energiyasi sarfi kam va xizmat muddati uzoq.", "stem": "LED電球は【消費】電力が少なく寿命が長い。", "reading": "しょうひ", "explanation_uz": "消費 → しょうひ (iste'mol, sarflash)"}, {"id": "t14-v1-3", "options": ["めいたく", "めいかく", "みょうたく", "みょうかく"], "answer": 2, "tr": "Kelajakda aniq maqsad qo'yib harakat qilish muhimdir.", "stem": "将来に【明確】な目標をもって努力することが大切だ。", "reading": "めいかく", "explanation_uz": "明確 → めいかく (aniq, ravshan)"}, {"id": "t14-v1-4", "options": ["さかもどり", "ぎゃくもどり", "ぎゃくもとり", "さかさもどり"], "answer": 2, "tr": "To'satdan sovuq qaytgani (orqaga qaytgani) sababli shamollab qoldim.", "stem": "急に寒さが【逆戻り】したため、風邪をひいてしまった。", "reading": "ぎゃくもどり", "explanation_uz": "逆戻り → ぎゃくもどり (orqaga qaytish, avvalgi holatga qaytish)"}, {"id": "t14-v1-5", "options": ["がいねん", "けねん", "かんねん", "りねん"], "answer": 3, "tr": "U ishni yaxshi uddalaydi, biroq vaqt hissi (vaqt qadri tushunchasi) yo'q.", "stem": "彼は仕事はできるが、時間の【観念】がない。", "reading": "かんねん", "explanation_uz": "観念 → かんねん (tushuncha, ong, his)"}]}, {"id": "v2", "type": "kanji_writing", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanjida yozish uchun eng to'g'risini tanlang.", "questions": [{"id": "t14-v2-1", "options": ["予裕", "余裕", "予有", "余有"], "answer": 2, "tr": "Men ruhiy jihatdan ham, vaqt jihatdan ham xotirjamlik (erkinlik) saqlashga intilaman.", "stem": "私は精神的にも時間的にも【よゆう】をもつように心がけている。", "reading": "よゆう", "explanation_uz": "余裕 → よゆう (mo'llik, xotirjamlik, vaqt/mablag' erkinligi)"}, {"id": "t14-v2-2", "options": ["壊れて", "傷れて", "破れて", "崩れて"], "answer": 1, "tr": "Mobil telefonim buzilib qolib, do'stim bilan bog'lana olmayapman.", "stem": "携帯電話が【こわれて】しまい、友人と連絡が取れない。", "reading": "こわれて", "explanation_uz": "壊れる → こわれる (buzilmoq, sinmoq)"}, {"id": "t14-v2-3", "options": ["公協", "交協", "公共", "交共"], "answer": 3, "tr": "Elektr va suv kabi kommunal (jamoat xizmatlari) to'lovlarini kredit karta orqali to'layman.", "stem": "電気や水道などの【こうきょう】料金を、クレジットカードで支払う。", "reading": "こうきょう", "explanation_uz": "公共 → こうきょう (jamoat, ommaviy, kommunal)"}, {"id": "t14-v2-4", "options": ["犯罰", "犯罪", "反罰", "反罪"], "answer": 2, "tr": "Maktab qoidalari va imtihonlarni qat'iylashtirish orqali o'smirlar jinoyatchiligini kamaytirdi.", "stem": "校則や試験を厳しくする教育によって少年【はんざい】を減らした。", "reading": "はんざい", "explanation_uz": "犯罪 → はんざい (jinoyat)"}, {"id": "t14-v2-5", "options": ["遂う", "遣う", "逸う", "遭う"], "answer": 4, "tr": "Uy o'g'riligi jabrini tortgan yolg'iz yashovchi ayollar kam emas.", "stem": "空き巣の被害に【あう】一人暮らしの女性が少なくない。", "reading": "あう", "explanation_uz": "遭う → あう (baxsiz hodisa yoki zararga uchramoq)"}]}, {"id": "v3", "type": "word_formation", "instruction_jp": "（ ）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga qo'yish uchun eng to'g'ri so'z yasovchi qo'shimchani tanlang.", "questions": [{"id": "t14-v3-1", "options": ["薄", "厚", "大", "小"], "answer": 4, "tr": "Jarayon bo'yicha tarqatilgan risolaga (kichik kitobchaga) qarang.", "stem": "手続きについては、お配りした（【小】）冊子をご覧ください。", "explanation_uz": "小冊子 → しょうさっし (risola, kichik buklet)"}, {"id": "t14-v3-2", "options": ["力", "前", "者", "並"], "answer": 2, "tr": "Bu sohada yetuk (mustaqil) hunarmand bo'lish uchun 10 yil kerak bo'lar ekan.", "stem": "この世界で一人（【前】）の職人になるには、10年かかるそうだ。", "explanation_uz": "一人前 → いちにんまえ (yetuk, to'laqonli mutaxassis)"}, {"id": "t14-v3-3", "options": ["俗", "個", "私", "自"], "answer": 3, "tr": "Haftalik jurnal mashhurlarning shaxsiy hayoti haqida shov-shuvli maqola yozdi.", "stem": "週刊誌は芸能人の（【私】）生活を書き立てた。", "explanation_uz": "私生活 → しせいかつ (shaxsiy hayot)"}, {"id": "t14-v3-4", "options": ["圏", "層", "間", "中"], "answer": 1, "tr": "Bu hududga vaqti-vaqti bilan yovvoyi hayvonlar insonlarning yashash hududiga kirib keladi.", "stem": "この地域にはときどき野生動物が人間の生活（【圏】）に入り込んでくる。", "explanation_uz": "生活圏 → せいかつけん (yashash hududi/doirasi)"}, {"id": "t14-v3-5", "options": ["者", "番", "順", "人"], "answer": 3, "tr": "Birinchi kelish tartibida navbat chiptalari tarqatiladi.", "stem": "先着（【順】）に整理券を配ります。", "explanation_uz": "先着順 → せんちゃくじゅん (kelish navbati/tartibi bo'yicha)"}]}, {"id": "v4", "type": "context_vocab", "instruction_jp": "（ ）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gap mazmuniga mos keluvchi eng to'g'ri so'zni tanlang.", "questions": [{"id": "t14-v4-1", "options": ["就任", "交代", "就職", "後任"], "answer": 1, "tr": "Otamning o'rniga prezidentlik lavozimiga tayinlangan paytlarimda faqat otamdan o'zib ketishni o'ylar edim.", "stem": "父に代わって社長に（【就任】）したころは、父を追い抜きたいとばかり思っていた。", "explanation_uz": "就任 → しゅうにん (lavozimga kirishish, tayinlanish)"}, {"id": "t14-v4-2", "options": ["皮肉", "深刻", "格別", "真剣"], "answer": 2, "tr": "Nonushta qilmasdan maktabga keladigan o'quvchilar ko'pligi jiddiy muammodir.", "stem": "朝ごはんを食べないで登校する児童が多いのは（【深刻】）な問題だ。", "explanation_uz": "深刻 → しんこく (jiddiy, og'ir)"}, {"id": "t14-v4-3", "options": ["平等", "陽気", "面倒", "純粋"], "answer": 4, "tr": "Talabalik davridagi qo'shimcha ishim faqatgina tirikchilik xarajatlari uchun edi.", "stem": "学生時代のアルバイトは、（【純粋】）に生活費のためのものだった。", "explanation_uz": "純粋に → じゅんすいに (faqatgina, sof)"}, {"id": "t14-v4-4", "options": ["厳重", "強力", "膨大", "過多"], "answer": 1, "tr": "Prezident o'tadigan yo'lni ko'plab politsiyachilar qattiq qo'riqlayotgan edi.", "stem": "大統領の通る道は、おおぜいの警官が（【厳重】）に警備していた。", "explanation_uz": "厳重 → げんじゅう (qat'iy, kuchaytirilgan)"}, {"id": "t14-v4-5", "options": ["栄え", "譲り", "誇り", "見ばえ"], "answer": 3, "tr": "Ot poygasi olamida Derbida g'alaba qozonish eng oliy faxr (iftixor) hisoblanadi.", "stem": "競馬の世界では、ダービーに勝つことが最高の（【誇り】）である。", "explanation_uz": "誇り → ほこり (faxr, iftixor)"}, {"id": "t14-v4-6", "options": ["とうとう", "いよいよ", "そろそろ", "たまたま"], "answer": 3, "tr": "Kech bo'lib qoldi, endi asta ruxsatingiz bilan qaytay. Ziyofat uchun katta rahmat.", "stem": "遅くなりましたから（【そろそろ】）失礼します。どうもごちそうになりました。", "explanation_uz": "そろそろ (sekin-asta, vaqti kelmoq)"}, {"id": "t14-v4-7", "options": ["ヒートアップ", "イメージアップ", "バックアップ", "タイアップ"], "answer": 1, "tr": "Qoidani qayta ko'rib chiqish bo'yicha fikrlar davom etib, bahs-munozara qizib ketdi.", "stem": "条例の改正について発言が続き、議論は（【ヒートアップ】）した。", "explanation_uz": "ヒートアップ (qizib ketish, avj olish)"}]}, {"id": "v5", "type": "paraphrase", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin so'zni tanlang.", "questions": [{"id": "t14-v5-1", "options": ["修正した", "伝達した", "記録した", "否定した"], "answer": 4, "tr": "U o'zining aytgan gapini rad etdi (inkor qildi).", "stem": "彼は自分の発言を【打ち消した】。", "explanation_uz": "打ち消す（うちけす）＝ 否定する（ひていする） (inkor qilmoq, rad etmoq)"}, {"id": "t14-v5-2", "options": ["間違っている", "優れている", "冷静である", "読まれている"], "answer": 2, "tr": "Siyosatni tanqid qilgan ushbu gazeta maqolasi nihoyatda o'tkir (yetuk).", "stem": "政治を批判したこの新聞記事は、とても【鋭い】。", "explanation_uz": "鋭い（するどい）＝ 優れている（すぐれている） (yetuk, teran, o'tkir)"}, {"id": "t14-v5-3", "options": ["何度か", "いつも", "はじめに", "たまに"], "answer": 2, "tr": "Kimura doimiy ravishda telefonidagi xabarlarni tekshirib turadi.", "stem": "木村さんは、【始終】携帯のメールをチェックしている。", "explanation_uz": "始終（しじゅう）＝ いつも (doim, to'xtovsiz)"}, {"id": "t14-v5-4", "options": ["いいかげんに", "つらくても", "できるだけ", "最後まで"], "answer": 3, "tr": "Senga bu ishni ishonib topshiryapman, shuning uchun bor kuching bilan harakat qil.", "stem": "君にこの仕事を任せるから【せいぜい】がんばってくれ。", "explanation_uz": "せいぜい ＝ できるだけ (qo'ldan kelgancha, bor kuchi bilan)"}, {"id": "t14-v5-5", "options": ["不利な点", "有利な点", "疑問点", "問題点"], "answer": 2, "tr": "Bu rejani amalga oshiradigan bo'lsak, qanday afzalliklari bor?", "stem": "この計画を実施する場合、どんな【メリット】がありますか。", "explanation_uz": "メリット ＝ 有利な点（ゆうりなてん） (afzallik, foydali jihat)"}]}, {"id": "v6", "type": "usage", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Berilgan so'z qaysi gapda eng to'g'ri ma'noda ishlatilganini tanlang.", "questions": [{"id": "t14-v6-1", "options": ["地震の被害は2兆円の大半に達した。", "日本はエネルギーの大半を輸入に頼っている。", "彼が犯人だという証拠は大半ある。", "あの人は株で大半の富を得たらしい。"], "answer": 2, "tr": "Yaponiya energiyaning katta qismini importga tayanadi.", "stem": "【大半】", "explanation_uz": "大半（たいはん）— katta qismi, aksariyati. 2-gap to'g'ri.", "optsTr": ["Zilzila zarari 2 trillion yenning katta qismiga yetdi (xato).", "Yaponiya energiyaning katta qismini importga tayanadi.", "Uning jinoyatchi ekanligiga dalil katta qismi bor (xato).", "U odam aksiyada katta qismi boylikka erishdi (xato)."]}, {"id": "t14-v6-2", "options": ["夫は仕事の付き合いを口実に、毎晩飲んで帰ってくる。", "財布を拾ったことが口実で彼女と知り合いになった。", "お金を借りるには一定の口実がある。", "学校に来ないのはどうもいじめが口実のようだ。"], "answer": 1, "tr": "Erim ishdagi oshno-og'aynigarchilikni bahona qilib, har kecha ichib qaytadi.", "stem": "【口実】", "explanation_uz": "口実（こうじつ）— bahona, vaj. 1-gap to'g'ri.", "optsTr": ["Erim ishdagi muloqotni bahona qilib, har kecha ichib qaytadi.", "Hamyon topib olganim sabab bo'lib u bilan tanishdim (xato, きっかけ ishlatiladi).", "Pul qarz olishda ma'lum bahona bor (xato, 理由 ishlatiladi).", "Maktabga kelmasligi bezorilik bahona shekilli (xato, 原因 ishlatiladi)."]}, {"id": "t14-v6-3", "options": ["明け方、亡くなった母のあいまいな夢を見た。", "あいまいな発言を繰り返す首相に国民は失望した。", "その情報は今のところあいまいなので、確からしい。", "暇がなくてあいまいになっている本がたくさんある。"], "answer": 2, "tr": "Noaniq bayonotlarni takrorlagan bosh vazirdan xalq hafsalasi pir bo'ldi.", "stem": "【あいまい】", "explanation_uz": "あいまい（曖昧）— noaniq, tushunarsiz, mujmal. 2-gap to'g'ri.", "optsTr": ["Tong payti vafot etgan onamning noaniq tushini ko'rdim (xato).", "Noaniq bayonotlarni takrorlayotgan bosh vazirdan xalq hafsalasi pir bo'ldi.", "U ma'lumot hozircha noaniq bo'lgani uchun ishonchli (xato, mantiqsiz).", "Vaqt bo'lmay noaniq bo'lib yotgan kitoblar ko'p (xato)."]}, {"id": "t14-v6-4", "options": ["この演説は要点よくまとめられている。", "彼は何をやらせても要点が悪い。", "人に説明するときは、要点をおさえて話しなさい。", "古都の要点を1日案内してもらった。"], "answer": 3, "tr": "Odamlarga tushuntirayotganda, asosiy mazmunni (muhim nuqtani) qamrab gapir.", "stem": "【要点】", "explanation_uz": "要点（ようてん）— asosiy muhim nuqta. 3-gap to'g'ri.", "optsTr": ["Bu nutq asosiy nuqta yaxshi tuzilgan (xato, 要領よく ishlatiladi).", "Unga nima topshirsang ham asosiy nuqtasi yomon (xato).", "Odamlarga tushuntirganda asosiy nuqtani qamrab gapir.", "Qadimiy shaharning asosiy nuqtasini 1 kun aylantirdi (xato)."]}, {"id": "t14-v6-5", "options": ["この頭痛薬は約12時間、効き目が持続する。", "一晩中持続して運転しないと、明日の朝までに故郷に帰れない。", "このところ、いやな事件が持続して起こる。", "この和菓子はあまり持続しないので早目に食べてください。"], "answer": 1, "tr": "Bu bosh og'rig'i dorisining ta'siri taxminan 12 soat davom etadi.", "stem": "【持続】", "explanation_uz": "持続（じぞく）— ta'sir yoki holatning uzoq saqlanib turishi. 1-gap to'g'ri.", "optsTr": ["Bu bosh og'rig'i dorisining ta'siri taxminan 12 soat davom etadi.", "Tun bo'yi to'xtovsiz haydamasang ertalabgacha yetib bo'lmaydi (xato).", "So'nggi paytlarda yoqimsiz hodisalar ketma-ket yuz beryapti (xato).", "Bu shirinlik uzoq saqlanmaydi, tezroq yeng (xato)."]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_sent_form", "instruction_jp": "次の文の（ ）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi qavs ichiga qo'yish uchun eng to'g'ri grammatik shaklni tanlang.", "questions": [{"id": "t14-g1-1", "options": ["だか", "だとさ", "だが", "だけど"], "answer": 2, "tr": "A: 'Imtihon qachon edi?' B: 'Adashmasam keyingi hafta emish, Yo shunday dedi.'", "stem": "A「試験はいつだっけ？」\nB「たしか来週（【だとさ】）、ヨウさんが言っていたよ。」", "explanation_uz": "〜だとさ（だとか）— eshitgan gapni yetkazish (eshitdimki / emish)."}, {"id": "t14-g1-2", "options": ["としたら", "といえば", "といっても", "といったら"], "answer": 4, "tr": "Jiyanimning shiringina yoqimtoyligini aytmaysizmi, xuddi farishtaning o'zginasi!", "stem": "めいのかわいらしさ（【といったら】）、まるで天使のようだ。", "explanation_uz": "〜といったら（ありはしない）— ...darajasini aytmaysizmi (kuchli hayrat/his)."}, {"id": "t14-g1-3", "options": ["からこそ", "からは", "くせに", "ことだから"], "answer": 1, "tr": "Men ham aynan shunday xatoga yo'l qo'yganim sababli ham sizni ogohlantiryapman.", "stem": "私も同じ失敗をした（【からこそ】）、あなたに注意しているのです。", "explanation_uz": "〜からこそ — aynan shu sabab tufayligina (kuchli urg'u)."}, {"id": "t14-g1-4", "options": ["真ん中に", "中心に", "中央に", "最大に"], "answer": 2, "tr": "Bizning kompaniya bolalar uchun rasmli kitoblarni asosiy yo'nalish qilib, ko'plab kitoblarni nashr etadi.", "stem": "我が社は、子ども向けの絵本を（【中心に】）多くの本を出版しています。", "explanation_uz": "〜を中心に — ...ni asosiy qilib olgan holda."}, {"id": "t14-g1-5", "options": ["にかぎりなく", "にかかわりなく", "はぬきにして", "のせいで"], "answer": 2, "tr": "Hukumat kompaniyalarga yoshiga qaramasdan (yoshidan qat'i nazar) xodimlarni ishga olishni tayinladi.", "stem": "年齢（【にかかわりなく】）社員を募集するように、政府は会社を指導した。", "explanation_uz": "〜にかかわりなく — ...dan qat'i nazar, farqsiz."}, {"id": "t14-g1-6", "options": ["ばかりに", "ところに", "ばかりか", "どころか"], "answer": 3, "tr": "U kishi yo'l ko'rsatib bergani yetmagandek, ataylab vokzalga qadar olib borib qo'ydi.", "stem": "その人は道を教えてくれた（【ばかりか】）、わざわざ駅まで連れて行ってくれた。", "explanation_uz": "〜ばかりか — ...gina emas, balki (ustiga-ustak)."}, {"id": "t14-g1-7", "options": ["事情にして", "結果として", "契機にして", "原因にして"], "answer": 3, "tr": "Rahbar almashishini yaxshi burilish yasab, kompaniya nomini o'zgartiradigan bo'ldik.", "stem": "社長が交代したことを（【契機にして】）、社名を変えることになった。", "explanation_uz": "〜を契機（けいき）にして — ...ni yaxshi fursat/turtki bilib."}, {"id": "t14-g1-8", "options": ["合格するわけがある", "合格するものがある", "合格することに決めてある", "合格するに決まっている"], "answer": 4, "tr": "Imtihondan xavotir olmasang ham bo'ladi. Sendek bilim bo'lsa, o'tishing aniq-ku!", "stem": "試験の心配はしなくていい。君ほどの学力があれば（【合格するに決まっている】）よ。", "explanation_uz": "〜に決まっている — albatta ...bo'lishi aniq, shubhasiz."}, {"id": "t14-g1-9", "options": ["贈らないものでない", "贈るものではない", "贈らないわけではない", "贈るわけはない"], "answer": 2, "tr": "To'y sovg'asiga pichoq berish to'g'ri emas deyilsa-da, agar qarshi tomon xohlayotgan bo'lsa yaxshi emasmi?", "stem": "結婚のお祝いに包丁を（【贈るものではない】）と言われるが、相手が欲しいならよいのではないか。", "explanation_uz": "〜ものではない — odatda ...qilish to'g'ri kelmaydi (axloqiy/an'anaviy qoida)."}, {"id": "t14-g1-10", "options": ["がんばるにすぎない", "がんばりすぎない", "がんばろうとする", "がんばるばかりの"], "answer": 2, "tr": "Haddan ortiq o'zini zo'riqtirmaydigan odamlar aksincha ishni uzoqroq davom ettira oladi.", "stem": "あまり（【がんばりすぎない】）人のほうが、かえって長続きするものだ。", "explanation_uz": "〜すぎない — me'yoridan oshirmaslik; がんばりすぎない = haddan ortiq zo'riqmaslik."}, {"id": "t14-g1-11", "options": ["お見舞いにくるところ", "お見舞いされるはず", "お見舞いにくること", "お見舞いにくるとき"], "answer": 1, "tr": "Aslida rahbarning o'zi hol so'ragani kelishi kerak bo'lgan vaziyat edi, ammo bo'lim boshlig'i bo'lgan men keldim.", "stem": "本来なら社長が（【お見舞いにくるところ】）ですが、失礼ながら部長の私がまいりました。", "explanation_uz": "〜ところ（ですが）— aslida shunday bo'lishi kerak bo'lgan vaziyatda."}, {"id": "t14-g1-12", "options": ["なりそうもない", "なるはずがない", "なりきれない", "なっていられない"], "answer": 3, "tr": "A: 'Balog'at bayramida to'polon qiladiganlar ko'payayotganga o'xshaydi-a?' B: 'Yaponiyada 20 yoshga to'lsa ham to'liq katta odam bo'la olmaganlar ko'p-da.'", "stem": "A「成人式であばれる人が増えているようですね。」\nB「日本では20歳になっても、大人に（【なりきれない】）人が多いのです。」", "explanation_uz": "〜きれない — oxirigacha / to'liq ...bo'la olmaslik."}]}, {"id": "g2", "type": "grammar_sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi yulduzcha (★) o'rniga keluvchi to'g'ri so'zni tanlang.", "questions": [{"id": "t14-g2-1", "options": ["にも", "ように", "理解できる", "絵による"], "answer": 2, "tr": "Yapon tilida o'qiy olmaydigan odamlarga ham tushunarli bo'lishi uchun rasmli belgilar qo'yilgan.", "explanation_uz": "日本語が読めない人【にも】【理解できる】【★ように】【絵による】マークがつけられている。", "prefix": "日本語が読めない人", "suffix": "マークがつけられている。", "starPos": 3, "order": [1, 3, 2, 4]}, {"id": "t14-g2-2", "options": ["やったほうが", "迷ったときは", "かと", "やめよう"], "answer": 3, "tr": "Qilsammi yoki qilmasammi deb ikkilanib qolganda qilgan afzalroq, shunda pushaymon bo'lmaysan.", "explanation_uz": "やろうか【やめよう】【★かと】【迷ったときは】【やったほうが】悔やまなくてすむことが多い。", "prefix": "やろうか", "suffix": "悔やまなくてすむことが多い。", "starPos": 2, "order": [4, 3, 2, 1]}, {"id": "t14-g2-3", "options": ["新製品を", "もとに", "作る", "して"], "answer": 4, "tr": "Mijozlarning fikr-mulohazalari asosida yangi mahsulot ishlab chiqish uchun yig'ilish o'tkazildi.", "explanation_uz": "お客様の意見を【もとに】【★して】【新製品を】【作る】ための会議が開かれた。", "prefix": "お客様の意見を", "suffix": "ための会議が開かれた。", "starPos": 2, "order": [2, 4, 1, 3]}, {"id": "t14-g2-4", "options": ["めぐって", "兄弟が", "あげく", "はげしく争った"], "answer": 4, "tr": "Ota-onaning merosi ustida aka-ukalar qattiq janjallashishi oqibatida oxir-oqibat bir-biridan yuz o'girdi.", "explanation_uz": "親の遺産を【めぐって】【兄弟が】【★はげしく争った】【あげく】とうとうけんか別れになった。", "prefix": "親の遺産を", "suffix": "とうとうけんか別れになった。", "starPos": 3, "order": [1, 2, 4, 3]}, {"id": "t14-g2-5", "options": ["料理をしなくていい", "好きな", "だけでなく", "ということ"], "answer": 1, "tr": "Sayohatni yoqtiruvchi uy bekalari ko'pligiga manzaralarni yoqtirishdan tashqari, ovqat pishirmaslik imkoni ham sababdir.", "explanation_uz": "旅好きの主婦が多いのは、めずらしい景色を見るのが【好きな】【だけでなく】【★料理をしなくていい】【ということ】も理由の1つだ。", "prefix": "旅好きの主婦が多いのは、めずらしい景色を見るのが", "suffix": "も理由の1つだ。", "starPos": 3, "order": [2, 3, 1, 4]}]}, {"id": "g3", "type": "grammar_passage_context", "instruction_jp": "次の文章を読んで、文章全体の趣旨を踏まえて、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh o'rinlar uchun kontekstga mos eng to'g'ri javobni tanlang.", "passage": "コミュニケーションには「聞く」「[ 50-a ]」という情報を中に取り入れる作業と、「話す」「[ 50-b ]」という情報を外に発信する作業があります。\nその場合、特に重要なのが「聞く」という作業です。ある学者の調査によると、コミュニケーションに使われる時間は、「話す」が30%、「読む」が16%、「書く」が9%なのに対して、「聞く」は45%も使われています。それ[ 51 ]、聞く練習はあまり行われない傾向があります。これは、声や音は自然に耳に入ってくるのに対して、話す・読む・書くは[ 52 ]作業になるからでしょう。\nそこで自然に音が耳に入ってくることを「聞く」、意識して聞くことを「聴く」と表しましょう。\nまず、話を聴くことによって、相手がどう考え、何を感じ、どうしようとしているかがわかります。一般的な情報も相手から得ることができます。\nその次に、相手の話を聴くことは、相手に注目すること、すなわち相手の存在を認めることを意味します。話を聴かないと逆に、相手は自分を[ 53 ]感じます。\n第三に、相手との関係をよくすることができます。話をよく聴くことによって、相手と親しい関係に[ 54 ]、相手もこちらに好意を感じるようになるのです。\nというわけで、コミュニケーション能力をつけるには、まず「聴く技術」を身につけることが大切なのです。", "questions": [{"id": "t14-g3-1", "options": ["a 読む / b 書く", "a 書く / b 読む", "a 話す / b 聞く", "a 読む / b 聞く"], "answer": 1, "tr": "［ 50-a ］va［ 50-b ］uchun to'g'ri juftlikni tanlang.", "stem": "［ 50-a ］ / ［ 50-b ］に入る組み合わせとして最もよいものを選びなさい。", "explanation_uz": "Axborotni qabul qilishga 'o'qish (読む)', tashqariga uzatishga 'yozish (書く)' to'g'ri keladi.", "blankNo": 50}, {"id": "t14-g3-2", "options": ["だからこそ", "のために", "にもかかわらず", "にしたがって"], "answer": 3, "tr": "［ 51 ］bo'sh o'rniga mos bog'lovchini tanlang.", "stem": "［ 51 ］に入る最もよいものを選びなさい。", "explanation_uz": "45% ishlatilishiga qaramasdan mashq qilinmaydi: 「にもかかわらず (qaramasdan)」.", "blankNo": 51}, {"id": "t14-g3-3", "options": ["無意識の", "自然な", "意識的な", "不自然な"], "answer": 3, "tr": "［ 52 ］bo'sh o'rniga mos so'zni tanlang.", "stem": "［ 52 ］に入る最もよいものを選びなさい。", "explanation_uz": "O'z ixtiyori bilan ongli ravishda bajariladigan faoliyat: 「意識的な (ongli/maqsadli)」.", "blankNo": 52}, {"id": "t14-g3-4", "options": ["攻撃されたように", "否定されたように", "認められたように", "注目されたように"], "answer": 2, "tr": "［ 53 ］bo'sh o'rniga mos ifodani tanlang.", "stem": "［ 53 ］に入る最もよいものを選びなさい。", "explanation_uz": "Suhbatdoshi uni eshitmasa, inkor etilgandek his qiladi: 「否定されたように」.", "blankNo": 53}, {"id": "t14-g3-5", "options": ["なりそうになると", "なるとしても", "なるにつけても", "なるとともに"], "answer": 4, "tr": "［ 54 ］bo'sh o'rniga mos grammatik shaklni tanlang.", "stem": "［ 54 ］に入る最もよいものを選びなさい。", "explanation_uz": "Yaqin munosabatga aylanishi bilan birga: 「なるとともに」.", "blankNo": 54}]}]}]}, "15": {"id": 15, "title_jp": "第15回 模擬テスト", "title_uz": "15-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t15-v1-1", "options": ["ていか", "ていが", "ていげ", "でいが"], "answer": 1, "tr": "Nonushta qilganda uyqu paytida pasaygan tana harorati ko'tariladi, shuning uchun tushgacha bo'lgan diqqat-e'tibor oshadi.", "stem": "朝食をとると睡眠中に【低下】した体温が上がるので、午前中の集中力が高まる。", "reading": "ていか", "explanation_uz": "低下 → ていか (pasayish, tushish)"}, {"id": "t15-v1-2", "options": ["しずむ", "ひずむ", "すすむ", "ゆがむ"], "answer": 1, "tr": "Sifatsiz qurilish tufayli, uyning poli yurganda cho'kadi (o'tirib qoladi).", "stem": "手抜き工事のせいで、家の床が歩くと【沈む】。", "reading": "しずむ", "explanation_uz": "沈む → しずむ (cho'kmoq, pasaymoq)"}, {"id": "t15-v1-3", "options": ["かんじんじ", "がんじんじ", "かんしんじ", "かんじんし"], "answer": 3, "tr": "Iqtisodiyotning tiklanishi ish qidirayotgan talabalar uchun eng katta qiziqish / diqqat markazidagi masaladir.", "stem": "景気の回復は就職活動中の学生にとって最大の【関心事】である。", "reading": "かんしんじ", "explanation_uz": "関心事 → かんしんじ (qiziqish mavzusi, e'tibor qaratilgan masala)"}, {"id": "t15-v1-4", "options": ["のうさんぶつ", "のうざんふつ", "のうさんもつ", "のうさくもつ"], "answer": 1, "tr": "Anormal ob-havo tufayli qishloq xo'jaligi mahsulotlarining nobud bo'lishi har yerda sodir bo'lmoqda.", "stem": "異常気象による【農産物】の被害が各地で起きている。", "reading": "のうさんぶつ", "explanation_uz": "農産物 → のうさんぶつ (qishloq xo'jaligi mahsulotlari)"}, {"id": "t15-v1-5", "options": ["きてい", "きそく", "きじゅん", "きはん"], "answer": 3, "tr": "Chaqaloqlar o'yinchoqlarining xavfsizlik standarti haddan tashqari qat'iy bo'lishi ortiqchalik qilmaydi.", "stem": "赤ちゃん用おもちゃの安全【基準】は厳し過ぎることはない。", "reading": "きじゅん", "explanation_uz": "基準 → きじゅん (standart, me'yor)"}]}, {"id": "v2", "type": "kanji_writing", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zni kanjida yozish uchun eng to'g'risini tanlang.", "questions": [{"id": "t15-v2-1", "options": ["診断", "侵断", "審断", "信断"], "answer": 1, "tr": "Ruhiy kasalliklarga hatto tashxis qo'yishning o'zi ham nihoyatda qiyindir.", "stem": "心の病は病名を【しんだん】するのさえ非常に難しい。", "reading": "しんだん", "explanation_uz": "診断 → しんだん (tashxis, tibbiy ko'rik)"}, {"id": "t15-v2-2", "options": ["項ける", "預ける", "領ける", "頂ける"], "answer": 2, "tr": "Teatrda katta yuk va ustki kiyimni kiyimxonaga (saqlash joyiga) topshiraman.", "stem": "劇場で、大きな荷物や上着をクロークに【あずける】。", "reading": "あずける", "explanation_uz": "預ける → あずける (saqlashga topshirmoq, berib turmoq)"}, {"id": "t15-v2-3", "options": ["利行", "利効", "利口", "利硬"], "answer": 3, "tr": "U bola juda ham aqlli (ziyrak) ko'rinadi.", "stem": "あの子はいかにも【りこう】そうだ。", "reading": "りこう", "explanation_uz": "利口 → りこう (aqlli, zehnli, ziyrak)"}, {"id": "t15-v2-4", "options": ["研修", "検修", "研習", "検習"], "answer": 1, "tr": "Yangi xodimlarning malaka oshirish mashg'uloti ishga kirgach bir oy davomida o'tkaziladi.", "stem": "新入社員の【けんしゅう】は入社後一カ月行う。", "reading": "けんしゅう", "explanation_uz": "研修 → けんしゅう (malaka oshirish, stajirovka, trening)"}, {"id": "t15-v2-5", "options": ["除まれた", "奪まれた", "詐まれた", "盗まれた"], "answer": 4, "tr": "Kecha tunda zargarlik do'konidan 200 million yenlik tovarlar noma'lum kimsalar tomonidan o'g'irlab ketildi.", "stem": "昨夜宝石店で2億円相当の商品が何者かに【ぬすまれた】。", "reading": "ぬすまれた", "explanation_uz": "盗む → ぬすむ (o'g'irlamoq; 盗まれた = o'g'irlandi)"}]}, {"id": "v3", "type": "word_formation", "instruction_jp": "（ ）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga qo'yish uchun eng to'g'ri so'z yasovchi qo'shimchani tanlang.", "questions": [{"id": "t15-v3-1", "options": ["新", "現", "反", "前"], "answer": 3, "tr": "U siyosatchi bir paytlar tuzumga qarshi harakatning yetakchisi edi.", "stem": "あの政治家はかつて（【反】）体制運動のリーダーだった。", "explanation_uz": "反体制 → はんたいせい (tuzumga/rejimga qarshi)"}, {"id": "t15-v3-2", "options": ["屋", "家", "人", "者"], "answer": 2, "tr": "Bo'lim boshlig'i o'ziga juda ishongan inson.", "stem": "部長はとても自信（【家】）だ。", "explanation_uz": "自信家 → じしんか (o'ziga qattiq ishongan odam)"}, {"id": "t15-v3-3", "options": ["大", "多", "広", "全"], "answer": 3, "tr": "Vulqon kuli keltirgan zarar keng ko'lamli hududga yoyildi.", "stem": "火山灰の被害は（【広】）範囲におよんだ。", "explanation_uz": "広範囲 → こうはんい (keng qamrovli, keng hudud)"}, {"id": "t15-v3-4", "options": ["良", "好", "優", "善"], "answer": 2, "tr": "Suhbatda qarshi tomonda ijobiy taassurot qoldiradigan kostyum tanlayman.", "stem": "面接で相手に（【好】）印象を与えるスーツを選ぶ。", "explanation_uz": "好印象 → こういんしょう (yaxshi/ijobiy taassurot)"}, {"id": "t15-v3-5", "options": ["期", "代", "性", "時"], "answer": 1, "tr": "U o'smirlik davrining aksar qismini chet elda o'tkazdi.", "stem": "彼は少年（【期】）のほとんどを海外で過ごした。", "explanation_uz": "少年期 → しょうねんき (o'smirlik/bolalik davri)"}]}, {"id": "v4", "type": "context_vocab", "instruction_jp": "（ ）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gap mazmuniga mos keluvchi eng to'g'ri so'zni tanlang.", "questions": [{"id": "t15-v4-1", "options": ["ようするに", "そういえば", "おたがいに", "ようやく"], "answer": 1, "tr": "Ishsizlar ko'paysa jinoyat ham ko'payadi. Qisqasi, iqtisodiy inqiroz jinoyatning sababi deb aytish mumkin.", "stem": "失業者が増えると犯罪も増える。（【ようするに】）不景気が犯罪の原因と言える。", "explanation_uz": "要するに → ようするに (qisqasi, xullas)"}, {"id": "t15-v4-2", "options": ["訂正", "修正", "修理", "治療"], "answer": 3, "tr": "Bolaligimdan buzilgan o'yinchoqlarni ta'mirlash yoki biror narsa yasashga usta edim.", "stem": "子どものころからこわれたおもちゃを（【修理】）したり、何かを組み立てたりするのが得意だった。", "explanation_uz": "修理 → しゅうり (ta'mirlash, tuzatish)"}, {"id": "t15-v4-3", "options": ["打ち抜いて", "出し抜いて", "引き抜いて", "勝ち抜いて"], "answer": 4, "tr": "Katta raqobatdan g'alaba bilan o'tib, mashhur kompaniyaga ishga kirdi.", "stem": "狭き門を（【勝ち抜いて】）、人気の会社に就職できた。", "explanation_uz": "勝ち抜く → かちぬく (raqobatda g'olib chiqmoq)"}, {"id": "t15-v4-4", "options": ["進入", "侵入", "加入", "移入"], "answer": 2, "tr": "Kompyuter virusi tarmoqqa noqonuniy ravishda kirib oldi.", "stem": "コンピューターウイルスが、ネットワークに不正に（【侵入】）した。", "explanation_uz": "侵入 → しんにゅう (bostirib kirish, ruxsatsiz suqilib kirish)"}, {"id": "t15-v4-5", "options": ["うらやましい", "にくらしい", "なつかしい", "ふさわしい"], "answer": 4, "tr": "Odamlar o'rtasidagi munosabatlarni qadrlaydigan u inson jamoa yetakchisi roliga munosib shaxsdir.", "stem": "人と人との結び付きを大切にする彼は、チームのまとめ役に（【ふさわしい】）人物だ。", "explanation_uz": "ふさわしい (munosib, loyiq, mos)"}, {"id": "t15-v4-6", "options": ["アップ", "ダウン", "プラス", "ダブル"], "answer": 3, "tr": "Qiyin ishni bir o'zim uddalagan tajribam mening hayotim uchun katta yutuq bo'ldi.", "stem": "1人で困難な仕事をやりとげた経験は、私の人生の（【プラス】）になった。", "explanation_uz": "プラス (foyda, yutuq, ijobiy tajriba)"}, {"id": "t15-v4-7", "options": ["設備", "完備", "建設", "整理"], "answer": 2, "tr": "Bu kompaniya ayollar orasida mashhurligining sababi — bolalar bog'chasi to'liq jihozlangan bo'lib, bolani topshirib ishlash mumkin.", "stem": "この会社が女性に人気なのは、託児所が（【完備】）され子どもを預けて働けるからだ。", "explanation_uz": "完備 → かんび (to'liq jihozlanganlik)"}]}, {"id": "v5", "type": "paraphrase", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin so'zni tanlang.", "questions": [{"id": "t15-v5-1", "options": ["不十分な", "不正確な", "不明な", "不透明な"], "answer": 1, "tr": "Internet jinoyatlariga nisbatan ogohlik darajasi yetarli bo'lmagan odamlar ko'p.", "stem": "ネット犯罪に対する意識が【薄い】人は多い。", "explanation_uz": "意識が薄い ＝ 不十分な（ふじゅうぶんな） (yetarli bo'lmagan)"}, {"id": "t15-v5-2", "options": ["思い当たる", "思い上がる", "思い浮かべる", "思い出す"], "answer": 3, "tr": "Bu qo'shiqni eshitgan sayin daryo oqimini ko'z oldimga keltiraman.", "stem": "この曲を聞くたびに、川の流れを【連想する】。", "explanation_uz": "連想する（れんそうする）＝ 思い浮かべる（おもいうかべる） (xayolga keltirmoq)"}, {"id": "t15-v5-3", "options": ["だから", "やがて", "どんな", "もしも"], "answer": 4, "tr": "Mabodo zilzila bo'lib qolsa ham buyumlarni olib chiqib keta oladigan qilib tayyorlab qo'yganman.", "stem": "【万一】地震があっても、荷物を持ち出せるように準備している。", "explanation_uz": "万一（まんいち）＝ もしも (mabodo, bordiyu)"}, {"id": "t15-v5-4", "options": ["細かく", "少しは", "最初から", "勝手に"], "answer": 1, "tr": "Kimura senpay to'garak faoliyatiga har bir mayda narsagacha burnini suqadi.", "stem": "木村先輩はサークル活動に【いちいち】口を出す。", "explanation_uz": "いちいち ＝ 細かく（こまかく） (maydalashib, har bir narsaga)"}, {"id": "t15-v5-5", "options": ["ベース", "ペース", "メーター", "パーセント"], "answer": 2, "tr": "Bu yil o'tmishdagi eng yuqori sur'atda yo'l-transport hodisasida vafot etganlar soni oshmoqda.", "stem": "今年は過去最高の【速度】で交通事故の死者が増えている。", "explanation_uz": "速度（そくど）＝ ペース (sur'at, tezlik)"}]}, {"id": "v6", "type": "usage", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Berilgan so'z qaysi gapda eng to'g'ri ma'noda ishlatilganini tanlang.", "questions": [{"id": "t15-v6-1", "options": ["親友が交通事故で亡くなったというみじめなお知らせを受け取った。", "息子が口答えしたら母はみじめな顔をした。", "彼は事業に失敗し、今ではみじめな生活をしているという。", "犯罪が低年齢化しているとは、なんとみじめなことだ。"], "answer": 3, "tr": "U biznesda inqirozga uchrab, hozirda achinarli hayot kechirayotgan ekan.", "stem": "【みじめ】", "explanation_uz": "みじめ（惨め）— achinarli, ayanchli, xor holat. 3-gap to'g'ri.", "optsTr": ["Yaqin do'stim vafot etgani haqida ayanchli xabar oldim (xato).", "O'g'li gap qaytargach ona ayanchli yuz qildi (xato).", "U biznesda inqirozga uchrab, hozirda achinarli hayot kechirayotgan ekan.", "Jinoyat yosharib borayotgani naqadar ayanchli ish (xato)."]}, {"id": "t15-v6-2", "options": ["最近は経済の具合が悪いので仕事が少ない。", "頭の具合がよくないといい考えが浮かばない。", "政治の具合がよくならないと国民の生活も大変だ。", "車のエンジンの具合が悪くて、変な音がする。"], "answer": 4, "tr": "Mashina motorining ishlash holati yomonlashib, g'alati ovoz chiqaryapti.", "stem": "【具合】", "explanation_uz": "具合（ぐあい）— tana yoki texnikaning ishlash holati/ahvoli. 4-gap to'g'ri.", "optsTr": ["So'nggi paytlarda iqtisod holati yomon (xato).", "Bosh holati yaxshi bo'lmasa yaxshi fikr kelmaydi (xato).", "Siyosat holati yaxshilanmasa fuqarolar hayoti ham qiyin (xato).", "Mashina dvigatelining holati yomon bo'lib, g'alati ovoz chiqmoqda."]}, {"id": "t15-v6-3", "options": ["子どもが世の中に目を覚ますことが多く寝不足気味だ。", "動物の世の中は力の関係がはっきりしている。", "そんな甘い考えでは世の中渡っていけない。", "彼は若くして政治の世の中に入った。"], "answer": 3, "tr": "Bunday xomxayol fikrlar bilan jamiyatda yashab ketolmaysan.", "stem": "【世の中】", "explanation_uz": "世の中（よのなか）— insonlar jamiyati; 世の中を渡る = hayotda yashab o'tmoq. 3-gap to'g'ri.", "optsTr": ["Bola jamiyatda ko'zini ochib uyqusizlik bo'lyapti (xato, 夜中 ishlatiladi).", "Hayvonlar jamiyati kuchlar munosabati aniq (xato, 世界 ishlatiladi).", "Bunday xomxayol fikrlar bilan jamiyatda yashab ketolmaysan.", "U yoshligidan siyosat jamiyatiga kirdi (xato, 政界 ishlatiladi)."]}, {"id": "t15-v6-4", "options": ["道路工事の雑音がして一晩中眠れなかった。", "このラジオは雑音がひどくて、声が聞き取りにくい。", "飛行場の近くの住民は、飛行機の雑音に悩まされている。", "私の母は細かいことまで雑音を言う。"], "answer": 2, "tr": "Bu radioning shovqini (xirillashi) kuchli bo'lib, ovoz yaxshi eshitilmayapti.", "stem": "【雑音】", "explanation_uz": "雑音（ざつおん）— apparatlar yoki radioning g'ashga teguvchi xirillash shovqini. 2-gap to'g'ri.", "optsTr": ["Yo'l qurilishi xirillashi sabab uxlolmadim (xato, 騒音 ishlatiladi).", "Bu radioning shovqini (xirillashi) kuchli bo'lib, ovoz yaxshi eshitilmayapti.", "Aeroport yaqinidagi aholi samolyot shovqinidan qiynalmoqda (xato, 騒音 ishlatiladi).", "Onam mayda narsalargacha xirillash aytadi (xato, 小言 ishlatiladi)."]}, {"id": "t15-v6-5", "options": ["あっという間に彼らの結婚のうわさが拡張した。", "海外事業を拡張するため、社員を募集する。", "山頂に着くと目の前に美しい景色が拡張した。", "ペットの写真を拡張して、部屋に飾った。"], "answer": 2, "tr": "Chet eldagi biznesni kengaytirish uchun yangi xodimlarni qabul qilmoqda.", "stem": "【拡張】", "explanation_uz": "拡張（かくちょう）— ko'lam yoki maydonni kengaytirish. 2-gap to'g'ri.", "optsTr": ["Tezda ularning to'yi haqidagi mish-mish kengaydi (xato, 広まった ishlatiladi).", "Chet eldagi biznesni kengaytirish uchun xodimlarni qabul qilmoqda.", "Tog' cho'qqisiga chiqqach go'zal manzara kengaydi (xato, 広がった ishlatiladi).", "Uy hayvoni rasmini kengaytirib xonaga qo'ydi (xato, 拡大して ishlatiladi)."]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_sent_form", "instruction_jp": "次の文の（ ）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi qavs ichiga qo'yish uchun eng to'g'ri grammatik shaklni tanlang.", "questions": [{"id": "t15-g1-1", "options": ["とっても", "かけても", "ついても", "よっても"], "answer": 2, "tr": "'Beysbol dargohi' degan nomimiz sha'niga qasamki, maktabimiz albatta g'alaba qozonishini istayman.", "stem": "「野球の名門」という名前に（【かけても】）、ぜひ我が校が優勝したいものだ。", "explanation_uz": "〜にかけて（も）— ...ning sha'ni yoki obro'sini o'rtaga qo'yib."}, {"id": "t15-g1-2", "options": ["せいで", "ために", "くせに", "あまり"], "answer": 3, "tr": "U boyvachcha bo'la turib shunaqangi xasiski, to'lashi kerak bo'lgan pulni ham sira to'lamaydi.", "stem": "彼は大金持ちの（【くせに】）けちで、払うべき金もなかなか払わない。", "explanation_uz": "〜くせに — ...bo'la turib (norozilik va tanqidiy urg'u)."}, {"id": "t15-g1-3", "options": ["によらず", "にかかわらず", "を問わず", "もかまわず"], "answer": 4, "tr": "10 yildan so'ng o'g'lining yuzini ko'rgan ona odamlarning nigohiga ham parvo qilmay o'g'lini bag'riga bosdi.", "stem": "10年ぶりに息子の顔を見た母は、人目（【もかまわず】）息子を抱きしめた。", "explanation_uz": "〜もかまわず — ...ga ham parvo qilmay, e'tibor bermasdan."}, {"id": "t15-g1-4", "options": ["火をつけている", "火をつける", "火をつけそうな", "火をつけた"], "answer": 4, "tr": "Sigaretga o't yoqqan zahoti baland ovoz bilan xona portlab ketdi.", "stem": "たばこに（【火をつけた】）とたんに、大きな音とともに部屋が爆発した。", "explanation_uz": "動詞タ形＋とたんに — ...qilgan zahotiyoq."}, {"id": "t15-g1-5", "options": ["からでないと", "からすると", "からといって", "からして"], "answer": 1, "tr": "Bu masala bo'yicha rahbardan aniqlashtirib olmaguncha javob bera olmayman.", "stem": "この件に関しては、上司に確認して（【からでないと】）お答えできません。", "explanation_uz": "〜てからでないと（〜できない）— ...qilmaguncha (keyingisini qilib bo'lmaydi)."}, {"id": "t15-g1-6", "options": ["だらけ", "ばかり", "だけ", "のみ"], "answer": 1, "tr": "Bunday axlatga to'la uyga uyalganimdan mehmon ham chaqira olmayman.", "stem": "こんなごみ（【だらけ】）の家には、はずかしくてお客さんが呼べない。", "explanation_uz": "〜だらけ — ...ga to'la, bosib ketgan (salbiy narsalar uchun)."}, {"id": "t15-g1-7", "options": ["というより", "としたら", "とするなら", "といっては"], "answer": 1, "tr": "Bu vino degandan ko'ra ko'proq uzum sharbatiga yaqin ta'mga ega.", "stem": "これはワイン（【というより】）、むしろぶどうジュースに近い味だ。", "explanation_uz": "〜というより（むしろ）— ...degandan ko'ra ko'proq."}, {"id": "t15-g1-8", "options": ["かねる", "かねない", "きれる", "きれない"], "answer": 2, "tr": "U erkak pul uchun bo'lsa hattoki do'stiga ham xiyonat qilib yuborishi hech gap emas.", "stem": "あの男は金のためなら、友人だって裏切り（【かねない】）。", "explanation_uz": "動詞マス形＋かねない — ...qilib yuborishi mumkin (salbiy ehtimol)."}, {"id": "t15-g1-9", "options": ["ぬれたままの", "ぬらしたっきりの", "ぬれたばかりの", "ぬらされたものの"], "answer": 1, "tr": "Yomg'irda ivigan kiyimni kiyib yuraversangiz shamollab qolasiz. Tezda kiyimingizni almashtiring.", "stem": "雨に（【ぬれたままの】）服を着ていたら、風邪をひきますよ。早く着替えなさい。", "explanation_uz": "〜たままの — ...holaticha turgan."}, {"id": "t15-g1-10", "options": ["なりっこない", "ならずにはいられない", "なるおそれがある", "なるともかぎらない"], "answer": 3, "tr": "Bundan buyon ham yomg'ir yog'maydigan kunlar davom etsa, suv ta'minoti to'xtab qolish xavfi bor.", "stem": "これ以上雨が降らない日が続くと、断水に（【なるおそれがある】）。", "explanation_uz": "〜おそれがある — ...xavfi/xatari mavjud."}, {"id": "t15-g1-11", "options": ["いらっしゃいますね", "おっしゃいますね", "申されますね", "おられますね"], "answer": 1, "tr": "A: 'Ito bo'laman, bugun kechga 2 kishilik joy band qilgan bo'lishim kerak.' B: 'Ito janoblari bo'lasiz-a? Ha, haqiqatan buyurtmangiz bor.'", "stem": "A「伊藤といいますが、今夜2名で予約を取っているはずです。」\nB「伊藤様で（【いらっしゃいますね】）。はい、たしかにご予約いただいています。」", "explanation_uz": "〜でいらっしゃいますね — muloyim ehtirom/hurmat shakli."}, {"id": "t15-g1-12", "options": ["を怒らせそうになったら", "に怒りそうになったら", "が怒られそうになったら", "が怒りそうにしたら"], "answer": 2, "tr": "Siz juda jahldorsiz, shuning uchun qarshi tomonga qarab jahlingiz chiqa boshlaganda, avval 1 dan 10 gacha sanab tinchlaning.", "stem": "あなたは本当に短気だから、相手（【に怒りそうになったら】）、まずゆっくり1から10まで数えて落ち着きなさい。", "explanation_uz": "相手に怒る — birovga jahli chiqmoq."}]}, {"id": "g2", "type": "grammar_sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi yulduzcha (★) o'rniga keluvchi to'g'ri so'zni tanlang.", "questions": [{"id": "t15-g2-1", "options": ["待たされた", "診察はすぐ", "あげくに", "さんざん"], "answer": 3, "tr": "Ahvolim yomonlashib shifoxonaga borgan edim, uzoq kuttirishgach tekshiruv tezda tugab, 'shunchaki shamollash' deyishdi.", "explanation_uz": "気分が悪くて病院に行ったが【さんざん】【待たされた】【★あげくに】【診察はすぐ】終わり、「ただの風邪です」と言われた。", "prefix": "気分が悪くて病院に行ったが", "suffix": "終わり、「ただの風邪です」と言われた。", "starPos": 3, "order": [4, 1, 3, 2]}, {"id": "t15-g2-2", "options": ["彼も", "子どもに", "対しては", "言われる"], "answer": 2, "tr": "Pishiq va sovuqqon deyilgan u kishi ham bolalarga nisbatan doimo mehribon edi.", "explanation_uz": "皮肉で冷たいと【言われる】【彼も】【★子どもに】【対しては】いつもやさしかった。", "prefix": "皮肉で冷たいと", "suffix": "いつもやさしかった。", "starPos": 3, "order": [4, 1, 2, 3]}, {"id": "t15-g2-3", "options": ["既卒かを", "新卒か", "問わず", "採用試験を"], "answer": 1, "tr": "Bu kompaniyada yangi bitiruvchimi yoki avval bitirganmi qat'i nazar qabul imtihonini topshirish mumkin.", "explanation_uz": "この会社は【新卒か】【★既卒かを】【問わず】【採用試験を】受けることができます。", "prefix": "この会社は", "suffix": "受けることができます。", "starPos": 2, "order": [2, 1, 3, 4]}, {"id": "t15-g2-4", "options": ["実行されるのに", "試してみる", "少数の学校で", "先立ち"], "answer": 4, "tr": "Yangi ta'lim uslubi amaliyotga joriy etilishidan oldin bir nechta maktablarda sinovdan o'tkaziladigan bo'ldi.", "explanation_uz": "新しい教育方法が【実行されるのに】【★先立ち】【少数の学校で】【試してみる】ことになった。", "prefix": "新しい教育方法が", "suffix": "ことになった。", "starPos": 2, "order": [1, 4, 3, 2]}, {"id": "t15-g2-5", "options": ["あるまいが", "道に迷う", "一応", "ことなど"], "answer": 1, "tr": "Kimura kabi tajribali gid yo'ldan adashishi amrimahol bo'lsa-da, har ehtimolga qarshi politsiyaga telefon qilaylik.", "explanation_uz": "木村さんほどのベテランのガイドが【道に迷う】【ことなど】【★あるまいが】【一応】警察に電話しよう。", "prefix": "木村さんほどのベテランのガイドが", "suffix": "警察に電話しよう。", "starPos": 3, "order": [2, 4, 1, 3]}]}, {"id": "g3", "type": "grammar_passage_context", "instruction_jp": "次の文章を読んで、文章全体の趣旨を踏まえて、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh o'rinlar uchun kontekstga mos eng to'g'ri javobni tanlang.", "passage": "うそをついている人を、どこで見分ければいいでしょうか。\nある大学教授が、何人かの人が話しているビデオを学生に見せ、「だれがうそをついているか。なぜそう判断したか」をたずねました。\n最も多くの人が注目したのが「話し方」で、次に「話の内容」でした。「目の動き」「顔の表情」「話す時間」が同じくらいで、「手の動き」「足の動き」に注目した人はわずかでした。\nところが[ 50 ]、一番多くうそをついている人を当てたのは、「手の動き」に注目した人でした。この人たちの実に90パーセントがうそをついている人を当てています。\nこれに続いて「足の動き」に注目した人の正解が多くなっています。反対に正解が少なかったのは「顔の表情」「話す時間」で、半分以下でした。\n以上のデータから、本心が表れやすいのは[ 51 ]だとわかります。\n一生懸命しゃべっているが目と目を合わさないときなどは、手と足に注目すると本心が見えやすくなります。手をオーバーに動かす、何回も座りなおす、足をゆさぶるなどに注意しないと、自分のうそも相手にわかってしまいます。\n顔は、言葉と同じように、その場の状況[ 52 ]本心と異なる表情ができます。つまり、必要ならばうそがつ託けるのです。\nしかし[ 53 ]ことは、人間関係を維持するのに非常に大切です。人々が本心通りにしゃべったり顔に表すようになったら、人間関係の多くがこわれてしまいます。人が着ている服が「似合わない」と思っても、ふつうは「お似合いですね」と言います。正直であることが必ず[ 54 ]。", "questions": [{"id": "t15-g3-1", "options": ["予想通りに", "予想に反し", "予想に基づいて", "予想にかかわらず"], "answer": 2, "tr": "［ 50 ］bo'sh o'rniga mos so'zni tanlang.", "stem": "［ 50 ］に入る最もよいものを選びなさい。", "explanation_uz": "Kutilgan taxminlarga zid ravishda: 「予想に反し (kutilganiga teskari o'laroq)」.", "blankNo": 50}, {"id": "t15-g3-2", "options": ["話の内容", "顔の表情", "手足の動き", "目の動き"], "answer": 3, "tr": "［ 51 ］bo'sh o'rniga mos iborani tanlang.", "stem": "［ 51 ］に入る最もよいものを選びなさい。", "explanation_uz": "Chin dildagi niyat qo'l va oyoq harakatlarida namoyon bo'ladi: 「手足の動き」.", "blankNo": 51}, {"id": "t15-g3-3", "options": ["に応じて", "に関して", "に際して", "をめぐって"], "answer": 1, "tr": "［ 52 ］bo'sh o'rniga mos grammatik shaklni tanlang.", "stem": "［ 52 ］に入る最もよいものを選びなさい。", "explanation_uz": "Vaziyatga qarab o'zgartira olish: 「に応じて (vaziyatga qarab)」.", "blankNo": 52}, {"id": "t15-g3-4", "options": ["うそをつく", "うそをつかない", "本心を語る", "正直に言う"], "answer": 1, "tr": "［ 53 ］bo'sh o'rniga mos ifodani tanlang.", "stem": "［ 53 ］に入る最もよいものを選びなさい。", "explanation_uz": "Odamlar bilan munosabatni saqlash uchun yolg'on gapirish (xushomad qilish): 「うそをつく」.", "blankNo": 53}, {"id": "t15-g3-5", "options": ["正しいはずがありません", "正しいに相違ありません", "正しいと決まっています", "正しいわけではありません"], "answer": 4, "tr": "［ 54 ］bo'sh o'rniga mos ifodani tanlang.", "stem": "［ 54 ］に入る最もよいものを選びなさい。", "explanation_uz": "To'g'riso'z bo'lish har doim ham to'g'ri degani emas: 「正しいわけではありません」.", "blankNo": 54}]}]}]}};
